function getGuestSessionId() {
  const existing = window.sessionStorage.getItem(GUEST_SESSION_KEY);
  if (existing) {
    return existing;
  }
  const next = `guest_${Date.now().toString(36)}_${Math.random().toString(36).slice(2, 8)}`;
  window.sessionStorage.setItem(GUEST_SESSION_KEY, next);
  return next;
}

function getPrivateViewerInstanceId() {
  const existing = window.sessionStorage.getItem(PRIVATE_VIEWER_INSTANCE_KEY);
  if (existing) {
    return existing;
  }
  const next = `viewer_${Date.now().toString(36)}_${Math.random().toString(36).slice(2, 8)}`;
  window.sessionStorage.setItem(PRIVATE_VIEWER_INSTANCE_KEY, next);
  return next;
}

function getPublicViewerSessionIdForPrivateJoin(params = new URLSearchParams(window.location.search)) {
  const explicit = String(params.get("publicViewerSessionId") ?? "").trim();
  if (explicit) {
    return explicit;
  }
  try {
    return String(window.sessionStorage.getItem(PUBLIC_VIEWER_SESSION_KEY) ?? "").trim() || undefined;
  } catch (_error) {
    return undefined;
  }
}

function parsePrivateViewerSessionId(viewerSessionId = "") {
  const raw = String(viewerSessionId ?? "").trim();
  if (!raw) {
    return {
      kind: "",
      subjectId: "",
      instanceId: "",
    };
  }
  if (raw.startsWith("profile:")) {
    const [, profileId = "", instanceId = ""] = raw.split(":");
    return {
      kind: "profile",
      subjectId: String(profileId ?? "").trim(),
      instanceId: String(instanceId ?? "").trim(),
    };
  }
  if (raw.startsWith("guest:")) {
    const [, guestSessionId = "", instanceId = ""] = raw.split(":");
    return {
      kind: "guest",
      subjectId: String(guestSessionId ?? "").trim(),
      instanceId: String(instanceId ?? "").trim(),
    };
  }
  return {
    kind: raw.startsWith("guest_") ? "guest" : "",
    subjectId: raw,
    instanceId: "",
  };
}

function setStatus(text) {
  if (elements.authStatus) {
    elements.authStatus.textContent = text || "";
  }
}

function resetPrivateInteractionState(options = {}) {
  const releaseRuntimeKeys = options.releaseRuntimeKeys !== false;
  const releasePointerCapture = options.releasePointerCapture !== false;
  if (releaseRuntimeKeys && state.pressedRuntimeKeys.size > 0) {
    releaseHeldRuntimeKeys({
      headingY: Number.isFinite(Number(options.headingY))
        ? Number(options.headingY)
        : getRuntimeInputHeadingY(),
    });
  }
  state.pressedRuntimeKeys.clear();
  state.buildModifierKeys.clear();
  privateInputState.keys.clear();
  privateInputState.jumpHeld = false;
  privateInputState.jumpVelocityY = 0;
  privateInputState.sprintHoldSeconds = 0;
  privateInputState.pointerDown = false;
  privateInputState.pointerButtonToken = "";
  privateInputState.pointerMoved = false;
  privateInputState.dragDistance = 0;
  privateInputState.lastPointerX = 0;
  privateInputState.lastPointerY = 0;
  const pointerId = Number(privateInputState.pointerId ?? 0) || 0;
  privateInputState.pointerId = 0;
  state.viewerSuppressClickAt = 0;
  state.buildSuppressedClick = null;
  state.previewPointer.inside = false;
  state.buildHover = null;
  endBuildDrag(pointerId || undefined);
  if (releasePointerCapture && pointerId && elements.previewCanvas?.releasePointerCapture) {
    try {
      elements.previewCanvas.releasePointerCapture(pointerId);
    } catch (_error) {
      // Ignore stale capture state while clearing loading/input locks.
    }
  }
  syncBuildPlacementOverlay();
}

function setEntryLoading(active, options = {}) {
  state.entryLoading = active === true;
  if (state.entryLoading) {
    resetPrivateInteractionState();
  }
  if (elements.entryLoadingTitle && options.title) {
    elements.entryLoadingTitle.textContent = options.title;
  } else if (elements.entryLoadingTitle && !state.entryLoading) {
    elements.entryLoadingTitle.textContent = "Opening private world";
  }
  if (elements.entryLoadingNote && options.note) {
    elements.entryLoadingNote.textContent = options.note;
  } else if (elements.entryLoadingNote && !state.entryLoading) {
    elements.entryLoadingNote.textContent = "Loading the scene you picked.";
  }
  if (elements.entryLoading) {
    elements.entryLoading.hidden = !state.entryLoading;
  }
  document.body.classList.toggle("is-world-entry-loading", state.entryLoading);
  renderPrivateRuntimeActions();
}

function waitForUiPaint() {
  return new Promise((resolve) => {
    window.requestAnimationFrame(() => {
      window.requestAnimationFrame(resolve);
    });
  });
}

function setPrivateShareStatus(text) {
  if (elements.panelShareStatus) {
    elements.panelShareStatus.textContent = text || "";
    return;
  }
  setStatus(text);
}

function canCopyToClipboard() {
  return typeof navigator?.clipboard?.writeText === "function" || typeof document?.execCommand === "function";
}

async function copyTextToClipboard(text) {
  const value = String(text ?? "");
  if (!value) {
    return false;
  }
  if (typeof navigator?.clipboard?.writeText === "function") {
    await navigator.clipboard.writeText(value);
    return true;
  }
  if (typeof document?.execCommand !== "function") {
    throw new Error("Clipboard copy is not available in this browser.");
  }
  const textarea = document.createElement("textarea");
  const previousActiveElement = document.activeElement;
  textarea.value = value;
  textarea.setAttribute("readonly", "");
  textarea.style.position = "fixed";
  textarea.style.left = "-9999px";
  textarea.style.top = "0";
  textarea.style.opacity = "0";
  document.body.append(textarea);
  textarea.focus({ preventScroll: true });
  textarea.select();
  textarea.setSelectionRange(0, value.length);
  const copied = document.execCommand("copy");
  textarea.remove();
  if (previousActiveElement instanceof HTMLElement) {
    previousActiveElement.focus?.({ preventScroll: true });
  }
  if (!copied) {
    throw new Error("Could not copy entry link.");
  }
  return true;
}

function getPrivateViewerSessionId() {
  const instanceId = getPrivateViewerInstanceId();
  if (state.profile?.id) {
    return `profile:${state.profile.id}:${instanceId}`;
  }
  return `guest:${getGuestSessionId()}:${instanceId}`;
}

function getPrivateDisplayName() {
  return state.profile?.display_name || state.profile?.username || "guest viewer";
}

function cloneJson(value) {
  return JSON.parse(JSON.stringify(value ?? null));
}

function getPrivateProfileId() {
  return String(state.profile?.id ?? "").trim();
}

const privateWorldGamesApi = createWorldGamesApi({
  getAccessToken: () => String(state.session?.access_token ?? "").trim(),
});

const privateGameLibrary = createWorldGameLibrary({
  api: privateWorldGamesApi,
  storagePrefix: "mauworld-private-world-games",
  onSelect(game) {
    state.selectedWorldGameId = String(game?.id ?? "").trim();
    updatePrivateBrowserPanel();
  },
  onGenerated(game) {
    state.selectedWorldGameId = String(game?.id ?? "").trim();
    updatePrivateBrowserPanel();
  },
  onShare(game) {
    void startPrivateWorldGameShare(game);
  },
});

const privateGameShell = createWorldGameShell({
  getViewerSessionId: getPrivateViewerSessionId,
  getProfileId: getPrivateProfileId,
  onOpenSession(sessionId) {
    const sent = sendWorldSocketMessage({
      type: "game:open",
      sessionId,
    });
    if (!sent) {
      privateGameShell.setStatus("Private world share is offline.");
      setPrivateBrowserStatus("Private world share is offline.");
    }
  },
  onClaimSeat(sessionId, seatId) {
    sendWorldSocketMessage({
      type: "game:seat-claim",
      sessionId,
      seatId,
    });
  },
  onReleaseSeat(sessionId, seatId = "") {
    sendWorldSocketMessage({
      type: "game:seat-release",
      sessionId,
      seatId,
    });
  },
  onReady(sessionId, ready) {
    sendWorldSocketMessage({
      type: "game:ready",
      sessionId,
      ready,
    });
  },
  onStartMatch(sessionId) {
    sendWorldSocketMessage({
      type: "game:start-match",
      sessionId,
    });
  },
  onAction(sessionId, action) {
    sendWorldSocketMessage({
      type: "game:action",
      sessionId,
      action,
    });
  },
  onState(sessionId, nextState) {
    sendWorldSocketMessage({
      type: "game:state",
      sessionId,
      state: nextState,
    });
  },
  onPreview(sessionId, preview, meta = {}) {
    const normalizedSessionId = String(sessionId ?? "").trim();
    const isFinalHidePreview = String(meta?.reason ?? "").trim() === "hide-final";
    const existingPreviewUrl = String(
      state.gameSessions.get(normalizedSessionId)?.latest_preview?.data_url ?? "",
    ).trim();
    if (isFinalHidePreview && existingPreviewUrl) {
      return;
    }
    updateLocalPrivateGamePreview(sessionId, preview);
    queuePrivateGamePreviewMediaFrame(sessionId, preview);
    sendWorldSocketMessage({
      type: "game:preview",
      sessionId,
      preview,
    });
  },
  onCopy(sessionId) {
    if (!state.session) {
      setPrivateBrowserStatus("Sign in to copy this game.");
      return;
    }
    sendWorldSocketMessage({
      type: "game:copy",
      sessionId,
    });
  },
});

function getPrivateBrowserMediaCanvas() {
  if (!state.browserMediaCanvas) {
    state.browserMediaCanvas = document.createElement("canvas");
    state.browserMediaCanvas.width = 960;
    state.browserMediaCanvas.height = 540;
    state.browserMediaCanvasContext = state.browserMediaCanvas.getContext("2d");
    state.browserMediaImage = new Image();
  }
  if (state.browserMediaCanvas.width !== 960 || state.browserMediaCanvas.height !== 540) {
    state.browserMediaCanvas.width = 960;
    state.browserMediaCanvas.height = 540;
  }
  return state.browserMediaCanvas;
}

function drawPrivateBrowserMediaFrame(frame = {}) {
  if (!frame?.dataUrl) {
    return;
  }
  const nextFrameId = Math.max(0, Math.floor(Number(frame.frameId) || 0));
  if (nextFrameId < state.browserMediaPendingFrameId) {
    return;
  }
  state.browserMediaPendingFrameId = nextFrameId;
  const canvas = getPrivateBrowserMediaCanvas();
  const context = state.browserMediaCanvasContext;
  const image = state.browserMediaImage;
  if (!canvas || !context || !image) {
    return;
  }
  image.onload = () => {
    if (nextFrameId < state.browserMediaPendingFrameId) {
      return;
    }
    const sourceWidth = image.naturalWidth || frame.width || canvas.width;
    const sourceHeight = image.naturalHeight || frame.height || canvas.height;
    const scale = Math.min(canvas.width / Math.max(1, sourceWidth), canvas.height / Math.max(1, sourceHeight));
    const drawWidth = Math.max(1, sourceWidth * scale);
    const drawHeight = Math.max(1, sourceHeight * scale);
    const offsetX = (canvas.width - drawWidth) / 2;
    const offsetY = (canvas.height - drawHeight) / 2;
    context.fillStyle = "#02050f";
    context.fillRect(0, 0, canvas.width, canvas.height);
    context.drawImage(image, offsetX, offsetY, drawWidth, drawHeight);
  };
  image.src = frame.dataUrl;
}

function ensurePrivateGamePreviewMediaEntry(sessionId) {
  const normalizedSessionId = String(sessionId ?? "").trim();
  if (!normalizedSessionId) {
    return null;
  }
  let entry = state.gamePreviewMedia.get(normalizedSessionId);
  if (entry) {
    return entry;
  }
  const canvas = document.createElement("canvas");
  canvas.width = 480;
  canvas.height = 270;
  const context = canvas.getContext("2d");
  const image = new Image();
  entry = {
    sessionId: normalizedSessionId,
    canvas,
    context,
    image,
    published: false,
    publishing: false,
    lastPublishAttemptAt: 0,
    pendingPreview: null,
  };
  image.onload = () => {
    const nextPreview = entry.pendingPreview;
    if (!nextPreview?.data_url || !entry.context) {
      return;
    }
    const width = Math.max(1, Math.floor(Number(nextPreview.width) || image.naturalWidth || canvas.width || 480));
    const height = Math.max(1, Math.floor(Number(nextPreview.height) || image.naturalHeight || canvas.height || 270));
    if (canvas.width !== width || canvas.height !== height) {
      if (entry.published) {
        void getPrivateBrowserMediaController().unpublishSession?.(normalizedSessionId);
        entry.published = false;
      }
      canvas.width = width;
      canvas.height = height;
    }
    entry.context.clearRect(0, 0, canvas.width, canvas.height);
    entry.context.drawImage(image, 0, 0, canvas.width, canvas.height);
    void ensurePublishedPrivateGamePreviewMedia(normalizedSessionId);
  };
  state.gamePreviewMedia.set(normalizedSessionId, entry);
  return entry;
}

function clearPrivateGamePreviewMedia(sessionId, { unpublish = true } = {}) {
  const normalizedSessionId = String(sessionId ?? "").trim();
  if (!normalizedSessionId) {
    return;
  }
  const entry = state.gamePreviewMedia.get(normalizedSessionId);
  if (!entry) {
    return;
  }
  if (unpublish) {
    void getPrivateBrowserMediaController().unpublishSession?.(normalizedSessionId);
  }
  getPrivateBrowserMediaController().removeSession?.(normalizedSessionId);
  state.gamePreviewMedia.delete(normalizedSessionId);
}

function clearAllPrivateGamePreviewMedia({ unpublish = true } = {}) {
  for (const sessionId of [...state.gamePreviewMedia.keys()]) {
    clearPrivateGamePreviewMedia(sessionId, { unpublish });
  }
}

function getPrivateGameSessionHostViewerSessionId(session = {}) {
  return String(session?.host_viewer_session_id ?? session?.hostViewerSessionId ?? "").trim();
}

function getPrivateGameSessionDeliveryMode(session = {}) {
  if (getPrivateGameSessionHostViewerSessionId(session) === getPrivateViewerSessionId()) {
    return "full";
  }
  return String(session?.deliveryMode ?? "").trim() === "full" ? "full" : "placeholder";
}

function isPrivateLocalHostedGameShareSession(session = {}) {
  return getPrivateGameSessionHostViewerSessionId(session) === getPrivateViewerSessionId();
}

function getPrivateLocalGamePreviewCanvas(sessionId = "") {
  return state.gamePreviewMedia.get(String(sessionId ?? "").trim())?.canvas ?? null;
}

function hasPrivateSiblingNearbyMediaForGameHost(session = {}) {
  const hostSessionId = getPrivateGameSessionHostViewerSessionId(session);
  const sessionId = String(session?.session_id ?? "").trim();
  const browserWorldKey = getPrivateBrowserWorldKey();
  if (!hostSessionId) {
    return false;
  }
  for (const browserSession of state.browserSessions.values()) {
    const browserHostSessionId = String(browserSession?.hostSessionId ?? "").trim();
    const bindingKey = String(browserSession?.bindingKey ?? browserSession?.binding_key ?? "").trim();
    const countsAsNearbyShare = isPrivateListedLiveSession(browserSession)
      || (isPrivatePersistentVoiceSession(browserSession) && !isPrivateBrowserMemberSession(browserSession));
    if (
      !countsAsNearbyShare
      || browserHostSessionId !== hostSessionId
      || (browserWorldKey && bindingKey && bindingKey !== browserWorldKey)
    ) {
      continue;
    }
    return true;
  }
  for (const gameSession of state.gameSessions.values()) {
    const otherSessionId = String(gameSession?.session_id ?? "").trim();
    const bindingKey = String(gameSession?.binding_key ?? "").trim();
    if (
      !isPrivateListedLiveGameSession(gameSession)
      || !otherSessionId
      || otherSessionId === sessionId
      || getPrivateGameSessionHostViewerSessionId(gameSession) !== hostSessionId
      || (browserWorldKey && bindingKey && bindingKey !== browserWorldKey)
    ) {
      continue;
    }
    return true;
  }
  return false;
}

function getPrivateGameShareLaneOffset(session = {}) {
  if (!hasPrivateSiblingNearbyMediaForGameHost(session)) {
    return { x: 0, y: 0, z: 0 };
  }
  const laneOffset = getSharedNearbyLaneOffset({ shareKind: "game" });
  return {
    x: laneOffset.x + (SHARED_BROWSER_SHARE_LAYOUT.screenWidth * 0.24),
    y: laneOffset.y,
    z: laneOffset.z - 0.9,
  };
}

function getPrivateGameShareLocalCanvasTexture(entry) {
  if (!entry) {
    return null;
  }
  const canvas = isPrivateLocalHostedGameShareSession(entry.session)
    ? getPrivateLocalGamePreviewCanvas(entry.sessionId)
    : null;
  if (!canvas) {
    entry.localCanvasTexture?.dispose?.();
    entry.localCanvasTexture = null;
    entry.localCanvas = null;
    entry.localCanvasWidth = 0;
    entry.localCanvasHeight = 0;
    return null;
  }
  const canvasWidth = Math.max(1, Math.round(Number(canvas.width) || canvas.clientWidth || 0));
  const canvasHeight = Math.max(1, Math.round(Number(canvas.height) || canvas.clientHeight || 0));
  if (
    entry.localCanvas !== canvas
    || !entry.localCanvasTexture
    || entry.localCanvasWidth !== canvasWidth
    || entry.localCanvasHeight !== canvasHeight
  ) {
    entry.localCanvasTexture?.dispose?.();
    entry.localCanvas = canvas;
    entry.localCanvasTexture = new THREE.CanvasTexture(canvas);
    entry.localCanvasTexture.colorSpace = THREE.SRGBColorSpace;
    entry.localCanvasTexture.generateMipmaps = false;
    entry.localCanvasTexture.minFilter = THREE.LinearFilter;
    entry.localCanvasTexture.magFilter = THREE.LinearFilter;
    entry.localCanvasWidth = canvasWidth;
    entry.localCanvasHeight = canvasHeight;
  }
  entry.localCanvasTexture.needsUpdate = true;
  return entry.localCanvasTexture;
}

function updateLocalPrivateGamePreview(sessionId, preview = null) {
  const normalizedSessionId = String(sessionId ?? "").trim();
  const existing = state.gameSessions.get(normalizedSessionId);
  if (!existing || !preview?.data_url) {
    return;
  }
  const updatedPreview = {
    ...cloneJson(preview),
    updated_at: String(preview.updated_at ?? "").trim() || new Date().toISOString(),
  };
  state.gameSessions.set(normalizedSessionId, {
    ...existing,
    latest_preview: updatedPreview,
  });
  if (privateGameShell.isOpen(normalizedSessionId)) {
    privateGameShell.updateSession(state.gameSessions.get(normalizedSessionId), { syncFrame: false });
  }
}

function updateCachedPrivateGameSession(sessionId, patch = {}) {
  const normalizedSessionId = String(sessionId ?? "").trim();
  if (!normalizedSessionId) {
    return null;
  }
  const existing = state.gameSessions.get(normalizedSessionId) ?? {};
  const hostViewerSessionId = getPrivateGameSessionHostViewerSessionId({
    ...existing,
    ...patch,
  });
  const next = {
    ...existing,
    ...patch,
    session_id: normalizedSessionId,
    deliveryMode: hostViewerSessionId === getPrivateViewerSessionId()
      ? "full"
      : String(patch?.deliveryMode ?? existing?.deliveryMode ?? "").trim() === "full"
        ? "full"
        : "placeholder",
  };
  state.gameSessions.set(normalizedSessionId, next);
  return next;
}

async function ensurePublishedPrivateGamePreviewMedia(sessionId) {
  const normalizedSessionId = String(sessionId ?? "").trim();
  const localSession = getLocalPrivateGameSession();
  const browserWorldKey = getPrivateBrowserWorldKey();
  if (
    !normalizedSessionId
    || !localSession
    || String(localSession.session_id ?? "").trim() !== normalizedSessionId
    || String(localSession.host_viewer_session_id ?? "").trim() !== getPrivateViewerSessionId()
    || !browserWorldKey
  ) {
    return false;
  }
  const entry = state.gamePreviewMedia.get(normalizedSessionId);
  if (!entry || entry.published || entry.publishing) {
    return entry?.published === true;
  }
  const now = Date.now();
  if (now - Number(entry.lastPublishAttemptAt || 0) < 3000) {
    return entry.published === true;
  }
  entry.lastPublishAttemptAt = now;
  entry.publishing = true;
  try {
    const published = await getPrivateBrowserMediaController().publishCanvas({
      sessionId: normalizedSessionId,
      canvas: entry.canvas,
      fps: 12,
      viewerSessionId: getPrivateViewerSessionId(),
      worldSnapshotId: browserWorldKey,
    });
    entry.published = published === true;
    return entry.published;
  } finally {
    entry.publishing = false;
  }
}

function queuePrivateGamePreviewMediaFrame(sessionId, preview = null) {
  if (!preview?.data_url) {
    return;
  }
  const entry = ensurePrivateGamePreviewMediaEntry(sessionId);
  if (!entry?.image) {
    return;
  }
  entry.pendingPreview = cloneJson(preview);
  entry.image.src = preview.data_url;
}

function syncPrivateGameMediaSubscription(sessionId, subscribed) {
  const normalizedSessionId = String(sessionId ?? "").trim();
  const browserWorldKey = getPrivateBrowserWorldKey();
  if (!normalizedSessionId || !browserWorldKey) {
    return;
  }
  updateCachedPrivateGameSession(normalizedSessionId, {
    deliveryMode: subscribed ? "full" : "placeholder",
  });
  if (subscribed) {
    state.gameMediaSubscriptions.add(normalizedSessionId);
  } else {
    state.gameMediaSubscriptions.delete(normalizedSessionId);
  }
  const session = state.gameSessions.get(normalizedSessionId) ?? null;
  void getPrivateBrowserMediaController().setSubscribed({
    sessionId: normalizedSessionId,
    subscribed,
    viewerSessionId: getPrivateViewerSessionId(),
    worldSnapshotId: browserWorldKey,
    canPublish: String(session?.host_viewer_session_id ?? "").trim() === getPrivateViewerSessionId(),
  });
  if (!subscribed) {
    clearPrivateGameShareVideo(normalizedSessionId);
  }
}

function publishLocalPrivateBrowserMedia(sessionId) {
  const session = state.browserSessions.get(sessionId);
  const worldSnapshotId = getPrivateBrowserWorldKey();
  if (
    !session
    || session.hostSessionId !== getPrivateViewerSessionId()
    || session.frameTransport !== "livekit-canvas"
    || !worldSnapshotId
  ) {
    return;
  }
  void getPrivateBrowserMediaController().publishCanvas({
    sessionId,
    canvas: getPrivateBrowserMediaCanvas(),
    fps: 24,
    viewerSessionId: getPrivateViewerSessionId(),
    worldSnapshotId,
  });
}

function getPrivateBrowserWorldKey(world = state.selectedWorld) {
  if (!world?.world_id || !world?.creator?.username) {
    return "";
  }
  return `private:${world.world_id}:${String(world.creator.username).trim().toLowerCase()}`;
}

function normalizePrivatePanelTab(tab) {
  return PRIVATE_PANEL_TABS.has(tab) ? tab : "chat";
}

function normalizeWorldPanelSection(section) {
  return WORLD_PANEL_SECTIONS.has(section) ? section : "overview";
}

function normalizeSceneDrawerTab(tab) {
  return SCENE_DRAWER_TABS.has(tab) ? tab : "scenes";
}

function renderWorldPanelSections(options = {}) {
  const activeSection = normalizeWorldPanelSection(state.worldPanelSection);
  state.worldPanelSection = activeSection;
  const hasWorld = Boolean(state.selectedWorld);
  for (const button of elements.worldSectionJumpButtons ?? []) {
    const sectionName = normalizeWorldPanelSection(button.getAttribute("data-world-section-jump") || "");
    const isActive = hasWorld && sectionName === activeSection;
    button.classList.toggle("is-active", isActive);
    button.setAttribute("aria-selected", String(isActive));
    button.tabIndex = isActive ? 0 : -1;
  }
  for (const section of elements.worldSections ?? []) {
    const sectionName = normalizeWorldPanelSection(section.getAttribute("data-world-section") || "");
    const isActive = hasWorld && sectionName === activeSection;
    section.hidden = !isActive;
    section.setAttribute("aria-hidden", String(!isActive));
  }
  const fieldName = String(options.fieldName || "").trim();
  if (!fieldName || !hasWorld || state.privatePanelTab !== "world" || activeSection !== "ai") {
    return;
  }
  window.requestAnimationFrame(() => {
    const field = elements.aiForm?.elements?.[fieldName];
    field?.focus?.();
    if (fieldName.toLowerCase().includes("apikey") && typeof field?.select === "function") {
      field.select();
    }
  });
}

function setWorldPanelSection(section, options = {}) {
  state.worldPanelSection = normalizeWorldPanelSection(String(section ?? "").trim().toLowerCase());
  if (options.openWorldPanel !== false && state.selectedWorld) {
    setPrivatePanelTab("world");
  }
  renderWorldPanelSections(options);
}

function renderSceneDrawerTabs() {
  const activeTab = normalizeSceneDrawerTab(state.sceneDrawerTab);
  state.sceneDrawerTab = activeTab;
  for (const button of elements.sceneDrawerTabButtons ?? []) {
    const isActive = button.getAttribute("data-scene-drawer-tab") === activeTab;
    button.classList.toggle("is-active", isActive);
    button.setAttribute("aria-selected", String(isActive));
  }
  for (const view of elements.sceneDrawerViews ?? []) {
    const isActive = view.getAttribute("data-scene-drawer-view") === activeTab;
    view.hidden = !isActive;
    view.setAttribute("aria-hidden", String(!isActive));
  }
}

function setSceneDrawerTab(tab) {
  const nextTab = normalizeSceneDrawerTab(tab);
  if (nextTab !== "scenes" && state.sceneDrawerFocusId !== state.selectedSceneId) {
    if (state.sceneEditorSceneId) {
      rememberSceneDraft();
    }
    state.sceneDrawerFocusId = state.selectedSceneId;
  }
  state.sceneDrawerTab = nextTab;
  renderSceneDrawerTabs();
  renderSceneLibrary();
  renderSceneDrawerSceneIndicator();
  renderSceneEditor();
  if (elements.sceneDrawer) {
    elements.sceneDrawer.scrollTop = 0;
  }
}

function resetHorizontalScroll(element) {
  if (!element) {
    return;
  }
  if (element.scrollLeft !== 0) {
    element.scrollLeft = 0;
  }
}

function settleHorizontalScroll(element) {
  if (!element) {
    return;
  }
  resetHorizontalScroll(element);
  window.requestAnimationFrame(() => {
    resetHorizontalScroll(element);
  });
  window.setTimeout(() => {
    resetHorizontalScroll(element);
  }, 32);
}

function setPrivatePanelTab(tab, options = {}) {
  const nextTab = normalizePrivatePanelTab(tab);
  const refreshWorld = options.refreshWorld === true;
  state.privatePanelTab = nextTab;
  if (nextTab !== "share" && state.browserOverlayOpen) {
    setPrivateBrowserOverlayOpen(false);
  }
  for (const button of elements.privatePanelTabButtons ?? []) {
    const active = button.getAttribute("data-private-panel-tab") === nextTab;
    button.classList.toggle("is-active", active);
    if (button.getAttribute("role") === "tab") {
      button.setAttribute("aria-selected", String(active));
    } else {
      button.setAttribute("aria-pressed", String(active));
    }
  }
  for (const view of elements.privatePanelViews ?? []) {
    view.hidden = view.getAttribute("data-private-panel-view") !== nextTab;
  }
  renderWorldPanelSections();
  if (nextTab === "live") {
    renderPrivateLiveSharesList();
  }
  if (refreshWorld && state.selectedWorld) {
    renderSelectedWorld();
  }
  settleHorizontalScroll(elements.panelRoot);
}

function syncCreateWorldDialogVisibility() {
  document.body.classList.toggle("is-create-world-dialog-open", state.createWorldDialogOpen === true);
  if (elements.createWorldDialog) {
    elements.createWorldDialog.hidden = !(state.createWorldDialogOpen && canShowCreateWorldDialog());
  }
}

function updateShellState() {
  const activePlacementTool = getActivePlacementTool();
  const activePrefabPlacementId = getActivePrefabPlacementId();
  const buildTransformMode = getResolvedBuildTransformMode();
  const authGated = state.authReady === true && !state.session;
  document.body.classList.toggle("has-world", Boolean(state.selectedWorld));
  document.body.classList.toggle("is-launcher-open", state.launcherOpen === true);
  document.body.classList.toggle("is-auth-gated", authGated);
  document.body.classList.toggle("is-world-entry-loading", state.entryLoading === true);
  document.body.classList.toggle("is-scene-drawer-open", state.sceneDrawerOpen === true);
  document.body.classList.toggle("is-ai-dialog-open", state.aiDialog.open === true);
  document.body.classList.toggle("is-signed-in", Boolean(state.session));
  document.body.classList.toggle(
    "has-placement-tool",
    Boolean((activePlacementTool || activePrefabPlacementId) && canUsePlacementTools()),
  );
  document.body.classList.toggle(
    "has-selection",
    Boolean(hasBuilderSelection() && state.mode === "build" && isEditor()),
  );
  for (const mode of ["move", "scale", "rotate", "multi", "delete"]) {
    document.body.classList.toggle(`is-build-${mode}`, buildTransformMode === mode);
  }
  for (const kind of ["voxel", "primitive", "panel", "player", "screen", "text", "trigger"]) {
    const button = getPlacementToolButton(kind);
    if (!button) {
      continue;
    }
    const active = kind === activePlacementTool && canUsePlacementTools();
    button.classList.toggle("is-active", active);
    button.setAttribute("aria-pressed", String(active));
    button.title = buildPlacementToolLabel(kind);
  }
  if (elements.placePrefab) {
    const hasActivePrefab = Boolean(state.selectedPrefabId);
    const isArmed = Boolean(activePrefabPlacementId) && activePrefabPlacementId === state.selectedPrefabId;
    elements.placePrefab.classList.toggle("is-active", isArmed);
    elements.placePrefab.textContent = isArmed ? "Cancel world placement" : "Use in world";
    elements.placePrefab.disabled = !canUsePlacementTools() || !hasActivePrefab;
  }
  if (elements.prefabSearch) {
    elements.prefabSearch.disabled = !state.selectedWorld;
  }
  if (elements.launcherClose) {
    elements.launcherClose.hidden = authGated;
  }
  syncCreateWorldDialogVisibility();
  setLauncherTab(state.launcherTab);
  setPrivatePanelTab(state.privatePanelTab, { syncMode: false });
  renderToolPresetPanel();
  syncPreviewCanvasCursor();
}

function setLauncherOpen(open) {
  state.launcherOpen = !state.session ? true : open === true;
  if (state.launcherOpen) {
    state.sceneDrawerOpen = false;
    writeBuilderSelection([]);
    if (!LAUNCHER_TABS.has(state.launcherTab)) {
      state.launcherTab = getPreferredLauncherTab();
    }
  } else {
    state.createWorldDialogOpen = false;
  }
  updateShellState();
}

function setCreateWorldDialogOpen(open) {
  state.createWorldDialogOpen = open === true && canShowCreateWorldDialog();
  if (state.createWorldDialogOpen) {
    state.launcherOpen = true;
    state.sceneDrawerOpen = false;
    writeBuilderSelection([]);
  }
  updateShellState();
}

function setSceneDrawerOpen(open) {
  state.sceneDrawerOpen = open === true;
  updateShellState();
}

function pushEvent(title, body) {
  state.eventLog.unshift({
    id: `${Date.now()}_${Math.random().toString(36).slice(2, 8)}`,
    title,
    body,
    createdAt: new Date().toLocaleTimeString(),
  });
  state.eventLog = state.eventLog.slice(0, 18);
  renderEventLog();
}

function htmlEscape(value) {
  return String(value ?? "")
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#39;");
}

function slugToken(value) {
  return String(value ?? "")
    .trim()
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-|-$/g, "")
    .slice(0, 40);
}

function slugPrivateEntityToken(value) {
  return String(value ?? "")
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/-+/g, "-")
    .replace(/^-|-$/g, "");
}

function renormalizePrivateEntityId(prefix, value) {
  const cleaned = slugPrivateEntityToken(value);
  return cleaned ? `${prefix}_${cleaned}` : null;
}

function normalizePrivateEntityId(prefix, value) {
  const raw = String(value ?? "").trim();
  if (!raw) {
    return null;
  }
  if (raw.toLowerCase().startsWith(`${prefix}_`)) {
    const suffix = slugPrivateEntityToken(raw.slice(prefix.length + 1));
    if (suffix) {
      return `${prefix}_${suffix}`;
    }
  }
  return renormalizePrivateEntityId(prefix, raw);
}

function collectPrivateEntityIdVariants(prefix, value, maxDepth = 4) {
  const variants = new Set();
  const raw = String(value ?? "").trim();
  if (!raw) {
    return variants;
  }
  variants.add(raw);
  const normalized = normalizePrivateEntityId(prefix, raw);
  if (normalized) {
    variants.add(normalized);
  }
  let current = raw;
  for (let depth = 0; depth < maxDepth; depth += 1) {
    current = renormalizePrivateEntityId(prefix, current);
    if (!current || variants.has(current)) {
      break;
    }
    variants.add(current);
  }
  current = normalized;
  for (let depth = 0; current && depth < maxDepth; depth += 1) {
    current = renormalizePrivateEntityId(prefix, current);
    if (!current || variants.has(current)) {
      break;
    }
    variants.add(current);
  }
  return variants;
}

function resolvePrivateEntityIdAlias(prefix, value, knownIds = []) {
  const raw = String(value ?? "").trim();
  if (!raw) {
    return null;
  }
  const candidates = Array.from(new Set(
    (Array.isArray(knownIds) ? knownIds : [])
      .map((entry) => String(entry ?? "").trim())
      .filter(Boolean),
  ));
  if (candidates.length === 0) {
    return normalizePrivateEntityId(prefix, raw) ?? raw;
  }
  const requestedVariants = collectPrivateEntityIdVariants(prefix, raw);
  for (const candidate of candidates) {
    if (requestedVariants.has(candidate)) {
      return candidate;
    }
  }
  for (const candidate of candidates) {
    const candidateVariants = collectPrivateEntityIdVariants(prefix, candidate);
    for (const variant of candidateVariants) {
      if (requestedVariants.has(variant)) {
        return candidate;
      }
    }
  }
  return normalizePrivateEntityId(prefix, raw) ?? raw;
}

function getRuntimePlayerIds(snapshot = state.runtimeSnapshot) {
  return Array.isArray(snapshot?.players)
    ? snapshot.players
      .map((entry) => String(entry?.id ?? "").trim())
      .filter(Boolean)
    : [];
}

function resolvePrivatePlayerEntityId(value, knownIds = getRuntimePlayerIds()) {
  return resolvePrivateEntityIdAlias("player", value, knownIds);
}

function deepClone(value) {
  return JSON.parse(JSON.stringify(value ?? null));
}

function clampNumber(value, fallback, min, max) {
  const numeric = Number(value);
  if (!Number.isFinite(numeric)) {
    return fallback;
  }
  return Math.max(min, Math.min(max, numeric));
}

function normalizeAngle(angle) {
  let next = Number(angle) || 0;
  while (next > Math.PI) {
    next -= Math.PI * 2;
  }
  while (next < -Math.PI) {
    next += Math.PI * 2;
  }
  return next;
}

function hashPrivateString(value = "") {
  let hash = 0;
  const source = String(value ?? "");
  for (let index = 0; index < source.length; index += 1) {
    hash = ((hash << 5) - hash + source.charCodeAt(index)) | 0;
  }
  return Math.abs(hash);
}

function pickPrivateAccent(seed, offset = 0) {
  return PRIVATE_WORLD_STYLE.accents[(hashPrivateString(seed) + offset) % PRIVATE_WORLD_STYLE.accents.length];
}

function pickPrivateAccentSet(seed) {
  return {
    primary: pickPrivateAccent(seed, 0),
    secondary: pickPrivateAccent(seed, 2),
    tertiary: pickPrivateAccent(seed, 4),
  };
}

function getPrivateToonGradientTexture() {
  if (privateToonGradientTexture) {
    return privateToonGradientTexture;
  }

  const canvas = document.createElement("canvas");
  canvas.width = 4;
  canvas.height = 1;
  const context = canvas.getContext("2d");
  context.fillStyle = "#444444";
  context.fillRect(0, 0, 1, 1);
  context.fillStyle = "#8d8d8d";
  context.fillRect(1, 0, 1, 1);
  context.fillStyle = "#d7d7d7";
  context.fillRect(2, 0, 1, 1);
  context.fillStyle = "#ffffff";
  context.fillRect(3, 0, 1, 1);

  privateToonGradientTexture = new THREE.CanvasTexture(canvas);
  privateToonGradientTexture.minFilter = THREE.NearestFilter;
  privateToonGradientTexture.magFilter = THREE.NearestFilter;
  privateToonGradientTexture.generateMipmaps = false;
  privateToonGradientTexture.needsUpdate = true;
  return privateToonGradientTexture;
}

function createOutlineShell(geometry, color, scale = 1.08) {
  const shell = new THREE.Mesh(
    geometry.clone(),
    new THREE.MeshBasicMaterial({
      color: new THREE.Color(color),
      side: THREE.BackSide,
      transparent: true,
      opacity: 1,
      fog: false,
    }),
  );
  shell.scale.setScalar(scale);
  return shell;
}

function createPrivateBillboard(texture, width, height, options = {}) {
  const material = new THREE.MeshBasicMaterial({
    map: texture,
    transparent: true,
    depthTest: options.depthTest ?? true,
    depthWrite: false,
    opacity: options.opacity ?? 1,
    fog: options.fog ?? true,
  });
  const geometry = new THREE.PlaneGeometry(width, height);
  const mesh = new THREE.Mesh(geometry, material);
  mesh.renderOrder = options.renderOrder ?? 10;
  return mesh;
}

function createViewerAvatarFigure(options = {}) {
  const seed = options.seed ?? "viewer-self";
  const scale = options.scale ?? 0.52;
  const accents = pickPrivateAccentSet(seed);
  const outlineColor = options.outlineColor ?? PRIVATE_WORLD_STYLE.accents[0];
  const primary = options.primary ?? accents.primary;
  const secondary = options.secondary ?? accents.secondary;
  const tertiary = options.tertiary ?? accents.tertiary;
  const group = new THREE.Group();
  const poseRoot = new THREE.Group();
  const shadow = new THREE.Mesh(
    new THREE.CircleGeometry(3.9 * scale, 40),
    new THREE.MeshBasicMaterial({
      color: new THREE.Color("#dfe7f5"),
      transparent: true,
      opacity: 0.72,
      depthWrite: false,
      fog: false,
    }),
  );
  shadow.rotation.x = -Math.PI / 2;
  shadow.position.y = 0.05;
  shadow.scale.set(1.16, 0.72, 1);
  group.add(shadow);
  group.add(poseRoot);

  const bodyGeometry = new THREE.CapsuleGeometry(1.45 * scale, 2.4 * scale, 6, 16);
  const headGeometry = new THREE.SphereGeometry(2.15 * scale, 24, 24);
  const earGeometry = new THREE.ConeGeometry(0.8 * scale, 1.9 * scale, 16);
  const limbGeometry = new THREE.CapsuleGeometry(0.38 * scale, 1.3 * scale, 4, 10);

  const whiteMaterial = new THREE.MeshToonMaterial({ color: new THREE.Color(PRIVATE_WORLD_STYLE.white) });
  const primaryMaterial = new THREE.MeshToonMaterial({ color: new THREE.Color(primary) });
  const secondaryMaterial = new THREE.MeshToonMaterial({ color: new THREE.Color(secondary) });
  const faceMaterial = new THREE.MeshBasicMaterial({ color: new THREE.Color(outlineColor), fog: false });

  const bodyShell = createOutlineShell(bodyGeometry, outlineColor, 1.12);
  bodyShell.position.y = 4.2 * scale;
  poseRoot.add(bodyShell);

  const body = new THREE.Mesh(bodyGeometry, whiteMaterial);
  body.position.y = 4.2 * scale;
  poseRoot.add(body);

  const headShell = createOutlineShell(headGeometry, outlineColor, 1.12);
  headShell.position.y = 8.3 * scale;
  poseRoot.add(headShell);

  const head = new THREE.Mesh(headGeometry, whiteMaterial);
  head.position.y = 8.3 * scale;
  poseRoot.add(head);

  for (const side of [-1, 1]) {
    const earShell = createOutlineShell(earGeometry, primary, 1.12);
    earShell.position.set(side * 1.45 * scale, 11 * scale, 0);
    earShell.rotation.z = side * 0.36;
    poseRoot.add(earShell);

    const ear = new THREE.Mesh(earGeometry, side > 0 ? primaryMaterial : secondaryMaterial);
    ear.position.copy(earShell.position);
    ear.rotation.copy(earShell.rotation);
    poseRoot.add(ear);

    const arm = new THREE.Mesh(limbGeometry, side > 0 ? secondaryMaterial : primaryMaterial);
    arm.position.set(side * 2.25 * scale, 4.9 * scale, 0.1 * scale);
    arm.rotation.z = side * 0.84;
    poseRoot.add(arm);
  }

  for (const side of [-1, 1]) {
    const eye = new THREE.Mesh(new THREE.SphereGeometry(0.25 * scale, 10, 10), faceMaterial);
    eye.position.set(side * 0.72 * scale, 8.45 * scale, 1.92 * scale);
    poseRoot.add(eye);

    const cheek = new THREE.Mesh(
      new THREE.SphereGeometry(0.3 * scale, 10, 10),
      new THREE.MeshBasicMaterial({
        color: new THREE.Color(side > 0 ? primary : secondary),
        transparent: true,
        opacity: 0.82,
        fog: false,
      }),
    );
    cheek.position.set(side * 1.2 * scale, 7.65 * scale, 1.8 * scale);
    poseRoot.add(cheek);
  }

  const halo = new THREE.Mesh(
    new THREE.TorusGeometry(2.9 * scale, 0.2 * scale, 10, 42),
    new THREE.MeshBasicMaterial({
      color: new THREE.Color(primary),
      transparent: true,
      opacity: 0.9,
      fog: false,
    }),
  );
  halo.rotation.x = Math.PI / 2;
  halo.position.y = 5.6 * scale;
  poseRoot.add(halo);

  const orb = new THREE.Mesh(
    new THREE.SphereGeometry(0.46 * scale, 16, 16),
    new THREE.MeshToonMaterial({ color: new THREE.Color(tertiary) }),
  );
  orb.position.set(0, 12.8 * scale, 0);
  poseRoot.add(orb);

  return {
    group,
    poseRoot,
    halo,
    orb,
    shadow,
  };
}

function ensurePrivatePlayerJumpShadow(mesh) {
  if (!mesh) {
    return null;
  }
  const existing = mesh.userData.privateWorldJumpShadow;
  if (existing?.parent === mesh) {
    return existing;
  }
  const shadow = new THREE.Mesh(
    new THREE.CircleGeometry(PRIVATE_PLAYER_JUMP_SHADOW.radius, 36),
    new THREE.MeshBasicMaterial({
      color: new THREE.Color(PRIVATE_PLAYER_JUMP_SHADOW.color),
      transparent: true,
      opacity: PRIVATE_PLAYER_JUMP_SHADOW.opacity,
      depthWrite: false,
      fog: false,
    }),
  );
  shadow.rotation.x = -Math.PI / 2;
  shadow.renderOrder = 1;
  shadow.scale.set(1.36, 0.9, 1);
  mesh.add(shadow);
  mesh.userData.privateWorldJumpShadow = shadow;
  return shadow;
}

function syncPrivatePlayerJumpShadow(mesh, playerLike = {}) {
  if (!mesh) {
    return;
  }
  const jumpEnabled = normalizePlayerJumpEnabled(
    playerLike?.jumpEnabled ?? playerLike?.jump_enabled ?? mesh.userData.privateWorldJumpEnabled ?? false,
  );
  mesh.userData.privateWorldJumpEnabled = jumpEnabled;
  mesh.userData.privateWorldPlayerOnGround = playerLike?.onGround === true || playerLike?.on_ground === true;
  const shadow = jumpEnabled ? ensurePrivatePlayerJumpShadow(mesh) : (mesh.userData.privateWorldJumpShadow ?? null);
  if (!shadow) {
    return;
  }
  shadow.visible = jumpEnabled && mesh.visible !== false;
  if (!jumpEnabled) {
    return;
  }
  const resolvedScale = Math.max(0.25, Number(playerLike?.scale ?? mesh.scale.x ?? 1) || 1);
  const playerPosition = {
    x: Number(playerLike?.position?.x ?? mesh.position.x ?? 0) || 0,
    y: Number(playerLike?.position?.y ?? mesh.position.y ?? 0) || 0,
    z: Number(playerLike?.position?.z ?? mesh.position.z ?? 0) || 0,
  };
  const playerHalf = getHalfExtentsFromScale(getPrivatePlayerCollisionSize(resolvedScale));
  const surface = getPrivatePlayerProjectedShadowSurface({
    ...playerLike,
    position: playerPosition,
    scale: resolvedScale,
  });
  let surfaceY = Number(surface?.surfaceY);
  if (Number.isFinite(surfaceY)) {
    mesh.userData.privateWorldJumpShadowSurfaceY = surfaceY;
    mesh.userData.privateWorldJumpShadowSurfaceX = playerPosition.x;
    mesh.userData.privateWorldJumpShadowSurfaceZ = playerPosition.z;
  } else {
    const cachedSurfaceY = Number(mesh.userData.privateWorldJumpShadowSurfaceY);
    const cachedSurfaceX = Number(mesh.userData.privateWorldJumpShadowSurfaceX);
    const cachedSurfaceZ = Number(mesh.userData.privateWorldJumpShadowSurfaceZ);
    const cachedHorizontalDistance = Number.isFinite(cachedSurfaceX) && Number.isFinite(cachedSurfaceZ)
      ? Math.hypot(playerPosition.x - cachedSurfaceX, playerPosition.z - cachedSurfaceZ)
      : Number.POSITIVE_INFINITY;
    const cachedReuseDistance = Math.max(
      PRIVATE_WORLD_BLOCK_UNIT * 1.5,
      playerHalf.x * 2,
      playerHalf.z * 2,
    );
    if (
      mesh.userData.privateWorldPlayerOnGround !== true
      && Number.isFinite(cachedSurfaceY)
      && cachedHorizontalDistance <= cachedReuseDistance
    ) {
      surfaceY = cachedSurfaceY;
    } else {
      const groundCenterY = Number(playerLike?.groundY);
      const fallbackGroundSurfaceY = Number.isFinite(groundCenterY)
        ? groundCenterY - playerHalf.y
        : Number.NaN;
      if (mesh.userData.privateWorldPlayerOnGround !== true && Number.isFinite(fallbackGroundSurfaceY)) {
        surfaceY = fallbackGroundSurfaceY;
      }
    }
  }
  if (!Number.isFinite(surfaceY)) {
    shadow.visible = false;
    return;
  }
  const playerBottom = playerPosition.y - playerHalf.y;
  const shadowDistance = Math.max(0, playerBottom - surfaceY);
  const heightRatio = Math.min(1, shadowDistance / Math.max(0.0001, PRIVATE_WORLD_BLOCK_UNIT * 2.5));
  shadow.position.y = (surfaceY - playerPosition.y) / resolvedScale + (0.03 / resolvedScale);
  shadow.scale.set(1.36 + heightRatio * 0.08, 0.9 + heightRatio * 0.05, 1);
  if (shadow.material) {
    shadow.material.opacity = PRIVATE_PLAYER_JUMP_SHADOW.opacity * (1 - heightRatio * 0.32);
  }
}

function isEmojiOnlyPrivateChatText(value) {
  return sharedIsEmojiOnlyChatText(value);
}

function createPrivateActorBubbleState(color, options = {}) {
  return createChatBubbleState({
    accent: color,
    anchorY: Number(options.anchorY ?? PRIVATE_CHAT_BUBBLE.anchorY) || PRIVATE_CHAT_BUBBLE.anchorY,
    baseWidth: PRIVATE_CHAT_BUBBLE.baseWidth,
    baseHeight: PRIVATE_CHAT_BUBBLE.baseHeight,
    stroke: PRIVATE_WORLD_STYLE.outline,
    createTexture: createBubbleTexture,
    createBillboard: createPrivateBillboard,
    persistent: options.persistent === true,
  });
}

function orientPrivateBillboardToCamera(mesh, camera) {
  if (!mesh || !camera) {
    return;
  }
  const parent = mesh.parent;
  if (!parent) {
    mesh.quaternion.copy(camera.quaternion);
    return;
  }
  parent.updateWorldMatrix(true, false);
  camera.updateWorldMatrix(true, false);
  parent.getWorldQuaternion(privateBillboardParentQuaternion);
  camera.getWorldQuaternion(privateBillboardCameraQuaternion);
  privateBillboardParentQuaternion.invert();
  mesh.quaternion.copy(privateBillboardParentQuaternion.multiply(privateBillboardCameraQuaternion));
}

const privateChatBubbleRenderer = createChatBubbleRenderer({
  baseWidth: PRIVATE_CHAT_BUBBLE.baseWidth,
  baseHeight: PRIVATE_CHAT_BUBBLE.baseHeight,
  minWidth: PRIVATE_CHAT_BUBBLE.minWidth,
  minHeight: PRIVATE_CHAT_BUBBLE.minHeight,
  maxTextureWidth: PRIVATE_CHAT_BUBBLE.textureMaxWidth,
  maxTextureHeight: PRIVATE_CHAT_BUBBLE.textureMaxHeight,
  maxLines: PRIVATE_CHAT_BUBBLE.maxLines,
  stroke: PRIVATE_WORLD_STYLE.outline,
  getDefaultAccent: () => PRIVATE_WORLD_STYLE.accents[1],
  createTexture: createBubbleTexture,
  createBillboard: createPrivateBillboard,
  getGhostState: () => ({
    root: state.preview?.chatBubbleGhosts ?? null,
    entries: state.preview?.animatedChatBubbleGhosts ?? null,
  }),
  isEmojiOnly: isEmojiOnlyPrivateChatText,
  clampSize: clampNumber,
  orientToCamera: orientPrivateBillboardToCamera,
});

function removePrivateChatBubbleGhost(preview, entry) {
  const activePreview = preview ?? state.preview;
  if (!activePreview?.animatedChatBubbleGhosts || !entry?.mesh) {
    return;
  }
  if (entry.mesh.parent) {
    entry.mesh.parent.remove(entry.mesh);
  }
  entry.mesh.geometry?.dispose?.();
  entry.mesh.material?.map?.dispose?.();
  entry.mesh.material?.dispose?.();
  const index = activePreview.animatedChatBubbleGhosts.indexOf(entry);
  if (index >= 0) {
    activePreview.animatedChatBubbleGhosts.splice(index, 1);
  }
}

function applyPrivateChatBubbleToActor(actorEntry, chatEvent) {
  privateChatBubbleRenderer.apply(actorEntry, chatEvent);
}

function updatePrivateActorBubble(actorEntry, deltaSeconds, camera = state.preview?.camera) {
  privateChatBubbleRenderer.update(actorEntry, deltaSeconds, { camera });
}

function pruneExpiredPrivateChatEvents() {
  const now = Date.now();
  for (const [presenceId, event] of state.activeChats.entries()) {
    if (Date.parse(event.expiresAt ?? 0) > now) {
      continue;
    }
    state.activeChats.delete(presenceId);
    const presenceEntry = state.preview?.presenceEntries?.get(presenceId);
    if (presenceEntry?.bubble) {
      presenceEntry.bubble.targetOpacity = 0;
    }
    if (presenceId === getPrivateViewerSessionId() && state.preview?.viewerAvatar?.bubble) {
      state.preview.viewerAvatar.bubble.targetOpacity = 0;
    }
  }
}

function getPrivatePresenceEntryId(entry = {}) {
  return String(entry.viewer_session_id ?? entry.viewerSessionId ?? entry.id ?? "").trim();
}

function getPrivatePresenceDisplayName(entry = {}) {
  const actor = entry.actor ?? {};
  const actorName = String(actor.display_name ?? actor.displayName ?? "").trim();
  if (actorName) {
    return actorName;
  }
  const movementName = String(entry.movement_state?.displayName ?? entry.movement_state?.display_name ?? "").trim();
  if (movementName) {
    return movementName;
  }
  return "viewer";
}

function getPrivateDisplayNameForSessionId(viewerSessionId = "") {
  const normalized = String(viewerSessionId ?? "").trim();
  if (!normalized) {
    return "";
  }
  if (normalized === getPrivateViewerSessionId()) {
    return getPrivateDisplayName();
  }
  const presenceEntry = state.livePresence.get(normalized);
  if (presenceEntry) {
    return getPrivatePresenceDisplayName(presenceEntry);
  }
  return "viewer";
}

function buildPrivatePresenceObject(entry) {
  const presenceId = getPrivatePresenceEntryId(entry);
  const displayName = getPrivatePresenceDisplayName(entry);
  const seed = hashPrivateString(presenceId || displayName);
  const accents = PRIVATE_WORLD_STYLE.accents;
  const primary = accents[seed % accents.length];
  const secondary = accents[(seed + 2) % accents.length];
  const tertiary = accents[(seed + 4) % accents.length];
  const figure = createViewerAvatarFigure({
    scale: 0.72,
    outlineColor: primary,
    primary,
    secondary,
    tertiary,
  });
  figure.group.position.set(
    Number(entry.position_x ?? 0) || 0,
    Number(entry.position_y ?? PRIVATE_CAMERA.minY) || PRIVATE_CAMERA.minY,
    Number(entry.position_z ?? 0) || 0,
  );
  const bubble = createPrivateActorBubbleState(primary);
  figure.group.add(bubble.mesh);
  return {
    id: presenceId,
    group: figure.group,
    shadow: figure.shadow,
    halo: figure.halo,
    orb: figure.orb,
    orbBaseY: figure.orb.position.y,
    baseY: Number(entry.position_y ?? PRIVATE_CAMERA.minY) || PRIVATE_CAMERA.minY,
    position: new THREE.Vector3(
      Number(entry.position_x ?? 0) || 0,
      Number(entry.position_y ?? PRIVATE_CAMERA.minY) || PRIVATE_CAMERA.minY,
      Number(entry.position_z ?? 0) || 0,
    ),
    targetPosition: new THREE.Vector3(
      Number(entry.position_x ?? 0) || 0,
      Number(entry.position_y ?? PRIVATE_CAMERA.minY) || PRIVATE_CAMERA.minY,
      Number(entry.position_z ?? 0) || 0,
    ),
    displayName,
    bob: 0.55 + Math.random() * 0.35,
    phase: Math.random() * Math.PI * 2,
    bubble,
    bubbleAccent: primary,
  };
}

function getPrivateBrowserHostPosition(hostSessionId = "") {
  const normalized = String(hostSessionId ?? "").trim();
  if (!normalized) {
    return null;
  }
  const getPlayerAnchorPosition = (playerEntityId = "") => {
    const playerId = resolvePrivatePlayerEntityId(playerEntityId, getRuntimePlayerIds()) ?? String(playerEntityId ?? "").trim();
    if (!playerId) {
      return null;
    }
    const renderedPosition = state.preview?.entityMeshes?.get(playerId)?.position ?? null;
    if (renderedPosition) {
      return renderedPosition;
    }
    const runtimePlayer = state.runtimeSnapshot?.players?.find((entry) => entry.id === playerId) ?? null;
    if (!runtimePlayer?.position) {
      return null;
    }
    return new THREE.Vector3(
      Number(runtimePlayer.position.x ?? 0) || 0,
      Number(runtimePlayer.position.y ?? PRIVATE_CAMERA.minY) || PRIVATE_CAMERA.minY,
      Number(runtimePlayer.position.z ?? 0) || 0,
    );
  };
  const participants = state.selectedWorld?.active_instance?.participants ?? [];
  const getParticipantByViewerSessionId = (viewerSessionId = "") => {
    const identity = parsePrivateViewerSessionId(viewerSessionId);
    if (!identity.subjectId) {
      return null;
    }
    if (identity.kind === "profile") {
      const profileId = identity.subjectId;
      return participants.find((entry) => String(entry.profile?.id ?? entry.profile_id ?? "").trim() === profileId) ?? null;
    }
    return participants.find(
      (entry) => String(entry.guest_session_id ?? entry.guestSessionId ?? "").trim() === identity.subjectId,
    ) ?? null;
  };
  if (normalized === getPrivateViewerSessionId()) {
    const localAvatarPosition = state.preview?.viewerAvatar?.group?.visible !== false
      ? state.preview?.viewerAvatar?.group?.position ?? null
      : null;
    if (localAvatarPosition) {
      return localAvatarPosition;
    }
    const localParticipant = getLocalParticipant();
    const occupiedPlayerPosition = getPlayerAnchorPosition(localParticipant?.player_entity_id);
    if (occupiedPlayerPosition) {
      return occupiedPlayerPosition;
    }
    const localPresencePosition = getPrivatePresencePosition();
    return state.preview?.viewerAvatar?.group?.position
      ?? new THREE.Vector3(localPresencePosition.x, localPresencePosition.y, localPresencePosition.z);
  }
  const renderedPresenceEntry = state.preview?.presenceEntries?.get(normalized) ?? null;
  const renderedPosition = renderedPresenceEntry?.group?.position ?? null;
  if (renderedPosition && renderedPresenceEntry.group.visible !== false) {
    return renderedPosition;
  }
  const entry = state.livePresence.get(normalized);
  if (entry) {
    return new THREE.Vector3(
      Number(entry.position_x ?? 0) || 0,
      Number(entry.position_y ?? PRIVATE_CAMERA.minY) || PRIVATE_CAMERA.minY,
      Number(entry.position_z ?? 0) || 0,
    );
  }
  const occupiedPlayerPosition = getPlayerAnchorPosition(getParticipantByViewerSessionId(normalized)?.player_entity_id);
  if (occupiedPlayerPosition) {
    return occupiedPlayerPosition;
  }
  return null;
}

function getPrivateBrowserHostAnchorGroup(hostSessionId = "") {
  const normalized = String(hostSessionId ?? "").trim();
  if (!normalized) {
    return null;
  }
  if (normalized === getPrivateViewerSessionId()) {
    const localGroup = state.preview?.viewerAvatar?.group ?? null;
    return localGroup?.visible !== false ? localGroup : null;
  }
  const presenceGroup = state.preview?.presenceEntries?.get(normalized)?.group ?? null;
  return presenceGroup?.visible !== false ? presenceGroup : null;
}

function setPrivateShareBubbleParent(entry, parent = null) {
  const nextParent = parent ?? state.preview?.browserShares ?? null;
  if (!entry?.group || !nextParent || entry.group.parent === nextParent) {
    return;
  }
  nextParent.add(entry.group);
}

function getPrivateBrowserSessionShareKind(session = {}) {
  return normalizeBrowserShareKind(session?.shareKind, session?.sessionMode === "remote-browser" ? "browser" : "screen");
}

function getPrivateBrowserPlaceholderBadge(session = {}) {
  if (
    !session
    || String(session.hostSessionId ?? "").trim() === getPrivateViewerSessionId()
    || session.deliveryMode !== "placeholder"
  ) {
    return "";
  }
  const maxViewers = getPrivateBrowserSessionMaxViewers(session);
  const viewerCount = getPrivateBrowserSessionViewerCount(session);
  if (viewerCount < maxViewers) {
    return "";
  }
  const spatialCenter = getPrivateBrowserSpatialCenter(session);
  if (!spatialCenter) {
    return "";
  }
  const listenerPosition = getPrivatePresencePosition();
  const planarDistance = Math.hypot(
    listenerPosition.x - spatialCenter.x,
    listenerPosition.z - spatialCenter.z,
  );
  if (planarDistance > Math.max(16, PRIVATE_BROWSER_RADIUS)) {
    return "";
  }
  return "FULL";
}

function computePrivateRemoteBrowserAudioVolume(session) {
  if (!session || session.hostSessionId === getPrivateViewerSessionId() || session.deliveryMode !== "full") {
    return 0;
  }
  const spatialCenter = getPrivateBrowserSpatialCenter(session);
  if (!spatialCenter) {
    return 0;
  }
  const listenerPosition = getPrivatePresencePosition();
  const planarDistance = Math.hypot(
    listenerPosition.x - spatialCenter.x,
    listenerPosition.z - spatialCenter.z,
  );
  const maxDistance = Math.max(16, PRIVATE_BROWSER_RADIUS);
  const fullVolumeDistance = Math.min(8, Math.max(5, maxDistance * 0.08));
  if (planarDistance <= fullVolumeDistance) {
    return 1;
  }
  if (planarDistance >= maxDistance) {
    return 0;
  }
  const t = clampNumber(
    (planarDistance - fullVolumeDistance) / Math.max(1, maxDistance - fullVolumeDistance),
    0,
    0,
    1,
  );
  const gain = Math.pow(1 - t, 3.5);
  return gain < 0.02 ? 0 : gain;
}

function updatePrivateRemoteBrowserAudioMix() {
  if (!state.browserMediaController) {
    return;
  }
  for (const session of state.browserSessions.values()) {
    if (session.hostSessionId === getPrivateViewerSessionId()) {
      continue;
    }
    state.browserMediaController.setRemoteAudioVolume({
      sessionId: session.sessionId,
      volume: computePrivateRemoteBrowserAudioVolume(session),
    });
  }
}

function getPrivateBrowserPlaceholderTextureKey(session = {}) {
  return [
    getPrivateBrowserSessionShareKind(session),
    String(session?.deliveryMode ?? "placeholder"),
    String(getPrivateBrowserPlaceholderBadge(session)),
  ].join(":");
}

function createPrivateShareBubbleTexture(session = {}) {
  const shareKind = getPrivateBrowserSessionShareKind(session);
  const badge = getPrivateBrowserPlaceholderBadge(session);
  const accent = shareKind === "audio"
    ? PRIVATE_WORLD_STYLE.accents[3]
    : shareKind === "camera"
      ? PRIVATE_WORLD_STYLE.accents[0]
      : PRIVATE_WORLD_STYLE.accents[1];
  const symbol = shareKind === "audio"
    ? "📞"
    : shareKind === "camera"
      ? "🤩"
      : "📺";
  return createBubbleTexture(symbol, {
    accent,
    stroke: PRIVATE_WORLD_STYLE.outline,
    badge,
    badgeBackground: badge ? "rgba(255, 79, 168, 0.92)" : undefined,
    badgeStroke: badge ? "rgba(255, 255, 255, 0.26)" : undefined,
  });
}

function updatePrivateShareBubbleGeometry(entry) {
  if (!entry?.frame || !entry?.frameShell) {
    return;
  }
  const aspectRatio = Number(entry.session?.aspectRatio) || PRIVATE_BROWSER_SHARE.aspectRatio;
  const width = getSharedNearbyMediaWidth({
    shareKind: getPrivateBrowserSessionShareKind(entry.session),
    sessionSlot: entry.session?.sessionSlot,
  });
  if (
    Math.abs((entry.geometryAspectRatio ?? 0) - aspectRatio) < 0.01
    && Math.abs((entry.geometryWidth ?? 0) - width) < 0.01
  ) {
    return;
  }
  const height = width / Math.max(0.1, aspectRatio);
  entry.frame.geometry.dispose();
  entry.frame.geometry = new THREE.PlaneGeometry(width, height);
  entry.frameShell.geometry.dispose();
  entry.frameShell.geometry = new THREE.PlaneGeometry(width + 1.2, height + 1.2);
  entry.geometryAspectRatio = aspectRatio;
  entry.geometryWidth = width;
}

function updatePrivateShareBubbleAspectFromVideo(entry, videoElement) {
  if (!entry || !videoElement) {
    return;
  }
  const applyAspect = () => {
    const width = Math.max(0, Math.floor(Number(videoElement.videoWidth) || 0));
    const height = Math.max(0, Math.floor(Number(videoElement.videoHeight) || 0));
    if (!width || !height) {
      return;
    }
    const nextAspectRatio = width / Math.max(1, height);
    if (Math.abs(nextAspectRatio - (Number(entry.session?.aspectRatio) || 0)) < 0.01) {
      return;
    }
    entry.session = {
      ...entry.session,
      aspectRatio: nextAspectRatio,
    };
    updatePrivateShareBubbleGeometry(entry);
  };
  if (videoElement.videoWidth && videoElement.videoHeight) {
    applyAspect();
    return;
  }
  videoElement.addEventListener("loadedmetadata", applyAspect, { once: true });
}

function isPrivateShareBubbleShowingLiveMedia(entry) {
  return Boolean(entry?.deliveryMode === "full" && (entry.videoTexture || entry.currentFrameId > 0));
}

function updatePrivateShareBubblePresentation(entry) {
  if (!entry?.frame) {
    return;
  }
  const nextPlaceholderKey = getPrivateBrowserPlaceholderTextureKey(entry.session);
  if (entry.placeholderKey !== nextPlaceholderKey) {
    entry.placeholderTexture?.dispose?.();
    entry.placeholderTexture = createPrivateShareBubbleTexture(entry.session);
    entry.placeholderKey = nextPlaceholderKey;
  }
  const hasRemoteVideo = entry.deliveryMode === "full" && entry.videoTexture;
  const hasLiveFrame = entry.deliveryMode === "full" && entry.currentFrameId > 0;
  const desiredMap = hasRemoteVideo
    ? entry.videoTexture
    : hasLiveFrame
      ? entry.liveTexture
      : entry.placeholderTexture;
  const showingPlaceholder = desiredMap === entry.placeholderTexture;
  const shareKind = getPrivateBrowserSessionShareKind(entry.session);
  const aspectRatio = Number(entry.session?.aspectRatio) || PRIVATE_BROWSER_SHARE.aspectRatio;
  const baseWidth = getSharedNearbyMediaWidth({
    shareKind,
    sessionSlot: entry.session?.sessionSlot,
  });
  const baseHeight = baseWidth / Math.max(0.1, aspectRatio);
  const bubbleWidth = shareKind === "audio"
    ? PRIVATE_BROWSER_SHARE.placeholderAudioWidth
    : PRIVATE_BROWSER_SHARE.placeholderVideoWidth;
  const bubbleHeight = bubbleWidth / PRIVATE_BROWSER_SHARE.placeholderAspectRatio;
  const scaleX = showingPlaceholder ? bubbleWidth / baseWidth : 1;
  const scaleY = showingPlaceholder ? bubbleHeight / Math.max(0.1, baseHeight) : 1;
  entry.frame.scale.set(scaleX, scaleY, 1);
  entry.frame.position.set(0, 0, 0);
  entry.frame.material.depthTest = false;
  entry.frame.material.opacity = showingPlaceholder ? 0.96 : 1;
  entry.frame.renderOrder = showingPlaceholder ? 11 : 10;
  entry.frameShell.visible = !showingPlaceholder;
  if (entry.frameShell.material) {
    entry.frameShell.material.opacity = showingPlaceholder ? 0 : 0.92;
  }
  if (entry.frame.material.map !== desiredMap) {
    entry.frame.material.map = desiredMap;
    entry.frame.material.needsUpdate = true;
  }
  entry.frame.material.needsUpdate = true;
}

function setPrivateShareBubbleVideo(sessionId, videoElement) {
  const preview = state.preview;
  if (!preview?.browserShareEntries) {
    return;
  }
  const entry = preview.browserShareEntries.get(sessionId);
  if (!entry || !videoElement) {
    return;
  }
  if (entry.videoElement === videoElement && entry.videoTexture) {
    updatePrivateShareBubblePresentation(entry);
    return;
  }
  clearPrivateShareBubbleVideo(sessionId);
  entry.videoElement = videoElement;
  entry.videoTexture = new THREE.VideoTexture(videoElement);
  entry.videoTexture.colorSpace = THREE.SRGBColorSpace;
  entry.videoTexture.generateMipmaps = false;
  entry.videoTexture.minFilter = THREE.LinearFilter;
  entry.videoTexture.magFilter = THREE.LinearFilter;
  updatePrivateShareBubbleAspectFromVideo(entry, videoElement);
  updatePrivateShareBubblePresentation(entry);
}

function clearPrivateShareBubbleVideo(sessionId) {
  const preview = state.preview;
  if (!preview?.browserShareEntries) {
    return;
  }
  const entry = preview.browserShareEntries.get(sessionId);
  if (!entry) {
    return;
  }
  entry.videoTexture?.dispose?.();
  entry.videoTexture = null;
  if (entry.videoElement && entry.videoElement !== elements.panelBrowserVideo) {
    entry.videoElement.remove?.();
  }
  entry.videoElement = null;
  updatePrivateShareBubblePresentation(entry);
}

function updatePrivateShareBubbleFrame(sessionId, frame) {
  const preview = state.preview;
  if (!preview?.browserShareEntries) {
    return;
  }
  const entry = preview.browserShareEntries.get(sessionId);
  if (!entry || !frame?.dataUrl || Number(frame.frameId ?? 0) <= entry.currentFrameId) {
    return;
  }
  entry.currentFrameId = Number(frame.frameId ?? 0);
  entry.liveImage.src = frame.dataUrl;
  updatePrivateShareBubblePresentation(entry);
}

function removePrivateShareBubbleEntry(sessionId) {
  const preview = state.preview;
  const entry = preview?.browserShareEntries?.get(sessionId);
  if (!entry) {
    return;
  }
  clearPrivateShareBubbleVideo(sessionId);
  preview.browserShareEntries.delete(sessionId);
  entry.group.parent?.remove(entry.group);
  entry.liveTexture?.dispose?.();
  entry.placeholderTexture?.dispose?.();
  entry.frame.geometry?.dispose?.();
  entry.frameShell.geometry?.dispose?.();
  entry.frame.material?.dispose?.();
  entry.frameShell.material?.dispose?.();
}

function ensurePrivateShareBubbleEntry(session = {}) {
  const preview = state.preview;
  if (!preview?.browserShares) {
    return null;
  }
  const sessionId = String(session.sessionId ?? "").trim();
  if (!sessionId) {
    return null;
  }
  const existing = preview.browserShareEntries.get(sessionId);
  if (existing) {
    existing.session = { ...existing.session, ...session };
    existing.hostSessionId = String(session.hostSessionId ?? existing.hostSessionId ?? "").trim();
    updatePrivateShareBubbleGeometry(existing);
    return existing;
  }

  const aspectRatio = Number(session.aspectRatio) || PRIVATE_BROWSER_SHARE.aspectRatio;
  const width = getSharedNearbyMediaWidth({
    shareKind: getPrivateBrowserSessionShareKind(session),
    sessionSlot: session?.sessionSlot,
  });
  const height = width / Math.max(0.1, aspectRatio);
  const group = new THREE.Group();
  const frameShell = new THREE.Mesh(
    new THREE.PlaneGeometry(width + 1.2, height + 1.2),
    new THREE.MeshBasicMaterial({
      color: new THREE.Color("#0d1537"),
      transparent: true,
      opacity: 0.92,
      depthWrite: false,
      fog: false,
    }),
  );
  frameShell.renderOrder = 9;
  group.add(frameShell);

  const liveImage = new Image();
  const liveTexture = new THREE.Texture(liveImage);
  liveTexture.colorSpace = THREE.SRGBColorSpace;
  liveImage.addEventListener("load", () => {
    liveTexture.needsUpdate = true;
  });
  const placeholderTexture = createPrivateShareBubbleTexture(session);
  const frame = createPrivateBillboard(placeholderTexture, width, height, {
    opacity: 1,
    fog: false,
    depthTest: false,
    renderOrder: 10,
    persistent: true,
  });
  frame.frustumCulled = false;
  frameShell.frustumCulled = false;
  group.add(frame);
  preview.browserShares.add(group);
  const entry = {
    sessionId,
    hostSessionId: String(session.hostSessionId ?? "").trim(),
    session,
    group,
    frameShell,
    frame,
    liveImage,
    liveTexture,
    placeholderTexture,
    placeholderKey: getPrivateBrowserPlaceholderTextureKey(session),
    videoElement: null,
    videoTexture: null,
    position: new THREE.Vector3(),
    targetPosition: new THREE.Vector3(),
    currentFrameId: 0,
    deliveryMode: String(session.deliveryMode ?? "placeholder"),
    geometryAspectRatio: aspectRatio,
    geometryWidth: width,
  };
  preview.browserShareEntries.set(sessionId, entry);
  updatePrivateShareBubblePresentation(entry);
  return entry;
}

function getPrivateLocalPreviewBubbleSession() {
  const localPreviewShare = state.localBrowserShare?.hasVideo
    ? state.localBrowserShare
    : state.pendingBrowserShare?.hasVideo
      ? state.pendingBrowserShare
      : null;
  if (!localPreviewShare || !elements.panelBrowserVideo?.srcObject) {
    return null;
  }
  const realSessionId = String(state.localBrowserSessionId ?? "").trim();
  if (realSessionId && state.browserSessions.has(realSessionId)) {
    return null;
  }
  return {
    sessionId: realSessionId || PRIVATE_LOCAL_PREVIEW_SESSION_ID,
    hostSessionId: getPrivateViewerSessionId(),
    title: String(localPreviewShare.title ?? "").trim() || "Live share",
    shareKind: localPreviewShare.shareKind || "screen",
    hasVideo: true,
    hasAudio: localPreviewShare.hasAudio === true,
    aspectRatio: Number(localPreviewShare.aspectRatio) || PRIVATE_BROWSER_SHARE.aspectRatio,
    sessionMode: "display-share",
    frameTransport: "local-preview",
    deliveryMode: "full",
    _syntheticLocalPreview: true,
  };
}

function getPrivateShareBubbleSessions() {
  const sessions = [...state.browserSessions.values()];
  const localPreviewSession = getPrivateLocalPreviewBubbleSession();
  if (localPreviewSession) {
    sessions.push(localPreviewSession);
  }
  return sessions;
}

function reconcilePrivateShareBubbles() {
  const preview = state.preview;
  if (!preview?.browserShareEntries) {
    return;
  }
  const bubbleSessions = getPrivateShareBubbleSessions();
  const activeIds = new Set(bubbleSessions.map((session) => String(session.sessionId ?? "").trim()).filter(Boolean));
  for (const sessionId of [...preview.browserShareEntries.keys()]) {
    if (!activeIds.has(sessionId)) {
      removePrivateShareBubbleEntry(sessionId);
    }
  }
  for (const session of bubbleSessions) {
    const entry = ensurePrivateShareBubbleEntry(session);
    if (!entry) {
      continue;
    }
    entry.deliveryMode = session.deliveryMode ?? "placeholder";
    entry.session = session;
    entry.hostSessionId = String(session.hostSessionId ?? entry.hostSessionId ?? "").trim();
    updatePrivateShareBubbleGeometry(entry);
    if (session.hasVideo === false) {
      clearPrivateShareBubbleVideo(session.sessionId);
    }
    if (session._remoteElement) {
      setPrivateShareBubbleVideo(session.sessionId, session._remoteElement);
    } else if (
      session.hostSessionId === getPrivateViewerSessionId()
      && elements.panelBrowserVideo
      && elements.panelBrowserVideo.srcObject
    ) {
      setPrivateShareBubbleVideo(session.sessionId, elements.panelBrowserVideo);
    }
    updatePrivateShareBubblePresentation(entry);
  }
}

function getPrivateGameBubbleAspectRatio(session = {}) {
  const previewFrame = session?.latest_preview ?? null;
  if (previewFrame?.width && previewFrame?.height) {
    return Math.max(0.6, Math.min(2.4, Number(previewFrame.width) / Math.max(1, Number(previewFrame.height))));
  }
  return Math.max(0.6, Math.min(2.4, Number(session?.game?.manifest?.aspect_ratio) || PRIVATE_BROWSER_SHARE.aspectRatio));
}

function getPrivateGameBubblePlaceholderKey(session = {}) {
  const occupiedSeats = normalizePrivateGameSeats(session).filter((seat) => seat.viewer_session_id).length;
  return [
    getPrivateGameSessionTitle(session),
    getPrivateGameSessionDescription(session),
    String(session?.started === true),
    `${occupiedSeats}/${getPrivateGameSeatCapacity(session)}`,
  ].join(":");
}

function createPrivateGameBubbleTexture(session = {}) {
  return createBubbleTexture("🎮", {
    accent: PRIVATE_WORLD_STYLE.accents[1],
    stroke: PRIVATE_WORLD_STYLE.outline,
  });
}

function updatePrivateGameBubbleGeometry(entry) {
  if (!entry?.frame || !entry?.frameShell) {
    return;
  }
  const aspectRatio = getPrivateGameBubbleAspectRatio(entry.session);
  const width = getSharedNearbyMediaWidth({ shareKind: "game" });
  if (
    Math.abs((entry.geometryAspectRatio ?? 0) - aspectRatio) < 0.01
    && Math.abs((entry.geometryWidth ?? 0) - width) < 0.01
  ) {
    return;
  }
  const height = width / Math.max(0.1, aspectRatio);
  entry.frame.geometry.dispose();
  entry.frame.geometry = new THREE.PlaneGeometry(width, height);
  entry.frameShell.geometry.dispose();
  entry.frameShell.geometry = new THREE.PlaneGeometry(width + 1.2, height + 1.2);
  if (entry.hitTarget?.geometry) {
    entry.hitTarget.geometry.dispose();
    entry.hitTarget.geometry = new THREE.PlaneGeometry(
      width + PRIVATE_GAME_SHARE_HIT_PADDING,
      height + PRIVATE_GAME_SHARE_HIT_PADDING,
    );
  }
  entry.geometryAspectRatio = aspectRatio;
  entry.geometryWidth = width;
}

function removePrivateGameBubbleEntry(sessionId = "") {
  const preview = state.preview;
  const entry = preview?.gameShareEntries?.get(String(sessionId ?? "").trim());
  if (!entry) {
    return;
  }
  clearPrivateGameShareVideo(entry.sessionId);
  entry.localCanvasTexture?.dispose?.();
  preview.gameShareEntries.delete(entry.sessionId);
  preview.entityPickables = preview.entityPickables.filter((mesh) => mesh !== entry.frame && mesh !== entry.hitTarget);
  entry.group.parent?.remove(entry.group);
  entry.liveTexture?.dispose?.();
  entry.placeholderTexture?.dispose?.();
  entry.frame.geometry?.dispose?.();
  entry.frameShell.geometry?.dispose?.();
  entry.hitTarget?.geometry?.dispose?.();
  entry.frame.material?.dispose?.();
  entry.frameShell.material?.dispose?.();
  entry.hitTarget?.material?.dispose?.();
}

function ensurePrivateGameBubbleEntry(session = {}) {
  const preview = state.preview;
  if (!preview?.gameShares) {
    return null;
  }
  const sessionId = String(session.session_id ?? "").trim();
  if (!sessionId) {
    return null;
  }
  const existing = preview.gameShareEntries.get(sessionId);
  if (existing) {
    existing.session = { ...existing.session, ...session };
    existing.hostSessionId = String(session.host_viewer_session_id ?? existing.hostSessionId ?? "").trim();
    updatePrivateGameBubbleGeometry(existing);
    return existing;
  }
  const aspectRatio = getPrivateGameBubbleAspectRatio(session);
  const width = getSharedNearbyMediaWidth({ shareKind: "game" });
  const height = width / aspectRatio;
  const group = new THREE.Group();
  const frameShell = new THREE.Mesh(
    new THREE.PlaneGeometry(width + 1.2, height + 1.2),
    new THREE.MeshBasicMaterial({
      color: new THREE.Color("#0d1537"),
      transparent: true,
      opacity: 0.92,
      depthWrite: false,
      fog: false,
    }),
  );
  frameShell.renderOrder = 9;
  group.add(frameShell);
  const liveImage = new Image();
  const liveTexture = new THREE.Texture(liveImage);
  liveTexture.colorSpace = THREE.SRGBColorSpace;
  liveImage.addEventListener("load", () => {
    liveTexture.needsUpdate = true;
  });
  const placeholderTexture = createPrivateGameBubbleTexture(session);
  const frame = createPrivateBillboard(placeholderTexture, width, height, {
    opacity: 1,
    fog: false,
    depthTest: false,
    renderOrder: 10,
    persistent: true,
  });
  frame.frustumCulled = false;
  frame.userData.privateWorldGameSessionId = sessionId;
  frame.userData.privateWorldPickPriority = PRIVATE_GAME_SHARE_PICK_PRIORITY;
  group.add(frame);
  const hitTarget = new THREE.Mesh(
    new THREE.PlaneGeometry(width + PRIVATE_GAME_SHARE_HIT_PADDING, height + PRIVATE_GAME_SHARE_HIT_PADDING),
    new THREE.MeshBasicMaterial({
      color: new THREE.Color("#ffffff"),
      transparent: true,
      opacity: PRIVATE_GAME_SHARE_HIT_PROXY_OPACITY,
      side: THREE.DoubleSide,
      depthTest: false,
      depthWrite: false,
      fog: false,
    }),
  );
  hitTarget.renderOrder = 11;
  hitTarget.frustumCulled = false;
  hitTarget.userData.privateWorldGameSessionId = sessionId;
  hitTarget.userData.privateWorldPickPriority = PRIVATE_GAME_SHARE_PICK_PRIORITY;
  group.add(hitTarget);
  preview.entityPickables.push(hitTarget, frame);
  preview.gameShares.add(group);
  const entry = {
    sessionId,
    hostSessionId: String(session.host_viewer_session_id ?? "").trim(),
    session,
    group,
    frameShell,
    frame,
    hitTarget,
    liveImage,
    liveTexture,
    videoElement: null,
    videoTexture: null,
    localCanvas: null,
    localCanvasTexture: null,
    localCanvasWidth: 0,
    localCanvasHeight: 0,
    placeholderTexture,
    position: new THREE.Vector3(),
    targetPosition: new THREE.Vector3(),
    currentPreviewAt: "",
    geometryAspectRatio: aspectRatio,
    geometryWidth: width,
    placeholderKey: getPrivateGameBubblePlaceholderKey(session),
  };
  preview.gameShareEntries.set(sessionId, entry);
  return entry;
}

function setPrivateGameShareVideo(sessionId, videoElement) {
  const preview = state.preview;
  const entry = preview?.gameShareEntries?.get(String(sessionId ?? "").trim());
  if (!entry || !videoElement) {
    return;
  }
  if (entry.videoElement === videoElement && entry.videoTexture) {
    updatePrivateGameBubblePresentation(entry);
    return;
  }
  clearPrivateGameShareVideo(sessionId);
  entry.videoElement = videoElement;
  entry.videoTexture = new THREE.VideoTexture(videoElement);
  entry.videoTexture.colorSpace = THREE.SRGBColorSpace;
  entry.videoTexture.generateMipmaps = false;
  entry.videoTexture.minFilter = THREE.LinearFilter;
  entry.videoTexture.magFilter = THREE.LinearFilter;
  updatePrivateGameBubblePresentation(entry);
}

function clearPrivateGameShareVideo(sessionId) {
  const preview = state.preview;
  const entry = preview?.gameShareEntries?.get(String(sessionId ?? "").trim());
  if (!entry) {
    return;
  }
  entry.videoTexture?.dispose?.();
  entry.videoTexture = null;
  entry.videoElement = null;
  updatePrivateGameBubblePresentation(entry);
}

function updatePrivateGameBubblePresentation(entry) {
  if (!entry?.frame) {
    return;
  }
  updatePrivateGameBubbleGeometry(entry);
  const nextPlaceholderKey = getPrivateGameBubblePlaceholderKey(entry.session);
  if (entry.placeholderKey !== nextPlaceholderKey) {
    entry.placeholderTexture?.dispose?.();
    entry.placeholderTexture = createPrivateGameBubbleTexture(entry.session);
    entry.placeholderKey = nextPlaceholderKey;
  }
  const previewFrame = entry.session?.latest_preview ?? null;
  if (previewFrame?.data_url && previewFrame.updated_at && previewFrame.updated_at !== entry.currentPreviewAt) {
    entry.currentPreviewAt = previewFrame.updated_at;
    entry.liveImage.src = previewFrame.data_url;
  }
  const deliveryMode = getPrivateGameSessionDeliveryMode(entry.session);
  const showLiveMedia = deliveryMode === "full";
  const localCanvasTexture = showLiveMedia ? getPrivateGameShareLocalCanvasTexture(entry) : null;
  const desiredMap = showLiveMedia && localCanvasTexture
    ? localCanvasTexture
    : showLiveMedia && entry.videoTexture
    ? entry.videoTexture
    : showLiveMedia && previewFrame?.data_url
      ? entry.liveTexture
      : entry.placeholderTexture;
  const showingPlaceholder = desiredMap === entry.placeholderTexture;
  const baseAspectRatio = getPrivateGameBubbleAspectRatio(entry.session);
  const baseWidth = getSharedNearbyMediaWidth({ shareKind: "game" });
  const baseHeight = baseWidth / Math.max(0.1, baseAspectRatio);
  const bubbleWidth = PRIVATE_BROWSER_SHARE.placeholderVideoWidth;
  const bubbleHeight = bubbleWidth / PRIVATE_BROWSER_SHARE.placeholderAspectRatio;
  const scaleX = showingPlaceholder ? bubbleWidth / baseWidth : 1;
  const scaleY = showingPlaceholder ? bubbleHeight / Math.max(0.1, baseHeight) : 1;
  entry.frame.scale.set(scaleX, scaleY, 1);
  entry.frame.position.set(0, 0, 0);
  if (entry.hitTarget) {
    entry.hitTarget.scale.set(scaleX, scaleY, 1);
    entry.hitTarget.position.set(0, 0, 0);
  }
  entry.frame.material.depthTest = false;
  entry.frame.material.opacity = showingPlaceholder ? 0.96 : 1;
  entry.frame.renderOrder = showingPlaceholder ? 11 : 10;
  entry.frameShell.visible = false;
  if (entry.frame.material.map !== desiredMap) {
    entry.frame.material.map = desiredMap;
    entry.frame.material.needsUpdate = true;
  }
  entry.frame.material.needsUpdate = true;
}

function updatePrivateGameBubbles(deltaSeconds = 0.016, elapsedSeconds = 0) {
  const preview = state.preview;
  if (!preview?.gameShareEntries) {
    return;
  }
  const activeSessions = [...state.gameSessions.values()];
  const activeIds = new Set(activeSessions.map((session) => String(session?.session_id ?? "").trim()).filter(Boolean));
  for (const sessionId of [...preview.gameShareEntries.keys()]) {
    if (!activeIds.has(sessionId)) {
      removePrivateGameBubbleEntry(sessionId);
    }
  }
  for (const session of activeSessions) {
    const entry = ensurePrivateGameBubbleEntry(session);
    if (!entry) {
      continue;
    }
    if (!preview.entityPickables.includes(entry.hitTarget)) {
      preview.entityPickables.push(entry.hitTarget);
    }
    if (!preview.entityPickables.includes(entry.frame)) {
      preview.entityPickables.push(entry.frame);
    }
    entry.session = session;
    entry.hostSessionId = String(session.host_viewer_session_id ?? entry.hostSessionId ?? "").trim();
    if (session._remoteElement) {
      setPrivateGameShareVideo(entry.sessionId, session._remoteElement);
    }
    const hostPosition = getPrivateBrowserHostPosition(entry.hostSessionId);
    if (!hostPosition) {
      entry.group.visible = false;
      continue;
    }
    const showingLiveMedia = getPrivateGameSessionDeliveryMode(entry.session) === "full"
      && Boolean(
        (isPrivateLocalHostedGameShareSession(entry.session) && getPrivateLocalGamePreviewCanvas(entry.sessionId))
        || entry.videoTexture
        || entry.session?.latest_preview?.data_url,
      );
    const laneOffset = getPrivateGameShareLaneOffset(entry.session);
    entry.targetPosition.copy(hostPosition);
    entry.targetPosition.x += laneOffset.x;
    entry.targetPosition.z += laneOffset.z;
    entry.targetPosition.y += getSharedBrowserScreenOffsetY(showingLiveMedia, elapsedSeconds) + laneOffset.y;
    entry.position.lerp(entry.targetPosition, 1 - Math.exp(-deltaSeconds * 8));
    entry.group.position.copy(entry.position);
    entry.group.rotation.set(0, 0, 0);
    entry.group.visible = true;
    updatePrivateGameBubblePresentation(entry);
  }
}

function removePrivateBrowserAnchorEntry(anchorSessionId = "") {
  const preview = state.preview;
  const normalizedAnchorSessionId = String(anchorSessionId ?? "").trim();
  const entry = preview?.browserAnchorEntries?.get(normalizedAnchorSessionId);
  if (!entry) {
    return;
  }
  preview.browserAnchorEntries.delete(normalizedAnchorSessionId);
  entry.group.parent?.remove(entry.group);
  entry.group.traverse((node) => {
    if (node.geometry) {
      node.geometry.dispose();
    }
    if (Array.isArray(node.material)) {
      node.material.forEach(disposeMaterial);
    } else {
      disposeMaterial(node.material);
    }
  });
}

function getPrivateBrowserAnchorEntryKey(session = {}) {
  return `host:${String(session?.hostSessionId ?? "").trim()}`;
}

function updatePrivateBrowserAnchorGeometry(entry) {
  if (!entry?.fill || !entry?.ring) {
    return;
  }
  if (Math.abs((entry.radius ?? 0) - PRIVATE_BROWSER_RADIUS) < 0.01) {
    return;
  }
  const ringInnerRadius = Math.max(0.1, PRIVATE_BROWSER_RADIUS - 2.2);
  entry.fill.geometry.dispose();
  entry.fill.geometry = new THREE.CircleGeometry(PRIVATE_BROWSER_RADIUS, 96);
  entry.ring.geometry.dispose();
  entry.ring.geometry = new THREE.RingGeometry(ringInnerRadius, PRIVATE_BROWSER_RADIUS, 96);
  entry.radius = PRIVATE_BROWSER_RADIUS;
}

function ensurePrivateBrowserAnchorEntry(session = {}) {
  const preview = state.preview;
  if (!preview?.browserAnchors) {
    return null;
  }
  const anchorEntryKey = getPrivateBrowserAnchorEntryKey(session);
  if (anchorEntryKey === "host:") {
    return null;
  }
  const existing = preview.browserAnchorEntries.get(anchorEntryKey);
  if (existing) {
    existing.session = session;
    existing.hostSessionId = String(session.hostSessionId ?? existing.hostSessionId ?? "").trim();
    updatePrivateBrowserAnchorGeometry(existing);
    return existing;
  }
  const fill = new THREE.Mesh(
    new THREE.CircleGeometry(PRIVATE_BROWSER_RADIUS, 96),
    new THREE.MeshBasicMaterial({
      color: new THREE.Color(PRIVATE_WORLD_STYLE.accents[0]),
      transparent: true,
      opacity: 0.12,
      side: THREE.DoubleSide,
      depthTest: false,
      depthWrite: false,
      fog: false,
    }),
  );
  fill.rotation.x = -Math.PI / 2;
  fill.renderOrder = 3;
  const ring = new THREE.Mesh(
    new THREE.RingGeometry(Math.max(0.1, PRIVATE_BROWSER_RADIUS - 2.2), PRIVATE_BROWSER_RADIUS, 96),
    new THREE.MeshBasicMaterial({
      color: new THREE.Color(PRIVATE_WORLD_STYLE.accents[0]),
      transparent: true,
      opacity: 0.72,
      side: THREE.DoubleSide,
      depthTest: false,
      depthWrite: false,
      fog: false,
    }),
  );
  ring.rotation.x = -Math.PI / 2;
  ring.renderOrder = 4;
  const group = new THREE.Group();
  group.add(fill);
  group.add(ring);
  preview.browserAnchors.add(group);
  const entry = {
    session,
    hostSessionId: String(session.hostSessionId ?? "").trim(),
    group,
    fill,
    ring,
    radius: PRIVATE_BROWSER_RADIUS,
  };
  preview.browserAnchorEntries.set(anchorEntryKey, entry);
  return entry;
}

function reconcilePrivateBrowserAnchors() {
  const preview = state.preview;
  if (!preview?.browserAnchorEntries) {
    return;
  }
  const browserAnchorSessions = [...state.browserSessions.values()]
    .filter((session) =>
      isPrivateBrowserOriginSession(session)
      && session?.movementLocked === true
      && String(session?.sessionMode ?? "").trim() === "display-share");
  const gameAnchorSessions = [...state.gameSessions.values()]
    .filter((session) =>
      isPrivateGameOriginSession(session)
      && (session?.movement_locked === true || session?.movementLocked === true))
    .map((session) => ({
      sessionId: String(session?.session_id ?? "").trim(),
      hostSessionId: String(session?.host_viewer_session_id ?? "").trim(),
    }));
  const anchorSessions = [];
  const seenHosts = new Set();
  for (const session of [...browserAnchorSessions, ...gameAnchorSessions]) {
    const anchorEntryKey = getPrivateBrowserAnchorEntryKey(session);
    if (!anchorEntryKey || seenHosts.has(anchorEntryKey)) {
      continue;
    }
    seenHosts.add(anchorEntryKey);
    anchorSessions.push(session);
  }
  const activeAnchorIds = new Set(
    anchorSessions
      .map((session) => getPrivateBrowserAnchorEntryKey(session))
      .filter(Boolean),
  );
  for (const anchorSessionId of [...preview.browserAnchorEntries.keys()]) {
    if (!activeAnchorIds.has(anchorSessionId)) {
      removePrivateBrowserAnchorEntry(anchorSessionId);
    }
  }
  for (const session of anchorSessions) {
    if (!activeAnchorIds.has(getPrivateBrowserAnchorEntryKey(session))) {
      continue;
    }
    ensurePrivateBrowserAnchorEntry(session);
  }
}

function updatePrivateBrowserAnchors() {
  const preview = state.preview;
  if (!preview?.browserAnchorEntries) {
    return;
  }
  reconcilePrivateBrowserAnchors();
  if (preview.browserAnchors) {
    preview.browserAnchors.visible = true;
  }
  for (const entry of preview.browserAnchorEntries.values()) {
    const hostPosition = getPrivateBrowserHostPosition(entry.hostSessionId);
    if (!hostPosition) {
      entry.group.visible = false;
      continue;
    }
    updatePrivateBrowserAnchorGeometry(entry);
    entry.group.visible = true;
    entry.group.position.set(hostPosition.x, hostPosition.y + 0.12, hostPosition.z);
  }
}

function updatePrivateShareBubbles(deltaSeconds, elapsedSeconds) {
  const preview = state.preview;
  if (!preview?.camera) {
    return;
  }
  reconcilePrivateShareBubbles();
  updatePrivateBrowserAnchors();
  const bubbleSessions = getPrivateShareBubbleSessions();
  if (bubbleSessions.length === 0) {
    return;
  }
  for (const session of bubbleSessions) {
    const entry = ensurePrivateShareBubbleEntry(session);
    if (!entry) {
      continue;
    }
    const hostPosition = getPrivateBrowserHostPosition(session.hostSessionId);
    if (!hostPosition) {
      entry.group.visible = false;
      continue;
    }
    entry.session = session;
    entry.hostSessionId = String(session.hostSessionId ?? entry.hostSessionId ?? "").trim();
    entry.deliveryMode = session.deliveryMode ?? "placeholder";
    updatePrivateShareBubbleGeometry(entry);
    updatePrivateShareBubblePresentation(entry);
    const showingLiveMedia = isPrivateShareBubbleShowingLiveMedia(entry);
    const hostAnchorGroup = getPrivateBrowserHostAnchorGroup(session.hostSessionId);
    const laneOffset = getSharedNearbyLaneOffset({
      shareKind: getPrivateBrowserSessionShareKind(session),
      sessionSlot: session?.sessionSlot,
    });
    const offsetY = getSharedBrowserScreenOffsetY(showingLiveMedia, elapsedSeconds);
    setPrivateShareBubbleParent(entry, hostAnchorGroup);
    entry.group.visible = true;
    entry.group.rotation.set(0, 0, 0);
    if (hostAnchorGroup) {
      entry.group.position.set(laneOffset.x, offsetY + laneOffset.y, laneOffset.z);
    } else {
      entry.targetPosition.copy(hostPosition);
      entry.targetPosition.x += laneOffset.x;
      entry.targetPosition.z += laneOffset.z;
      entry.targetPosition.y += offsetY;
      entry.position.lerp(entry.targetPosition, 1 - Math.exp(-deltaSeconds * 8));
      entry.group.position.copy(entry.position);
    }
    orientPrivateBillboardToCamera(entry.frame, preview.camera);
  }
}

function updatePrivateChatBubbleGhosts(preview, deltaSeconds, camera = preview?.camera) {
  updateChatBubbleGhosts({
    entries: preview?.animatedChatBubbleGhosts ?? null,
    deltaSeconds,
    camera,
    orientToCamera: orientPrivateBillboardToCamera,
    removeGhost: (entry) => removePrivateChatBubbleGhost(preview, entry),
  });
}

function removePrivatePresenceObject(presenceId) {
  const preview = state.preview;
  const entry = preview?.presenceEntries?.get(presenceId);
  if (!entry) {
    return;
  }
  preview.presenceEntries.delete(presenceId);
  entry.group.parent?.remove(entry.group);
  entry.group.traverse((node) => {
    node.geometry?.dispose?.();
    if (Array.isArray(node.material)) {
      node.material.forEach((material) => {
        material?.map?.dispose?.();
        material?.dispose?.();
      });
    } else {
      node.material?.map?.dispose?.();
      node.material?.dispose?.();
    }
  });
}

function upsertPrivatePresenceObject(entry) {
  const preview = state.preview;
  const presenceId = getPrivatePresenceEntryId(entry);
  if (!preview?.presence || !presenceId || presenceId === getPrivateViewerSessionId()) {
    return;
  }
  if (isPrivatePresencePlayerBodyHidden(entry)) {
    removePrivatePresenceObject(presenceId);
    return;
  }
  const displayName = getPrivatePresenceDisplayName(entry);
  const existing = preview.presenceEntries.get(presenceId);
  if (!existing) {
    const next = buildPrivatePresenceObject(entry);
    preview.presenceEntries.set(presenceId, next);
    preview.presence.add(next.group);
    applyPrivateChatBubbleToActor(next, state.activeChats.get(presenceId));
    return;
  }
  existing.displayName = displayName;
  existing.baseY = Number(entry.position_y ?? existing.baseY) || existing.baseY;
  existing.targetPosition.set(
    Number(entry.position_x ?? existing.targetPosition.x) || 0,
    Number(entry.position_y ?? existing.targetPosition.y) || existing.targetPosition.y,
    Number(entry.position_z ?? existing.targetPosition.z) || 0,
  );
}

function reconcilePrivatePresenceScene() {
  const preview = state.preview;
  if (!preview?.presenceEntries) {
    return;
  }
  const desiredIds = new Set(
    [...state.livePresence.values()]
      .filter((entry) => !isPrivatePresencePlayerBodyHidden(entry))
      .map((entry) => getPrivatePresenceEntryId(entry))
      .filter((presenceId) => presenceId && presenceId !== getPrivateViewerSessionId()),
  );
  for (const presenceId of [...preview.presenceEntries.keys()]) {
    if (!desiredIds.has(presenceId)) {
      removePrivatePresenceObject(presenceId);
    }
  }
  for (const entry of state.livePresence.values()) {
    upsertPrivatePresenceObject(entry);
  }
}

function isPrivatePresencePlayerBodyHidden(entry = {}) {
  const joinRole = String(entry.join_role ?? entry.joinRole ?? "").trim().toLowerCase();
  const playerEntityId = String(entry.player_entity_id ?? entry.playerEntityId ?? "").trim();
  return joinRole === "player" && Boolean(playerEntityId);
}

function mergePrivatePresenceRows(rows = [], options = {}) {
  if (options.replaceViewerSnapshot) {
    state.livePresence.clear();
  }
  for (const entry of rows) {
    const presenceId = getPrivatePresenceEntryId(entry);
    if (!presenceId || presenceId === getPrivateViewerSessionId()) {
      continue;
    }
    state.livePresence.set(presenceId, {
      ...entry,
    });
  }
  reconcilePrivatePresenceScene();
}

function removePrivatePresence(presenceId) {
  const normalized = String(presenceId ?? "").trim();
  if (!normalized) {
    return;
  }
  state.livePresence.delete(normalized);
  removePrivatePresenceObject(normalized);
}

function updatePrivatePresenceScene(deltaSeconds, elapsedSeconds) {
  const preview = state.preview;
  if (!preview?.presenceEntries) {
    return;
  }
  for (const entry of preview.presenceEntries.values()) {
    entry.position.lerp(entry.targetPosition, 1 - Math.exp(-deltaSeconds * 7.5));
    entry.group.position.copy(entry.position);
    entry.group.position.y = entry.baseY + Math.sin(elapsedSeconds * entry.bob + entry.phase) * 0.9;
    if (entry.shadow) {
      entry.shadow.position.y = -entry.group.position.y + 0.05;
    }
    if (entry.halo) {
      entry.halo.rotation.z += deltaSeconds * 1.14;
    }
    if (entry.orb) {
      entry.orb.position.y = entry.orbBaseY + Math.sin(elapsedSeconds * 1.4 + entry.phase) * 0.26;
    }
    updatePrivateActorBubble(entry, deltaSeconds, preview.camera);
  }
}

function getPreferredLauncherTab() {
  return state.session ? "worlds" : "access";
}

function canShowCreateWorldDialog(launcherTab = state.launcherTab, profileTab = state.profileLauncherTab) {
  if (!state.session) {
    return false;
  }
  if (launcherTab === "worlds") {
    return true;
  }
  return launcherTab === "profile" && normalizeProfileLauncherTab(profileTab) === "worlds";
}

function getLauncherTitle() {
  if (state.launcherTab === "profile") {
    return "My Profile";
  }
  if (state.launcherTab === "access") {
    if (!state.authReady) {
      return "Checking Account";
    }
    return state.session ? "Account" : "Sign In";
  }
  return "Select Worlds";
}

function renderLauncherTitle() {
  if (elements.launcherTitle) {
    elements.launcherTitle.textContent = getLauncherTitle();
  }
}

function normalizeLauncherWorldTab(tab) {
  return LAUNCHER_WORLD_BROWSER_TABS.has(tab) ? tab : "mine";
}

function getLauncherSearchPlaceholder() {
  return normalizeLauncherWorldTab(state.launcherWorldTab) === "all"
    ? "Search all private worlds"
    : "Search your private worlds";
}

function renderLauncherWorldTabs() {
  const activeTab = normalizeLauncherWorldTab(state.launcherWorldTab);
  state.launcherWorldTab = activeTab;
  for (const button of elements.launcherWorldTabButtons ?? []) {
    const isActive = button.getAttribute("data-launcher-world-tab") === activeTab;
    button.classList.toggle("is-active", isActive);
    button.setAttribute("aria-selected", String(isActive));
  }
  if (elements.worldSearch) {
    elements.worldSearch.placeholder = getLauncherSearchPlaceholder();
  }
  if (elements.launcherWorldTypeField) {
    elements.launcherWorldTypeField.hidden = activeTab !== "all";
  }
  if (elements.publicWorldType) {
    elements.publicWorldType.disabled = activeTab !== "all";
  }
}

function setLauncherWorldTab(tab, options = {}) {
  state.launcherWorldTab = normalizeLauncherWorldTab(tab);
  renderLauncherWorldTabs();
  renderLauncherWorldBrowser();
  if (options.load === false) {
    return;
  }
  if (state.launcherWorldTab === "all") {
    void loadPublicWorlds();
    return;
  }
  if (state.session) {
    void loadWorlds();
  }
}

function setLauncherTab(tab) {
  const nextTab = LAUNCHER_TABS.has(tab) ? tab : getPreferredLauncherTab();
  state.launcherTab = nextTab;
  if (!canShowCreateWorldDialog(nextTab, state.profileLauncherTab)) {
    state.createWorldDialogOpen = false;
  }
  syncCreateWorldDialogVisibility();
  for (const section of elements.launcherSections ?? []) {
    const active = section.getAttribute("data-launcher-section") === nextTab;
    section.hidden = !active;
    section.classList.toggle("is-active", active);
  }
  renderLauncherTitle();
  renderLauncherWorldTabs();
  renderProfileLauncher();
  if (nextTab === "profile") {
    loadProfileLauncherData();
  }
}

function getPrimaryViewerSpawnPlayer(world = state.selectedWorld) {
  const activeSceneId = String(world?.active_instance?.active_scene_id ?? "").trim();
  const activeScene = world?.scenes?.find((entry) => String(entry?.id ?? "").trim() === activeSceneId)
    ?? getDefaultScene(world)
    ?? world?.scenes?.[0]
    ?? null;
  const sceneDoc = activeScene?.compiled_doc?.runtime?.resolved_scene_doc
    ?? activeScene?.scene_doc
    ?? null;
  const players = Array.isArray(sceneDoc?.players) ? sceneDoc.players : [];
  return players.find((entry) => entry?.occupiable !== false) ?? players[0] ?? null;
}

function getViewerSpawnPosition(world = state.selectedWorld) {
  if (!world) {
    return new THREE.Vector3(0, PRIVATE_CAMERA.minY, 0);
  }
  const rig = getPrivateViewerRigConfig(world);
  const primaryPlayer = getPrimaryViewerSpawnPlayer(world);
  if (primaryPlayer?.position) {
    return new THREE.Vector3(
      Number(primaryPlayer.position.x ?? 0) || 0,
      Number(primaryPlayer.position.y ?? rig.spawnHeight) || rig.spawnHeight,
      Number(primaryPlayer.position.z ?? 0) || 0,
    );
  }
  const width = Math.max(PRIVATE_WORLD_BLOCK_UNIT * 4, Number(world?.width ?? PRIVATE_WORLD_DEFAULT_SIZE.width) || PRIVATE_WORLD_DEFAULT_SIZE.width);
  const length = Math.max(PRIVATE_WORLD_BLOCK_UNIT * 4, Number(world?.length ?? PRIVATE_WORLD_DEFAULT_SIZE.length) || PRIVATE_WORLD_DEFAULT_SIZE.length);
  return new THREE.Vector3(
    clampNumber(-width * 0.06, -2, -4, 4),
    rig.spawnHeight,
    clampNumber(length * 0.08, 0, -4, 8),
  );
}

function getPrivateViewerRigConfig(world = state.selectedWorld) {
  const width = Math.max(PRIVATE_WORLD_BLOCK_UNIT * 4, Number(world?.width ?? PRIVATE_WORLD_DEFAULT_SIZE.width) || PRIVATE_WORLD_DEFAULT_SIZE.width);
  const length = Math.max(PRIVATE_WORLD_BLOCK_UNIT * 4, Number(world?.length ?? PRIVATE_WORLD_DEFAULT_SIZE.length) || PRIVATE_WORLD_DEFAULT_SIZE.length);
  const height = Math.max(PRIVATE_WORLD_BLOCK_UNIT * 2, Number(world?.height ?? PRIVATE_WORLD_DEFAULT_SIZE.height) || PRIVATE_WORLD_DEFAULT_SIZE.height);
  const minRadius = PRIVATE_PLAYER_VIEW.minRadius;
  const defaultRadius = PRIVATE_PLAYER_VIEW.defaultRadius;
  const maxRadius = PRIVATE_PLAYER_VIEW.maxRadius;
  const spawnHeight = PRIVATE_CAMERA.minY;
  const lookHeight = PRIVATE_PLAYER_VIEW.lookHeight;
  return {
    width,
    length,
    height,
    minRadius,
    defaultRadius,
    maxRadius,
    spawnHeight,
    lookHeight,
    minY: PRIVATE_CAMERA.minY,
    maxY: Math.max(PRIVATE_CAMERA.minY + 8, height + 12),
  };
}

function getPrivateWorldBounds(world = state.selectedWorld) {
  const rig = getPrivateViewerRigConfig(world);
  const { width, length, height } = rig;
  return {
    width,
    length,
    height,
    minX: -width / 2,
    maxX: width / 2,
    minZ: -length / 2,
    maxZ: length / 2,
    minY: rig.minY,
    maxY: rig.maxY,
  };
}

function clampViewerPositionToWorldBounds(position, world = state.selectedWorld) {
  if (!position) {
    return position;
  }
  const bounds = getPrivateWorldBounds(world);
  position.x = clampNumber(position.x, position.x, bounds.minX, bounds.maxX);
  position.z = clampNumber(position.z, position.z, bounds.minZ, bounds.maxZ);
  position.y = clampNumber(position.y, position.y, bounds.minY, bounds.maxY);
  return position;
}

function resetViewerRig(world = state.selectedWorld) {
  const rig = getPrivateViewerRigConfig(world);
  clearPossessedOverworldCameraCenter();
  privateInputState.yaw = 0;
  privateInputState.pitch = world ? -0.34 : 0.66;
  privateInputState.sprintHoldSeconds = 0;
  privateInputState.pointerDown = false;
  privateInputState.pointerButtonToken = "";
  privateInputState.pointerMoved = false;
  privateInputState.dragDistance = 0;
  privateInputState.keys.clear();
  state.cameraRadius = rig.defaultRadius;
  state.trailAccumulator = 0;
  state.viewerSuppressClickAt = 0;
  state.buildSuppressedClick = null;
  state.viewerPosition.copy(getViewerSpawnPosition(world));
  state.viewerCameraPosition.set(
    state.viewerPosition.x,
    state.viewerPosition.y + Math.max(4, rig.defaultRadius * 0.42),
    state.viewerPosition.z + state.cameraRadius,
  );
  if (state.preview?.camera) {
    syncPrivateCameraToFollowTarget(state.preview);
  }
  if (state.preview?.viewerAvatar) {
    state.preview.viewerAvatar.position.copy(state.viewerPosition);
    state.preview.viewerAvatar.lastPosition.copy(state.viewerPosition);
    state.preview.viewerAvatar.group.position.copy(state.viewerPosition);
    state.preview.viewerAvatar.facingYaw = normalizeAngle(privateInputState.yaw + Math.PI);
  }
}

function setByPath(target, path, value) {
  const segments = String(path ?? "").split(".").filter(Boolean);
  if (!segments.length) {
    return;
  }
  let cursor = target;
  for (let index = 0; index < segments.length - 1; index += 1) {
    const key = segments[index];
    if (!cursor[key] || typeof cursor[key] !== "object") {
      cursor[key] = {};
    }
    cursor = cursor[key];
  }
  cursor[segments[segments.length - 1]] = value;
}

function getValueByPath(target, path) {
  const segments = String(path ?? "").split(".").filter(Boolean);
  if (!segments.length) {
    return { exists: false, value: undefined };
  }
  let cursor = target;
  for (const segment of segments) {
    if (cursor == null || typeof cursor !== "object" || !Object.prototype.hasOwnProperty.call(cursor, segment)) {
      return { exists: false, value: undefined };
    }
    cursor = cursor[segment];
  }
  return { exists: true, value: cursor };
}

function deleteByPath(target, path) {
  const segments = String(path ?? "").split(".").filter(Boolean);
  if (!target || typeof target !== "object" || !segments.length) {
    return;
  }
  const stack = [];
  let cursor = target;
  for (let index = 0; index < segments.length - 1; index += 1) {
    const segment = segments[index];
    if (!cursor[segment] || typeof cursor[segment] !== "object") {
      return;
    }
    stack.push([cursor, segment]);
    cursor = cursor[segment];
  }
  delete cursor[segments[segments.length - 1]];
  for (let index = stack.length - 1; index >= 0; index -= 1) {
    const [parent, key] = stack[index];
    const value = parent?.[key];
    if (!value || typeof value !== "object" || Array.isArray(value) || Object.keys(value).length > 0) {
      break;
    }
    delete parent[key];
  }
}

function isRecordObject(value) {
  return Boolean(value) && typeof value === "object" && !Array.isArray(value);
}

function getPrivateFlatForwardVector(yaw = privateInputState.yaw) {
  return new THREE.Vector3(-Math.sin(yaw), 0, -Math.cos(yaw)).normalize();
}

function getPrivatePlayerLookTarget(position = state.viewerPosition, world = state.selectedWorld) {
  const rig = getPrivateViewerRigConfig(world);
  return position.clone().add(new THREE.Vector3(0, rig.lookHeight, 0));
}

function getPrivateCameraForwardVector(yaw = privateInputState.yaw, pitch = privateInputState.pitch) {
  const cosPitch = Math.cos(pitch);
  return new THREE.Vector3(
    -Math.sin(yaw) * cosPitch,
    Math.sin(pitch),
    -Math.cos(yaw) * cosPitch,
  ).normalize();
}

function getPrivateCameraPlanarBasis(preview = state.preview) {
  if (isFixedTopDownCameraMode(getActivePossessedCameraMode())) {
    const orientation = getPlayerFixedTopDownOrientation(getActivePossessedFixedTopDownDirection());
    return {
      forward: orientation.upVector.clone(),
      right: orientation.rightVector.clone(),
    };
  }
  const fallbackForward = getPrivateFlatForwardVector();
  if (!preview?.camera) {
    return {
      forward: fallbackForward,
      right: new THREE.Vector3(Math.cos(privateInputState.yaw), 0, -Math.sin(privateInputState.yaw)),
    };
  }

  const forward = new THREE.Vector3();
  preview.camera.getWorldDirection(forward);
  forward.y = 0;
  if (forward.lengthSq() < 0.000001) {
    forward.copy(fallbackForward);
  } else {
    forward.normalize();
  }

  const right = new THREE.Vector3().crossVectors(forward, new THREE.Vector3(0, 1, 0));
  if (right.lengthSq() < 0.000001) {
    right.set(Math.cos(privateInputState.yaw), 0, -Math.sin(privateInputState.yaw));
  } else {
    right.normalize();
  }
  return { forward, right };
}

function releaseHeldRuntimeKeys(options = {}) {
  const shouldReleaseKey = typeof options.shouldReleaseKey === "function"
    ? options.shouldReleaseKey
    : () => true;
  const keys = [...state.pressedRuntimeKeys].filter((key) => shouldReleaseKey(key));
  if (!keys.length) {
    return [];
  }
  const headingY = Number(options.headingY);
  const resolvedHeadingY = Number.isFinite(headingY) ? headingY : getRuntimeInputHeadingY();
  for (const key of keys) {
    state.pressedRuntimeKeys.delete(key);
    void sendRuntimeInput(key, "up", {
      headingY: resolvedHeadingY,
    });
  }
  return keys;
}

function isRuntimeMovementInputKey(key = "") {
  const normalized = String(key ?? "").trim().toLowerCase();
  if (!normalized) {
    return false;
  }
  const player = getPossessedRuntimePlayer() ?? state.predictedPossessedPlayer ?? null;
  const movementTokens = [
    ["move_forward_key", getPlayerMoveForwardBinding(player)],
    ["move_back_key", getPlayerMoveBackBinding(player)],
    ["move_left_key", getPlayerMoveLeftBinding(player)],
    ["move_right_key", getPlayerMoveRightBinding(player)],
  ];
  for (const [bindingName, token] of movementTokens) {
    if (normalized === token) {
      return true;
    }
    if (getMovementBindingAliases(bindingName, token).includes(normalized)) {
      return true;
    }
  }
  return RUNTIME_MOVEMENT_INPUT_KEYS.has(normalized);
}

function getPrivateCameraMovementBasis(preview = state.preview) {
  const planarBasis = getPrivateCameraPlanarBasis(preview);
  if (!preview?.camera) {
    return planarBasis;
  }
  const fullForward = new THREE.Vector3();
  preview.camera.getWorldDirection(fullForward);
  if (fullForward.lengthSq() < 0.000001) {
    return planarBasis;
  }
  fullForward.normalize();
  const tiltMix = Math.max(0, Math.min(1, (Math.abs(privateInputState.pitch) - 0.34) / 0.5));
  const forward = planarBasis.forward.clone().lerp(fullForward, tiltMix);
  if (forward.lengthSq() < 0.000001) {
    forward.copy(planarBasis.forward);
  } else {
    forward.normalize();
  }
  return {
    forward,
    right: planarBasis.right,
  };
}

function syncPrivateCameraToFollowTarget(preview = state.preview) {
  if (!preview?.camera) {
    return;
  }
  const camera = activatePerspectivePreviewCamera(preview);
  const rig = getPrivateViewerRigConfig();
  const target = getPrivatePlayerLookTarget();
  const radius = clampNumber(
    state.cameraRadius,
    state.cameraRadius,
    rig.minRadius,
    rig.maxRadius,
  );
  const cosPitch = Math.cos(privateInputState.pitch);
  const nextPosition = new THREE.Vector3(
    target.x + Math.sin(privateInputState.yaw) * cosPitch * radius,
    target.y - Math.sin(privateInputState.pitch) * radius,
    target.z + Math.cos(privateInputState.yaw) * cosPitch * radius,
  );
  camera.position.copy(nextPosition);
  camera.lookAt(target);
  state.viewerCameraPosition.copy(camera.position);
}

function describeVector3(input = {}) {
  return `${Number(input.x ?? 0).toFixed(1)}, ${Number(input.y ?? 0).toFixed(1)}, ${Number(input.z ?? 0).toFixed(1)}`;
}

const ENTITY_COLLECTIONS = [
  { kind: "voxel", key: "voxels", label: "Voxels", singular: "Voxel" },
  { kind: "primitive", key: "primitives", label: "Objects", singular: "Object" },
  { kind: "panel", key: "panels", label: "Panels", singular: "Panel" },
  { kind: "model", key: "models", label: "Models", singular: "Model" },
  { kind: "player", key: "players", label: "Players", singular: "Player" },
  { kind: "screen", key: "screens", label: "Screens", singular: "Screen" },
  { kind: "text", key: "texts", label: "3D Text", singular: "3D Text" },
  { kind: "trigger", key: "trigger_zones", label: "Trigger Zones", singular: "Trigger Zone" },
  { kind: "sound", key: "sounds", label: "Sounds", singular: "Sound" },
  { kind: "particle", key: "particles", label: "Particles", singular: "Particle" },
  { kind: "prefab_instance", key: "prefab_instances", label: "Prefab Instances", singular: "Prefab Instance" },
];

const MATERIAL_PRESET_OPTIONS = [
  "none",
  "grass",
  "wood",
  "wall",
  "floor",
  "stone",
  "metal",
  "glass",
  "fabric",
];

const PRIMITIVE_SHAPES = ["box", "sphere", "capsule", "cylinder", "cone", "plane", "panel"];
const PLAYER_CAMERA_MODE_OPTIONS = [
  { value: "third_person", label: "third person" },
  { value: "first_person", label: "first person" },
  { value: "orthogonal", label: "orthogonal" },
  { value: "fixed_orthogonal", label: "orthogonal fixed" },
  { value: "overworld", label: "overworld" },
  { value: "overworld_fixed", label: "overworld fixed" },
];
const PLAYER_CAMERA_MODES = PLAYER_CAMERA_MODE_OPTIONS.map((option) => option.value);
const PLAYER_FIXED_TOP_DOWN_DIRECTION_OPTIONS = [
  { value: "north", label: "north" },
  { value: "north_east", label: "north east" },
  { value: "east", label: "east" },
  { value: "south_east", label: "south east" },
  { value: "south", label: "south" },
  { value: "south_west", label: "south west" },
  { value: "west", label: "west" },
  { value: "north_west", label: "north west" },
];
const PLAYER_FIXED_TOP_DOWN_ANGLE_OPTIONS = [
  { value: 90, label: "fully top down (90deg)" },
  { value: 45, label: "angled (45deg)" },
  { value: 0, label: "side scroller (0deg)" },
];
const PLAYER_BODY_MODES = ["rigid", "ghost"];
const EFFECT_OPTIONS = ["", "sparkles", "smoke", "glow", "embers", "mist"];
const TRAIL_OPTIONS = ["", "ribbon", "glow", "spark", "comet"];
const SCRIPT_FUNCTION_HEADER_RE = PRIVATE_SCRIPT_FUNCTION_HEADER_RE;

function isPlacementToolKind(kind) {
  return kind === "voxel"
    || kind === "primitive"
    || kind === "panel"
    || kind === "player"
    || kind === "sound"
    || kind === "screen"
    || kind === "text"
    || kind === "trigger";
}

function isToolPresetKind(kind) {
  return TOOL_PRESET_KINDS.includes(kind);
}

function getToolPresetOptions(kind) {
  if (!isToolPresetKind(kind)) {
    return [];
  }
  return [
    ...(TOOL_PRESET_BUILTINS[kind] ?? []),
    ...(state.toolPresetCustoms?.[kind] ?? []),
  ];
}

function getSelectedToolPresetId(kind) {
  const options = getToolPresetOptions(kind);
  const selectedId = String(state.toolPresetSelection?.[kind] ?? "").trim();
  if (options.some((preset) => preset.id === selectedId)) {
    return selectedId;
  }
  return options[0]?.id || "";
}

function getToolPreset(kind, presetId = getSelectedToolPresetId(kind)) {
  return getToolPresetOptions(kind).find((preset) => preset.id === presetId) ?? null;
}

function persistToolPresetState() {
  try {
    window.localStorage.setItem(TOOL_PRESET_STORAGE_KEY, JSON.stringify({
      selected: state.toolPresetSelection,
      customs: state.toolPresetCustoms,
    }));
  } catch (_error) {
    // local storage can fail in private browsing; presets still work for this session
  }
}

function setSelectedToolPreset(kind, presetId) {
  if (!isToolPresetKind(kind)) {
    return;
  }
  const nextPresetId = String(presetId ?? "").trim();
  const options = getToolPresetOptions(kind);
  const resolvedPresetId = options.some((preset) => preset.id === nextPresetId)
    ? nextPresetId
    : (options[0]?.id || "");
  state.toolPresetSelection[kind] = resolvedPresetId;
  persistToolPresetState();
  renderToolPresetPanel();
  updateShellState();
}

function buildToolPresetDisplayName(kind) {
  if (kind === "voxel") {
    return "Voxel";
  }
  if (kind === "primitive") {
    return "Object";
  }
  if (kind === "panel") {
    return "Panel";
  }
  if (kind === "player") {
    return "Player";
  }
  if (kind === "sound") {
    return "Sound";
  }
  if (kind === "model") {
    return "Model";
  }
  if (kind === "screen") {
    return "Screen";
  }
  if (kind === "text") {
    return "Text";
  }
  if (kind === "trigger") {
    return "Trigger";
  }
  return "Tool";
}

function createCustomToolPresetId(kind, name = "") {
  const baseToken = slugToken(name) || `${kind}-preset`;
  let nextId = `custom-${baseToken}-${Date.now().toString(36)}`;
  let suffix = 1;
  while (getToolPresetOptions(kind).some((preset) => preset.id === nextId)) {
    suffix += 1;
    nextId = `custom-${baseToken}-${Date.now().toString(36)}-${suffix}`;
  }
  return nextId;
}

function getSelectedEntityForToolPreset(kind) {
  if (!isToolPresetKind(kind)) {
    return null;
  }
  try {
    const sceneDoc = parseSceneTextarea();
    const selected = getSelectedEntity(sceneDoc);
    if (!selected || selected.kind !== kind) {
      return null;
    }
    return selected.entry;
  } catch (_error) {
    return null;
  }
}

function saveToolPreset(kind, options = {}) {
  if (!isToolPresetKind(kind)) {
    return;
  }
  const sourceEntry = options.sourceEntry
    ? extractToolPresetEntry(kind, options.sourceEntry)
    : extractToolPresetEntry(kind, getToolPreset(kind)?.entry ?? createBaseToolPresetEntry(kind));
  const nextName = String(options.name ?? "").trim() || `${buildToolPresetDisplayName(kind)} Preset ${Math.max(1, (state.toolPresetCustoms?.[kind] ?? []).length + 1)}`;
  const nextPreset = {
    id: createCustomToolPresetId(kind, nextName),
    name: nextName,
    builtin: false,
    entry: sourceEntry,
  };
  state.toolPresetCustoms[kind] = [
    ...(state.toolPresetCustoms?.[kind] ?? []),
    nextPreset,
  ];
  state.toolPresetSelection[kind] = nextPreset.id;
  persistToolPresetState();
  renderToolPresetPanel();
  updateShellState();
}

function updateCustomToolPreset(kind, presetId, sourceEntry) {
  if (!isToolPresetKind(kind) || !sourceEntry) {
    return;
  }
  const nextPresets = [...(state.toolPresetCustoms?.[kind] ?? [])];
  const targetIndex = nextPresets.findIndex((preset) => preset.id === presetId);
  if (targetIndex < 0) {
    return;
  }
  nextPresets[targetIndex] = {
    ...nextPresets[targetIndex],
    entry: extractToolPresetEntry(kind, sourceEntry),
  };
  state.toolPresetCustoms[kind] = nextPresets;
  persistToolPresetState();
  renderToolPresetPanel();
  updateShellState();
}

function deleteCustomToolPreset(kind, presetId) {
  if (!isToolPresetKind(kind)) {
    return;
  }
  state.toolPresetCustoms[kind] = (state.toolPresetCustoms?.[kind] ?? []).filter((preset) => preset.id !== presetId);
  const fallbackPresetId = getToolPresetOptions(kind).find((preset) => preset.id !== presetId)?.id || "";
  state.toolPresetSelection[kind] = fallbackPresetId;
  persistToolPresetState();
  renderToolPresetPanel();
  updateShellState();
}

function getPlacementToolButton(kind) {
  if (kind === "voxel") {
    return elements.addVoxel;
  }
  if (kind === "primitive") {
    return elements.addPrimitive;
  }
  if (kind === "panel") {
    return elements.addPanel;
  }
  if (kind === "player") {
    return elements.addPlayer;
  }
  if (kind === "screen") {
    return elements.addScreen;
  }
  if (kind === "text") {
    return elements.addText;
  }
  if (kind === "trigger") {
    return elements.addTrigger;
  }
  return null;
}

function canUsePlacementTools() {
  return Boolean(state.selectedWorld && isEditor() && state.mode === "build");
}

function getActivePlacementTool() {
  const temporary = String(state.placementShortcutTool ?? "").trim();
  if (isPlacementToolKind(temporary)) {
    return temporary;
  }
  const persistent = String(state.placementTool ?? "").trim();
  return isPlacementToolKind(persistent) ? persistent : "";
}

function getActivePrefabPlacementId() {
  return canUsePlacementTools() ? String(state.prefabPlacementId ?? "").trim() : "";
}

function clearPlacementTool(options = {}) {
  const temporaryOnly = options.temporaryOnly === true;
  if (temporaryOnly) {
    state.placementShortcutTool = "";
  } else {
    state.placementShortcutTool = "";
    state.placementTool = "";
    state.prefabPlacementId = "";
  }
  if (state.previewPointer.inside && canUsePlacementTools()) {
    refreshBuildHoverFromStoredPointer();
  } else {
    state.buildHover = null;
    syncBuildPlacementOverlay();
  }
  updateShellState();
}

function setPlacementTool(kind, options = {}) {
  const normalized = isPlacementToolKind(kind) ? kind : "";
  if (!canUsePlacementTools() && normalized) {
    return;
  }
  if (options.temporary === true) {
    state.placementShortcutTool = normalized;
  } else {
    state.prefabPlacementId = "";
    state.placementTool = normalized && state.placementTool === normalized ? "" : normalized;
  }
  refreshBuildHoverFromStoredPointer();
  syncBuildPlacementOverlay();
  updateShellState();
}

function armPrefabPlacement(prefabId = state.selectedPrefabId, options = {}) {
  const normalizedPrefabId = String(prefabId ?? "").trim();
  if (!canUsePlacementTools()) {
    return;
  }
  state.selectedPrefabId = normalizedPrefabId;
  state.placementShortcutTool = "";
  state.placementTool = "";
  state.prefabPlacementId = options.toggle === true && state.prefabPlacementId === normalizedPrefabId ? "" : normalizedPrefabId;
  refreshBuildHoverFromStoredPointer();
  syncBuildPlacementOverlay();
  updateShellState();
}

function buildPlacementToolLabel(kind) {
  const shortcut = [...BUILD_PLACEMENT_SHORTCUTS.entries()].find(([, value]) => value === kind)?.[0] || "";
  const presetName = getToolPreset(kind)?.name || "";
  const suffix = presetName ? ` · ${presetName}` : "";
  if (kind === "voxel") {
    return `${shortcut ? `Voxel (${shortcut})` : "Voxel"}${suffix}`;
  }
  if (kind === "primitive") {
    return `${shortcut ? `Object (${shortcut})` : "Object"}${suffix}`;
  }
  if (kind === "panel") {
    return `${shortcut ? `Panel (${shortcut})` : "Panel"}${suffix}`;
  }
  if (kind === "player") {
    return `${shortcut ? `Player (${shortcut})` : "Player"}${suffix}`;
  }
  if (kind === "screen") {
    return `${shortcut ? `Screen (${shortcut})` : "Screen"}${suffix}`;
  }
  if (kind === "text") {
    return `${shortcut ? `Text (${shortcut})` : "Text"}${suffix}`;
  }
  if (kind === "trigger") {
    return `${shortcut ? `Trigger (${shortcut})` : "Trigger"}${suffix}`;
  }
  return "";
}

function getPlacementShortcutTool(event) {
  const key = String(event?.key ?? "").trim();
  if (BUILD_PLACEMENT_SHORTCUTS.has(key)) {
    return BUILD_PLACEMENT_SHORTCUTS.get(key) || "";
  }
  const code = String(event?.code ?? "").trim();
  if (code.startsWith("Digit")) {
    return BUILD_PLACEMENT_SHORTCUTS.get(code.slice(5)) || "";
  }
  if (code.startsWith("Numpad")) {
    return BUILD_PLACEMENT_SHORTCUTS.get(code.slice(6)) || "";
  }
  return "";
}

function getBuildTransformAxisShortcut(event) {
  const key = String(event?.key ?? "").trim();
  if (BUILD_TRANSFORM_AXIS_SHORTCUTS.has(key)) {
    return BUILD_TRANSFORM_AXIS_SHORTCUTS.get(key) || "";
  }
  const code = String(event?.code ?? "").trim();
  if (code.startsWith("Digit")) {
    return BUILD_TRANSFORM_AXIS_SHORTCUTS.get(code.slice(5)) || "";
  }
  if (code.startsWith("Numpad")) {
    return BUILD_TRANSFORM_AXIS_SHORTCUTS.get(code.slice(6)) || "";
  }
  return "";
}

function createEntityRef(kind, id) {
  const normalizedKind = String(kind ?? "").trim();
  const normalizedId = String(id ?? "").trim();
  if (!normalizedKind || !normalizedId) {
    return null;
  }
  return {
    kind: normalizedKind,
    id: normalizedId,
  };
}

function isSameEntityRef(left, right) {
  return Boolean(
    left
    && right
    && String(left.kind ?? "").trim() === String(right.kind ?? "").trim()
    && String(left.id ?? "").trim() === String(right.id ?? "").trim(),
  );
}

function normalizeEntityRefs(refs = []) {
  const normalized = [];
  for (const ref of refs) {
    const next = createEntityRef(ref?.kind, ref?.id);
    if (!next || normalized.some((entry) => isSameEntityRef(entry, next))) {
      continue;
    }
    normalized.push(next);
  }
  return normalized;
}

function writeBuilderSelection(refs = [], primaryRef = null) {
  const normalizedRefs = normalizeEntityRefs(refs);
  const normalizedPrimary = createEntityRef(primaryRef?.kind, primaryRef?.id)
    ?? normalizedRefs[normalizedRefs.length - 1]
    ?? null;
  if (!normalizedPrimary) {
    state.builderSelection = null;
    state.builderSelectionSet = [];
    return;
  }
  const orderedRefs = normalizedRefs.filter((entry) => !isSameEntityRef(entry, normalizedPrimary));
  orderedRefs.push(normalizedPrimary);
  state.builderSelection = normalizedPrimary;
  state.builderSelectionSet = orderedRefs.length > 1 ? orderedRefs : [];
}

function getBuilderSelectionRefs() {
  if (state.builderSelectionSet?.length) {
    return normalizeEntityRefs(state.builderSelectionSet);
  }
  const primary = createEntityRef(state.builderSelection?.kind, state.builderSelection?.id);
  return primary ? [primary] : [];
}

function getEntityPersistentGroupId(entry = {}) {
  return String(entry?.group_id ?? "").trim();
}

function getPersistentGroupRefs(sceneDoc, groupId = "") {
  const normalizedGroupId = String(groupId ?? "").trim();
  if (!normalizedGroupId) {
    return [];
  }
  const refs = [];
  for (const config of ENTITY_COLLECTIONS) {
    for (const entry of getEntityArray(sceneDoc, config.key)) {
      if (getEntityPersistentGroupId(entry) !== normalizedGroupId) {
        continue;
      }
      refs.push({ kind: config.kind, id: entry.id });
    }
  }
  return normalizeEntityRefs(refs);
}

function expandSelectionRefsWithPersistentGroups(refs = [], sceneDoc) {
  const normalizedRefs = normalizeEntityRefs(refs);
  if (!sceneDoc || !normalizedRefs.length) {
    return normalizedRefs;
  }
  const expanded = [...normalizedRefs];
  for (const ref of normalizedRefs) {
    const selected = findEntityByRef(sceneDoc, ref);
    const groupId = getEntityPersistentGroupId(selected?.entry);
    if (!groupId) {
      continue;
    }
    for (const groupedRef of getPersistentGroupRefs(sceneDoc, groupId)) {
      if (!expanded.some((entry) => isSameEntityRef(entry, groupedRef))) {
        expanded.push(groupedRef);
      }
    }
  }
  return normalizeEntityRefs(expanded);
}

function getSelectionPersistentGroupInfo(sceneDoc = parseSceneTextarea(), selectedEntities = getSelectedEntities(sceneDoc)) {
  const selectedRefs = normalizeEntityRefs(selectedEntities.map((entry) => ({ kind: entry.kind, id: entry.entry.id })));
  const groupIds = [...new Set(selectedEntities.map((entry) => getEntityPersistentGroupId(entry.entry)).filter(Boolean))];
  if (groupIds.length !== 1) {
    return {
      groupId: "",
      memberRefs: [],
      isWholeGroupSelected: false,
    };
  }
  const memberRefs = getPersistentGroupRefs(sceneDoc, groupIds[0]);
  const isWholeGroupSelected = memberRefs.length > 1
    && memberRefs.length === selectedRefs.length
    && memberRefs.every((memberRef) => selectedRefs.some((selectedRef) => isSameEntityRef(selectedRef, memberRef)));
  return {
    groupId: groupIds[0],
    memberRefs,
    isWholeGroupSelected,
  };
}

function createNextPersistentGroupId(sceneDoc) {
  const usedGroupIds = new Set();
  for (const config of ENTITY_COLLECTIONS) {
    for (const entry of getEntityArray(sceneDoc, config.key)) {
      const groupId = getEntityPersistentGroupId(entry);
      if (groupId) {
        usedGroupIds.add(groupId);
      }
    }
  }
  let index = 1;
  while (usedGroupIds.has(`group_${index}`)) {
    index += 1;
  }
  return `group_${index}`;
}

function hasBuilderSelection() {
  return getBuilderSelectionRefs().length > 0;
}

function isEntitySelected(kind, id) {
  const ref = createEntityRef(kind, id);
  return Boolean(ref && getBuilderSelectionRefs().some((entry) => isSameEntityRef(entry, ref)));
}

function getBuildTransformShortcut(event) {
  return BUILD_TRANSFORM_SHORTCUTS.get(normalizeRuntimeKey(event)) || "";
}

function hasBuildTransformAxisModifier() {
  return state.buildModifierKeys.has("q")
    || state.buildModifierKeys.has("e")
    || state.buildModifierKeys.has("r");
}

function getBuildTransformAxisLock(transformMode = getBuildTransformMode()) {
  if (transformMode !== "move" && transformMode !== "scale" && transformMode !== "rotate") {
    return "";
  }
  for (const key of ["1", "2", "3"]) {
    if (state.buildModifierKeys.has(key)) {
      return BUILD_TRANSFORM_AXIS_SHORTCUTS.get(key) || "";
    }
  }
  return "";
}

function canUseBuildTransformShortcuts() {
  return canUsePlacementTools() && !getActivePlacementTool() && !getActivePrefabPlacementId();
}

function getBuildTransformMode() {
  if (!canUseBuildTransformShortcuts()) {
    return "";
  }
  if (state.buildModifierKeys.has("t")) {
    return "delete";
  }
  if (state.buildModifierKeys.has("r")) {
    return "rotate";
  }
  if (state.buildModifierKeys.has("e")) {
    return "scale";
  }
  if (state.buildModifierKeys.has("q")) {
    return "move";
  }
  if (state.buildModifierKeys.has("shift")) {
    return "multi";
  }
  return "";
}

function getResolvedBuildTransformMode(transformMode = getBuildTransformMode(), sceneDoc = null) {
  if (!transformMode || (transformMode !== "scale" && transformMode !== "rotate")) {
    return transformMode;
  }
  if (Array.isArray(sceneDoc)) {
    return resolveBuildTransformModeForSelection(transformMode, sceneDoc);
  }
  try {
    return resolveBuildTransformModeForSelection(transformMode, getSelectedEntities(sceneDoc ?? parseSceneTextarea()));
  } catch (_error) {
    return transformMode;
  }
}

function resolveBuildTransformModeForSelection(transformMode = "", selectedEntities = []) {
  if (!transformMode || (transformMode !== "scale" && transformMode !== "rotate")) {
    return transformMode;
  }
  if (selectedEntities.length > 1 && !canGroupScaleRotateSelection(selectedEntities)) {
    return "move";
  }
  return transformMode;
}

function getEntityCollection(key) {
  return ENTITY_COLLECTIONS.find((entry) => entry.key === key || entry.kind === key) ?? null;
}

function getEntityArray(sceneDoc, key) {
  return Array.isArray(sceneDoc?.[key]) ? sceneDoc[key] : [];
}

function findEntityByRef(sceneDoc, ref) {
  const normalizedRef = createEntityRef(ref?.kind, ref?.id);
  if (!normalizedRef) {
    return null;
  }
  const config = getEntityCollection(normalizedRef.kind);
  if (!config) {
    return null;
  }
  const entries = getEntityArray(sceneDoc, config.key);
  const index = entries.findIndex((entry) => entry.id === normalizedRef.id);
  if (index < 0) {
    return null;
  }
  return {
    ...config,
    index,
    entry: entries[index],
  };
}

function getDisplayNameForEntity(kind, entry = {}, index = 0) {
  if (kind === "voxel") {
    return entry.id || `Voxel ${index + 1}`;
  }
  if (kind === "primitive") {
    return entry.label || entry.id || `Object ${index + 1}`;
  }
  if (kind === "panel") {
    return entry.label || entry.id || `Panel ${index + 1}`;
  }
  if (kind === "model") {
    return entry.label || entry.id || `Model ${index + 1}`;
  }
  if (kind === "player") {
    return entry.label || entry.id || `Player ${index + 1}`;
  }
  if (kind === "screen") {
    return entry.id || `Screen ${index + 1}`;
  }
  if (kind === "text") {
    return entry.value || entry.id || `Text ${index + 1}`;
  }
  if (kind === "trigger") {
    return entry.label || entry.id || `Trigger ${index + 1}`;
  }
  if (kind === "sound") {
    return entry.label || entry.id || `Sound ${index + 1}`;
  }
  if (kind === "particle") {
    return entry.effect || entry.id || `Particle ${index + 1}`;
  }
  if (kind === "prefab_instance") {
    return entry.label || entry.id || `Prefab ${index + 1}`;
  }
  return entry.id || `Item ${index + 1}`;
}

function truncatePrivateUiLabel(value = "", maxLength = 48) {
  const normalized = String(value ?? "").trim().replace(/\s+/g, " ");
  if (!normalized) {
    return "";
  }
  if (normalized.length <= maxLength) {
    return normalized;
  }
  return `${normalized.slice(0, Math.max(1, maxLength - 1)).trimEnd()}...`;
}

function buildCompactEntityTitle(kind, entry = {}, index = 0) {
  const config = getEntityCollection(kind);
  const fallbackLabel = config?.singular || "Item";
  if (kind === "text") {
    const value = truncatePrivateUiLabel(entry.value, 42);
    return value || `${fallbackLabel} ${index + 1}`;
  }
  const label = String(entry.label ?? "").trim();
  if (label) {
    return truncatePrivateUiLabel(label, 42);
  }
  if (kind === "model" && String(entry.asset_id ?? "").trim()) {
    return truncatePrivateUiLabel(`Model ${index + 1}`, 42);
  }
  if (kind === "screen") {
    return `Screen ${index + 1}`;
  }
  if (kind === "panel") {
    return `Panel ${index + 1}`;
  }
  if (kind === "primitive") {
    return `Object ${index + 1}`;
  }
  if (kind === "voxel") {
    return `Voxel ${index + 1}`;
  }
  if (kind === "player") {
    return `Player ${index + 1}`;
  }
  if (kind === "trigger") {
    return `Trigger ${index + 1}`;
  }
  if (kind === "sound") {
    return `Sound ${index + 1}`;
  }
  if (kind === "particle") {
    return `Particle ${index + 1}`;
  }
  if (kind === "prefab_instance") {
    return `Prefab ${index + 1}`;
  }
  return `${fallbackLabel} ${index + 1}`;
}

function getSelectedEntity(sceneDoc = parseSceneTextarea()) {
  return findEntityByRef(sceneDoc, state.builderSelection);
}

function getSelectedEntities(sceneDoc = parseSceneTextarea()) {
  return getBuilderSelectionRefs()
    .map((ref) => findEntityByRef(sceneDoc, ref))
    .filter(Boolean);
}

const GROUP_PREFAB_SUPPORTED_KINDS = new Set([
  "voxel",
  "primitive",
  "panel",
  "model",
  "screen",
  "text",
  "trigger",
  "sound",
]);

function canConvertSelectionToGroupPrefab(selectedEntities = []) {
  return Array.isArray(selectedEntities)
    && selectedEntities.length > 0
    && selectedEntities.every((entry) => GROUP_PREFAB_SUPPORTED_KINDS.has(String(entry?.kind ?? "").trim()));
}

function getConvertPrefabButtonLabel(selectedEntities = []) {
  return selectedEntities.length > 1 ? "Create Group Prefab" : "Convert to Prefab";
}

function ensureBuilderSelection(sceneDoc = parseSceneTextarea()) {
  const expandedRefs = expandSelectionRefsWithPersistentGroups(getBuilderSelectionRefs(), sceneDoc);
  const validSelections = expandedRefs
    .map((ref) => findEntityByRef(sceneDoc, ref))
    .filter(Boolean);
  if (!validSelections.length) {
    writeBuilderSelection([]);
    return null;
  }
  const selected = validSelections.find((entry) => isSameEntityRef({ kind: entry.kind, id: entry.entry.id }, state.builderSelection))
    ?? validSelections[validSelections.length - 1];
  writeBuilderSelection(
    validSelections.map((entry) => ({ kind: entry.kind, id: entry.entry.id })),
    { kind: selected.kind, id: selected.entry.id },
  );
  return selected;
}

function setBuilderSelection(kind, id, options = {}) {
  const nextRef = createEntityRef(kind, id);
  let sceneDoc = null;
  try {
    sceneDoc = parseSceneTextarea();
  } catch (_error) {
    sceneDoc = null;
  }
  if (!nextRef) {
    writeBuilderSelection([]);
  } else if (options.append === true) {
    const nextRefs = getBuilderSelectionRefs();
    if (!nextRefs.some((entry) => isSameEntityRef(entry, nextRef))) {
      nextRefs.push(nextRef);
    }
    writeBuilderSelection(expandSelectionRefsWithPersistentGroups(nextRefs, sceneDoc), nextRef);
  } else {
    writeBuilderSelection(expandSelectionRefsWithPersistentGroups([nextRef], sceneDoc), nextRef);
  }
  updateShellState();
  renderSceneBuilder();
  updatePreviewFromSelection();
}

function getAiProviderFieldNames(group) {
  if (group === "image") {
    return {
      provider: "imageProvider",
      model: "imageModel",
      apiKey: "imageApiKey",
    };
  }
  if (group === "model") {
    return {
      provider: "modelProvider",
      model: "modelModel",
      apiKey: "modelApiKey",
    };
  }
  return {
    provider: "reasoningProvider",
    model: "reasoningModel",
    apiKey: "reasoningApiKey",
  };
}

function normalizeTextReasoningProviderName(value = "") {
  const normalized = String(value ?? "").trim().toLowerCase();
  if (normalized === "claude" || normalized === "anthropic") {
    return "anthropic";
  }
  if (normalized === "gemini" || normalized === "google") {
    return "google";
  }
  return normalized || "openai";
}

function getDefaultAiModelForGroup(group, provider = "") {
  if (group === "reasoning") {
    return TEXT_REASONING_PROVIDER_DEFAULT_MODELS[normalizeTextReasoningProviderName(provider)] || TEXT_REASONING_PROVIDER_DEFAULT_MODELS.openai;
  }
  return group === "image" ? "gpt-image-1" : "meshy-4";
}

function maybeAdoptAiProviderDefaultModel(group, providerField = null, modelField = null) {
  if (group !== "reasoning" || !providerField || !modelField) {
    return;
  }
  const currentValue = String(modelField.value ?? "").trim();
  if (currentValue && !Object.values(TEXT_REASONING_PROVIDER_DEFAULT_MODELS).includes(currentValue)) {
    return;
  }
  modelField.value = getDefaultAiModelForGroup(group, providerField.value);
}

function readAiProviderState(group) {
  const storageKey = AI_PROVIDER_SESSION_KEYS[group];
  if (!storageKey) {
    return { provider: "openai", model: "", apiKey: "" };
  }
  try {
    const parsed = JSON.parse(window.sessionStorage.getItem(storageKey) || "{}");
    const provider = group === "reasoning"
      ? normalizeTextReasoningProviderName(parsed.provider ?? "openai")
      : String(parsed.provider ?? "").trim() || (group === "model" ? "meshy" : "openai");
    return {
      provider,
      model: String(parsed.model ?? "").trim(),
      apiKey: String(parsed.apiKey ?? "").trim(),
    };
  } catch (_error) {
    return {
      provider: group === "model" ? "meshy" : "openai",
      model: "",
      apiKey: "",
    };
  }
}

function writeAiProviderState(group, value = {}) {
  const storageKey = AI_PROVIDER_SESSION_KEYS[group];
  if (!storageKey) {
    return;
  }
  const nextValue = {
    provider: String(value.provider ?? "").trim(),
    model: String(value.model ?? "").trim(),
    apiKey: String(value.apiKey ?? "").trim(),
  };
  if (!nextValue.provider && !nextValue.model && !nextValue.apiKey) {
    window.sessionStorage.removeItem(storageKey);
    return;
  }
  window.sessionStorage.setItem(storageKey, JSON.stringify(nextValue));
}

function getAiProviderState(group) {
  const names = getAiProviderFieldNames(group);
  const stored = readAiProviderState(group);
  const providerValue = String(elements.aiForm?.elements?.[names.provider]?.value ?? stored.provider ?? "").trim()
    || stored.provider
    || (group === "model" ? "meshy" : "openai");
  return {
    provider: group === "reasoning" ? normalizeTextReasoningProviderName(providerValue) : providerValue,
    model: String(elements.aiForm?.elements?.[names.model]?.value ?? stored.model ?? "").trim() || stored.model || "",
    apiKey: String(elements.aiForm?.elements?.[names.apiKey]?.value ?? stored.apiKey ?? "").trim() || stored.apiKey || "",
  };
}

function syncAiProviderFormFromSession() {
  for (const group of ["reasoning", "image", "model"]) {
    const names = getAiProviderFieldNames(group);
    const value = readAiProviderState(group);
    if (elements.aiForm?.elements?.[names.provider] && !elements.aiForm.elements[names.provider].value) {
      elements.aiForm.elements[names.provider].value = value.provider || (group === "model" ? "meshy" : "openai");
    }
    if (elements.aiForm?.elements?.[names.model] && !elements.aiForm.elements[names.model].value) {
      elements.aiForm.elements[names.model].value = value.model
        || getDefaultAiModelForGroup(group, value.provider);
    }
    if (elements.aiForm?.elements?.[names.apiKey]) {
      elements.aiForm.elements[names.apiKey].value = value.apiKey || "";
    }
  }
}

function setAiBuilderStatus(text = "", tone = "") {
  if (!elements.aiStatus) {
    return;
  }
  elements.aiStatus.textContent = String(text ?? "");
  if (tone) {
    elements.aiStatus.dataset.tone = tone;
  } else {
    delete elements.aiStatus.dataset.tone;
  }
}

function setFormControlsDisabled(form, disabled) {
  if (!form?.elements) {
    return;
  }
  for (const control of Array.from(form.elements)) {
    if (!control || typeof control.disabled !== "boolean") {
      continue;
    }
    control.disabled = disabled;
  }
}

function getWorldAccessPolicy(world = state.selectedWorld) {
  return {
    allowNonEditorExport:
      world?.access_policy?.allow_non_editor_export === true
      || world?.allow_non_editor_export === true,
    allowNonEditorFork:
      world?.access_policy?.allow_non_editor_fork === true
      || world?.allow_non_editor_fork === true,
  };
}

function buildWorldAccessPolicySummary(policy = getWorldAccessPolicy()) {
  const exportLabel = policy.allowNonEditorExport ? "can export packages" : "cannot export packages";
  const forkLabel = policy.allowNonEditorFork ? "can fork this world" : "cannot fork this world";
  return `Signed-in non-editors ${exportLabel} and ${forkLabel}.`;
}

function setWorldAccessStatus(text = "", tone = "") {
  if (!elements.worldAccessStatus) {
    return;
  }
  elements.worldAccessStatus.textContent = String(text ?? "");
  if (tone) {
    elements.worldAccessStatus.dataset.tone = tone;
  } else {
    delete elements.worldAccessStatus.dataset.tone;
  }
}

function syncWorldAccessControlsFromWorld(world = state.selectedWorld) {
  if (!world) {
    setWorldAccessStatus("Open a world to configure viewer export and fork access.");
  }
  const policy = getWorldAccessPolicy(world);
  if (elements.worldAccessExport) {
    elements.worldAccessExport.checked = policy.allowNonEditorExport;
  }
  if (elements.worldAccessFork) {
    elements.worldAccessFork.checked = policy.allowNonEditorFork;
  }
  if (world) {
    const suffix = isEditor() ? "" : " Only editors can change this.";
    setWorldAccessStatus(`${buildWorldAccessPolicySummary(policy)}${suffix}`);
  }
}

function updateWorldAccessControlsState() {
  const hasWorld = Boolean(state.selectedWorld);
  const canEdit = isEditor();
  const policy = getWorldAccessPolicy();
  const exportChecked = elements.worldAccessExport?.checked === true;
  const forkChecked = elements.worldAccessFork?.checked === true;
  if (elements.worldAccessExport) {
    elements.worldAccessExport.disabled = !hasWorld || !canEdit;
  }
  if (elements.worldAccessFork) {
    elements.worldAccessFork.disabled = !hasWorld || !canEdit;
  }
  if (elements.saveWorldAccess) {
    elements.saveWorldAccess.disabled =
      !hasWorld
      || !canEdit
      || (policy.allowNonEditorExport === exportChecked && policy.allowNonEditorFork === forkChecked);
  }
}

function refreshAiBuilderStatus() {
  if (!state.selectedWorld) {
    setAiBuilderStatus("Open a world to use AI Builder.", "error");
    return;
  }
  if (!isEditor()) {
    setAiBuilderStatus("Only editors can use AI Builder in this world.", "error");
    return;
  }
  const reasoning = getAiProviderState("reasoning");
  const image = getAiProviderState("image");
  const model = getAiProviderState("model");
  if (!state.session) {
    setAiBuilderStatus("Sign in to use AI Builder.", "error");
    return;
  }
  if (!reasoning.apiKey) {
    setAiBuilderStatus("Add your text reasoning API key to enable brainstorming and generation.", "error");
    return;
  }
  const readyBits = [
    `Reasoning ${reasoning.provider}${reasoning.model ? ` · ${reasoning.model}` : ""}`,
    image.apiKey ? `Texture ${image.provider}${image.model ? ` · ${image.model}` : ""}` : "Texture key missing",
    model.apiKey ? `3D ${model.provider}${model.model ? ` · ${model.model}` : ""}` : "3D key missing",
  ];
  setAiBuilderStatus(readyBits.join(" | "), image.apiKey && model.apiKey ? "success" : "");
}

function cloneAiDialogMessages(messages = []) {
  return Array.isArray(messages)
    ? messages
      .map((entry) => ({
        role: String(entry?.role ?? "user").trim().toLowerCase() === "assistant" ? "assistant" : "user",
        text: String(entry?.text ?? "").trim(),
      }))
      .filter((entry) => entry.text)
    : [];
}

function cloneAiDialogThread(thread = {}) {
  const createdAt = Number(thread?.createdAt) || Date.now();
  const updatedAt = Number(thread?.updatedAt) || createdAt;
  return {
    id: String(thread?.id ?? "").trim() || createAiDialogThreadId(),
    messages: cloneAiDialogMessages(thread.messages),
    input: String(thread?.input ?? ""),
    result: String(thread?.result ?? ""),
    awaitingValidationClarification: thread?.awaitingValidationClarification === true,
    generatedAsset: thread.generatedAsset ? deepClone(thread.generatedAsset) : null,
    createdAt,
    updatedAt,
  };
}

function normalizeAiDialogThreads(dialog = {}) {
  const hasLegacyThreadState = Array.isArray(dialog.messages)
    || dialog.input
    || dialog.result
    || dialog.generatedAsset;
  const sourceThreads = Array.isArray(dialog.threads)
    ? dialog.threads
    : (hasLegacyThreadState ? [{
      messages: dialog.messages,
      input: dialog.input,
      result: dialog.result,
      generatedAsset: dialog.generatedAsset,
    }] : []);
  const threads = sourceThreads.map((thread) => cloneAiDialogThread(thread)).filter(Boolean);
  return threads.length ? threads : [createEmptyAiDialogThread()];
}

function cloneAiDialogState(dialog = {}) {
  const threads = normalizeAiDialogThreads(dialog);
  const activeThreadId = threads.some((thread) => thread.id === dialog.activeThreadId)
    ? dialog.activeThreadId
    : threads[0].id;
  return {
    ...createEmptyAiDialogState(),
    ...dialog,
    activeThreadId,
    threads,
  };
}

function getAiDialogThreadKey(config = {}) {
  const worldId = String(config.worldId ?? state.selectedWorld?.world_id ?? "world").trim() || "world";
  const artifactType = String(config.artifactType ?? "screen_html").trim().toLowerCase() || "screen_html";
  const targetKind = String(config.targetKind ?? "world").trim().toLowerCase() || "world";
  const targetId = String(config.targetId ?? "world").trim() || "world";
  return `${worldId}:${artifactType}:${targetKind}:${targetId}`;
}

function ensureAiDialogThreads(dialog = state.aiDialog) {
  if (!dialog || typeof dialog !== "object") {
    return [createEmptyAiDialogThread()];
  }
  if (!Array.isArray(dialog.threads) || !dialog.threads.length) {
    dialog.threads = [createEmptyAiDialogThread()];
  }
  if (!dialog.threads.some((thread) => thread.id === dialog.activeThreadId)) {
    dialog.activeThreadId = dialog.threads[0].id;
  }
  return dialog.threads;
}

function getActiveAiDialogThread(dialog = state.aiDialog) {
  const threads = ensureAiDialogThreads(dialog);
  return threads.find((thread) => thread.id === dialog.activeThreadId) || threads[0];
}

function touchAiDialogThread(thread = null) {
  if (!thread) {
    return;
  }
  thread.updatedAt = Date.now();
}

function getAiDialogThreadPreview(thread = {}) {
  const previewSource = thread.messages.find((entry) => entry.role === "user")?.text
    || thread.result
    || "";
  if (!previewSource) {
    return "No prompt yet";
  }
  return truncatePrivateUiLabel(previewSource.replace(/\s+/g, " "), 80);
}

function getAiDialogThreadSummary(thread = {}) {
  const turnCount = Array.isArray(thread.messages) ? thread.messages.length : 0;
  const turnLabel = `${turnCount} message${turnCount === 1 ? "" : "s"}`;
  if (thread.awaitingValidationClarification === true) {
    return `${turnLabel} · needs reply\n${getAiDialogThreadPreview(thread)}`;
  }
  if (thread.generatedAsset?.id) {
    return `${turnLabel} · asset ready\n${getAiDialogThreadPreview(thread)}`;
  }
  if (thread.result) {
    return `${turnLabel} · final ready\n${getAiDialogThreadPreview(thread)}`;
  }
  if (turnCount > 0) {
    return `${turnLabel} · brainstorming\n${getAiDialogThreadPreview(thread)}`;
  }
  return "New thread";
}

function persistAiDialogThreadState() {
  if (!state.aiDialog.key) {
    return;
  }
  ensureAiDialogThreads(state.aiDialog);
  state.aiThreadDrafts.set(state.aiDialog.key, cloneAiDialogState({
    ...state.aiDialog,
    open: false,
    busy: false,
    status: "",
    statusTone: "",
  }));
}

function setAiDialogStatus(text = "", tone = "") {
  state.aiDialog.status = String(text ?? "");
  state.aiDialog.statusTone = String(tone ?? "");
}

function getCreatedAiDialogScriptFunction(dialog = state.aiDialog) {
  if (dialog.targetKind !== "new_script_function") {
    return null;
  }
  const createdId = String(dialog.createdScriptFunctionId ?? "").trim();
  if (!createdId) {
    return null;
  }
  return getSceneScriptFunctions().find((entry) => entry.id === createdId) ?? null;
}

function getAiDialogNoteText(dialog = state.aiDialog) {
  const baseNote = dialog.note
    || "Start with a brief, let the AI surface assumptions and questions, then generate when it is ready.";
  if (dialog.targetKind !== "new_script_function") {
    return baseNote;
  }
  const createdFunction = getCreatedAiDialogScriptFunction(dialog);
  if (createdFunction?.name) {
    return `${baseNote} This thread updates ${createdFunction.name}, not the currently selected function.`;
  }
  return `${baseNote} This thread creates a brand new function and does not overwrite the currently selected one.`;
}

function getAiDialogResultTabLabel(dialog = state.aiDialog) {
  if (dialog.artifactType === "screen_html") {
    return "Generated HTML";
  }
  if (dialog.artifactType === "texture") {
    return "Generated texture";
  }
  if (dialog.artifactType === "3d_model") {
    return "Generated model";
  }
  return "Generated script";
}

function getAiDialogApplyButtonLabel(dialog = state.aiDialog, activeThread = getActiveAiDialogThread(dialog)) {
  if (dialog.targetKind === "new_script_function") {
    const createdFunction = getCreatedAiDialogScriptFunction(dialog);
    return createdFunction?.name
      ? `Update ${createdFunction.name}`
      : "Create new function";
  }
  if (dialog.targetKind === "script_function") {
    return "Apply to selected function";
  }
  const canApplyAsset = dialog.artifactType === "texture" || dialog.artifactType === "3d_model";
  return dialog.applyLabel || (canApplyAsset ? "Apply asset" : "Apply result");
}

function setAiDialogPane(pane = "conversation", options = {}) {
  const normalizedPane = String(pane ?? "conversation").trim().toLowerCase() === "result" ? "result" : "conversation";
  if (normalizedPane === "result" && !String(getActiveAiDialogThread()?.result ?? "").trim()) {
    return false;
  }
  state.aiDialog.activePane = normalizedPane;
  if (options.persist !== false) {
    persistAiDialogThreadState();
  }
  renderAiDialog();
  return true;
}

function renderAiDialog() {
  const dialog = state.aiDialog;
  const threads = ensureAiDialogThreads(dialog);
  const activeThread = getActiveAiDialogThread(dialog);
  const hasResult = Boolean(activeThread.result);
  if (dialog.activePane === "result" && !hasResult) {
    dialog.activePane = "conversation";
  }
  const activePane = dialog.activePane === "result" && hasResult ? "result" : "conversation";
  if (elements.aiDialogBackdrop) {
    elements.aiDialogBackdrop.hidden = !dialog.open;
  }
  if (elements.aiDialog) {
    elements.aiDialog.hidden = !dialog.open;
  }
  if (elements.aiDialogTitle) {
    elements.aiDialogTitle.textContent = dialog.title || "AI brainstorm";
  }
  if (elements.aiDialogNote) {
    elements.aiDialogNote.textContent = getAiDialogNoteText(dialog);
  }
  if (elements.aiDialogThreadList) {
    elements.aiDialogThreadList.innerHTML = threads.map((thread, index) => {
      const activeClass = thread.id === dialog.activeThreadId ? " is-active" : "";
      const deleteDisabled = dialog.busy || threads.length <= 1 ? "disabled" : "";
      return `
        <div class="pw-ai-dialog__threadcard${activeClass}">
          <button type="button" class="pw-ai-dialog__threadselect" data-ai-dialog-thread-select="${htmlEscape(thread.id)}" ${dialog.busy ? "disabled" : ""}>
            <p class="pw-ai-dialog__threadlabel">Thread ${index + 1}</p>
            <p class="pw-ai-dialog__threadmeta">${htmlEscape(getAiDialogThreadSummary(thread))}</p>
          </button>
          <button type="button" class="is-muted" data-ai-dialog-thread-delete="${htmlEscape(thread.id)}" ${deleteDisabled}>Delete</button>
        </div>
      `;
    }).join("");
  }
  if (elements.aiDialogThread) {
    elements.aiDialogThread.innerHTML = activeThread.messages.length
      ? activeThread.messages.map((entry) => `
        <article class="pw-ai-dialog__message pw-ai-dialog__message--${entry.role}">
          <strong>${entry.role === "assistant" ? "AI" : "You"}</strong>
          <p>${htmlEscape(entry.text)}</p>
        </article>
      `).join("")
      : '<div class="pw-ai-dialog__empty">Start with a short brief. The AI answers with assumptions and questions first, then you decide when to generate the final result.</div>';
  }
  if (elements.aiDialogStatus) {
    elements.aiDialogStatus.textContent = dialog.status || "";
    if (dialog.statusTone) {
      elements.aiDialogStatus.dataset.tone = dialog.statusTone;
    } else {
      delete elements.aiDialogStatus.dataset.tone;
    }
  }
  if (elements.aiDialogInput && elements.aiDialogInput.value !== activeThread.input) {
    elements.aiDialogInput.value = activeThread.input || "";
  }
  if (elements.aiDialogInput) {
    elements.aiDialogInput.disabled = !dialog.open || dialog.busy || !state.selectedWorld || !state.session;
  }
  if (elements.aiDialogSend) {
    elements.aiDialogSend.disabled = !dialog.open || dialog.busy || !state.selectedWorld || !state.session;
  }
  if (elements.aiDialogNewThread) {
    elements.aiDialogNewThread.disabled = !dialog.open || dialog.busy || !state.selectedWorld || !state.session;
  }
  const canGenerate = activeThread.messages.some((entry) => entry.role === "assistant")
    && activeThread.awaitingValidationClarification !== true;
  if (elements.aiDialogGenerate) {
    elements.aiDialogGenerate.disabled = !dialog.open || dialog.busy || !canGenerate || !state.selectedWorld || !state.session;
  }
  if (elements.aiDialogTabs) {
    const tabButtons = [...elements.aiDialogTabs.querySelectorAll("[data-ai-dialog-tab]")];
    for (const button of tabButtons) {
      const pane = button.getAttribute("data-ai-dialog-tab");
      const isResultTab = pane === "result";
      const enabled = pane === "conversation" || hasResult;
      const isSelected = pane === activePane;
      button.classList.toggle("is-active", isSelected);
      button.setAttribute("aria-selected", isSelected ? "true" : "false");
      button.disabled = !enabled;
      button.hidden = isResultTab && !hasResult;
      if (isResultTab) {
        button.textContent = getAiDialogResultTabLabel(dialog);
      }
    }
  }
  if (elements.aiDialogApply) {
    const canApplyAsset = dialog.artifactType === "texture" || dialog.artifactType === "3d_model";
    const canApply = canApplyAsset
      ? Boolean(activeThread.generatedAsset) && dialog.targetKind !== "world"
      : Boolean(activeThread.result) && dialog.targetKind !== "world" && activeThread.awaitingValidationClarification !== true;
    elements.aiDialogApply.hidden = !canApply;
    elements.aiDialogApply.disabled = !canApply || dialog.busy;
    if (canApply) {
      elements.aiDialogApply.textContent = getAiDialogApplyButtonLabel(dialog, activeThread);
    }
  }
  if (elements.aiDialogResultPanel) {
    elements.aiDialogResultPanel.hidden = !hasResult;
  }
  if (elements.aiDialogResultTitle) {
    elements.aiDialogResultTitle.textContent =
      dialog.artifactType === "screen_html"
        ? "Generated HTML"
        : dialog.artifactType === "world_script"
          ? (activeThread.awaitingValidationClarification === true ? "Generated script draft" : "Generated script")
          : dialog.artifactType === "texture"
            ? "Generated texture asset"
            : "Generated model asset";
  }
  if (elements.aiDialogResult && elements.aiDialogResult.value !== activeThread.result) {
    elements.aiDialogResult.value = activeThread.result || "";
  }
  if (elements.aiDialogResult) {
    elements.aiDialogResult.disabled = !dialog.open || dialog.busy;
  }
  if (elements.aiDialog) {
    const panes = [...elements.aiDialog.querySelectorAll("[data-ai-dialog-pane]")];
    for (const pane of panes) {
      pane.hidden = pane.getAttribute("data-ai-dialog-pane") !== activePane;
    }
  }
}

function closeAiDialog(options = {}) {
  if (state.aiDialog.open && options.preserve !== false) {
    persistAiDialogThreadState();
  }
  state.aiDialog = createEmptyAiDialogState();
  updateShellState();
  renderAiDialog();
}

function buildSceneLogicAiObjective(prompt, options = {}) {
  const selectedFunction = options.selectedFunction ?? null;
  const createNewFunction = options.createNewFunction === true;
  return [
    String(prompt ?? "").trim(),
    createNewFunction ? "Create a brand new scene logic function instead of rewriting the currently selected function." : "",
    selectedFunction?.name ? `Target function name: ${selectedFunction.name}.` : "",
    "This should end up as one self-contained Mauworld modular logic function using directives, comments, and rule lines when helpful.",
    "Keep the editable directive surface visible instead of hiding defaults behind implicit behavior.",
    "When the behavior needs real math, nearest-target selection, or per-tick scripted motion, prefer @module script.runtime instead of forcing it into a config-only module.",
    "Use @target for entity, player, or scene ids. Use @bind only for supported input bindings.",
    "Return one self-contained function body for this request, not a whole script library.",
  ]
    .filter(Boolean)
    .join(" ");
}

function buildSceneLogicEntityContext() {
  const scene = getSelectedScene();
  const sceneDoc = scene?.compiled_doc?.runtime?.resolved_scene_doc ?? scene?.scene_doc ?? null;
  if (!sceneDoc) {
    return "";
  }
  const sections = [
    ["voxels", "Voxels", "voxel"],
    ["players", "Players", "player"],
    ["panels", "Panels", "panel"],
    ["primitives", "Primitives", "primitive"],
    ["models", "Models", "model"],
    ["prefab_instances", "Prefab instances", "prefab_instance"],
    ["trigger_zones", "Trigger zones", "trigger"],
    ["texts", "Texts", "text"],
    ["particles", "Particles", "particle"],
    ["sounds", "Sounds", "sound"],
    ["screens", "Screens", "screen"],
  ];
  const lines = [];
  for (const [key, label, kind] of sections) {
    const entries = Array.isArray(sceneDoc[key]) ? sceneDoc[key] : [];
    if (!entries.length) {
      continue;
    }
    lines.push(`${label}:`);
    for (const [index, entry] of entries.slice(0, 12).entries()) {
      lines.push(`- ${entry.id}: ${getDisplayNameForEntity(kind, entry, index)} · ${buildEntitySummary(kind, entry)}`);
    }
  }
  return lines.join("\n");
}

function formatSceneLogicModuleContextEntry(entry = {}) {
  const type = String(entry?.type ?? "value").trim().toLowerCase() || "value";
  const name = String(entry?.name ?? "").trim();
  if (!name) {
    return "";
  }
  if (type === "enum" && Array.isArray(entry.values) && entry.values.length) {
    return `${name}<enum:${entry.values.join("|")}>`;
  }
  if ((type === "number" || type === "integer") && Number.isFinite(entry.min) && Number.isFinite(entry.max)) {
    return `${name}<${type}:${entry.min}..${entry.max}>`;
  }
  if (type === "vector3") {
    return `${name}<vector3>`;
  }
  return `${name}<${type}>`;
}

function buildSceneLogicModuleContext() {
  const blocks = [];
  for (const [moduleKind, definition] of Object.entries(PRIVATE_WORLD_MODULE_DEFINITIONS)) {
    if (moduleKind === "script.runtime") {
      blocks.push([
        `${moduleKind} [scope=scene|entity]`,
        "params: custom @set constants with literal values (number, boolean, string, vector3)",
        "bindings: (none)",
        "directives: @run every_tick|on_call|on_timer|on_overlap|on_hit|on_destroy, @input name [default], @set constant value",
        "targeting: use @target scene or @target <entity_id>; @run on_call helpers may omit @target and inherit the caller self",
        "program: line-based scripting statements; every_tick scripts auto-run, event scripts run from engine hooks, on_call scripts run through call(...)",
        "syntax: let name = expr · if (expr) return · if (expr) { ... } · assignment like self.position = expr",
        "expressions: identifiers, object literals, array literals, property access, function calls, + - * /, comparisons, &&, ||, !",
        "events: event.type plus event.other / event.entity / event.cause depending on the run mode",
        "timer constants: use @set timer_ms 1000 or @set interval_ms 1000 for @run on_timer scripts",
        "builtins: entity(id), entities(kind), players(), nearest(list, from), sort_by_distance(list, from), distance(a, b), normalize(v), length(v), vec(x,y,z), clamp(v,min,max), min(...), max(...), move_toward(from,to,max_step,stop_distance), spawn(source, position, rotation, options), destroy(entity), set_active(entity, bool), emit_particles(effect, at_or_on, options), raycast(origin, direction, max_distance, options), overlap(subject, options), find_by_group(group_id), call(function_id_or_name, ...args), play_sound(sound), stop_sound(sound)",
        "returns: use return <expr>; called scripts can return values to the caller",
      ].join("\n"));
      continue;
    }
    const params = Array.isArray(definition?.params)
      ? definition.params.map((entry) => formatSceneLogicModuleContextEntry(entry)).filter(Boolean)
      : [];
    const bindings = Array.isArray(definition?.bindings)
      ? definition.bindings.map((entry) => formatSceneLogicModuleContextEntry(entry)).filter(Boolean)
      : [];
    blocks.push([
      `${moduleKind} [scope=${definition?.scope || "entity"}]`,
      `params: ${params.length ? params.join(", ") : "(none)"}`,
      `bindings: ${bindings.length ? bindings.join(", ") : "(none)"}`,
    ].join("\n"));
  }
  blocks.push("rule_triggers: zone_enter, zone_exit, key_press, timer, scene_start, all_players_ready");
  blocks.push("rule_actions: apply_force, teleport, move_platform, switch_scene, set_material, set_visibility, toggle_particles, play_sound, stop_sound, set_text, set_screen_state, start_scene");
  return blocks.join("\n\n");
}

function buildSceneLogicTargetCatalogContext() {
  const scene = getSelectedScene();
  const sceneDoc = scene?.compiled_doc?.runtime?.resolved_scene_doc ?? scene?.scene_doc ?? null;
  if (!sceneDoc) {
    return "";
  }
  const catalog = [...buildPrivateWorldScriptTargetCatalog(sceneDoc).values()];
  if (!catalog.length) {
    return "";
  }
  return catalog
    .sort((left, right) => {
      if (left.id === "scene") {
        return -1;
      }
      if (right.id === "scene") {
        return 1;
      }
      return String(left.target_kind ?? "").localeCompare(String(right.target_kind ?? ""))
        || String(left.id ?? "").localeCompare(String(right.id ?? ""));
    })
    .map((entry) => `${entry.id} [${entry.target_kind || entry.target_scope || "entity"}]`)
    .join("\n");
}

function buildSceneLogicLibraryContext() {
  const functions = getSceneScriptFunctions().map((entry, index) => normalizeScriptFunctionEntry(entry, index));
  if (!functions.length) {
    return "";
  }
  return serializeScriptFunctionLibrary(functions);
}

function buildScreenAiObjective(entry, prompt) {
  const viewport = entry ? getScreenTextureRenderSize(entry) : null;
  return [
    String(prompt ?? "").trim(),
    viewport ? `This should fit a Mauworld screen with an approximate viewport of ${viewport.width} by ${viewport.height}.` : "",
    entry?.html ? `Current HTML to replace or improve: ${String(entry.html).slice(0, 600)}` : "",
  ]
    .filter(Boolean)
    .join(" ");
}

function getAiDialogTargetContext(dialog = state.aiDialog) {
  if (dialog.targetKind === "screen") {
    const sceneDoc = parseSceneTextarea();
    const found = findEntityByRef(sceneDoc, { kind: "screen", id: dialog.targetId });
    const entry = found?.entry ?? null;
    const viewport = entry ? getScreenTextureRenderSize(entry) : null;
    return {
      valid: Boolean(entry),
      error: entry ? "" : "That screen is no longer available.",
      objective: buildScreenAiObjective(entry, getScreenAiPrompt(dialog.targetId)),
      targetLabel: entry ? getDisplayNameForEntity("screen", entry, found?.index ?? 0) : "Screen",
      currentArtifact: entry?.html || "",
      viewportSummary: viewport ? `${viewport.width} x ${viewport.height}` : "",
    };
  }
  if (dialog.targetKind === "script_function") {
    const selectedFunction = getSceneScriptFunctions().find((entry) => entry.id === dialog.targetId) ?? null;
    return {
      valid: Boolean(selectedFunction),
      error: selectedFunction ? "" : "That logic function is no longer available.",
      objective: buildSceneLogicAiObjective(elements.scriptFunctionPrompt?.value ?? "", {
        selectedFunction,
      }),
      targetLabel: selectedFunction?.name ? `Logic function ${selectedFunction.name}` : "Scene logic function",
      currentArtifact: selectedFunction?.body || "",
      viewportSummary: "",
      entityContext: buildSceneLogicEntityContext(),
    };
  }
  if (dialog.targetKind === "new_script_function") {
    const createdFunction = getSceneScriptFunctions().find((entry) => entry.id === dialog.createdScriptFunctionId) ?? null;
    const hasScene = Boolean(getSelectedScene());
    return {
      valid: hasScene,
      error: hasScene ? "" : "That scene is no longer available.",
      objective: buildSceneLogicAiObjective(elements.scriptFunctionPrompt?.value ?? "", {
        selectedFunction: createdFunction,
        createNewFunction: !createdFunction,
      }),
      targetLabel: createdFunction?.name ? `Logic function ${createdFunction.name}` : "New scene logic function",
      currentArtifact: createdFunction?.body || "",
      viewportSummary: "",
      entityContext: buildSceneLogicEntityContext(),
    };
  }
  if (dialog.artifactType === "texture") {
    if (dialog.targetKind === "world" || !dialog.targetId) {
      return {
        valid: true,
        error: "",
        objective: [
          String(elements.aiForm?.elements?.objective?.value ?? "").trim(),
          "Generate a reusable texture asset for this world.",
        ].filter(Boolean).join(" "),
        targetLabel: "Texture library asset",
        currentArtifact: "",
        viewportSummary: "",
        entityContext: "",
      };
    }
    const sceneDoc = parseSceneTextarea();
    const found = findEntityByRef(sceneDoc, { kind: dialog.targetKind, id: dialog.targetId });
    const entry = found?.entry ?? null;
    return {
      valid: Boolean(entry),
      error: entry ? "" : "That object is no longer available.",
      objective: [
        String(elements.aiForm?.elements?.objective?.value ?? "").trim(),
        `Generate a reusable texture for ${getDisplayNameForEntity(dialog.targetKind, entry || {}, found?.index ?? 0)}.`,
      ].filter(Boolean).join(" "),
      targetLabel: entry ? getDisplayNameForEntity(dialog.targetKind, entry, found?.index ?? 0) : "Texture target",
      currentArtifact: entry ? JSON.stringify(entry.material ?? {}, null, 2) : "",
      viewportSummary: "",
      entityContext: entry ? buildEntitySummary(dialog.targetKind, entry) : "",
    };
  }
  if (dialog.artifactType === "3d_model") {
    const sceneDoc = parseSceneTextarea();
    const found = dialog.targetId ? findEntityByRef(sceneDoc, { kind: dialog.targetKind, id: dialog.targetId }) : null;
    const entry = found?.entry ?? null;
    return {
      valid: true,
      error: "",
      objective: [
        String(elements.aiForm?.elements?.objective?.value ?? "").trim(),
        "Generate a reusable Mauworld 3D model library asset.",
      ].filter(Boolean).join(" "),
      targetLabel: entry ? getDisplayNameForEntity(dialog.targetKind, entry, found?.index ?? 0) : "Model library asset",
      currentArtifact: entry ? JSON.stringify(entry, null, 2) : "",
      viewportSummary: "",
      entityContext: entry ? buildEntitySummary(dialog.targetKind, entry) : "",
    };
  }
  return {
    valid: true,
    error: "",
    objective: String(elements.aiForm?.elements?.objective?.value ?? "").trim(),
    targetLabel: dialog.artifactType === "screen_html" ? "Scratch screen output" : "Scratch script output",
    currentArtifact: String(elements.aiOutput?.value ?? "").trim(),
    viewportSummary: "",
    entityContext: "",
  };
}

function buildAiRequestOptions(dialog = state.aiDialog) {
  if (!state.selectedWorld) {
    throw new Error("Open a world before using AI Builder.");
  }
  if (!state.session) {
    throw new Error("Sign in to use AI Builder.");
  }
  const reasoning = getAiProviderState("reasoning");
  writeAiProviderState("reasoning", reasoning);
  if (!reasoning.apiKey) {
    throw new Error("Missing text reasoning API key");
  }
  const targetContext = getAiDialogTargetContext(dialog);
  if (!targetContext.valid) {
    throw new Error(targetContext.error || "That AI target is no longer available.");
  }
  const isWorldScriptArtifact = dialog.artifactType === "world_script";
  return {
    provider: reasoning.provider,
    model: reasoning.model || getDefaultAiModelForGroup("reasoning", reasoning.provider),
    apiKey: reasoning.apiKey,
    artifactType: dialog.artifactType,
    worldName: state.selectedWorld.name,
    worldAbout: state.selectedWorld.about,
    objective: targetContext.objective,
    sceneSummary: JSON.stringify(getSelectedScene()?.compiled_doc?.stats ?? {}),
    targetLabel: targetContext.targetLabel,
    currentArtifact: targetContext.currentArtifact,
    viewportSummary: targetContext.viewportSummary,
    entityContext: isWorldScriptArtifact
      ? (targetContext.entityContext || buildSceneLogicEntityContext())
      : targetContext.entityContext,
    scriptModuleContext: isWorldScriptArtifact ? buildSceneLogicModuleContext() : "",
    scriptTargetContext: isWorldScriptArtifact ? buildSceneLogicTargetCatalogContext() : "",
    scriptLibraryContext: isWorldScriptArtifact ? buildSceneLogicLibraryContext() : "",
  };
}

function buildAiDialogValidationDiagnosticsPayload(diagnostics = []) {
  return (Array.isArray(diagnostics) ? diagnostics : [])
    .map((issue) => ({
      line: Number(issue?.line) || 0,
      message: String(issue?.message ?? "").trim(),
    }))
    .filter((issue) => issue.message)
    .slice(0, 12);
}

function selectAiDialogThread(threadId = "") {
  const normalizedThreadId = String(threadId ?? "").trim();
  if (!normalizedThreadId || state.aiDialog.busy) {
    return false;
  }
  const threads = ensureAiDialogThreads(state.aiDialog);
  if (!threads.some((thread) => thread.id === normalizedThreadId)) {
    return false;
  }
  state.aiDialog.activeThreadId = normalizedThreadId;
  const nextThread = threads.find((thread) => thread.id === normalizedThreadId) ?? null;
  if (!String(nextThread?.result ?? "").trim()) {
    state.aiDialog.activePane = "conversation";
  }
  setAiDialogStatus("", "");
  persistAiDialogThreadState();
  renderAiDialog();
  window.setTimeout(() => {
    elements.aiDialogInput?.focus?.();
  }, 0);
  return true;
}

function createAiDialogThread(options = {}) {
  const thread = createEmptyAiDialogThread();
  const threads = ensureAiDialogThreads(state.aiDialog);
  threads.push(thread);
  state.aiDialog.activeThreadId = thread.id;
  state.aiDialog.activePane = "conversation";
  setAiDialogStatus(options.status ?? "Started a fresh brainstorm thread.", "success");
  persistAiDialogThreadState();
  renderAiDialog();
  if (options.focus !== false) {
    window.setTimeout(() => {
      elements.aiDialogInput?.focus?.();
    }, 0);
  }
  return thread;
}

function deleteAiDialogThread(threadId = "") {
  const normalizedThreadId = String(threadId ?? "").trim();
  if (!normalizedThreadId || state.aiDialog.busy) {
    return false;
  }
  const threads = ensureAiDialogThreads(state.aiDialog);
  const index = threads.findIndex((thread) => thread.id === normalizedThreadId);
  if (index < 0 || threads.length <= 1) {
    return false;
  }
  if (typeof window.confirm === "function" && !window.confirm("Delete this brainstorm thread?")) {
    return false;
  }
  threads.splice(index, 1);
  if (state.aiDialog.activeThreadId === normalizedThreadId) {
    state.aiDialog.activeThreadId = threads[Math.max(0, index - 1)]?.id || threads[0]?.id || "";
  }
  setAiDialogStatus("Deleted brainstorm thread.", "success");
  persistAiDialogThreadState();
  renderAiDialog();
  return true;
}

function openAiDialog(config = {}) {
  const key = getAiDialogThreadKey(config);
  const stored = cloneAiDialogState(state.aiThreadDrafts.get(key) ?? {});
  state.aiDialog = cloneAiDialogState({
    ...stored,
    ...config,
    open: true,
    key,
    busy: false,
    status: "",
    statusTone: "",
  });
  updateShellState();
  renderAiDialog();
  const seedPrompt = String(config.seedPrompt ?? "").trim();
  const activeThread = getActiveAiDialogThread(state.aiDialog);
  const shouldAutoStart = Boolean(seedPrompt)
    && !activeThread.messages.length
    && !activeThread.result
    && !activeThread.generatedAsset;
  if (shouldAutoStart) {
    void sendAiDialogMessage(seedPrompt);
    return;
  }
  window.setTimeout(() => {
    elements.aiDialogInput?.focus?.();
  }, 0);
}

async function sendAiDialogMessage(seedText = "") {
  const activeThread = getActiveAiDialogThread();
  const message = String(seedText || activeThread.input || "").trim();
  if (!message) {
    setAiDialogStatus("Add a short brief first.", "error");
    renderAiDialog();
    elements.aiDialogInput?.focus?.();
    return;
  }
  const nextMessages = [...activeThread.messages, { role: "user", text: message }];
  activeThread.messages = nextMessages;
  activeThread.input = "";
  activeThread.result = "";
  activeThread.awaitingValidationClarification = false;
  activeThread.generatedAsset = null;
  touchAiDialogThread(activeThread);
  state.aiDialog.busy = true;
  setAiDialogStatus("Thinking through assumptions and questions...", "");
  persistAiDialogThreadState();
  renderAiDialog();
  try {
    const request = buildAiRequestOptions();
    const endpoint = state.aiDialog.artifactType === "texture" || state.aiDialog.artifactType === "3d_model"
      ? "/private/assets/ai/brainstorm"
      : "/private/worlds/ai/brainstorm";
    const payload = await apiFetch(endpoint, {
      method: "POST",
      body: {
        ...request,
        messages: nextMessages,
      },
    });
    const reply = String(payload.text ?? "").trim() || "I need a little more detail before I can help shape this.";
    activeThread.messages = [...nextMessages, { role: "assistant", text: reply }];
    touchAiDialogThread(activeThread);
    state.aiDialog.busy = false;
    setAiDialogStatus("AI replied. Revise the thread or generate when it feels right.", "success");
    persistAiDialogThreadState();
    renderAiDialog();
    window.setTimeout(() => {
      elements.aiDialogInput?.focus?.();
    }, 0);
  } catch (error) {
    state.aiDialog.busy = false;
    setAiDialogStatus(error.message, "error");
    persistAiDialogThreadState();
    renderAiDialog();
    handleAiGenerationError(error, { confirm: false });
  }
}

function applyAiDialogAssetToTarget(asset = getActiveAiDialogThread().generatedAsset) {
  if (!asset?.id) {
    return {
      ok: false,
      error: state.aiDialog.artifactType === "texture"
        ? "Generate a texture asset first."
        : "Generate a model asset first.",
    };
  }
  if (state.aiDialog.targetKind === "world") {
    return {
      ok: true,
      applied: false,
      message: "Final asset created and saved in your library.",
    };
  }
  const applied = state.aiDialog.artifactType === "texture"
    ? applyTextureAssetToSelection(asset.id, {
      targetKind: state.aiDialog.targetKind,
      targetId: state.aiDialog.targetId,
    })
    : applyModelAssetToSelection(asset.id, {
      targetKind: state.aiDialog.targetKind,
      targetId: state.aiDialog.targetId,
    });
  if (!applied) {
    return {
      ok: false,
      error: state.aiDialog.artifactType === "texture"
        ? "That texture target is no longer available."
        : "That model target is no longer available.",
    };
  }
  return {
    ok: true,
    applied: true,
    message: state.aiDialog.artifactType === "texture"
      ? "Applied texture to the selected item."
      : "Applied model to the selected item.",
  };
}

function applyAiDialogTextToTarget(result = "") {
  const normalizedResult = String(result ?? "").trim();
  if (!normalizedResult) {
    return {
      ok: false,
      error: "Generate something first.",
    };
  }
  if (state.aiDialog.targetKind === "screen") {
    let applied = false;
    mutateSceneDoc((sceneDoc) => {
      const found = findEntityByRef(sceneDoc, { kind: "screen", id: state.aiDialog.targetId });
      if (!found?.entry) {
        return;
      }
      found.entry.html = normalizedResult;
      applied = true;
    });
    if (!applied) {
      return {
        ok: false,
        error: "That screen is no longer available.",
      };
    }
    return {
      ok: true,
      applied: true,
      appliedResult: normalizedResult,
      message: "Applied to the screen.",
    };
  }
  if (state.aiDialog.targetKind === "script_function") {
    let applied = false;
    const normalizedBody = normalizeGeneratedScriptBody(normalizedResult);
    mutateSceneScriptFunctions((functions) => {
      const target = functions.find((entry) => entry.id === state.aiDialog.targetId);
      if (!target) {
        return;
      }
      target.body = normalizedBody;
      applied = true;
    });
    if (!applied) {
      return {
        ok: false,
        error: "That logic function is no longer available.",
      };
    }
    return {
      ok: true,
      applied: true,
      appliedResult: normalizedBody,
      focusScript: true,
      message: "Applied to the function.",
    };
  }
  if (state.aiDialog.targetKind === "new_script_function") {
    let applied = false;
    let createdEntry = null;
    let updatedExisting = false;
    const normalizedBody = normalizeGeneratedScriptBody(normalizedResult);
    mutateSceneScriptFunctions((functions) => {
      const existingTarget = functions.find((entry) => entry.id === state.aiDialog.createdScriptFunctionId) ?? null;
      if (existingTarget) {
        existingTarget.body = normalizedBody;
        createdEntry = existingTarget;
        updatedExisting = true;
      } else {
        const nextEntry = normalizeScriptFunctionEntry({
          id: createScriptFunctionId("generated_logic"),
          name: buildScriptTemplateFunctionName(functions, "Generated Function"),
          body: normalizedBody,
        }, functions.length);
        functions.push(nextEntry);
        createdEntry = nextEntry;
        state.aiDialog.createdScriptFunctionId = nextEntry.id;
      }
      state.aiDialog.title = `Brainstorm ${createdEntry?.name || "Generated Function"}`;
      state.selectedScriptFunctionId = createdEntry?.id || "";
      applied = true;
    });
    if (!applied || !createdEntry) {
      return {
        ok: false,
        error: "Could not create the new logic function.",
      };
    }
    return {
      ok: true,
      applied: true,
      appliedResult: normalizedBody,
      focusScript: true,
      message: updatedExisting
        ? `Updated ${createdEntry?.name || "the generated function"}.`
        : `Created ${createdEntry?.name || "a new function"} and applied the script.`,
    };
  }
  if (elements.aiOutput) {
    elements.aiOutput.value = normalizedResult;
  }
  return {
    ok: true,
    applied: false,
    appliedResult: normalizedResult,
    message: "Saved as the latest result in AI Builder.",
  };
}

async function generateAiDialogResult() {
  const activeThread = getActiveAiDialogThread();
  if (!activeThread.messages.some((entry) => entry.role === "assistant")) {
    setAiDialogStatus("Ask AI first so it can answer with assumptions and questions before you generate.", "error");
    renderAiDialog();
    return;
  }
  if (String(activeThread.input || "").trim()) {
    setAiDialogStatus("Send your latest revision to AI first, then generate from the updated thread.", "error");
    renderAiDialog();
    elements.aiDialogInput?.focus?.();
    return;
  }
  const kind = state.aiDialog.artifactType === "screen_html"
    ? "html"
    : state.aiDialog.artifactType === "world_script"
      ? "script"
      : state.aiDialog.artifactType;
  state.aiDialog.busy = true;
  setAiDialogStatus(
    kind === "html"
      ? "Generating final HTML..."
      : kind === "script"
        ? "Generating final script..."
        : kind === "texture"
          ? "Generating texture asset..."
          : "Generating 3D model asset...",
    "",
  );
  renderAiDialog();
  try {
    const request = buildAiRequestOptions();
    let finalStatusMessage = "Final result ready.";
    let finalStatusTone = "success";
    if (kind === "texture" || kind === "3d_model") {
      const reasoning = getAiProviderState("reasoning");
      const generationSettings = kind === "texture" ? getAiProviderState("image") : getAiProviderState("model");
      const endpoint = kind === "texture" ? "/private/assets/ai/texture" : "/private/assets/ai/model";
      if (!generationSettings.apiKey) {
        throw new Error(kind === "texture" ? "Missing image texture API key" : "Missing 3D model API key");
      }
      writeAiProviderState(kind === "texture" ? "image" : "model", generationSettings);
      const payload = await apiFetch(endpoint, {
        method: "POST",
        timeoutMs: kind === "3d_model" ? 300000 : 60000,
        body: {
          worldId: state.selectedWorld.world_id,
          worldName: state.selectedWorld.name,
          worldAbout: state.selectedWorld.about,
          objective: request.objective,
          sceneSummary: request.sceneSummary,
          messages: activeThread.messages,
          targetLabel: request.targetLabel,
          currentArtifact: request.currentArtifact,
          entityContext: request.entityContext,
          reasoningProvider: reasoning.provider,
          reasoningModel: reasoning.model || "gpt-5.4-mini",
          reasoningApiKey: reasoning.apiKey,
          imageProvider: kind === "texture" ? generationSettings.provider : undefined,
          imageModel: kind === "texture" ? generationSettings.model : undefined,
          imageApiKey: kind === "texture" ? generationSettings.apiKey : undefined,
          modelProvider: kind === "3d_model" ? generationSettings.provider : undefined,
          modelModel: kind === "3d_model" ? generationSettings.model : undefined,
          modelApiKey: kind === "3d_model" ? generationSettings.apiKey : undefined,
        },
      });
      activeThread.generatedAsset = payload.asset || null;
      activeThread.result = payload.asset ? JSON.stringify(payload.asset, null, 2) : "";
      touchAiDialogThread(activeThread);
      await loadAssets();
      const applyOutcome = applyAiDialogAssetToTarget(activeThread.generatedAsset);
      if (!applyOutcome.ok) {
        finalStatusMessage = `${applyOutcome.error} The asset is still saved in your library.`;
        finalStatusTone = "error";
      } else if (applyOutcome.applied) {
        finalStatusMessage = kind === "texture"
          ? "Final texture asset created and applied to the selected item."
          : "Final 3D model asset created and applied to the selected item.";
      } else {
        finalStatusMessage = applyOutcome.message;
      }
      state.aiDialog.activePane = "result";
    } else {
      let scriptRepairAttempts = 0;
      if (kind === "script") {
        const generation = await generateValidatedAiDialogScriptResult({
          objective: request.objective,
          sceneSummary: request.sceneSummary,
          messages: activeThread.messages,
          targetLabel: request.targetLabel,
          currentArtifact: request.currentArtifact,
          viewportSummary: request.viewportSummary,
          entityContext: request.entityContext,
          scriptModuleContext: request.scriptModuleContext,
          scriptTargetContext: request.scriptTargetContext,
          scriptLibraryContext: request.scriptLibraryContext,
        });
        scriptRepairAttempts = generation.attempts;
        activeThread.result = generation.validation.normalizedBody;
        activeThread.generatedAsset = null;
        activeThread.awaitingValidationClarification = false;
        if (!generation.validation.ok) {
          state.aiDialog.busy = false;
          if (generation.validation.requiresUserClarification !== true) {
            setAiDialogStatus(generation.validation.diagnostics[0]?.message || "The generated script could not be validated.", "error");
            persistAiDialogThreadState();
            renderAiDialog();
            return;
          }
          handleAiDialogInvalidScriptResult(generation.validation, activeThread);
          return;
        }
      } else {
        const generatedText = await generateAi(kind, {
          objective: request.objective,
          sceneSummary: request.sceneSummary,
          messages: activeThread.messages,
          targetLabel: request.targetLabel,
          currentArtifact: request.currentArtifact,
          viewportSummary: request.viewportSummary,
          entityContext: request.entityContext,
          outputTarget: elements.aiDialogResult,
          mirrorToAiOutput: state.aiDialog.targetKind === "world",
        });
        activeThread.result = String(generatedText ?? "").trim();
      }
      activeThread.generatedAsset = null;
      activeThread.awaitingValidationClarification = false;
      touchAiDialogThread(activeThread);
      const applyOutcome = applyAiDialogTextToTarget(activeThread.result);
      if (applyOutcome.appliedResult) {
        activeThread.result = applyOutcome.appliedResult;
      }
      if (!applyOutcome.ok) {
        finalStatusMessage = `${applyOutcome.error} The generated result is still available below.`;
        finalStatusTone = "error";
      } else if (applyOutcome.applied) {
        finalStatusMessage = kind === "html"
          ? "Generated HTML and applied to the screen."
          : (scriptRepairAttempts > 1
              ? "Generated script, repaired it against scene validation, and applied it to the function."
              : "Generated script and applied to the function.");
      } else {
        finalStatusMessage = applyOutcome.message;
      }
      state.aiDialog.activePane = "result";
      if (applyOutcome.focusScript) {
        focusSelectedScriptFunctionBody();
      }
    }
    state.aiDialog.busy = false;
    setAiDialogStatus(finalStatusMessage, finalStatusTone);
    persistAiDialogThreadState();
    renderAiDialog();
  } catch (error) {
    state.aiDialog.busy = false;
    setAiDialogStatus(error.message, "error");
    persistAiDialogThreadState();
    renderAiDialog();
    handleAiGenerationError(error, { confirm: false });
  }
}

function applyAiDialogResult() {
  const activeThread = getActiveAiDialogThread();
  const result = String(elements.aiDialogResult?.value ?? activeThread.result ?? "").trim();
  activeThread.result = result;
  let applyOutcome = null;
  if (state.aiDialog.artifactType === "texture" || state.aiDialog.artifactType === "3d_model") {
    applyOutcome = applyAiDialogAssetToTarget(activeThread.generatedAsset);
  } else {
    const validation = buildAiDialogScriptValidationResult(result);
    if (!validation.ok) {
      activeThread.result = validation.normalizedBody;
      if (validation.requiresUserClarification !== true) {
        setAiDialogStatus(validation.diagnostics[0]?.message || "The generated script could not be validated.", "error");
        persistAiDialogThreadState();
        renderAiDialog();
        return;
      }
      handleAiDialogInvalidScriptResult(validation, activeThread);
      return;
    }
    activeThread.result = validation.normalizedBody;
    activeThread.awaitingValidationClarification = false;
    applyOutcome = applyAiDialogTextToTarget(activeThread.result);
    if (applyOutcome.appliedResult) {
      activeThread.result = applyOutcome.appliedResult;
    }
  }
  if (!applyOutcome.ok) {
    setAiDialogStatus(applyOutcome.error, "error");
    renderAiDialog();
    return;
  }
  setAiDialogStatus(applyOutcome.message, "success");
  persistAiDialogThreadState();
  renderAiDialog();
  if (applyOutcome.focusScript) {
    focusSelectedScriptFunctionBody();
  }
}

function focusAiBuilder(fieldName = "reasoningApiKey") {
  setWorldPanelSection("ai", { fieldName });
}

function promptForAiBuilder(message, options = {}) {
  const fieldName = options.fieldName || "reasoningApiKey";
  setAiBuilderStatus(message, "error");
  setStatus(message);
  if (state.selectedWorld) {
    setPrivatePanelTab("world");
  }
  let shouldOpen = true;
  if (options.confirm !== false && typeof window.confirm === "function") {
    shouldOpen = window.confirm(`${message}\n\nOpen AI Builder now?`);
  }
  if (shouldOpen) {
    focusAiBuilder(fieldName);
  }
}

function handleAiGenerationError(error, options = {}) {
  const message = String(error?.message || "Could not generate with AI.");
  if (/missing text reasoning api key/i.test(message)) {
    promptForAiBuilder("AI Builder needs your text reasoning API key before it can generate.", {
      fieldName: "reasoningApiKey",
      confirm: options.confirm !== false,
    });
    return;
  }
  if (/missing image texture api key/i.test(message)) {
    promptForAiBuilder("AI Builder needs your image texture API key before it can generate textures.", {
      fieldName: "imageApiKey",
      confirm: options.confirm !== false,
    });
    return;
  }
  if (/missing 3d model api key/i.test(message)) {
    promptForAiBuilder("AI Builder needs your 3D model API key before it can generate models.", {
      fieldName: "modelApiKey",
      confirm: options.confirm !== false,
    });
    return;
  }
  if (/unsupported ai provider/i.test(message)) {
    promptForAiBuilder(message, {
      fieldName: "reasoningProvider",
      confirm: options.confirm !== false,
    });
    return;
  }
  setAiBuilderStatus(message, "error");
  setStatus(message);
}

function getJoinAnchorPayload() {
  const params = new URLSearchParams(window.location.search);
  const asNumber = (key) => {
    const raw = params.get(key);
    if (raw == null || raw === "") {
      return undefined;
    }
    const value = Number(raw);
    return Number.isFinite(value) ? value : undefined;
  };
  return {
    publicWorldSnapshotId: params.get("publicWorldSnapshotId") || undefined,
    publicViewerSessionId: getPublicViewerSessionIdForPrivateJoin(params),
    position_x: asNumber("anchorX") ?? 0,
    position_y: asNumber("anchorY") ?? 0,
    position_z: asNumber("anchorZ") ?? 0,
  };
}

function getLaunchRequest() {
  const params = new URLSearchParams(window.location.search);
  const worldId = String(params.get("worldId") ?? "").trim();
  const creatorUsername = String(params.get("creatorUsername") ?? "").trim();
  return {
    worldId: worldId || "",
    creatorUsername: creatorUsername || "",
    autojoin: params.get("autojoin") === "true",
    fork: params.get("fork") === "true",
  };
}

function getLauncherIntent() {
  const params = new URLSearchParams(window.location.search);
  return {
    create: params.get("intent") === "create",
  };
}

function selectedWorldMatchesLaunchRequest(launch = getLaunchRequest(), world = state.selectedWorld) {
  if (!launch?.worldId || !launch?.creatorUsername || !world?.world_id || !world?.creator?.username) {
    return false;
  }
  return (
    String(world.world_id).trim() === String(launch.worldId).trim()
    && String(world.creator.username).trim().toLowerCase() === String(launch.creatorUsername).trim().toLowerCase()
  );
}

function normalizeRuntimeKey(event) {
  return normalizePrivateInputKey(event);
}

function focusPrivateWorldCanvas(options = {}) {
  const canvas = elements.previewCanvas;
  if (!(canvas instanceof HTMLCanvasElement)) {
    return false;
  }
  if (options.blurActiveElement !== false) {
    const activeElement = document.activeElement;
    if (
      activeElement
      && activeElement !== canvas
      && activeElement instanceof HTMLElement
      && (
        activeElement instanceof HTMLInputElement
        || activeElement instanceof HTMLTextAreaElement
        || activeElement instanceof HTMLSelectElement
        || activeElement instanceof HTMLButtonElement
        || activeElement.isContentEditable
      )
    ) {
      activeElement.blur();
    }
  }
  if (document.activeElement === canvas) {
    return true;
  }
  canvas.focus({ preventScroll: true });
  return document.activeElement === canvas;
}

function buildSocketUrl(worldId, creatorUsername) {
  const url = new URL(
    mauworldApiUrl("/ws/private/worlds", {
      worldId,
      creatorUsername,
      accessToken: state.session?.access_token || "",
      viewerSessionId: getPrivateViewerSessionId(),
      guestSessionId: state.session ? "" : getGuestSessionId(),
    }),
  );
  url.protocol = url.protocol === "https:" ? "wss:" : "ws:";
  return url.toString();
}

function sendWorldSocketMessage(payload) {
  if (!state.worldSocket || state.worldSocket.readyState !== WebSocket.OPEN) {
    return false;
  }
  if (typeof window !== "undefined" && window.__mwPrivateDebug) {
    const history = Array.isArray(window.__mwPrivateDebug.sentMessages)
      ? window.__mwPrivateDebug.sentMessages
      : [];
    history.push({
      at: Date.now(),
      payload: cloneJson(payload),
    });
    if (history.length > 40) {
      history.splice(0, history.length - 40);
    }
    window.__mwPrivateDebug.sentMessages = history;
  }
  state.worldSocket.send(JSON.stringify(payload));
  return true;
}

function getPrivatePresencePosition() {
  const possessed = getPossessedRuntimePlayer();
  const prediction = state.predictedPossessedPlayer;
  if (prediction?.playerId && possessed?.id === prediction.playerId) {
    return {
      x: prediction.position.x,
      y: prediction.position.y,
      z: prediction.position.z,
      heading: Number(prediction.rotation?.y ?? privateInputState.yaw) || privateInputState.yaw,
    };
  }
  if (possessed?.position) {
    return {
      x: Number(possessed.position.x ?? 0) || 0,
      y: Number(possessed.position.y ?? PRIVATE_CAMERA.minY) || PRIVATE_CAMERA.minY,
      z: Number(possessed.position.z ?? 0) || 0,
      heading: Number(possessed.rotation?.y ?? privateInputState.yaw) || privateInputState.yaw,
    };
  }
  return {
    x: state.viewerPosition.x,
    y: state.viewerPosition.y,
    z: state.viewerPosition.z,
    heading: privateInputState.yaw,
  };
}

function getLocalPossessedPlayerPosePayload(options = {}) {
  const runtimePlayer = getPossessedRuntimePlayer();
  const prediction = getLocalPossessedPlayerPrediction();
  const source = prediction ?? runtimePlayer;
  if (!source) {
    return null;
  }
  const positionX = Number(source.position?.x);
  const positionY = Number(source.position?.y);
  const positionZ = Number(source.position?.z);
  const velocityX = Number(source.velocity?.x);
  const velocityY = Number(source.velocity?.y);
  const velocityZ = Number(source.velocity?.z);
  const bodyMode = String(source.bodyMode ?? source.body_mode ?? runtimePlayer?.body_mode ?? "rigid").trim().toLowerCase();
  const includePlanarForRigid = options.includePlanarForRigid !== false;
  const includeVerticalForRigid = options.includeVerticalForRigid === true;
  const includeVerticalPose = bodyMode === "ghost" || (includeVerticalForRigid && bodyMode !== "ghost");
  if (!includeVerticalPose && !includePlanarForRigid) {
    return null;
  }
  return {
    position_x: Number((Number.isFinite(positionX) ? positionX : 0).toFixed(4)),
    position_z: Number((Number.isFinite(positionZ) ? positionZ : 0).toFixed(4)),
    velocity_x: Number((Number.isFinite(velocityX) ? velocityX : 0).toFixed(4)),
    velocity_z: Number((Number.isFinite(velocityZ) ? velocityZ : 0).toFixed(4)),
    position_y: includeVerticalPose
      ? Number((Number.isFinite(positionY) ? positionY : PRIVATE_CAMERA.minY).toFixed(4))
      : undefined,
    velocity_y: includeVerticalPose
      ? Number((Number.isFinite(velocityY) ? velocityY : 0).toFixed(4))
      : undefined,
  };
}

function getPrivatePlayerReleaseSpawn(playerEntityId = "", world = state.selectedWorld) {
  const resolvedPlayerId = resolvePrivatePlayerEntityId(playerEntityId, getRuntimePlayerIds()) ?? String(playerEntityId ?? "").trim();
  if (!resolvedPlayerId) {
    return null;
  }
  const activeSceneId = String(world?.active_instance?.active_scene_id ?? "").trim();
  const activeScene = world?.scenes?.find((entry) => String(entry?.id ?? "").trim() === activeSceneId)
    ?? getSelectedScene()
    ?? null;
  const sceneDoc = activeScene?.compiled_doc?.runtime?.resolved_scene_doc ?? activeScene?.scene_doc ?? null;
  const players = Array.isArray(sceneDoc?.players) ? sceneDoc.players : [];
  const runtimePlayerIds = getRuntimePlayerIds();
  const playerEntry = players.find((entry) => {
    const authoredPlayerId = String(entry?.id ?? "").trim();
    if (!authoredPlayerId) {
      return false;
    }
    const canonicalPlayerId = resolvePrivatePlayerEntityId(authoredPlayerId, runtimePlayerIds) ?? authoredPlayerId;
    return canonicalPlayerId === resolvedPlayerId || authoredPlayerId === resolvedPlayerId;
  }) ?? null;
  if (!playerEntry) {
    return null;
  }
  const positionX = Number(playerEntry.position?.x);
  const positionY = Number(playerEntry.position?.y);
  const positionZ = Number(playerEntry.position?.z);
  const headingY = Number(playerEntry.rotation?.y);
  return {
    player_entity_id: resolvedPlayerId,
    position_x: Number.isFinite(positionX) ? positionX : 0,
    position_y: Number.isFinite(positionY) ? positionY : PRIVATE_CAMERA.minY,
    position_z: Number.isFinite(positionZ) ? positionZ : 0,
    heading_y: Number.isFinite(headingY) ? headingY : 0,
  };
}

function applyPrivateViewerReleaseSpawn(spawn = null) {
  if (!spawn) {
    return false;
  }
  const nextX = Number(spawn.position_x);
  const nextY = Number(spawn.position_y);
  const nextZ = Number(spawn.position_z);
  if (Number.isFinite(nextX)) {
    state.viewerPosition.x = nextX;
  }
  if (Number.isFinite(nextY)) {
    state.viewerPosition.y = nextY;
  }
  if (Number.isFinite(nextZ)) {
    state.viewerPosition.z = nextZ;
  }
  clampViewerPositionToWorldBounds(state.viewerPosition);
  privateInputState.jumpGroundY = state.viewerPosition.y;
  privateInputState.jumpVelocityY = 0;
  privateInputState.jumpHeld = false;
  const headingY = Number(spawn.heading_y);
  if (Number.isFinite(headingY)) {
    privateInputState.yaw = normalizeAngle(headingY);
  }
  if (state.preview?.viewerAvatar) {
    state.preview.viewerAvatar.position.copy(state.viewerPosition);
    state.preview.viewerAvatar.lastPosition.copy(state.viewerPosition);
    state.preview.viewerAvatar.group.position.copy(state.viewerPosition);
    state.preview.viewerAvatar.facingYaw = normalizeAngle(privateInputState.yaw + Math.PI);
  }
  return true;
}

function sendPrivatePresence(force = false) {
  const localParticipant = getLocalParticipant();
  if (!state.joined || !localParticipant) {
    return false;
  }
  const now = performance.now();
  const minIntervalMs = localParticipant.join_role === "player"
    ? PRIVATE_POSSESSED_PRESENCE_INTERVAL_MS
    : 120;
  if (!force && now - state.lastPresenceSentAt < minIntervalMs) {
    return false;
  }
  state.lastPresenceSentAt = now;
  const position = getPrivatePresencePosition();
  const payload = {
    type: "presence:update",
    position_x: Number(position.x.toFixed(4)),
    position_y: Number(position.y.toFixed(4)),
    position_z: Number(position.z.toFixed(4)),
    heading_y: Number(position.heading.toFixed(4)),
    join_role: String(localParticipant.join_role ?? "viewer").trim() || "viewer",
    player_entity_id: localParticipant.player_entity_id ?? null,
  };
  const possessedPose = getLocalPossessedPlayerPosePayload({
    includePlanarForRigid: true,
    includeVerticalForRigid: true,
  });
  if (possessedPose && localParticipant.join_role === "player") {
    payload.motion_seq = nextPrivateMotionSequence();
    payload.position_x = possessedPose.position_x;
    payload.position_y = possessedPose.position_y;
    payload.position_z = possessedPose.position_z;
    payload.velocity_x = possessedPose.velocity_x;
    payload.velocity_y = possessedPose.velocity_y;
    payload.velocity_z = possessedPose.velocity_z;
    payload.force_runtime_pose = true;
  }
  const socketSent = sendWorldSocketMessage(payload);
  if (
    possessedPose
    && localParticipant.join_role === "player"
    && state.selectedWorld
  ) {
    const shouldMirrorHttp =
      force
      || !socketSent
      || now - Number(state.lastPresenceHttpMirrorAt ?? 0) >= PRIVATE_POSSESSED_PRESENCE_HTTP_MIRROR_MS;
    if (shouldMirrorHttp) {
      state.lastPresenceHttpMirrorAt = now;
      void apiFetch(`/private/worlds/${encodeURIComponent(state.selectedWorld.world_id)}/input`, {
        method: "POST",
        body: {
          creatorUsername: state.selectedWorld.creator.username,
          heading_y: payload.heading_y,
          position_x: payload.position_x,
          position_y: payload.position_y,
          position_z: payload.position_z,
          velocity_x: payload.velocity_x,
          velocity_y: payload.velocity_y,
          velocity_z: payload.velocity_z,
          motion_seq: payload.motion_seq,
          force_client_pose: true,
        },
      }).catch(() => {});
    }
  }
  return socketSent;
}

function buildRuntimeDynamicInteractionPayloads() {
  if (!state.joined || getLocalParticipant()?.join_role !== "player") {
    return [];
  }
  const runtime = state.runtimeSnapshot ?? state.selectedWorld?.active_instance?.runtime ?? null;
  const dynamicObjects = Array.isArray(runtime?.dynamic_objects) ? runtime.dynamic_objects : [];
  if (!dynamicObjects.length) {
    return [];
  }
  const nowMs = performance.now();
  const payloads = [];
  for (const entry of dynamicObjects) {
    const objectId = String(entry?.id ?? "").trim();
    if (!objectId) {
      continue;
    }
    const mesh = state.preview?.entityMeshes?.get(objectId) ?? null;
    const motionState = mesh?.userData?.privateWorldRuntimeMotionState ?? null;
    if (!motionState?.initialized) {
      continue;
    }
    if (Number(motionState.localInteractionUntilMs ?? 0) <= nowMs) {
      continue;
    }
    payloads.push({
      object_id: objectId,
      interaction_seq: nextPrivateMotionSequence(),
      position_x: Number((Number(motionState.renderPosition?.x ?? mesh.position.x ?? 0) || 0).toFixed(4)),
      position_y: Number((Number(motionState.renderPosition?.y ?? mesh.position.y ?? 0) || 0).toFixed(4)),
      position_z: Number((Number(motionState.renderPosition?.z ?? mesh.position.z ?? 0) || 0).toFixed(4)),
      velocity_x: Number((Number(motionState.renderVelocity?.x ?? 0) || 0).toFixed(4)),
      velocity_y: Number((Number(motionState.renderVelocity?.y ?? 0) || 0).toFixed(4)),
      velocity_z: Number((Number(motionState.renderVelocity?.z ?? 0) || 0).toFixed(4)),
      rotation_x: Number((Number(entry?.rotation?.x ?? mesh.rotation.x ?? 0) || 0).toFixed(4)),
      rotation_y: Number((Number(entry?.rotation?.y ?? mesh.rotation.y ?? 0) || 0).toFixed(4)),
      rotation_z: Number((Number(entry?.rotation?.z ?? mesh.rotation.z ?? 0) || 0).toFixed(4)),
      angular_velocity_x: Number((Number(entry?.angular_velocity?.x ?? 0) || 0).toFixed(4)),
      angular_velocity_y: Number((Number(entry?.angular_velocity?.y ?? 0) || 0).toFixed(4)),
      angular_velocity_z: Number((Number(entry?.angular_velocity?.z ?? 0) || 0).toFixed(4)),
    });
  }
  return payloads;
}

function sendRuntimeDynamicInteractions(force = false) {
  if (!state.selectedWorld || !state.session || state.entryLoading === true || getLocalParticipant()?.join_role !== "player") {
    return false;
  }
  const interactions = buildRuntimeDynamicInteractionPayloads();
  if (!interactions.length) {
    return false;
  }
  const now = performance.now();
  if (!force && now - Number(state.lastRuntimeInteractionSentAt ?? 0) < PRIVATE_POSSESSED_PRESENCE_INTERVAL_MS) {
    return false;
  }
  state.lastRuntimeInteractionSentAt = now;
  return sendWorldSocketMessage({
    type: "runtime:interactions",
    interactions,
  });
}

function pushPrivateChatEntry(payload = {}) {
  const text = String(payload.text ?? "").trim();
  if (!text) {
    return;
  }
  const actorSessionId = String(payload.actorSessionId ?? payload.viewerSessionId ?? "").trim();
  const expiresAt = payload.expiresAt
    || new Date(Date.now() + Math.max(2200, Math.min(8800, text.length * 82 + 2400))).toISOString();
  const createdAt = payload.createdAt
    ? new Date(payload.createdAt).toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" })
    : new Date().toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" });
  state.privateChatEntries.unshift({
    id: `${Date.now()}_${Math.random().toString(36).slice(2, 8)}`,
    actorSessionId,
    displayName: String(payload.displayName ?? payload.actor?.display_name ?? "viewer").trim() || "viewer",
    text,
    createdAt,
  });
  state.privateChatEntries = state.privateChatEntries.slice(0, PRIVATE_CHAT_MAX_ENTRIES);
  if (actorSessionId) {
    state.activeChats.set(actorSessionId, {
      text,
      mode: payload.mode === "placeholder" ? "placeholder" : "full",
      expiresAt,
    });
    const presenceEntry = state.preview?.presenceEntries?.get(actorSessionId);
    if (presenceEntry) {
      applyPrivateChatBubbleToActor(presenceEntry, state.activeChats.get(actorSessionId));
    }
    if (actorSessionId === getPrivateViewerSessionId() && state.preview?.viewerAvatar) {
      applyPrivateChatBubbleToActor(state.preview.viewerAvatar, state.activeChats.get(actorSessionId));
    }
  }
  renderPrivateChat();
}

function sendPrivateChat(text) {
  const message = String(text ?? "").trim();
  if (!message || !state.selectedWorld || !state.session || !getLocalParticipant()) {
    return false;
  }
  return sendWorldSocketMessage({
    type: "chat:send",
    text: message,
  });
}

const privateChatFeature = createChatFeature({
  input: elements.panelChatInput,
  form: elements.panelChatComposer,
  reactionButtons: elements.panelChatReactionButtons,
  reactionAttribute: "data-private-chat-reaction",
  onAfterInputChange: () => {
    renderPrivateChat();
  },
  onSubmit: sendPrivateChat,
  onBeforeReaction() {
    setPrivatePanelTab("chat");
  },
  onSubmitFailed: () => {
    renderPrivateChat();
  },
  onReactionFailed: () => {
    renderPrivateChat();
  },
});

function openPrivateChatComposer() {
  if (!elements.panelChatInput) {
    return;
  }
  setPrivatePanelTab("chat");
  if (elements.panelChatInput.disabled) {
    return;
  }
  elements.panelChatInput.focus();
  elements.panelChatInput.select();
}

function isEditablePrivateTarget(target) {
  if (!(target instanceof Element)) {
    return false;
  }
  return Boolean(target.closest('input, textarea, select, [contenteditable="true"]'));
}

function isLiveKitBrowserTransport(frameTransport) {
  return String(frameTransport ?? "").startsWith("livekit");
}

function stopMediaStream(stream) {
  stream?.getTracks?.().forEach((track) => track.stop());
}

function setLocalPrivateBrowserPreviewStream(stream = null) {
  state.localBrowserPreviewStream = stream ?? null;
  setPrivateBrowserPreviewStream(state.localBrowserPreviewStream);
}

function ensurePrivateBrowserVideoPlayback(element) {
  if (!element) {
    return;
  }
  const localAudibleStream = state.localBrowserShare?.hasAudio
    ? state.localBrowserShare.stream
    : state.pendingBrowserShare?.hasAudio
      ? state.pendingBrowserShare.stream
      : null;
  const shouldPlayAudio = Boolean(localAudibleStream && element.srcObject === localAudibleStream);
  element.autoplay = true;
  element.playsInline = true;
  element.muted = !shouldPlayAudio;
  element.defaultMuted = !shouldPlayAudio;
  element.volume = shouldPlayAudio ? 1 : 0;
  const playPromise = element.play?.();
  playPromise?.then?.(() => {
    if (state.browserMediaState.lastPlayError) {
      state.browserMediaState.lastPlayError = "";
      updatePrivateBrowserPanel();
    }
  });
  playPromise?.catch?.((error) => {
    const message = String(error?.name || error?.message || "play failed");
    if (state.browserMediaState.lastPlayError !== message) {
      state.browserMediaState.lastPlayError = message;
      updatePrivateBrowserPanel();
    }
  });
}

function resumePrivateBrowserMediaPlayback() {
  const seen = new Set();
  const candidates = [];
  if (elements.panelBrowserVideo) {
    candidates.push(elements.panelBrowserVideo);
  }
  for (const session of state.browserSessions.values()) {
    if (session?._remoteElement) {
      candidates.push(session._remoteElement);
    }
  }
  for (const element of candidates) {
    if (!element || seen.has(element)) {
      continue;
    }
    seen.add(element);
    if (element.srcObject && element.paused) {
      ensurePrivateBrowserVideoPlayback(element);
    }
  }
  void getPrivateBrowserMediaController().resumePlayback({
    sessionId: state.browserPanelRemoteSessionId || state.browserMediaState.remoteAudioSessionId,
    kinds: ["audio", "video"],
  });
}

function setPrivateBrowserPreviewStream(stream) {
  if (!elements.panelBrowserVideo) {
    return;
  }
  if (elements.panelBrowserVideo.srcObject !== stream) {
    elements.panelBrowserVideo.srcObject = stream ?? null;
  }
  elements.panelBrowserVideo.hidden = !stream;
  if (stream) {
    ensurePrivateBrowserVideoPlayback(elements.panelBrowserVideo);
  } else {
    elements.panelBrowserVideo.pause?.();
  }
}

function setPrivateBrowserStatus(text) {
  if (elements.panelBrowserStatus) {
    elements.panelBrowserStatus.textContent = text || "";
  }
}

function updatePrivateBrowserSummary(summary = {}) {
  if (elements.panelBrowserSummaryBadge) {
    elements.panelBrowserSummaryBadge.textContent = summary.badge || "Idle";
    elements.panelBrowserSummaryBadge.dataset.state = summary.state || "idle";
  }
  if (elements.panelBrowserSummaryCurrent) {
    elements.panelBrowserSummaryCurrent.textContent = summary.current || "Not sharing yet";
  }
  if (elements.panelBrowserSummaryHint) {
    elements.panelBrowserSummaryHint.textContent = summary.hint || "";
  }
}

function getPrivateLocalBrowserShareStackEntries() {
  const entries = [];
  for (const session of getLocalPrivateBrowserDisplaySessions()) {
    const shareKind = getPrivateBrowserSessionShareKind(session);
    const active = String(session.sessionId ?? "").trim() === String(state.localBrowserSessionId ?? "").trim();
    entries.push({
      id: String(session.sessionId ?? "").trim(),
      type: "browser",
      label: getBrowserShareKindLabel(shareKind),
      title: getPrivateBrowserSessionTitle(session),
      active,
      stateLabel: active ? "Previewing" : "Live",
      secondary: isPrivateBrowserMemberSession(session) ? "Contributor share" : "Anchor share",
    });
  }
  const localVoiceSession = getLocalPrivateVoiceSession();
  if (localVoiceSession) {
    entries.push({
      id: String(localVoiceSession.sessionId ?? "").trim(),
      type: "voice",
      label: "Voice",
      title: "Persistent voice chat",
      active: false,
      stateLabel: localVoiceSession.groupJoined === true ? "Joined" : "Live",
      secondary: localVoiceSession.groupJoined === true ? "Inside anchor group" : "Open nearby",
    });
  }
  const localGameSession = getLocalPrivateGameSession();
  if (localGameSession) {
    const active = state.browserShareMode === "game";
    entries.push({
      id: String(localGameSession.session_id ?? "").trim(),
      type: "game",
      label: "Game",
      title: getPrivateGameSessionTitle(localGameSession),
      active,
      stateLabel: active ? "Selected" : "Live",
      secondary: isPrivateGameMemberSession(localGameSession) ? "Contributor game" : "Anchor game",
    });
  }
  const order = {
    Screen: 0,
    Video: 1,
    Voice: 2,
    Game: 3,
  };
  return entries.sort((left, right) =>
    (order[left.label] ?? 99) - (order[right.label] ?? 99)
    || Number(right.active) - Number(left.active)
    || left.title.localeCompare(right.title));
}

function renderPrivateLocalBrowserShareStack(entries = getPrivateLocalBrowserShareStackEntries()) {
  if (!elements.panelBrowserLocalStack) {
    return;
  }
  elements.panelBrowserLocalStack.hidden = entries.length === 0;
  if (entries.length === 0) {
    elements.panelBrowserLocalStack.innerHTML = "";
    return;
  }
  const countLabel = entries.length === 1 ? "1 type live" : `${entries.length} types live`;
  elements.panelBrowserLocalStack.innerHTML = `
    <div class="world-local-share-stack__head">
      <strong>Live now</strong>
      <span>${htmlEscape(countLabel)}</span>
    </div>
    <div class="world-local-share-stack__grid">
      ${entries.map((entry) => `
        <section class="world-local-share-card ${entry.active ? "is-active" : ""}" data-private-local-share-id="${htmlEscape(entry.id)}" data-private-local-share-type="${htmlEscape(entry.type)}">
          <div class="world-local-share-card__top">
            <span class="world-local-share-card__badge">${htmlEscape(entry.label)}</span>
            <span class="world-local-share-card__state">${htmlEscape(entry.stateLabel || "Live")}</span>
          </div>
          <div class="world-local-share-card__meta">
            <strong>${htmlEscape(entry.title)}</strong>
            <span>${htmlEscape(entry.secondary)}</span>
          </div>
          <div class="world-local-share-card__actions">
            <button
              type="button"
              class="is-muted"
              data-private-local-share-focus="${htmlEscape(entry.id)}"
              data-private-local-share-type="${htmlEscape(entry.type)}"
              ${entry.type === "browser" && entry.active ? "disabled" : ""}
            >
              ${entry.type === "voice" ? "Manage" : entry.type === "game" ? "Open" : entry.active ? "Previewing" : "Preview"}
            </button>
            ${entry.type === "browser" ? `<button type="button" class="is-muted" data-private-local-share-rename="${htmlEscape(entry.id)}">Rename</button>` : ""}
            <button type="button" class="is-muted" data-private-local-share-stop="${htmlEscape(entry.id)}" data-private-local-share-type="${htmlEscape(entry.type)}">Stop</button>
          </div>
        </section>
      `).join("")}
    </div>
  `;

  for (const button of elements.panelBrowserLocalStack.querySelectorAll("[data-private-local-share-focus]")) {
    button.addEventListener("click", () => {
      const sessionId = String(button.getAttribute("data-private-local-share-focus") ?? "").trim();
      const entryType = String(button.getAttribute("data-private-local-share-type") ?? "").trim();
      if (entryType === "voice") {
        setPrivatePanelTab("chat");
        return;
      }
      if (entryType === "game") {
        const session = getLocalPrivateGameSession();
        if (session) {
          requestOpenPrivateGameSession(session);
        }
        return;
      }
      const session = state.browserSessions.get(sessionId);
      if (!session) {
        return;
      }
      state.browserShareMode = normalizeBrowserShareKind(getPrivateBrowserSessionShareKind(session), "screen");
      privateBrowserShareFeature.setSelectedMode(state.browserShareMode);
      setSelectedLocalPrivateBrowserSession(sessionId);
      updatePrivateBrowserPanel();
    });
  }
  for (const button of elements.panelBrowserLocalStack.querySelectorAll("[data-private-local-share-rename]")) {
    button.addEventListener("click", () => {
      const sessionId = String(button.getAttribute("data-private-local-share-rename") ?? "").trim();
      const session = state.browserSessions.get(sessionId);
      if (!session) {
        return;
      }
      state.browserShareMode = normalizeBrowserShareKind(getPrivateBrowserSessionShareKind(session), "screen");
      privateBrowserShareFeature.setSelectedMode(state.browserShareMode);
      setSelectedLocalPrivateBrowserSession(sessionId);
      if (elements.panelBrowserShareTitle) {
        elements.panelBrowserShareTitle.focus();
        elements.panelBrowserShareTitle.select();
      }
      updatePrivateBrowserPanel();
    });
  }
  for (const button of elements.panelBrowserLocalStack.querySelectorAll("[data-private-local-share-stop]")) {
    button.addEventListener("click", () => {
      const sessionId = String(button.getAttribute("data-private-local-share-stop") ?? "").trim();
      const entryType = String(button.getAttribute("data-private-local-share-type") ?? "").trim();
      if (entryType === "voice") {
        sendWorldSocketMessage({ type: "voice:stop", sessionId });
        return;
      }
      if (entryType === "game") {
        sendWorldSocketMessage({ type: "game:stop-share", sessionId });
        return;
      }
      sendWorldSocketMessage({ type: "browser:stop", sessionId });
    });
  }
}

function getPrivateBrowserStagePlaceholderText({
  localSession = null,
  remoteSession = null,
  needsManualPlaybackStart = false,
  needsManualAudioStart = false,
} = {}) {
  return getDisplayShareStagePlaceholderText({
    localSession,
    remoteSession,
    needsManualPlaybackStart,
    needsManualAudioStart,
    getSessionShareKind: getPrivateBrowserSessionShareKind,
    strings: {
      blockedAutoplay: "Browser blocked autoplay. Press start to watch this live stream.",
      enableAudioVoice: "Press enable sound to hear this live voice stream.",
      enableAudioDefault: "Press enable sound to hear this live stream.",
      localAudio: "Voice-only share is live inside this private world.",
      remoteAudio: (session) => `Listening to ${session?.title || "live voice"} from inside this private world.`,
      localCamera: "Video share is live inside this private world.",
      remoteCamera: (session) => `Watching ${session?.title || "live video"} from this private world.`,
      remoteDisplay: (session) => `Watching ${session?.title || "nearby share"} from this private world.`,
      localBrowser: "This browser session is live in this private world.",
      remoteBrowser: (session) => `Viewing ${session?.title || "nearby share"} from this private world.`,
    },
  });
}

function setPrivateBrowserOverlayOpen(open) {
  state.browserOverlayOpen = Boolean(open);
  setDisplayShareOverlayState({
    open: state.browserOverlayOpen,
    panel: elements.panelBrowserPanel,
    overlayRoot: elements.panelBrowserOverlayRoot,
    dockMarker: elements.panelBrowserDock,
    backdrop: elements.panelBrowserBackdrop,
    expandButton: elements.panelBrowserExpand,
    stage: elements.panelBrowserStage,
    updateView: updatePrivateBrowserPanel,
  });
}

function getActivePrivateBrowserShareModeFromUi() {
  const activeButton = (elements.panelBrowserShareModes ?? []).find((button) =>
    button?.getAttribute?.("aria-pressed") === "true"
    || button?.classList?.contains?.("is-active"));
  const activeMode = String(activeButton?.getAttribute?.("data-private-browser-share-mode") ?? "").trim();
  return normalizeBrowserShareKind(activeMode, "");
}

function getLocalPrivateBrowserSession() {
  return state.localBrowserSessionId ? state.browserSessions.get(state.localBrowserSessionId) ?? null : null;
}

function getLocalPrivateBrowserShare(sessionId = state.localBrowserSessionId) {
  const normalizedSessionId = String(sessionId ?? "").trim();
  return normalizedSessionId ? state.localBrowserShares.get(normalizedSessionId) ?? null : null;
}

function getLocalPrivateBrowserDisplaySessions() {
  return [...state.browserSessions.values()]
    .filter((session) =>
      session?.hostSessionId === getPrivateViewerSessionId()
      && session?.sessionMode === "display-share"
      && !isPrivatePersistentVoiceSession(session));
}

function getLocalPrivateBrowserDisplaySessionBySlot(sessionSlot = "") {
  const normalizedSessionSlot = String(sessionSlot ?? "").trim().toLowerCase();
  if (!normalizedSessionSlot) {
    return null;
  }
  const sessionId = String(state.localBrowserSessionIdsBySlot.get(normalizedSessionSlot) ?? "").trim();
  if (sessionId) {
    return state.browserSessions.get(sessionId) ?? null;
  }
  return getLocalPrivateBrowserDisplaySessions().find((session) =>
    getBrowserShareSessionSlot(session) === normalizedSessionSlot) ?? null;
}

function getPreferredLocalPrivateBrowserSessionId() {
  const preferredSlots = ["display-screen", "display-av"];
  for (const sessionSlot of preferredSlots) {
    const session = getLocalPrivateBrowserDisplaySessionBySlot(sessionSlot);
    if (session?.sessionId) {
      return String(session.sessionId ?? "").trim();
    }
  }
  const fallbackSession = getLocalPrivateBrowserDisplaySessions()
    .sort((left, right) =>
      Number(getBrowserShareSessionSlot(right) === "display-screen") - Number(getBrowserShareSessionSlot(left) === "display-screen")
      || Date.parse(left.startedAt ?? 0) - Date.parse(right.startedAt ?? 0)
      || String(left.sessionId ?? "").localeCompare(String(right.sessionId ?? "")))[0] ?? null;
  return String(fallbackSession?.sessionId ?? "").trim();
}

function syncSelectedLocalPrivateBrowserShare() {
  const preferredSessionId = getPreferredLocalPrivateBrowserSessionId();
  if (!state.localBrowserSessionId || !state.browserSessions.has(state.localBrowserSessionId)) {
    state.localBrowserSessionId = preferredSessionId;
  }
  if (
    state.localBrowserSessionId
    && !state.localBrowserShares.has(state.localBrowserSessionId)
    && preferredSessionId
  ) {
    state.localBrowserSessionId = preferredSessionId;
  }
  state.localBrowserShare = getLocalPrivateBrowserShare(state.localBrowserSessionId);
  return state.localBrowserShare;
}

function setSelectedLocalPrivateBrowserSession(sessionId = "") {
  const normalizedSessionId = String(sessionId ?? "").trim();
  state.localBrowserSessionId = normalizedSessionId || getPreferredLocalPrivateBrowserSessionId();
  const nextShare = syncSelectedLocalPrivateBrowserShare();
  if (nextShare?.hasVideo) {
    setLocalPrivateBrowserPreviewStream(nextShare.stream);
    if (elements.panelBrowserVideo && state.localBrowserSessionId) {
      setPrivateShareBubbleVideo(state.localBrowserSessionId, elements.panelBrowserVideo);
    }
  } else {
    setLocalPrivateBrowserPreviewStream(null);
  }
  return nextShare;
}

function isKnownLocalPrivateBrowserShare(share = null) {
  if (!share?.stream) {
    return false;
  }
  return [...state.localBrowserShares.values()].some((entry) => entry?.stream === share.stream);
}

function releasePrivateBrowserShare(share, { stopTracks = false } = {}) {
  if (!share) {
    return;
  }
  share.observedTrack?.removeEventListener?.("ended", share.endedHandler);
  if (stopTracks || share.stopTracksOnRelease === true) {
    stopMediaStream(share.stream);
  }
}

function clearPendingPrivateBrowserShare({ stopTracks = false } = {}) {
  if (!state.pendingBrowserShare) {
    return;
  }
  releasePrivateBrowserShare(state.pendingBrowserShare, { stopTracks });
  state.pendingBrowserShare = null;
  if (!syncSelectedLocalPrivateBrowserShare()) {
    setLocalPrivateBrowserPreviewStream(null);
  }
}

function clearLocalPrivateBrowserShare({ stopTracks = false, sessionId = "" } = {}) {
  const normalizedSessionId = String(sessionId ?? "").trim();
  const targetSessionId = normalizedSessionId || String(state.localBrowserSessionId ?? "").trim();
  if (!targetSessionId) {
    return;
  }
  const activeShare = state.localBrowserShares.get(targetSessionId) ?? null;
  if (!activeShare) {
    return;
  }
  releasePrivateBrowserShare(activeShare, { stopTracks });
  if (activeShare.sessionId) {
    clearPrivateShareBubbleVideo(activeShare.sessionId);
  }
  state.localBrowserShares.delete(targetSessionId);
  const sessionSlot = getBrowserShareSessionSlot(activeShare);
  if (sessionSlot && state.localBrowserSessionIdsBySlot.get(sessionSlot) === targetSessionId) {
    state.localBrowserSessionIdsBySlot.delete(sessionSlot);
  }
  if (String(state.localBrowserSessionId ?? "").trim() === targetSessionId) {
    state.localBrowserSessionId = "";
    setSelectedLocalPrivateBrowserSession("");
  } else {
    syncSelectedLocalPrivateBrowserShare();
  }
}

function dropLocalPrivateBrowserSession(sessionId, { unpublish = true } = {}) {
  const normalized = String(sessionId ?? "").trim();
  if (!normalized) {
    return false;
  }
  state.browserMediaController?.removeSession?.(normalized);
  if (unpublish) {
    void state.browserMediaController?.unpublishSession?.(normalized);
  }
  state.browserSessions.delete(normalized);
  if (state.localBrowserSessionId === normalized) {
    state.localBrowserSessionId = "";
  }
  if (state.localVoiceSessionId === normalized) {
    state.localVoiceSessionId = "";
  }
  if (state.browserPanelRemoteSessionId === normalized) {
    state.browserPanelRemoteSessionId = "";
    if (!syncSelectedLocalPrivateBrowserShare()) {
      setPrivateBrowserPreviewStream(null);
    }
  }
  state.localBrowserShares.delete(normalized);
  for (const [sessionSlot, trackedSessionId] of state.localBrowserSessionIdsBySlot.entries()) {
    if (trackedSessionId === normalized) {
      state.localBrowserSessionIdsBySlot.delete(sessionSlot);
    }
  }
  ensurePrivateRemoteAudioStateMap().delete(normalized);
  syncPrivateRemoteAudioState();
  removePrivateShareBubbleEntry(normalized);
  setSelectedLocalPrivateBrowserSession("");
  return true;
}

function getLocalPrivateVoiceSession() {
  return state.localVoiceSessionId ? state.browserSessions.get(state.localVoiceSessionId) ?? null : null;
}

function ensurePrivateRemoteAudioStateMap() {
  if (!(state.browserMediaState.remoteAudioBySession instanceof Map)) {
    state.browserMediaState.remoteAudioBySession = new Map();
  }
  return state.browserMediaState.remoteAudioBySession;
}

function isPrivateRemotePanelSessionCandidate(session = {}) {
  return Boolean(
    session
    && session.hostSessionId !== getPrivateViewerSessionId()
    && session.deliveryMode === "full"
    && session.hasVideo !== false
    && !isPrivatePersistentVoiceSession(session),
  );
}

function getPrivateRemotePanelSessionId(preferredSessionId = "") {
  const currentSessionId = String(state.browserPanelRemoteSessionId ?? "").trim();
  if (currentSessionId && isPrivateRemotePanelSessionCandidate(state.browserSessions.get(currentSessionId))) {
    return currentSessionId;
  }
  const normalizedPreferredSessionId = String(preferredSessionId ?? "").trim();
  const candidates = [...state.browserSessions.values()]
    .filter((session) => isPrivateRemotePanelSessionCandidate(session))
    .sort((left, right) =>
      Number(isPrivateBrowserOriginSession(right)) - Number(isPrivateBrowserOriginSession(left))
      || Number(getBrowserShareSessionSlot(right) === "display-screen")
        - Number(getBrowserShareSessionSlot(left) === "display-screen")
      || Number(normalizeBrowserShareKind(right.shareKind, "screen") === "camera")
        - Number(normalizeBrowserShareKind(left.shareKind, "screen") === "camera")
      || Number(String(right.sessionId ?? "").trim() === normalizedPreferredSessionId)
        - Number(String(left.sessionId ?? "").trim() === normalizedPreferredSessionId)
      || Date.parse(left.startedAt ?? 0) - Date.parse(right.startedAt ?? 0)
      || String(left.sessionId ?? "").localeCompare(String(right.sessionId ?? "")));
  return String(candidates[0]?.sessionId ?? "").trim();
}

function syncPrivateRemoteAudioState(preferredSessionId = "") {
  const audioStates = ensurePrivateRemoteAudioStateMap();
  const normalizedPreferredSessionId = String(preferredSessionId ?? "").trim();
  const selectedSessionId = normalizedPreferredSessionId || String(state.browserPanelRemoteSessionId ?? "").trim();
  let resolvedSessionId = "";
  let resolvedState = null;
  if (selectedSessionId) {
    const selectedState = audioStates.get(selectedSessionId) ?? null;
    if (selectedState?.available === true) {
      resolvedSessionId = selectedSessionId;
      resolvedState = selectedState;
    }
  }
  if (!resolvedState) {
    const fallbackEntry = [...audioStates.entries()].find(([, entry]) => entry?.available === true) ?? null;
    if (fallbackEntry) {
      resolvedSessionId = String(fallbackEntry[0] ?? "").trim();
      resolvedState = fallbackEntry[1];
    }
  }
  state.browserMediaState.remoteAudioSessionId = resolvedSessionId;
  state.browserMediaState.remoteAudioAvailable = resolvedState?.available === true;
  state.browserMediaState.remoteAudioBlocked = resolvedState?.blocked === true;
  state.browserMediaState.remoteAudioError = String(resolvedState?.error ?? "").trim();
}

function clearPendingPrivateVoiceShare({ stopTracks = false } = {}) {
  if (!state.pendingVoiceShare) {
    return;
  }
  releasePrivateBrowserShare(state.pendingVoiceShare, { stopTracks });
  state.pendingVoiceShare = null;
}

function clearLocalPrivateVoiceShare({ stopTracks = false, sessionId = "" } = {}) {
  const activeShare = state.localVoiceShare;
  if (!activeShare) {
    return;
  }
  if (sessionId && activeShare.sessionId && activeShare.sessionId !== sessionId) {
    return;
  }
  releasePrivateBrowserShare(activeShare, { stopTracks });
  state.localVoiceShare = null;
}

function getPrivateVoiceShareActionLabel() {
  const localVoiceSession = getLocalPrivateVoiceSession();
  if (state.pendingVoiceShare) {
    return "Starting...";
  }
  return localVoiceSession ? "Stop Persistent Voice Chat" : "Start Persistent Voice Chat";
}

function createPrivatePersistentVoiceContributionShare() {
  const sourceStream = state.localVoiceShare?.stream ?? null;
  const sourceAudioTrack = sourceStream?.getAudioTracks?.()[0] ?? null;
  if (!sourceAudioTrack || String(sourceAudioTrack.readyState ?? "live") === "ended") {
    return null;
  }
  const clonedStream = new MediaStream([sourceAudioTrack.clone()]);
  const share = createLocalDisplayShare(clonedStream, {
    title: "",
    shareKind: "audio",
    hasVideo: false,
    hasAudio: true,
    aspectRatio: 1.2,
    fallbackWidth: 540,
    fallbackHeight: 432,
    isPendingShare: (candidate) => state.pendingBrowserShare?.stream === candidate.stream,
    isLocalShare: isKnownLocalPrivateBrowserShare,
    onEndedWhilePending() {
      clearPendingPrivateBrowserShare({ stopTracks: false });
      updatePrivateBrowserPanel();
    },
    onEndedWhileLive() {
      const sessionId = String(share.sessionId ?? state.localBrowserSessionId ?? "").trim();
      clearLocalPrivateBrowserShare({ stopTracks: false, sessionId });
      dropLocalPrivateBrowserSession(sessionId);
      if (sessionId) {
        sendWorldSocketMessage({
          type: "browser:stop",
          sessionId,
        });
      }
      updatePrivateBrowserPanel();
    },
  });
  share.stopTracksOnRelease = true;
  return share;
}

function startPrivatePersistentVoiceContribution(anchorSessionId) {
  const normalizedAnchorSessionId = String(anchorSessionId ?? "").trim();
  if (!normalizedAnchorSessionId) {
    return false;
  }
  const anchorHostSessionId = resolvePrivateShareGroupHostSessionId(normalizedAnchorSessionId);
  const existingAvSession = getLocalPrivateBrowserDisplaySessionBySlot("display-av");
  if (existingAvSession) {
    const sameContribution = isPrivateBrowserMemberSession(existingAvSession)
      && getPrivateBrowserSessionShareKind(existingAvSession) === "audio"
      && getPrivateBrowserAnchorHostSessionId(existingAvSession) === anchorHostSessionId;
    if (sameContribution) {
      return true;
    }
    setPrivateBrowserStatus("Stop your current nearby video or voice share before joining with persistent voice.");
    return false;
  }
  if (state.pendingBrowserShare) {
    setPrivateBrowserStatus("Finish the current nearby share first.");
    return false;
  }
  const share = createPrivatePersistentVoiceContributionShare();
  if (!share) {
    setPrivateBrowserStatus("Restart persistent voice chat, then try joining again.");
    return false;
  }
  state.pendingBrowserShare = share;
  setPrivateBrowserStatus("Adding your persistent voice to this nearby share...");
  const sent = sendWorldSocketMessage({
    type: "browser:start",
    mode: "display-share",
    title: "",
    shareKind: "audio",
    hasVideo: false,
    hasAudio: true,
    aspectRatio: share.aspectRatio,
    anchorSessionId: normalizedAnchorSessionId,
  });
  if (!sent) {
    clearPendingPrivateBrowserShare({ stopTracks: true });
    updatePrivateBrowserPanel();
    setPrivateBrowserStatus("Private world share is offline right now.");
    return false;
  }
  updatePrivateBrowserPanel();
  return true;
}

function bindPrivatePanelPress(button, handler) {
  if (!button || typeof handler !== "function") {
    return;
  }
  let lastHandledAt = 0;
  const run = (event) => {
    const now = Date.now();
    if (now - lastHandledAt < 240) {
      return;
    }
    lastHandledAt = now;
    if (event?.type === "pointerup") {
      event.preventDefault();
    }
    handler(event);
  };
  button.addEventListener("click", run);
  button.addEventListener("pointerup", run);
}

function updatePrivateVoicePanel() {
  const localVoiceSession = getLocalPrivateVoiceSession();
  const localContributionSession = getLocalPrivateBrowserSession();
  if (!localVoiceSession && !state.pendingVoiceShare) {
    state.voiceJoinOffer = null;
    clearPendingPrivateVoiceJoinState();
  }
  const canToggle = Boolean(state.session && isPrivateWorldReadyForShare());
  const pendingVoiceJoinAnchorSessionId = String(state.pendingVoiceJoin?.anchorSessionId ?? "").trim();
  const cancelingVoiceJoinRequest = pendingVoiceJoinAnchorSessionId
    && isPrivateVoiceJoinCancellationPending(pendingVoiceJoinAnchorSessionId);
  if (elements.panelVoiceToggle) {
    elements.panelVoiceToggle.disabled = !canToggle && !localVoiceSession && !state.pendingVoiceShare;
    elements.panelVoiceToggle.textContent = getPrivateVoiceShareActionLabel();
  }
  if (elements.panelVoiceStatus) {
    if (!state.session) {
      elements.panelVoiceStatus.textContent = "Sign in to keep a nearby voice channel open.";
    } else if (!state.selectedWorld) {
      elements.panelVoiceStatus.textContent = "Open a private world to use persistent voice chat.";
    } else if (!getLocalParticipant()) {
      elements.panelVoiceStatus.textContent = "Enter this private world to use persistent voice chat.";
    } else if (state.pendingVoiceShare) {
      elements.panelVoiceStatus.textContent = "Starting persistent voice chat...";
    } else if (pendingVoiceJoinAnchorSessionId) {
      const hostName = getPrivateDisplayNameForSessionId(state.pendingVoiceJoin?.anchorHostSessionId) || "nearby host";
      elements.panelVoiceStatus.textContent = cancelingVoiceJoinRequest
        ? `Canceling your request to join ${hostName}'s live voice group...`
        : `Waiting for ${hostName} to approve your voice join.`;
    } else if (localVoiceSession) {
      elements.panelVoiceStatus.textContent = Boolean(
        localContributionSession
        && isPrivateBrowserMemberSession(localContributionSession)
        && getPrivateBrowserSessionShareKind(localContributionSession) === "audio",
      )
        ? "Persistent voice chat is joined to the nearby live group."
        : "Persistent voice chat is live nearby.";
    } else {
      elements.panelVoiceStatus.textContent = "Keep your mic nearby without showing up in What's Live.";
    }
  }
}

function handlePrivateIncomingVoiceJoinDecision(anchorSessionId, requesterSessionId, approved) {
  const sent = sendWorldSocketMessage({
    type: "voice:join-decision",
    anchorSessionId,
    requesterSessionId,
    approved,
  });
  if (!sent) {
    setPrivateBrowserStatus("Private world share is offline right now.");
    return false;
  }
  state.incomingVoiceJoinRequests = state.incomingVoiceJoinRequests.filter((request) =>
    !(request.anchorSessionId === anchorSessionId && request.requesterSessionId === requesterSessionId));
  updatePrivateBrowserPanel();
  return true;
}

function renderPrivateShareJoinRequests() {
  if (!elements.panelShareRequestStack) {
    return;
  }
  if (state.incomingShareJoinRequests.length === 0 && state.incomingVoiceJoinRequests.length === 0) {
    elements.panelShareRequestStack.innerHTML = "";
    elements.panelShareRequestStack.hidden = true;
    return;
  }
  elements.panelShareRequestStack.hidden = false;
  const shareRequestCards = state.incomingShareJoinRequests.map((request) => `
    <div class="world-request-card">
      <div class="world-request-card__title">${htmlEscape(request.requesterDisplayName || "Nearby visitor")}</div>
      <div class="world-request-card__body">Wants to join with ${htmlEscape(getBrowserShareKindLabel(request.shareKind || "screen").toLowerCase())}.</div>
      <div class="world-request-card__actions">
        <button type="button" data-private-share-join-decision="approve" data-anchor-session-id="${htmlEscape(request.anchorSessionId)}" data-requester-session-id="${htmlEscape(request.requesterSessionId)}">Approve</button>
        <button type="button" data-private-share-join-decision="decline" data-anchor-session-id="${htmlEscape(request.anchorSessionId)}" data-requester-session-id="${htmlEscape(request.requesterSessionId)}">Decline</button>
      </div>
    </div>
  `);
  const voiceRequestCards = state.incomingVoiceJoinRequests.map((request) => `
    <div class="world-request-card">
      <div class="world-request-card__title">${htmlEscape(request.requesterDisplayName || "Nearby visitor")}</div>
      <div class="world-request-card__body">Wants their persistent voice chat heard in your live group.</div>
      <div class="world-request-card__actions">
        <button type="button" data-private-share-panel-voice-join-decision="approve" data-anchor-session-id="${htmlEscape(request.anchorSessionId)}" data-requester-session-id="${htmlEscape(request.requesterSessionId)}">Approve</button>
        <button type="button" data-private-share-panel-voice-join-decision="decline" data-anchor-session-id="${htmlEscape(request.anchorSessionId)}" data-requester-session-id="${htmlEscape(request.requesterSessionId)}">Decline</button>
      </div>
    </div>
  `);
  elements.panelShareRequestStack.innerHTML = [...shareRequestCards, ...voiceRequestCards].join("");
  for (const button of elements.panelShareRequestStack.querySelectorAll("[data-private-share-join-decision]")) {
    bindPrivatePanelPress(button, () => {
      const anchorSessionId = String(button.getAttribute("data-anchor-session-id") ?? "").trim();
      const requesterSessionId = String(button.getAttribute("data-requester-session-id") ?? "").trim();
      const approved = button.getAttribute("data-private-share-join-decision") === "approve";
      const sent = sendWorldSocketMessage({
        type: "share:join-decision",
        anchorSessionId,
        requesterSessionId,
        approved,
      });
      if (!sent) {
        setPrivateBrowserStatus("Private world share is offline right now.");
        return;
      }
      state.incomingShareJoinRequests = state.incomingShareJoinRequests.filter((request) =>
        !(request.anchorSessionId === anchorSessionId && request.requesterSessionId === requesterSessionId));
      updatePrivateBrowserPanel();
    });
  }
  for (const button of elements.panelShareRequestStack.querySelectorAll("[data-private-share-panel-voice-join-decision]")) {
    bindPrivatePanelPress(button, () => {
      const anchorSessionId = String(button.getAttribute("data-anchor-session-id") ?? "").trim();
      const requesterSessionId = String(button.getAttribute("data-requester-session-id") ?? "").trim();
      const approved = button.getAttribute("data-private-share-panel-voice-join-decision") === "approve";
      handlePrivateIncomingVoiceJoinDecision(anchorSessionId, requesterSessionId, approved);
    });
  }
}

function isPrivateVoiceJoinCancellationPending(anchorSessionId = "") {
  return String(state.pendingVoiceJoinCancellationAnchorSessionId ?? "").trim() === String(anchorSessionId ?? "").trim()
    && Boolean(anchorSessionId);
}

function clearPendingPrivateVoiceJoinState() {
  state.pendingVoiceJoin = null;
  state.pendingVoiceJoinCancellationAnchorSessionId = "";
}

function cancelPendingPrivateVoiceJoinRequest() {
  const anchorSessionId = String(state.pendingVoiceJoin?.anchorSessionId ?? "").trim();
  if (!anchorSessionId || isPrivateVoiceJoinCancellationPending(anchorSessionId)) {
    return false;
  }
  const cancelled = sendWorldSocketMessage({
    type: "voice:join-cancel",
    anchorSessionId,
  });
  if (!cancelled) {
    setPrivateBrowserStatus("Private world share is offline right now.");
    return false;
  }
  state.pendingVoiceJoinCancellationAnchorSessionId = anchorSessionId;
  updatePrivateBrowserPanel();
  return true;
}

function renderPrivateVoiceJoinOffers() {
  if (!elements.panelVoiceOfferStack) {
    return;
  }
  const offer = state.voiceJoinOffer;
  const pendingJoin = state.pendingVoiceJoin;
  const activeAnchorSessionId = String(pendingJoin?.anchorSessionId ?? offer?.anchorSessionId ?? "").trim();
  if (!activeAnchorSessionId) {
    elements.panelVoiceOfferStack.innerHTML = "";
    elements.panelVoiceOfferStack.hidden = true;
    return;
  }
  const anchorHostSessionId = String(pendingJoin?.anchorHostSessionId ?? offer?.anchorHostSessionId ?? "").trim();
  const hostName = getPrivateDisplayNameForSessionId(anchorHostSessionId);
  const anchorSession = pendingJoin?.anchorSession ?? offer?.anchorSession ?? null;
  const title = anchorSession?.title
    ? `"${anchorSession.title}"`
    : "this nearby live share";
  const canceling = isPrivateVoiceJoinCancellationPending(activeAnchorSessionId);
  elements.panelVoiceOfferStack.hidden = false;
  elements.panelVoiceOfferStack.innerHTML = pendingJoin
    ? `
      <div class="world-request-card">
        <div class="world-request-card__title">Voice Join Requested</div>
        <div class="world-request-card__body">Waiting for ${htmlEscape(hostName || "Nearby host")} to approve ${htmlEscape(title)}.</div>
        <div class="world-request-card__actions">
          <button type="button" data-private-voice-join-cancel="true" ${canceling ? "disabled" : ""}>${canceling ? "Canceling..." : "Cancel Request"}</button>
        </div>
      </div>
    `
    : `
      <div class="world-request-card">
        <div class="world-request-card__title">Join Nearby Voice Group?</div>
        <div class="world-request-card__body">${htmlEscape(hostName || "Nearby host")} is live with ${htmlEscape(title)}.</div>
        <div class="world-request-card__actions">
          <button type="button" data-private-voice-offer-decision="accept">Join</button>
          <button type="button" data-private-voice-offer-decision="decline">Stay Nearby</button>
        </div>
      </div>
    `;
  for (const button of elements.panelVoiceOfferStack.querySelectorAll("[data-private-voice-join-cancel]")) {
    bindPrivatePanelPress(button, () => {
      cancelPendingPrivateVoiceJoinRequest();
    });
  }
  for (const button of elements.panelVoiceOfferStack.querySelectorAll("[data-private-voice-offer-decision]")) {
    bindPrivatePanelPress(button, () => {
      const localVoiceSession = getLocalPrivateVoiceSession();
      if (!localVoiceSession || !isPrivatePersistentVoiceSession(localVoiceSession)) {
        state.voiceJoinOffer = null;
        updatePrivateVoicePanel();
        renderPrivateVoiceJoinOffers();
        setPrivateBrowserStatus("Start persistent voice chat again to answer this offer.");
        return;
      }
      const accepted = button.getAttribute("data-private-voice-offer-decision") === "accept";
      const sent = sendWorldSocketMessage({
        type: "voice:join-offer-response",
        anchorSessionId: offer.anchorSessionId,
        accepted,
      });
      if (!sent) {
        setPrivateBrowserStatus("Private world share is offline right now.");
        return;
      }
      if (accepted) {
        state.pendingVoiceJoin = {
          anchorSessionId: offer.anchorSessionId,
          anchorHostSessionId: offer.anchorHostSessionId,
          anchorSession: offer.anchorSession ?? null,
        };
        state.pendingVoiceJoinCancellationAnchorSessionId = "";
        state.voiceJoinOffer = null;
        updatePrivateBrowserPanel();
        return;
      }
      if (!accepted) {
        state.voiceJoinOffer = null;
        updatePrivateVoicePanel();
        renderPrivateVoiceJoinOffers();
      }
    });
  }
}

function renderPrivateVoiceJoinRequests() {
  if (!elements.panelVoiceRequestStack) {
    return;
  }
  if (state.incomingVoiceJoinRequests.length === 0) {
    elements.panelVoiceRequestStack.innerHTML = "";
    elements.panelVoiceRequestStack.hidden = true;
    return;
  }
  elements.panelVoiceRequestStack.hidden = false;
  elements.panelVoiceRequestStack.innerHTML = state.incomingVoiceJoinRequests.map((request) => `
    <div class="world-request-card">
      <div class="world-request-card__title">${htmlEscape(request.requesterDisplayName || "Nearby visitor")}</div>
      <div class="world-request-card__body">Wants their persistent voice chat heard in your live group.</div>
      <div class="world-request-card__actions">
        <button type="button" data-private-voice-join-decision="approve" data-anchor-session-id="${htmlEscape(request.anchorSessionId)}" data-requester-session-id="${htmlEscape(request.requesterSessionId)}">Approve</button>
        <button type="button" data-private-voice-join-decision="decline" data-anchor-session-id="${htmlEscape(request.anchorSessionId)}" data-requester-session-id="${htmlEscape(request.requesterSessionId)}">Decline</button>
      </div>
    </div>
  `).join("");
  for (const button of elements.panelVoiceRequestStack.querySelectorAll("[data-private-voice-join-decision]")) {
    bindPrivatePanelPress(button, () => {
      const anchorSessionId = String(button.getAttribute("data-anchor-session-id") ?? "").trim();
      const requesterSessionId = String(button.getAttribute("data-requester-session-id") ?? "").trim();
      const approved = button.getAttribute("data-private-voice-join-decision") === "approve";
      handlePrivateIncomingVoiceJoinDecision(anchorSessionId, requesterSessionId, approved);
    });
  }
}

function renderPrivateShareGroupSummary() {
  if (!elements.panelShareGroupSummary) {
    return;
  }
  const localSession = getLocalPrivateBrowserSession();
  const anchorSession = getPrivateShareJoinTarget();
  if (!anchorSession) {
    elements.panelShareGroupSummary.innerHTML = "";
    elements.panelShareGroupSummary.hidden = true;
    return;
  }
  const contributorEntries = getPrivateShareGroupSessions(anchorSession.sessionId)
    .filter((session) => isPrivateBrowserMemberSession(session))
    .map((session) => ({
      sessionId: String(session.sessionId ?? "").trim(),
      displayName: getPrivateDisplayNameForSessionId(session.hostSessionId) || session.hostSessionId || "Nearby visitor",
      shareKindLabel: getBrowserShareKindLabel(getPrivateBrowserSessionShareKind(session)),
    }))
    .filter((entry) => entry.sessionId);
  const hostName = getPrivateDisplayNameForSessionId(anchorSession.hostSessionId) || "Nearby host";
  const viewerCount = Math.min(getPrivateBrowserSessionViewerCount(anchorSession), getPrivateBrowserSessionMaxViewers(anchorSession));
  const maxViewers = getPrivateBrowserSessionMaxViewers(anchorSession);
  const canKickMembers = Boolean(
    localSession
    && isPrivateBrowserOriginSession(localSession)
    && String(localSession.sessionId ?? "").trim() === String(anchorSession.sessionId ?? "").trim(),
  );
  const pendingState = state.pendingShareJoin?.anchorSessionId === anchorSession.sessionId
    ? state.pendingShareJoin.approved
      ? "Approved. Choose what to share."
      : isPrivateShareJoinCancellationPending(anchorSession.sessionId)
        ? "Canceling request..."
        : "Waiting for approval."
    : "";
  const summaryCopy = localSession
    ? isPrivateBrowserOriginSession(localSession)
      ? "You are the anchor for this nearby share group. Movement stays locked while it is live."
      : "You are contributing inside this nearby share group. Leaving the circle will stop your share."
    : `Join ${hostName}'s nearby share group without creating another live row.`;
  const shouldRenderSummary = !localSession
    || !isPrivateBrowserOriginSession(localSession)
    || contributorEntries.length > 0
    || Boolean(pendingState);
  if (!shouldRenderSummary) {
    elements.panelShareGroupSummary.innerHTML = "";
    elements.panelShareGroupSummary.hidden = true;
    return;
  }
  elements.panelShareGroupSummary.hidden = false;
  elements.panelShareGroupSummary.innerHTML = `
    <div class="world-group-summary__title">${htmlEscape(getPrivateBrowserSessionTitle(anchorSession))}</div>
    <div class="world-group-summary__meta">
      <span>${htmlEscape(hostName)}</span>
      <span>${viewerCount}/${maxViewers} viewers</span>
      <span>${contributorEntries.length} contributor${contributorEntries.length === 1 ? "" : "s"}</span>
    </div>
    <div class="world-group-summary__body">${htmlEscape(summaryCopy)}</div>
    ${contributorEntries.length > 0 ? `
      <ul class="world-group-summary__list">
        ${contributorEntries.map((entry) => `
          <li>
            <div class="world-group-summary__member">
              <span class="world-group-summary__member-name">${htmlEscape(entry.displayName)}</span>
              <span class="world-group-summary__badge">${htmlEscape(entry.shareKindLabel)}</span>
            </div>
            ${canKickMembers ? `<button type="button" class="world-group-summary__kick" data-private-share-member-kick="${htmlEscape(entry.sessionId)}">Kick</button>` : ""}
          </li>
        `).join("")}
      </ul>
    ` : ""}
    ${pendingState ? `<div class="world-group-summary__note">${htmlEscape(pendingState)}</div>` : ""}
  `;
  if (canKickMembers) {
    for (const button of elements.panelShareGroupSummary.querySelectorAll("[data-private-share-member-kick]")) {
      bindPrivatePanelPress(button, () => {
        const memberSessionId = String(button.getAttribute("data-private-share-member-kick") ?? "").trim();
        const sent = sendWorldSocketMessage({
          type: "share:member-kick",
          anchorSessionId: anchorSession.sessionId,
          memberSessionId,
        });
        if (!sent) {
          setPrivateBrowserStatus("Private world share is offline right now.");
        }
      });
    }
  }
}

function renderPrivateGameShareGroupSummary() {
  if (!elements.panelShareGroupSummary) {
    return;
  }
  const localSession = getLocalPrivateGameSession();
  const anchorSession = getPrivateGameShareJoinTarget();
  if (!anchorSession) {
    elements.panelShareGroupSummary.innerHTML = "";
    elements.panelShareGroupSummary.hidden = true;
    return;
  }
  const contributorEntries = getPrivateGameShareGroupSessions(anchorSession.session_id)
    .filter((session) => isPrivateGameMemberSession(session))
    .map((session) => ({
      sessionId: String(session?.session_id ?? session?.id ?? "").trim(),
      displayName: getPrivateGameHostName(session) || "Nearby visitor",
      shareKindLabel: "Game",
    }))
    .filter((entry) => entry.sessionId);
  const hostName = getPrivateGameHostName(anchorSession);
  const viewerCount = Math.max(0, Number(anchorSession?.viewer_count ?? anchorSession?.viewerCount) || 0);
  const maxViewers = Math.max(
    1,
    Number(anchorSession?.max_viewers ?? anchorSession?.maxViewers) || DEFAULT_WORLD_INTERACTION_MAX_RECIPIENTS,
  );
  const canKickMembers = Boolean(
    localSession
    && isPrivateGameOriginSession(localSession)
    && String(localSession?.session_id ?? "").trim() === String(anchorSession?.session_id ?? "").trim(),
  );
  const pendingState = state.pendingShareJoin?.anchorSessionId === String(anchorSession?.session_id ?? "").trim()
    ? state.pendingShareJoin.approved
      ? "Approved. Share your game to add it to this nearby group."
      : isPrivateShareJoinCancellationPending(anchorSession.session_id)
        ? "Canceling request..."
        : "Waiting for approval."
    : "";
  const summaryCopy = localSession
    ? isPrivateGameOriginSession(localSession)
      ? "You are the anchor for this nearby game group. Movement stays locked while it is live."
      : "You are contributing a game inside this nearby group. Leaving the circle will stop it."
    : `Join ${hostName}'s nearby game group without creating another live row.`;
  const shouldRenderSummary = !localSession
    || !isPrivateGameOriginSession(localSession)
    || contributorEntries.length > 0
    || Boolean(pendingState);
  if (!shouldRenderSummary) {
    elements.panelShareGroupSummary.innerHTML = "";
    elements.panelShareGroupSummary.hidden = true;
    return;
  }
  elements.panelShareGroupSummary.hidden = false;
  elements.panelShareGroupSummary.innerHTML = `
    <div class="world-group-summary__title">${htmlEscape(getPrivateGameSessionTitle(anchorSession))}</div>
    <div class="world-group-summary__meta">
      <span>${htmlEscape(hostName)}</span>
      <span>${viewerCount}/${maxViewers} viewers</span>
      <span>${contributorEntries.length} contributor${contributorEntries.length === 1 ? "" : "s"}</span>
    </div>
    <div class="world-group-summary__body">${htmlEscape(summaryCopy)}</div>
    ${contributorEntries.length > 0 ? `
      <ul class="world-group-summary__list">
        ${contributorEntries.map((entry) => `
          <li>
            <div class="world-group-summary__member">
              <span class="world-group-summary__member-name">${htmlEscape(entry.displayName)}</span>
              <span class="world-group-summary__badge">${htmlEscape(entry.shareKindLabel)}</span>
            </div>
            ${canKickMembers ? `<button type="button" class="world-group-summary__kick" data-private-share-member-kick="${htmlEscape(entry.sessionId)}">Kick</button>` : ""}
          </li>
        `).join("")}
      </ul>
    ` : ""}
    ${pendingState ? `<div class="world-group-summary__note">${htmlEscape(pendingState)}</div>` : ""}
  `;
  if (canKickMembers) {
    for (const button of elements.panelShareGroupSummary.querySelectorAll("[data-private-share-member-kick]")) {
      bindPrivatePanelPress(button, () => {
        const memberSessionId = String(button.getAttribute("data-private-share-member-kick") ?? "").trim();
        const sent = sendWorldSocketMessage({
          type: "share:member-kick",
          anchorSessionId: String(anchorSession?.session_id ?? "").trim(),
          memberSessionId,
        });
        if (!sent) {
          setPrivateBrowserStatus("Private world share is offline right now.");
        }
      });
    }
  }
}

function isPrivateShareJoinCancellationPending(anchorSessionId = "") {
  return String(state.pendingShareJoinCancellationAnchorSessionId ?? "").trim() === String(anchorSessionId ?? "").trim()
    && Boolean(anchorSessionId);
}

function clearPendingPrivateShareJoinState() {
  state.pendingShareJoin = null;
  state.pendingShareJoinCancellationAnchorSessionId = "";
}

function cancelPendingPrivateShareJoinRequest() {
  const anchorSessionId = String(state.pendingShareJoin?.anchorSessionId ?? "").trim();
  if (!anchorSessionId || state.pendingShareJoin?.approved === true || isPrivateShareJoinCancellationPending(anchorSessionId)) {
    return false;
  }
  const cancelled = sendWorldSocketMessage({
    type: "share:join-cancel",
    anchorSessionId,
  });
  if (!cancelled) {
    setPrivateBrowserStatus("Private world share is offline right now.");
    return false;
  }
  state.pendingShareJoinCancellationAnchorSessionId = anchorSessionId;
  updatePrivateBrowserPanel();
  return true;
}

async function handlePrivateNearbyShareLaunch({ defaultLaunch, getLocalSession, getSelectedMode }) {
  const selectedMode = normalizeBrowserShareKind(getSelectedMode?.(), state.browserShareMode);
  if (selectedMode === "game") {
    const localGameSession = getLocalPrivateGameSession();
    if (localGameSession) {
      requestOpenPrivateGameSession(localGameSession);
      return true;
    }
    if (!getSelectedPrivateWorldGame()) {
      await startPrivateWorldGameShare();
      return true;
    }
    const joinTarget = getPrivateGameShareJoinTarget();
    const approvedJoin = state.pendingShareJoin?.approved === true ? state.pendingShareJoin : null;
    if (!joinTarget || (approvedJoin && approvedJoin.anchorSessionId === String(joinTarget?.session_id ?? "").trim())) {
      await startPrivateWorldGameShare();
      return true;
    }
    if (!isPrivateWorldReadyForShare()) {
      updatePrivateBrowserPanel();
      return true;
    }
    state.pendingShareJoin = {
      anchorSessionId: String(joinTarget?.session_id ?? "").trim(),
      anchorHostSessionId: String(joinTarget?.host_viewer_session_id ?? "").trim(),
      shareKind: "game",
      approved: false,
    };
    state.pendingShareJoinCancellationAnchorSessionId = "";
    const sent = sendWorldSocketMessage({
      type: "share:join-request",
      anchorSessionId: joinTarget.session_id,
      shareKind: "game",
    });
    if (!sent) {
      clearPendingPrivateShareJoinState();
      updatePrivateBrowserPanel();
      setPrivateBrowserStatus("Private world share is offline right now.");
      return true;
    }
    updatePrivateBrowserPanel();
    setPrivateBrowserStatus(`Asked ${getPrivateGameHostName(joinTarget) || "the nearby host"} to join.`);
    return true;
  }
  const localSession = getLocalSession();
  if (localSession) {
    return defaultLaunch();
  }
  const joinTarget = getPrivateShareJoinTarget();
  const approvedJoin = state.pendingShareJoin?.approved === true ? state.pendingShareJoin : null;
  if (!joinTarget || (approvedJoin && approvedJoin.anchorSessionId === joinTarget.sessionId)) {
    return defaultLaunch();
  }
  if (!isPrivateWorldReadyForShare()) {
    updatePrivateBrowserPanel();
    return true;
  }
  const shareKind = selectedMode;
  state.pendingShareJoin = {
    anchorSessionId: joinTarget.sessionId,
    anchorHostSessionId: joinTarget.hostSessionId,
    shareKind,
    approved: false,
  };
  state.pendingShareJoinCancellationAnchorSessionId = "";
  const sent = sendWorldSocketMessage({
    type: "share:join-request",
    anchorSessionId: joinTarget.sessionId,
    shareKind,
  });
  if (!sent) {
    clearPendingPrivateShareJoinState();
    updatePrivateBrowserPanel();
    setPrivateBrowserStatus("Private world share is offline right now.");
    return true;
  }
  updatePrivateBrowserPanel();
  setPrivateBrowserStatus(`Asked ${getPrivateDisplayNameForSessionId(joinTarget.hostSessionId) || "the nearby host"} to join.`);
  return true;
}

const privateBrowserShareFeature = createNearbyDisplayShareFeature({
  modeButtons: elements.panelBrowserShareModes,
  modeAttribute: "data-private-browser-share-mode",
  titleInput: elements.panelBrowserShareTitle,
  launchButton: elements.panelBrowserLaunch,
  getMode: () => getActivePrivateBrowserShareModeFromUi() || state.browserShareMode,
  setMode(mode) {
    state.browserShareMode = mode;
  },
  onModeChanged() {
    state.browserShareMode = getActivePrivateBrowserShareModeFromUi() || state.browserShareMode;
    if (state.browserShareMode === "game" && state.browserOverlayOpen) {
      setPrivateBrowserOverlayOpen(false);
    }
    updatePrivateBrowserPanel();
  },
  handleLaunch: handlePrivateNearbyShareLaunch,
  getTitleInputValue: () => elements.panelBrowserShareTitle?.value ?? "",
  getSessionShareKind: getPrivateBrowserSessionShareKind,
  getPendingShare: () => state.pendingBrowserShare,
  getLocalSession: getLocalPrivateBrowserSession,
  getLocalShare: () => getLocalPrivateBrowserShare(),
  isLocalShare: isKnownLocalPrivateBrowserShare,
  clearPendingShare: clearPendingPrivateBrowserShare,
  clearLocalShare: clearLocalPrivateBrowserShare,
  onLocalShareEnded({ sessionId }) {
    dropLocalPrivateBrowserSession(sessionId);
    renderPrivateLiveSharesList();
  },
  getFallbackSize: () => ({ width: 16, height: 9 }),
  stopLiveShare(sessionId) {
    sendWorldSocketMessage({
      type: "browser:stop",
      sessionId,
    });
  },
  startLiveShare(payload) {
    return sendWorldSocketMessage({
      type: "browser:start",
      ...payload,
    });
  },
  beginShare: startLocalPrivateNearbyShare,
  patchSession(sessionId, sessionPatch) {
    state.browserSessions.set(sessionId, sessionPatch);
  },
  getDisplaySurface: () => state.localBrowserShare?.displaySurface || "",
  setStatus: setPrivateBrowserStatus,
  updateView: updatePrivateBrowserPanel,
  updatingStatusText: "Updating live share title...",
  canLaunch: () => isPrivateWorldReadyForShare(),
  onCannotLaunch() {
    updatePrivateBrowserPanel();
  },
  onUnsupported(message) {
    setPrivateBrowserStatus(message);
  },
  onError(message, error) {
    setPrivateBrowserStatus(error?.message || message);
  },
  unsupportedMessages: {
    screen: "This browser does not support screen sharing.",
    camera: "This browser does not support camera sharing.",
    audio: "This browser does not support voice sharing.",
  },
  failureMessages: {
    screen: "Could not start screen sharing.",
    camera: "Could not start video sharing.",
    audio: "Could not start voice sharing.",
  },
});

function startLocalPrivateNearbyShare(share) {
  if (!isPrivateWorldReadyForShare()) {
    updatePrivateBrowserPanel();
    return false;
  }
  if (!share) {
    return false;
  }
  state.browserPanelRemoteSessionId = "";
  clearPendingPrivateBrowserShare({ stopTracks: true });
  state.pendingBrowserShare = share;
  setLocalPrivateBrowserPreviewStream(share.hasVideo ? share.stream : null);
  setPrivateBrowserStatus("Starting nearby share...");
  const existingLocalSession = getLocalPrivateBrowserSession();
  const approvedJoin = state.pendingShareJoin?.approved === true ? state.pendingShareJoin : null;
  const anchorSessionId = approvedJoin?.anchorSessionId
    || (isPrivateBrowserMemberSession(existingLocalSession) ? getPrivateBrowserAnchorSessionId(existingLocalSession) : "");
  const memberShare = Boolean(anchorSessionId);
  const sent = sendWorldSocketMessage({
    type: "browser:start",
    mode: "display-share",
    title: memberShare ? "" : share.title,
    shareKind: share.shareKind,
    hasVideo: share.hasVideo,
    hasAudio: share.hasAudio,
    aspectRatio: share.aspectRatio,
    displaySurface: share.displaySurface,
    anchorSessionId,
  });
  if (!sent) {
    clearPendingPrivateBrowserShare({ stopTracks: true });
    setPrivateBrowserStatus("Live share is offline right now.");
    updatePrivateBrowserPanel();
    return false;
  }
  updatePrivateBrowserPanel();
  return true;
}

async function fetchPrivateBrowserMediaToken({ canPublish = false } = {}) {
  const viewerSessionId = getPrivateViewerSessionId();
  const worldSnapshotId = getPrivateBrowserWorldKey();
  if (!viewerSessionId || !worldSnapshotId) {
    return { enabled: false };
  }
  try {
    return await apiFetch("/public/world/current/browser-media-token", {
      method: "POST",
      body: {
        viewerSessionId,
        worldSnapshotId,
        canPublish,
      },
    });
  } catch (_error) {
    return { enabled: false };
  }
}

function getPrivateBrowserMediaController() {
  if (state.browserMediaController) {
    return state.browserMediaController;
  }
  state.browserMediaController = createBrowserMediaController({
    fetchToken: ({ canPublish = false } = {}) => fetchPrivateBrowserMediaToken({ canPublish }),
    onRemoteTrack: ({ sessionId, track, element }) => {
      if (state.gameSessions.has(sessionId) || state.gameMediaSubscriptions.has(sessionId)) {
        updateCachedPrivateGameSession(sessionId, {
          _remoteElement: element ?? null,
        });
        if (element) {
          setPrivateGameShareVideo(sessionId, element);
        }
        return;
      }
      const existing = state.browserSessions.get(sessionId) ?? {};
      state.browserSessions.set(sessionId, {
        ...existing,
        _remoteElement: element ?? existing._remoteElement ?? null,
      });
      const nextPanelSessionId = getPrivateRemotePanelSessionId(sessionId);
      if (!state.localBrowserShare && elements.panelBrowserVideo && nextPanelSessionId) {
        state.browserPanelRemoteSessionId = nextPanelSessionId;
      }
      if (!state.localBrowserShare && elements.panelBrowserVideo && nextPanelSessionId === sessionId) {
        state.browserMediaState.remoteVideoSessionId = sessionId;
        track.attach(elements.panelBrowserVideo);
        elements.panelBrowserVideo.hidden = false;
        ensurePrivateBrowserVideoPlayback(elements.panelBrowserVideo);
      }
      if (element) {
        setPrivateShareBubbleVideo(sessionId, element);
      }
      updatePrivateBrowserPanel();
    },
    onRemoteTrackRemoved: ({ sessionId }) => {
      if (state.gameSessions.has(sessionId) || state.gameMediaSubscriptions.has(sessionId)) {
        updateCachedPrivateGameSession(sessionId, {
          _remoteElement: null,
        });
        clearPrivateGameShareVideo(sessionId);
        return;
      }
      const existing = state.browserSessions.get(sessionId);
      if (existing) {
        state.browserSessions.set(sessionId, {
          ...existing,
          _remoteElement: null,
        });
      }
      if (state.browserPanelRemoteSessionId === sessionId && !state.localBrowserShare && elements.panelBrowserVideo) {
        state.browserPanelRemoteSessionId = "";
        elements.panelBrowserVideo.pause?.();
        elements.panelBrowserVideo.removeAttribute("src");
        elements.panelBrowserVideo.srcObject = null;
        elements.panelBrowserVideo.hidden = true;
      }
      if (state.browserMediaState.remoteVideoSessionId === sessionId) {
        state.browserMediaState.remoteVideoSessionId = "";
      }
      clearPrivateShareBubbleVideo(sessionId);
      updatePrivateBrowserPanel();
    },
    onRemoteAudioState: ({ sessionId, available, blocked, error }) => {
      const normalizedSessionId = String(sessionId ?? "").trim();
      if (!normalizedSessionId) {
        return;
      }
      const audioStates = ensurePrivateRemoteAudioStateMap();
      if (available === true) {
        audioStates.set(normalizedSessionId, {
          available: true,
          blocked: blocked === true,
          error: String(error ?? "").trim(),
        });
      } else {
        audioStates.delete(normalizedSessionId);
      }
      syncPrivateRemoteAudioState(normalizedSessionId);
      updatePrivateBrowserPanel();
    },
    onStatus: ({ enabled, transport, connected, roomName, canPublish }) => {
      state.browserMediaState.enabled = enabled;
      state.browserMediaState.connected = connected === true;
      state.browserMediaState.transport = transport || state.browserMediaState.transport;
      state.browserMediaState.roomName = roomName || "";
      state.browserMediaState.canPublish = canPublish === true;
      updatePrivateBrowserPanel();
    },
  });
  return state.browserMediaController;
}

function syncPrivateBrowserMediaSubscription(sessionId, subscribed) {
  const session = state.browserSessions.get(sessionId);
  if (!session || !isLiveKitBrowserTransport(session.frameTransport)) {
    return;
  }
  void getPrivateBrowserMediaController().setSubscribed({
    sessionId,
    subscribed,
    viewerSessionId: getPrivateViewerSessionId(),
    worldSnapshotId: getPrivateBrowserWorldKey(),
    canPublish: session.hostSessionId === getPrivateViewerSessionId(),
  });
}

function isPrivateWorldReadyForShare() {
  return Boolean(
    state.session
    && state.selectedWorld
    && getLocalParticipant()
    && state.browserMediaState.enabled !== false
    && state.worldSocket?.readyState === WebSocket.OPEN
    && !state.authRefreshPromise
  );
}

function attachLocalPrivateBrowserShare(sessionId, share) {
  if (!share || !sessionId || !getPrivateBrowserWorldKey()) {
    return;
  }
  clearLocalPrivateBrowserShare({ stopTracks: true, sessionId });
  const nextShare = {
    ...share,
    sessionId,
  };
  state.localBrowserShares.set(sessionId, nextShare);
  const sessionSlot = getBrowserShareSessionSlot(nextShare);
  if (sessionSlot) {
    state.localBrowserSessionIdsBySlot.set(sessionSlot, sessionId);
  }
  setSelectedLocalPrivateBrowserSession(sessionId);
  privateBrowserShareFeature.setSelectedMode(share.shareKind);
  if (elements.panelBrowserShareTitle) {
    elements.panelBrowserShareTitle.value = share.title || "";
  }
  void getPrivateBrowserMediaController().publishStream({
    sessionId,
    stream: share.stream,
    viewerSessionId: getPrivateViewerSessionId(),
    worldSnapshotId: getPrivateBrowserWorldKey(),
  }).then((published) => {
    if (!published) {
      clearLocalPrivateBrowserShare({ stopTracks: true, sessionId });
      dropLocalPrivateBrowserSession(sessionId);
      sendWorldSocketMessage({
        type: "browser:stop",
        sessionId,
      });
      updatePrivateBrowserPanel();
    }
  }).catch(() => {
    clearLocalPrivateBrowserShare({ stopTracks: true, sessionId });
    dropLocalPrivateBrowserSession(sessionId);
    sendWorldSocketMessage({
      type: "browser:stop",
      sessionId,
    });
    updatePrivateBrowserPanel();
  });
}

function attachLocalPrivateVoiceShare(sessionId, share) {
  if (!share || !sessionId || !getPrivateBrowserWorldKey()) {
    return;
  }
  clearLocalPrivateVoiceShare({ stopTracks: true });
  state.localVoiceShare = {
    ...share,
    sessionId,
  };
  void getPrivateBrowserMediaController().publishStream({
    sessionId,
    stream: share.stream,
    viewerSessionId: getPrivateViewerSessionId(),
    worldSnapshotId: getPrivateBrowserWorldKey(),
  }).then((published) => {
    if (!published) {
      clearLocalPrivateVoiceShare({ stopTracks: true, sessionId });
      dropLocalPrivateBrowserSession(sessionId);
      sendWorldSocketMessage({
        type: "voice:stop",
        sessionId,
      });
      updatePrivateVoicePanel();
    }
  }).catch(() => {
    clearLocalPrivateVoiceShare({ stopTracks: true, sessionId });
    dropLocalPrivateBrowserSession(sessionId);
    sendWorldSocketMessage({
      type: "voice:stop",
      sessionId,
    });
    updatePrivateVoicePanel();
  });
}

async function startPrivatePersistentVoiceChat() {
  if (!isPrivateWorldReadyForShare()) {
    updatePrivateBrowserPanel();
    return false;
  }
  clearPendingPrivateVoiceShare({ stopTracks: true });
  const started = await launchNearbyDisplayShare({
    shareKind: "audio",
    getRequestedTitle: () => "",
    createShare: (stream, shareOptions = {}) => createLocalDisplayShare(stream, {
      ...shareOptions,
      title: "",
      shareKind: "audio",
      hasVideo: false,
      hasAudio: true,
      aspectRatio: 1.2,
      fallbackWidth: 540,
      fallbackHeight: 432,
      isPendingShare: (candidate) => state.pendingVoiceShare?.stream === candidate.stream,
      isLocalShare: (candidate) => state.localVoiceShare?.stream === candidate.stream,
      onEndedWhilePending() {
        clearPendingPrivateVoiceShare({ stopTracks: false });
        updatePrivateVoicePanel();
      },
      onEndedWhileLive() {
        const sessionId = String(state.localVoiceShare?.sessionId ?? state.localVoiceSessionId ?? "").trim();
        clearLocalPrivateVoiceShare({ stopTracks: false, sessionId });
        dropLocalPrivateBrowserSession(sessionId);
        if (sessionId) {
          sendWorldSocketMessage({
            type: "voice:stop",
            sessionId,
          });
        }
        updatePrivateVoicePanel();
      },
    }),
    startShare(share) {
      state.pendingVoiceShare = share;
      const sent = sendWorldSocketMessage({
        type: "voice:start",
      });
      if (!sent) {
        clearPendingPrivateVoiceShare({ stopTracks: true });
        updatePrivateVoicePanel();
        setPrivateBrowserStatus("Private world share is offline right now.");
        return false;
      }
      updatePrivateVoicePanel();
      return true;
    },
    onUnsupported(message) {
      setPrivateBrowserStatus(message);
    },
    onError(message, error) {
      setPrivateBrowserStatus(error?.message || message);
    },
    unsupportedMessages: {
      audio: "This browser does not support voice sharing.",
    },
    failureMessages: {
      audio: "Could not start voice sharing.",
    },
  });
  updatePrivateVoicePanel();
  return started;
}

function stopPrivatePersistentVoiceChat() {
  const localVoiceSession = getLocalPrivateVoiceSession();
  if (localVoiceSession) {
    return sendWorldSocketMessage({
      type: "voice:stop",
      sessionId: localVoiceSession.sessionId,
    });
  }
  if (state.pendingVoiceShare) {
    clearPendingPrivateVoiceShare({ stopTracks: true });
    updatePrivateVoicePanel();
    return true;
  }
  return false;
}

function updatePrivateBrowserSessionState(sessionPatch = {}) {
  const sessionId = String(sessionPatch.sessionId ?? "").trim();
  if (!sessionId) {
    return;
  }
  const previous = state.browserSessions.get(sessionId) ?? {};
  const next = normalizeHostedBrowserSession({
    ...previous,
    ...sessionPatch,
    deliveryMode: sessionPatch.deliveryMode ?? previous.deliveryMode ?? "placeholder",
    frameTransport: sessionPatch.frameTransport ?? previous.frameTransport ?? "jpeg-sequence",
    lastFrameDataUrl: sessionPatch.lastFrameDataUrl ?? previous.lastFrameDataUrl ?? "",
    lastFrameId: Number(sessionPatch.lastFrameId ?? previous.lastFrameId) || 0,
    sessionMode: sessionPatch.sessionMode ?? previous.sessionMode ?? "display-share",
    aspectRatio: Number(sessionPatch.aspectRatio ?? previous.aspectRatio) || PRIVATE_BROWSER_SHARE.aspectRatio,
  }, getPrivateViewerSessionId());
  state.browserSessions.set(sessionId, next);
  if (next.hasVideo === false) {
    clearPrivateShareBubbleVideo(next.sessionId);
  }

  if (next.hostSessionId === getPrivateViewerSessionId()) {
    if (isPrivatePersistentVoiceSession(next)) {
      state.localVoiceSessionId = next.sessionId;
    } else if (next.sessionMode === "display-share") {
      const sessionSlot = getBrowserShareSessionSlot(next);
      if (sessionSlot) {
        state.localBrowserSessionIdsBySlot.set(sessionSlot, next.sessionId);
      }
      if (!state.localBrowserSessionId || !state.browserSessions.has(state.localBrowserSessionId)) {
        state.localBrowserSessionId = next.sessionId;
      }
    }
    if (isLiveKitBrowserTransport(next.frameTransport) && getPrivateBrowserWorldKey()) {
      void getPrivateBrowserMediaController().connect({
        viewerSessionId: getPrivateViewerSessionId(),
        worldSnapshotId: getPrivateBrowserWorldKey(),
        canPublish: true,
      });
    }
    if (isPrivatePersistentVoiceSession(next) && state.pendingVoiceShare?.stream) {
      const pendingVoiceShare = state.pendingVoiceShare;
      state.pendingVoiceShare = null;
      attachLocalPrivateVoiceShare(next.sessionId, pendingVoiceShare);
    } else if (
      next.sessionMode === "display-share"
      && state.pendingBrowserShare?.stream
      && getBrowserShareSessionSlot(next) === getBrowserShareSessionSlot(state.pendingBrowserShare)
      && !state.localBrowserShares.has(next.sessionId)
    ) {
      const pendingShare = state.pendingBrowserShare;
      state.pendingBrowserShare = null;
      attachLocalPrivateBrowserShare(next.sessionId, pendingShare);
    }
    if (isPrivateBrowserMemberSession(next)) {
      clearPendingPrivateShareJoinState();
    }
  }

  syncSelectedLocalPrivateBrowserShare();
  reconcilePrivateShareBubbles();
  reconcilePrivateBrowserAnchors();
  if (
    next.hostSessionId === getPrivateViewerSessionId()
    && state.localBrowserShare?.sessionId === next.sessionId
    && state.localBrowserShare?.hasVideo
    && elements.panelBrowserVideo
  ) {
    setPrivateShareBubbleVideo(next.sessionId, elements.panelBrowserVideo);
  }
  if (next.lastFrameDataUrl && next.lastFrameId > 0) {
    updatePrivateShareBubbleFrame(next.sessionId, {
      sessionId: next.sessionId,
      frameId: next.lastFrameId,
      dataUrl: next.lastFrameDataUrl,
    });
  }
  updatePrivateBrowserPanel();
  renderPrivateLiveSharesList();
}

function handlePrivateBrowserFrame(payload = {}) {
  const sessionId = String(payload.sessionId ?? "").trim();
  const existing = state.browserSessions.get(sessionId);
  if (!existing) {
    return;
  }
  const next = {
    ...existing,
    lastFrameDataUrl: payload.dataUrl,
    lastFrameId: Number(payload.frameId ?? 0) || 0,
    title: payload.title ?? existing.title,
    url: payload.url ?? existing.url,
  };
  state.browserSessions.set(sessionId, next);
  if (sessionId === state.localBrowserSessionId) {
    drawPrivateBrowserMediaFrame(payload);
    publishLocalPrivateBrowserMedia(sessionId);
  }
  updatePrivateShareBubbleFrame(sessionId, payload);
  updatePrivateBrowserPanel();
}

function handlePrivateBrowserStop(payload = {}) {
  const sessionId = String(payload.sessionId ?? "").trim();
  const hostSessionId = String(payload.hostSessionId ?? "").trim();
  if (!sessionId) {
    return;
  }
  if (hostSessionId && hostSessionId === getPrivateViewerSessionId() && sessionId === state.localVoiceSessionId) {
    clearPendingPrivateVoiceShare();
  } else if (
    hostSessionId
    && hostSessionId === getPrivateViewerSessionId()
    && state.pendingBrowserShare
    && getBrowserShareSessionSlot(state.pendingBrowserShare) === getBrowserShareSessionSlot(state.browserSessions.get(sessionId) ?? {})
  ) {
    clearPendingPrivateBrowserShare();
  }
  clearLocalPrivateBrowserShare({ sessionId });
  clearLocalPrivateVoiceShare({ sessionId });
  dropLocalPrivateBrowserSession(sessionId);
  if (
    state.pendingShareJoin?.anchorSessionId === sessionId
    || (hostSessionId && state.pendingShareJoin?.anchorHostSessionId === hostSessionId)
  ) {
    clearPendingPrivateShareJoinState();
  }
  if (state.pendingShareJoinCancellationAnchorSessionId === sessionId) {
    state.pendingShareJoinCancellationAnchorSessionId = "";
  }
  if (
    state.pendingVoiceJoin?.anchorSessionId === sessionId
    || (hostSessionId && state.pendingVoiceJoin?.anchorHostSessionId === hostSessionId)
  ) {
    clearPendingPrivateVoiceJoinState();
  }
  if (state.pendingVoiceJoinCancellationAnchorSessionId === sessionId) {
    state.pendingVoiceJoinCancellationAnchorSessionId = "";
  }
  if (
    state.voiceJoinOffer?.anchorSessionId === sessionId
    || (hostSessionId && state.voiceJoinOffer?.anchorHostSessionId === hostSessionId)
  ) {
    state.voiceJoinOffer = null;
  }
  state.incomingShareJoinRequests = state.incomingShareJoinRequests.filter((request) =>
    request.anchorSessionId !== sessionId
    && (!hostSessionId || request.anchorHostSessionId !== hostSessionId));
  state.incomingVoiceJoinRequests = state.incomingVoiceJoinRequests.filter((request) =>
    request.anchorSessionId !== sessionId
    && (!hostSessionId || request.anchorHostSessionId !== hostSessionId));
  reconcilePrivateShareBubbles();
  reconcilePrivateBrowserAnchors();
  updatePrivateBrowserPanel();
  renderPrivateLiveSharesList();
}

function updatePrivateGameSessionState(sessionPatch = {}) {
  const sessionId = String(sessionPatch?.session_id ?? "").trim();
  if (!sessionId) {
    return;
  }
  const next = updateCachedPrivateGameSession(sessionId, cloneJson(sessionPatch));
  if (
    state.pendingGameShareGameId
    && String(next?.host_viewer_session_id ?? "").trim() === getPrivateViewerSessionId()
    && String(next?.game?.id ?? "").trim() === state.pendingGameShareGameId
  ) {
    state.pendingGameShareGameId = "";
    requestOpenPrivateGameSession(next);
  }
  if (
    String(next?.host_viewer_session_id ?? "").trim() === getPrivateViewerSessionId()
    && isPrivateGameMemberSession(next)
  ) {
    clearPendingPrivateShareJoinState();
  }
  if (privateGameShell.isOpen(sessionId)) {
    privateGameShell.updateSession(next);
  }
  updatePrivateBrowserPanel();
  renderPrivateLiveSharesList();
}

function handlePrivateGamePreview(payload = {}) {
  const sessionId = String(payload.sessionId ?? "").trim();
  if (!sessionId) {
    return;
  }
  const existing = state.gameSessions.get(sessionId) ?? null;
  const isLocalHostSession = String(existing?.host_viewer_session_id ?? "").trim() === getPrivateViewerSessionId();
  if (isLocalHostSession && getPrivateLocalGamePreviewCanvas(sessionId)) {
    return;
  }
  state.gameMediaSubscriptions.add(sessionId);
  updateCachedPrivateGameSession(sessionId, {
    deliveryMode: "full",
    latest_preview: cloneJson(payload.preview ?? null),
  });
  if (privateGameShell.isOpen(sessionId)) {
    privateGameShell.updateSession(state.gameSessions.get(sessionId), { syncFrame: false });
  }
  updatePrivateBrowserPanel();
  renderPrivateLiveSharesList();
}

function handlePrivateGameStop(payload = {}) {
  const sessionId = String(payload.sessionId ?? "").trim();
  if (!sessionId) {
    return;
  }
  state.gameMediaSubscriptions.delete(sessionId);
  clearPrivateGamePreviewMedia(sessionId);
  const stoppedSession = state.gameSessions.get(sessionId);
  state.gameSessions.delete(sessionId);
  if (state.pendingShareJoin?.anchorSessionId === sessionId) {
    clearPendingPrivateShareJoinState();
  }
  if (state.pendingShareJoinCancellationAnchorSessionId === sessionId) {
    state.pendingShareJoinCancellationAnchorSessionId = "";
  }
  if (
    stoppedSession
    && String(stoppedSession?.host_viewer_session_id ?? "").trim() === getPrivateViewerSessionId()
  ) {
    state.pendingGameShareGameId = "";
  }
  if (privateGameShell.isOpen(sessionId)) {
    privateGameShell.close();
    setPrivateBrowserStatus("That game share just ended.");
  }
  updatePrivateBrowserPanel();
  renderPrivateLiveSharesList();
}

function resetPrivateBrowserState({ disconnectController = false, stopTracks = false } = {}) {
  if (state.browserOverlayOpen) {
    setPrivateBrowserOverlayOpen(false);
  }
  clearPendingPrivateBrowserShare({ stopTracks });
  clearLocalPrivateBrowserShare({ stopTracks });
  clearPendingPrivateVoiceShare({ stopTracks });
  clearLocalPrivateVoiceShare({ stopTracks });
  for (const sessionId of state.browserSessions.keys()) {
    state.browserMediaController?.removeSession?.(sessionId);
  }
  state.browserSessions = new Map();
  state.localBrowserSessionId = "";
  state.localVoiceSessionId = "";
  state.browserPanelRemoteSessionId = "";
  state.pendingShareJoin = null;
  state.pendingShareJoinCancellationAnchorSessionId = "";
  state.incomingShareJoinRequests = [];
  state.voiceJoinOffer = null;
  state.pendingVoiceJoin = null;
  state.pendingVoiceJoinCancellationAnchorSessionId = "";
  state.incomingVoiceJoinRequests = [];
  state.browserMediaState = createEmptyPrivateBrowserMediaState();
  setLocalPrivateBrowserPreviewStream(null);
  if (elements.panelBrowserFrame) {
    elements.panelBrowserFrame.hidden = true;
    elements.panelBrowserFrame.removeAttribute("src");
  }
  if (disconnectController) {
    void state.browserMediaController?.disconnect?.();
    state.browserMediaController = null;
  }
  reconcilePrivateShareBubbles();
  reconcilePrivateBrowserAnchors();
  updatePrivateBrowserPanel();
  renderPrivateLiveSharesList();
}

function updatePrivateGamePanel({ canShare, socketReady }) {
  const localGameSession = getLocalPrivateGameSession();
  const selectedGame = getSelectedPrivateWorldGame();
  const joinTarget = getPrivateGameShareJoinTarget();
  const pendingShareJoinRequest = Boolean(
    !localGameSession
    && state.pendingShareJoin?.shareKind === "game"
    && state.pendingShareJoin?.anchorSessionId
    && state.pendingShareJoin?.approved !== true,
  );
  const cancelingShareJoinRequest = pendingShareJoinRequest
    && isPrivateShareJoinCancellationPending(state.pendingShareJoin?.anchorSessionId);
  const joinMode = Boolean(!localGameSession && joinTarget);
  const joinStateMatches = String(state.pendingShareJoin?.anchorSessionId ?? "").trim() === String(joinTarget?.session_id ?? "").trim();
  const joinApproved = joinMode && joinStateMatches && state.pendingShareJoin?.approved === true;
  const previewUrl = String(localGameSession?.latest_preview?.data_url ?? "").trim();
  elements.panelBrowserPanel?.classList.add("is-game-mode");
  elements.panelBrowserPanel?.classList.remove("is-docked-compact");
  elements.panelBrowserStage?.classList.add("is-active");
  elements.panelBrowserStage?.classList.remove("is-collapsed", "is-permission-only", "needs-video-start");
  elements.panelBrowserShare?.classList.toggle("is-join-mode", joinMode);
  if (elements.panelBrowserStage) {
    elements.panelBrowserStage.tabIndex = -1;
    elements.panelBrowserStage.setAttribute("aria-hidden", "false");
  }
  if (elements.panelBrowserShareTitle) {
    elements.panelBrowserShareTitle.disabled = true;
    if (document.activeElement !== elements.panelBrowserShareTitle) {
      elements.panelBrowserShareTitle.value = "";
    }
  }

  if (!state.selectedWorld) {
    setPrivateBrowserStatus("Open a world to share nearby.");
    updatePrivateBrowserSummary({
      state: "offline",
      badge: "Offline",
      current: "No world selected",
      hint: "Open a world first.",
    });
  } else if (!state.session) {
    setPrivateBrowserStatus("Sign in to generate, save, or share games nearby.");
    updatePrivateBrowserSummary({
      state: "idle",
      badge: "Guest",
      current: "Game sharing is off for guests",
      hint: "Log in to build or share simple HTML games nearby.",
    });
  } else if (pendingShareJoinRequest) {
    const hostName = getPrivateGameHostName(joinTarget ?? {});
    setPrivateBrowserStatus(
      cancelingShareJoinRequest
        ? `Canceling your nearby game request to ${hostName}...`
        : `Waiting for ${hostName} to approve your nearby game request...`,
    );
    updatePrivateBrowserSummary({
      state: "starting",
      badge: cancelingShareJoinRequest ? "Canceling" : "Waiting",
      current: selectedGame ? `Requested ${getPrivateSavedGameTitle(selectedGame)}` : "Requested Game",
      hint: cancelingShareJoinRequest
        ? "This request will disappear from the anchor host as soon as the world socket updates."
        : "Once approved, sharing your game keeps it attached to this nearby group without creating another live row.",
    });
  } else if (state.pendingGameShareGameId) {
    const pendingGame = selectedGame && selectedGame.id === state.pendingGameShareGameId ? selectedGame : null;
    setPrivateBrowserStatus(`Starting ${getPrivateSavedGameTitle(pendingGame ?? {}, "your game")} nearby...`);
    updatePrivateBrowserSummary({
      state: "starting",
      badge: "Starting",
      current: pendingGame ? `Starting ${getPrivateSavedGameTitle(pendingGame)}` : "Starting your game",
      hint: "The host window opens as soon as the share session is ready.",
    });
  } else if (localGameSession) {
    const seatedPlayers = normalizePrivateGameSeats(localGameSession).filter((seat) => seat.viewer_session_id).length;
    const maxSeats = getPrivateGameSeatCapacity(localGameSession);
    const memberShare = isPrivateGameMemberSession(localGameSession);
    setPrivateBrowserStatus(
      localGameSession.started
        ? (memberShare ? "Your game match is live inside this nearby group." : "Your game match is live nearby.")
        : (memberShare ? "Your game lobby is open inside this nearby group." : "Your game lobby is open nearby."),
    );
    updatePrivateBrowserSummary({
      state: "live",
      badge: memberShare ? "Group" : (localGameSession.started ? "Live" : "Lobby"),
      current: getPrivateGameSessionTitle(localGameSession),
      hint: memberShare
        ? `${seatedPlayers} / ${maxSeats} seats claimed. Leaving the anchor circle stops this contributor game share.`
        : `${seatedPlayers} / ${maxSeats} seats claimed. Movement stays locked while this anchor game is live.`,
    });
  } else if (joinMode && selectedGame) {
    const hostName = getPrivateGameHostName(joinTarget);
    setPrivateBrowserStatus(`Join ${hostName}'s nearby game group after approval.`);
    updatePrivateBrowserSummary({
      state: "draft",
      badge: "Join",
      current: getPrivateSavedGameTitle(selectedGame),
      hint: joinApproved
        ? "Approval is in. Share Game to add this as a contributor game without creating another live row."
        : "Share Game to ask the anchor host for access first.",
    });
  } else if (selectedGame) {
    setPrivateBrowserStatus(`Selected ${getPrivateSavedGameTitle(selectedGame)}.`);
    updatePrivateBrowserSummary({
      state: "draft",
      badge: "Ready",
      current: getPrivateSavedGameTitle(selectedGame),
      hint: "Share it nearby, or open the library to generate something new.",
    });
  } else {
    setPrivateBrowserStatus("Pick or generate a game to share nearby.");
    updatePrivateBrowserSummary({
      state: "idle",
      badge: "Library",
      current: "No game selected",
      hint: "Open the game library to choose, generate, import, or package a nearby game.",
    });
  }

  if (elements.panelBrowserLaunch) {
    if (localGameSession) {
      elements.panelBrowserLaunch.textContent = "Open Game";
      elements.panelBrowserLaunch.disabled = !canShare;
    } else if (pendingShareJoinRequest) {
      elements.panelBrowserLaunch.textContent = cancelingShareJoinRequest ? "Canceling..." : "Waiting...";
      elements.panelBrowserLaunch.disabled = true;
    } else if (!selectedGame) {
      elements.panelBrowserLaunch.textContent = "Open Library";
      elements.panelBrowserLaunch.disabled = !canShare;
    } else if (joinMode) {
      elements.panelBrowserLaunch.textContent = joinApproved ? "Share Game" : "Request Game";
      elements.panelBrowserLaunch.disabled = !canShare || Boolean(state.pendingGameShareGameId);
    } else {
      elements.panelBrowserLaunch.textContent = "Share Game";
      elements.panelBrowserLaunch.disabled = !canShare || Boolean(state.pendingGameShareGameId);
    }
  }
  if (elements.panelBrowserStop) {
    elements.panelBrowserStop.hidden = !(localGameSession || pendingShareJoinRequest);
    if (pendingShareJoinRequest) {
      elements.panelBrowserStop.textContent = cancelingShareJoinRequest ? "Canceling..." : "Cancel Request";
      elements.panelBrowserStop.disabled = cancelingShareJoinRequest || !socketReady;
    } else {
      elements.panelBrowserStop.textContent = "Stop";
      elements.panelBrowserStop.disabled = !socketReady;
    }
  }
  if (elements.panelBrowserExpand) {
    elements.panelBrowserExpand.disabled = !localGameSession;
    syncDisplayShareExpandButton(elements.panelBrowserExpand, false);
  }
  if (elements.panelBrowserResume) {
    elements.panelBrowserResume.hidden = true;
  }
  if (elements.panelBrowserVideo) {
    elements.panelBrowserVideo.hidden = true;
  }
  setPrivateBrowserPreviewStream(null);
  if (elements.panelBrowserFrame && previewUrl) {
    elements.panelBrowserFrame.hidden = false;
    if (elements.panelBrowserFrame.getAttribute("src") !== previewUrl) {
      elements.panelBrowserFrame.src = previewUrl;
    }
    elements.panelBrowserPlaceholder.hidden = true;
  } else if (elements.panelBrowserFrame && elements.panelBrowserPlaceholder) {
    elements.panelBrowserFrame.hidden = true;
    elements.panelBrowserFrame.removeAttribute("src");
    elements.panelBrowserPlaceholder.hidden = false;
    elements.panelBrowserPlaceholder.textContent = localGameSession
      ? "Open the game window to play, refresh the live preview, and let nearby visitors claim seats."
      : pendingShareJoinRequest
        ? "Waiting for the anchor host to approve this nearby game request."
        : joinMode && selectedGame
          ? "Share Game to add this packaged game inside the nearby group once the host approves."
      : selectedGame
        ? `${getPrivateSavedGameTitle(selectedGame)} is ready to share nearby.`
        : "Open the game library to choose, generate, import, or package a nearby game.";
  }
  renderPrivateShareJoinRequests();
  renderPrivateGameShareGroupSummary();
  updatePrivateVoicePanel();
  renderPrivateVoiceJoinOffers();
  renderPrivateVoiceJoinRequests();
}

function updatePrivateBrowserPanel() {
  state.browserShareMode = getActivePrivateBrowserShareModeFromUi() || normalizeBrowserShareKind(state.browserShareMode, "screen");
  for (const [sessionId, localShare] of [...state.localBrowserShares.entries()]) {
    if (isLocalDisplayShareActive(localShare)) {
      continue;
    }
    clearLocalPrivateBrowserShare({ stopTracks: false, sessionId });
    dropLocalPrivateBrowserSession(sessionId);
    if (sessionId) {
      sendWorldSocketMessage({
        type: "browser:stop",
        sessionId,
      });
    }
  }
  if (state.localVoiceShare && !isLocalDisplayShareActive(state.localVoiceShare)) {
    const endedVoiceSessionId = String(state.localVoiceShare.sessionId ?? state.localVoiceSessionId ?? "").trim();
    clearLocalPrivateVoiceShare({ stopTracks: false, sessionId: endedVoiceSessionId });
    dropLocalPrivateBrowserSession(endedVoiceSessionId);
    if (endedVoiceSessionId) {
      sendWorldSocketMessage({
        type: "voice:stop",
        sessionId: endedVoiceSessionId,
      });
    }
  }
  const world = state.selectedWorld;
  const gameMode = state.browserShareMode === "game";
  const localParticipant = getLocalParticipant();
  syncSelectedLocalPrivateBrowserShare();
  const localSession = getLocalPrivateBrowserSession();
  const localShare = getLocalPrivateBrowserShare();
  const localVoiceSession = getLocalPrivateVoiceSession();
  const joinTarget = getPrivateShareJoinTarget();
  const joinMode = Boolean(!localSession && joinTarget);
  const pendingShareJoinRequest = Boolean(!localSession && state.pendingShareJoin?.anchorSessionId && state.pendingShareJoin.approved !== true);
  const cancelingShareJoinRequest = pendingShareJoinRequest
    && isPrivateShareJoinCancellationPending(state.pendingShareJoin?.anchorSessionId);
  const titleLocked = joinMode || isPrivateBrowserMemberSession(localSession);
  const draft = privateBrowserShareFeature.getDraft(localSession);
  if (state.browserPanelRemoteSessionId && !state.browserSessions.has(state.browserPanelRemoteSessionId)) {
    state.browserPanelRemoteSessionId = "";
  }
  const mediaAvailable = state.browserMediaState.enabled !== false;
  const socketReady = state.worldSocket?.readyState === WebSocket.OPEN;
  const authStable = !state.authRefreshPromise;
  if (state.browserPanelRemoteSessionId && !state.browserSessions.has(state.browserPanelRemoteSessionId)) {
    state.browserPanelRemoteSessionId = "";
  }
  const remoteSession = localSession
    ? null
    : (() => {
      const sessionId = getPrivateRemotePanelSessionId();
      return sessionId ? state.browserSessions.get(sessionId) ?? null : null;
    })();
  const canShare = Boolean(state.session && world && localParticipant && mediaAvailable && socketReady && authStable);
  if (gameMode) {
    updatePrivateGamePanel({ canShare, socketReady });
    renderPrivateLocalBrowserShareStack();
    return;
  }
  elements.panelBrowserPanel?.classList.remove("is-game-mode");
  const previewStream = state.pendingBrowserShare?.hasVideo
    ? state.pendingBrowserShare.stream
    : localShare?.hasVideo
      ? localShare.stream
      : state.localBrowserPreviewStream ?? null;
  const remoteSessionHasVideo = Boolean(remoteSession && remoteSession.hasVideo !== false);
  const hasRemotePanelVideo = Boolean(
    !previewStream
    && remoteSessionHasVideo
    && remoteSession
    && elements.panelBrowserVideo?.srcObject
    && state.browserPanelRemoteSessionId === remoteSession.sessionId,
  );
  const needsPlaybackStart = Boolean(
    !previewStream
    && remoteSession
    && remoteSessionHasVideo
    && String(state.browserMediaState.lastPlayError || "").includes("NotAllowedError"),
  );
  const needsAudioStart = Boolean(
    remoteSession
    && state.browserMediaState.remoteAudioAvailable
    && state.browserMediaState.remoteAudioBlocked
    && state.browserMediaState.remoteAudioSessionId === remoteSession.sessionId,
  );
  const frameUrl = localSession?.lastFrameDataUrl ?? remoteSession?.lastFrameDataUrl ?? "";
  const hasActiveBrowserMedia = Boolean(previewStream || hasRemotePanelVideo || remoteSession || localSession || frameUrl);
  const stageLayout = getDisplayShareStageLayout({
    overlayOpen: state.browserOverlayOpen,
    needsManualPlaybackStart: needsPlaybackStart,
    needsManualAudioStart: needsAudioStart,
  });

  privateBrowserShareFeature.setSelectedMode(state.browserShareMode);
  elements.panelBrowserPanel?.classList.toggle("is-docked-compact", stageLayout.collapseDockedStage);
  elements.panelBrowserStage?.classList.toggle("is-active", hasActiveBrowserMedia);
  elements.panelBrowserStage?.classList.toggle("is-collapsed", stageLayout.collapseDockedStage);
  elements.panelBrowserStage?.classList.toggle("is-permission-only", stageLayout.permissionOnlyDockedStage);
  elements.panelBrowserStage?.classList.toggle("needs-video-start", stageLayout.needsManualPlaybackStart);
  if (elements.panelBrowserStage) {
    elements.panelBrowserStage.tabIndex = state.browserOverlayOpen ? 0 : -1;
    elements.panelBrowserStage.setAttribute("aria-hidden", stageLayout.collapseDockedStage ? "true" : "false");
  }
  if (elements.panelBrowserShareTitle) {
    elements.panelBrowserShareTitle.disabled = !canShare || titleLocked;
    if (titleLocked && document.activeElement !== elements.panelBrowserShareTitle) {
      elements.panelBrowserShareTitle.value = "";
    }
  }
  elements.panelBrowserShare?.classList.toggle("is-join-mode", titleLocked);
  renderPrivateShareJoinRequests();
  renderPrivateShareGroupSummary();
  updatePrivateVoicePanel();
  renderPrivateVoiceJoinOffers();
  renderPrivateVoiceJoinRequests();
  const localShareEntries = getPrivateLocalBrowserShareStackEntries();
  renderPrivateLocalBrowserShareStack(localShareEntries);
  const launchState = getDisplayShareLaunchState({
    canShare,
    pending: Boolean(state.pendingBrowserShare),
    localSession,
    draft,
  });
  syncDisplayShareActionButtons({
    launchButton: elements.panelBrowserLaunch,
    stopButton: elements.panelBrowserStop,
    launchState,
    showStop: Boolean(pendingShareJoinRequest),
  });
  if (!localSession && pendingShareJoinRequest && elements.panelBrowserLaunch) {
    elements.panelBrowserLaunch.textContent = cancelingShareJoinRequest ? "Canceling..." : "Waiting...";
    elements.panelBrowserLaunch.disabled = true;
  } else if (!localSession && joinMode && elements.panelBrowserLaunch) {
    const joinStateMatches = state.pendingShareJoin?.anchorSessionId === joinTarget?.sessionId;
    const waitingForApproval = joinStateMatches && state.pendingShareJoin.approved !== true;
    const joinApproved = joinStateMatches && state.pendingShareJoin.approved === true;
    elements.panelBrowserLaunch.textContent = waitingForApproval
      ? "Waiting..."
      : joinApproved
        ? `Start ${getBrowserShareKindLabel(state.browserShareMode)}`
        : `Request ${getBrowserShareKindLabel(state.browserShareMode)}`;
    elements.panelBrowserLaunch.disabled = !canShare || waitingForApproval || Boolean(state.pendingBrowserShare);
  }
  if (elements.panelBrowserStop) {
    if (pendingShareJoinRequest) {
      elements.panelBrowserStop.hidden = false;
      elements.panelBrowserStop.textContent = cancelingShareJoinRequest ? "Canceling..." : "Cancel Request";
      elements.panelBrowserStop.disabled = cancelingShareJoinRequest || !socketReady;
      elements.panelBrowserStop.setAttribute("aria-hidden", "false");
    } else {
      elements.panelBrowserStop.textContent = "Stop";
    }
  }
  syncDisplayShareExpandButton(elements.panelBrowserExpand, state.browserOverlayOpen);

  if (!world) {
    setPrivateBrowserStatus("Open a world to use nearby share.");
    updatePrivateBrowserSummary({
      state: "offline",
      badge: "Offline",
      current: "No world selected",
      hint: "Open a world first.",
    });
  } else if (state.pendingBrowserShare) {
    setPrivateBrowserStatus(`Starting ${getBrowserShareKindLabel(state.pendingBrowserShare.shareKind).toLowerCase()} share...`);
    updatePrivateBrowserSummary({
      state: "starting",
      badge: "Starting",
      current: `Starting ${getBrowserShareKindLabel(state.pendingBrowserShare.shareKind)}`,
      hint: state.pendingBrowserShare.title
        ? `"${state.pendingBrowserShare.title}" will go live after the permission prompt finishes.`
        : "Finish the permission prompt to go live.",
    });
  } else if (state.pendingShareJoin?.anchorSessionId && state.pendingShareJoin.approved !== true) {
    const hostName = getPrivateDisplayNameForSessionId(state.pendingShareJoin.anchorHostSessionId) || "nearby host";
    setPrivateBrowserStatus(
      cancelingShareJoinRequest
        ? `Canceling your nearby share request to ${hostName}...`
        : `Waiting for ${hostName} to approve your nearby share request...`,
    );
    updatePrivateBrowserSummary({
      state: "starting",
      badge: cancelingShareJoinRequest ? "Canceling" : "Waiting",
      current: `Requested ${getBrowserShareKindLabel(state.pendingShareJoin.shareKind || state.browserShareMode)}`,
      hint: cancelingShareJoinRequest
        ? "This request will disappear from the anchor host as soon as the world socket updates."
        : "Once approved, you can choose your screen, video, or voice and it will stay attached to this anchor group.",
    });
  } else if (remoteSession) {
    const shareKind = getBrowserShareKindLabel(remoteSession.shareKind || "screen");
    setPrivateBrowserStatus(
      shareKind === "Voice"
        ? `Listening to ${remoteSession.title || "live voice"} from this private world.`
        : `Viewing ${remoteSession.title || "nearby share"} from this private world.`,
    );
    updatePrivateBrowserSummary({
      state: "draft",
      badge: "Nearby",
      current: shareKind === "Voice"
        ? `Hearing ${remoteSession.title || "live voice"}`
        : `Seeing ${remoteSession.title || "nearby share"}`,
      hint: state.session
        ? "Your Share controls still start your own nearby share."
        : "Sign in if you want to start your own nearby share.",
    });
  } else if (!state.session) {
    setPrivateBrowserStatus("Guests can watch but cannot start nearby share.");
    updatePrivateBrowserSummary({
      state: "offline",
      badge: "Signed out",
      current: "Sign in to go live",
      hint: "Signed-in participants can share screen, video, or voice.",
    });
  } else if (!localSession && localParticipant && joinTarget) {
    const hostName = getPrivateDisplayNameForSessionId(joinTarget.hostSessionId) || "Nearby host";
    setPrivateBrowserStatus(`Join ${hostName}'s nearby share group after approval.`);
    updatePrivateBrowserSummary({
      state: "draft",
      badge: "Join",
      current: getPrivateBrowserSessionTitle(joinTarget),
      hint: "Choose Screen, Video, or Voice to request access. Contributor shares stay above your own character and stay out of What's Live.",
    });
  } else if (!localParticipant) {
    setPrivateBrowserStatus("Enter this world to start a live share.");
    updatePrivateBrowserSummary({
      state: "idle",
      badge: "Idle",
      current: "Enter to share",
      hint: "Join this private world first.",
    });
  } else if (isPrivateBrowserMemberSession(localSession)) {
    const anchorSession = resolvePrivateOriginSession(localSession);
    const anchorHostName = getPrivateDisplayNameForSessionId(anchorSession?.hostSessionId) || "nearby host";
    const shareKind = getBrowserShareKindLabel(getPrivateBrowserSessionShareKind(localSession));
    setPrivateBrowserStatus(
      localShare?.sessionId === localSession.sessionId
        ? `Sharing ${shareKind.toLowerCase()} inside ${anchorHostName}'s nearby group.`
        : `Allow ${shareKind.toLowerCase()} access to contribute inside ${anchorHostName}'s nearby group.`,
    );
    updatePrivateBrowserSummary({
      state: "live",
      badge: "Group",
      current: `${shareKind} contributor`,
      hint: "You can move while sharing, but leaving the anchor circle stops this contributor share.",
    });
  } else if (localSession?.sessionMode === "display-share") {
    const presentation = getLocalDisplaySharePresentation({
      localSession,
      localShare,
      draft,
      audienceLabel: "this private world",
      screenPrompt: "Share a tab or window to start the live stream.",
    });
    if (presentation) {
      if (localSession.movementLocked === true) {
        presentation.hint = `${presentation.hint} Movement stays locked while this anchor share is live.`;
      }
      if (!authStable || !socketReady) {
        presentation.hint = "This private world is reconnecting, but your live share is still on.";
      } else if (!mediaAvailable) {
        presentation.hint = "Live media is unavailable for new shares right now, but this share is still on.";
      }
      setPrivateBrowserStatus(presentation.status);
      updatePrivateBrowserSummary(presentation);
    }
  } else if (!authStable || !socketReady) {
    setPrivateBrowserStatus("Private world is still connecting. Wait a moment, then share again.");
    updatePrivateBrowserSummary({
      state: "starting",
      badge: "Starting",
      current: "Connecting world",
      hint: "Nearby Share will turn on once this private world finishes reconnecting.",
    });
  } else if (!mediaAvailable) {
    setPrivateBrowserStatus("Live share is unavailable right now.");
    updatePrivateBrowserSummary({
      state: "offline",
      badge: "Offline",
      current: "Live share unavailable",
      hint: "Live media is not available on this server right now.",
    });
  } else {
    setPrivateBrowserStatus("Share a screen, video, or voice nearby.");
    updatePrivateBrowserSummary(
      getDisplayShareReadyPresentation({
        draft,
        scopeLabel: "in this private world",
      }),
    );
  }

  if (previewStream) {
    setLocalPrivateBrowserPreviewStream(previewStream);
  } else if (remoteSession?._remoteElement?.srcObject && elements.panelBrowserVideo) {
    if (elements.panelBrowserVideo.srcObject !== remoteSession._remoteElement.srcObject) {
      elements.panelBrowserVideo.srcObject = remoteSession._remoteElement.srcObject;
    }
    elements.panelBrowserVideo.hidden = false;
    ensurePrivateBrowserVideoPlayback(elements.panelBrowserVideo);
  } else if (!hasRemotePanelVideo) {
    setPrivateBrowserPreviewStream(null);
  }

  if (!elements.panelBrowserFrame || !elements.panelBrowserPlaceholder) {
    return;
  }
  if (previewStream || hasRemotePanelVideo) {
    if (elements.panelBrowserVideo) {
      elements.panelBrowserVideo.hidden = false;
    }
    elements.panelBrowserFrame.hidden = true;
    elements.panelBrowserFrame.removeAttribute("src");
    elements.panelBrowserPlaceholder.hidden = !needsPlaybackStart;
    if (needsPlaybackStart) {
      elements.panelBrowserPlaceholder.textContent = getPrivateBrowserStagePlaceholderText({
        localSession,
        remoteSession,
        needsManualPlaybackStart: true,
      });
    }
    if (elements.panelBrowserResume) {
      elements.panelBrowserResume.hidden = !stageLayout.needsPermissionAction;
      elements.panelBrowserResume.textContent = needsPlaybackStart ? "Start Stream" : "Enable Sound";
    }
    return;
  }
  if (frameUrl) {
    if (elements.panelBrowserVideo) {
      elements.panelBrowserVideo.hidden = true;
    }
    elements.panelBrowserFrame.hidden = false;
    if (elements.panelBrowserFrame.getAttribute("src") !== frameUrl) {
      elements.panelBrowserFrame.src = frameUrl;
    }
    elements.panelBrowserPlaceholder.hidden = true;
    if (elements.panelBrowserResume) {
      elements.panelBrowserResume.hidden = true;
    }
    return;
  }
  if (elements.panelBrowserVideo) {
    elements.panelBrowserVideo.hidden = true;
  }
  elements.panelBrowserFrame.hidden = true;
  elements.panelBrowserFrame.removeAttribute("src");
  elements.panelBrowserPlaceholder.hidden = false;
  elements.panelBrowserPlaceholder.textContent = getPrivateBrowserStagePlaceholderText({
    localSession,
    remoteSession,
    needsManualPlaybackStart: needsPlaybackStart,
    needsManualAudioStart: needsAudioStart,
  });
  if (elements.panelBrowserResume) {
    elements.panelBrowserResume.hidden = !stageLayout.needsPermissionAction;
    elements.panelBrowserResume.textContent = needsPlaybackStart ? "Start Stream" : "Enable Sound";
  }
  if (!localVoiceSession && !state.pendingVoiceShare) {
    state.voiceJoinOffer = state.voiceJoinOffer?.anchorSessionId ? state.voiceJoinOffer : null;
  }
}

async function apiFetch(path, options = {}) {
  const method = String(options.method ?? "GET").toUpperCase();
  const headers = {
    "Content-Type": "application/json",
    ...(options.headers ?? {}),
  };
  if (state.session?.access_token && !headers.Authorization) {
    headers.Authorization = `Bearer ${state.session.access_token}`;
  }
  if (options.body === undefined) {
    delete headers["Content-Type"];
  }
  const timeoutMs = Math.max(1000, Number(options.timeoutMs ?? 15000));
  const retryCount = Number.isFinite(Number(options.retryCount))
    ? Math.max(0, Math.floor(Number(options.retryCount)))
    : (method === "GET" ? 1 : 0);
  const requestUrl = mauworldApiUrl(path, options.search);
  let lastError = null;
  for (let attempt = 0; attempt <= retryCount; attempt += 1) {
    const controller = new AbortController();
    const timeoutId = window.setTimeout(() => controller.abort("timeout"), timeoutMs);
    try {
      const response = await fetch(requestUrl, {
        method,
        headers,
        body: options.body !== undefined ? JSON.stringify(options.body) : undefined,
        signal: controller.signal,
      });
      const payload = await response.json().catch(() => ({}));
      if (!response.ok || payload.ok === false) {
        throw new Error(payload.error || `Request failed (${response.status})`);
      }
      return payload;
    } catch (error) {
      lastError = error;
      const aborted = error?.name === "AbortError";
      const networkFailure = aborted || error instanceof TypeError || /failed to fetch/i.test(String(error?.message ?? ""));
      const canRetry = attempt < retryCount && networkFailure;
      if (canRetry) {
        await new Promise((resolve) => window.setTimeout(resolve, 500 * (attempt + 1)));
        continue;
      }
      if (aborted) {
        throw new Error("Mauworld API timed out. Please try again in a moment.");
      }
      if (error instanceof TypeError || /failed to fetch/i.test(String(error?.message ?? ""))) {
        throw new Error("Could not reach Mauworld right now. Please refresh or try again in a moment.");
      }
      throw error;
    } finally {
      window.clearTimeout(timeoutId);
    }
  }
  throw lastError ?? new Error("Could not complete the request.");
}

async function fetchAuthConfig() {
  state.authReady = false;
  renderSessionSummary();
  renderAccessSection();
  updateShellState();
  try {
    state.authConfig = await apiFetch("/public/auth/config");
    state.supabase = createClient(state.authConfig.supabaseUrl, state.authConfig.supabaseAnonKey);
    const { data } = await state.supabase.auth.getSession();
    state.session = data.session;
    state.supabase.auth.onAuthStateChange((_event, session) => {
      state.session = session;
      void refreshAuthState();
    });
  } finally {
    state.authReady = true;
    renderSessionSummary();
    renderAccessSection();
    updateShellState();
  }
}

async function runRefreshAuthState() {
  renderSessionSummary();
  renderAccessSection();
  if (!state.session) {
    await releaseSceneLock();
    state.profile = null;
    state.profileLauncherTab = "account";
    state.profileWorldQuery = "";
    state.profileAssets = [];
    state.profileAssetsLoading = false;
    state.profileResourceQuery = "";
    state.publicWorlds = [];
    state.publicWorldsLoading = false;
    state.publicWorldsError = "";
    state.worlds = [];
    state.worldsLoading = false;
    state.worldsError = "";
    state.assets = [];
    state.assetsLoading = false;
    state.selectedWorld = null;
    state.selectedSceneId = "";
    state.selectedPrefabId = "";
    state.selectedScriptFunctionId = "";
    clearRuntimeSnapshot();
    state.privateChatEntries = [];
    state.activeChats.clear();
    state.livePresence.clear();
    reconcilePrivatePresenceScene();
    state.pressedRuntimeKeys.clear();
    privateInputState.keys.clear();
    privateInputState.sprintHoldSeconds = 0;
    privateInputState.pointerDown = false;
    privateInputState.pointerButtonToken = "";
    privateInputState.pointerMoved = false;
    privateInputState.dragDistance = 0;
    state.viewerSuppressClickAt = 0;
    state.buildSuppressedClick = null;
    resetPrivateBrowserState({ disconnectController: true, stopTracks: true });
    setEntryLoading(false);
    renderProfileLauncher();
    renderLauncherWorldBrowser();
    renderSelectedWorld();
    renderAssetsLibrary();
    setLauncherTab("access");
    setLauncherOpen(true);
    disconnectWorldSocket();
    return;
  }
  try {
    state.worldsLoading = true;
    state.worldsError = "";
    renderLauncherWorldBrowser();
    const payload = await apiFetch("/private/profile");
    state.profile = payload.profile;
    renderProfileLauncher();
    renderAccessSection();
    renderSessionSummary();
    await loadWorlds();
    void loadAssets();
    if (state.launcherTab === "profile" && state.profileLauncherTab === "resources") {
      void loadProfileAssets();
    }
    const launch = getLaunchRequest();
    const launcherIntent = getLauncherIntent();
    const hasLaunchRequest = Boolean(launch.worldId && launch.creatorUsername);
    const launchParticipant = getLocalParticipant(state.selectedWorld);
    const shouldReplayLaunch =
      hasLaunchRequest
      && (
        !selectedWorldMatchesLaunchRequest(launch)
        || (launch.autojoin && (!launchParticipant || launchParticipant.join_role === "guest"))
      );
    if (shouldReplayLaunch) {
      await handleLaunchRequest({ force: true });
    }
    if (state.launcherTab === "access") {
      setLauncherTab("worlds");
    }
    if (!hasLaunchRequest && !state.selectedWorld) {
      setLauncherOpen(true);
      setLauncherTab(getPreferredLauncherTab());
      if (launcherIntent.create && !state.launcherIntentHandled) {
        state.launcherIntentHandled = true;
        setCreateWorldDialogOpen(true);
      }
    }
  } catch (error) {
    state.worldsLoading = false;
    state.worldsError = String(error?.message || "Could not load your private worlds.");
    renderWorldList();
    setStatus(error.message);
  }
}

async function refreshAuthState() {
  state.authRefreshQueued = true;
  if (state.authRefreshPromise) {
    return state.authRefreshPromise;
  }
  state.authRefreshPromise = (async () => {
    while (state.authRefreshQueued) {
      state.authRefreshQueued = false;
      await runRefreshAuthState();
    }
  })().finally(() => {
    state.authRefreshPromise = null;
  });
  return state.authRefreshPromise;
}

function renderProfile() {
  if (!state.authReady || !state.session || !state.profile) {
    elements.profileForm.hidden = true;
    elements.accountActions.hidden = true;
    return;
  }
  elements.profileForm.hidden = false;
  elements.accountActions.hidden = false;
  elements.profileForm.elements.username.value = state.profile.username || "";
  elements.profileForm.elements.displayName.value = state.profile.display_name || "";
}

function renderAccessSection() {
  if (state.authReady !== true) {
    if (elements.accessHeading) {
      elements.accessHeading.textContent = "Checking account";
    }
    if (elements.accessNote) {
      elements.accessNote.textContent = "Loading your account before this private world opens.";
    }
    if (elements.authForm) {
      elements.authForm.hidden = true;
    }
    elements.authForm.hidden = true;
    renderLauncherTitle();
    return;
  }
  if (elements.accessHeading) {
    elements.accessHeading.textContent = "Sign in";
  }
  if (elements.accessNote) {
    elements.accessNote.textContent = "There is no shared demo login here. Use your own email and password, or create an account first.";
  }
  if (elements.authForm) {
    elements.authForm.hidden = Boolean(state.session);
  }
  renderLauncherTitle();
}

function normalizeProfileLauncherTab(tab = "") {
  return PROFILE_LAUNCHER_TABS.has(tab) ? tab : "account";
}

function buildProfileAssetSummary(asset = {}) {
  const typeLabel = asset.asset_type === "model"
    ? "Model"
    : asset.asset_type === "sound"
      ? "Sound"
      : isVideoTextureAsset(asset)
        ? "Video Texture"
        : "Texture";
  return {
    title: asset.name || asset.id || "Untitled asset",
    meta: `${typeLabel} · ${buildAssetSummary(asset)}`,
    note: asset.intended_use || asset.world_context_summary || "Ready across your private worlds.",
    thumbnail: getPrivateAssetFile(asset, asset.asset_type === "model" ? "thumbnail" : "base_color"),
  };
}

function renderProfileWorldBrowser() {
  if (!elements.profileWorldList) {
    return;
  }
  if (!state.session) {
    elements.profileWorldList.innerHTML = '<div class="pw-world-card"><p>Sign in to load your private worlds.</p></div>';
    return;
  }
  if (elements.profileWorldSearch && elements.profileWorldSearch.value !== state.profileWorldQuery) {
    elements.profileWorldSearch.value = state.profileWorldQuery;
  }
  if (state.worldsLoading) {
    elements.profileWorldList.innerHTML = [
      '<div class="world-private-gate__placeholder" aria-hidden="true"></div>',
      '<div class="world-private-gate__placeholder" aria-hidden="true"></div>',
      '<div class="world-private-gate__placeholder" aria-hidden="true"></div>',
    ].join("");
    return;
  }
  if (state.worldsError) {
    elements.profileWorldList.innerHTML = `<p class="world-empty">${htmlEscape(state.worldsError)}</p>`;
    return;
  }
  const query = String(state.profileWorldQuery ?? "").trim().toLowerCase();
  const worlds = (state.worlds ?? []).filter((world) => {
    if (!query) {
      return true;
    }
    const haystack = [
      world.name,
      world.about,
      world.world_type,
      world.template_size,
    ].filter(Boolean).join(" ").toLowerCase();
    return haystack.includes(query);
  });
  if (!worlds.length) {
    elements.profileWorldList.innerHTML = query
      ? '<p class="world-empty">No private worlds match that search.</p>'
      : '<div class="pw-world-card"><p>No private worlds yet. Create one to get started.</p></div>';
    return;
  }
  elements.profileWorldList.innerHTML = buildPrivateWorldBrowserResultsMarkup(worlds, {
    selectedKey: state.selectedWorld ? getPrivateWorldBrowserKey(state.selectedWorld) : "",
    resultDataAttribute: "data-profile-world-result",
    includeStatus: true,
  });
}

function renderProfileGameLibrarySummary() {
  if (!elements.profileGameSummary) {
    return;
  }
  if (!state.session) {
    elements.profileGameSummary.innerHTML = '<p>Sign in to open your saved games and nearby share packages.</p>';
    return;
  }
  const selectedGame = getSelectedPrivateWorldGame();
  const liveSession = getLocalPrivateGameSession();
  if (liveSession) {
    elements.profileGameSummary.innerHTML = `
      <strong>${htmlEscape(getGameSessionTitle(liveSession))}</strong>
      <p>${htmlEscape(liveSession.started ? "Your nearby game match is live right now." : "Your nearby game lobby is open and ready for seats.")}</p>
    `;
    return;
  }
  if (selectedGame) {
    elements.profileGameSummary.innerHTML = `
      <strong>${htmlEscape(getPrivateSavedGameTitle(selectedGame))}</strong>
      <p>${htmlEscape(selectedGame.manifest?.summary || selectedGame.prompt || "Open the game library to refine, export, or share this game nearby.")}</p>
    `;
    return;
  }
  elements.profileGameSummary.innerHTML = `
    <strong>No game selected</strong>
    <p>Open your game library to generate new games, import packages, or pick one for nearby sharing.</p>
  `;
}

function renderProfileResourcesBrowser() {
  if (!elements.profileResourceList) {
    return;
  }
  if (!state.session) {
    elements.profileResourceList.innerHTML = '<div class="pw-world-card"><p>Sign in to load shared resources.</p></div>';
    if (elements.profileResourceStatus) {
      elements.profileResourceStatus.textContent = "";
    }
    return;
  }
  if (elements.profileResourceSearch && elements.profileResourceSearch.value !== state.profileResourceQuery) {
    elements.profileResourceSearch.value = state.profileResourceQuery;
  }
  if (state.profileAssetsLoading) {
    elements.profileResourceList.innerHTML = [
      '<article class="pw-prefab-card"><p class="pw-builder-empty">Loading shared resources...</p></article>',
      '<article class="pw-prefab-card"><p class="pw-builder-empty">Loading shared resources...</p></article>',
    ].join("");
    if (elements.profileResourceStatus) {
      elements.profileResourceStatus.textContent = "Loading shared resources...";
    }
    return;
  }
  const query = String(state.profileResourceQuery ?? "").trim().toLowerCase();
  const assets = (state.profileAssets ?? []).filter((asset) => {
    if (!query) {
      return true;
    }
    const haystack = [
      asset.name,
      asset.asset_type,
      asset.provider,
      asset.intended_use,
      asset.world_context_summary,
    ].filter(Boolean).join(" ").toLowerCase();
    return haystack.includes(query);
  });
  if (elements.profileResourceStatus) {
    elements.profileResourceStatus.textContent = `${assets.length} shared resource${assets.length === 1 ? "" : "s"} shown.`;
  }
  if (!assets.length) {
    elements.profileResourceList.innerHTML = query
      ? '<div class="pw-world-card"><p>No shared resources match that search.</p></div>'
      : '<div class="pw-world-card"><p>No shared resources yet. Generate or upload assets from a private world first.</p></div>';
    return;
  }
  elements.profileResourceList.innerHTML = assets.map((asset) => {
    const summary = buildProfileAssetSummary(asset);
    return `
      <article class="pw-prefab-card">
        <div class="pw-prefab-card__head">
          <strong>${htmlEscape(summary.title)}</strong>
          <span>${htmlEscape(asset.asset_type === "model" ? "model" : asset.asset_type === "sound" ? "sound" : isVideoTextureAsset(asset) ? "video texture" : "texture")}</span>
        </div>
        ${summary.thumbnail?.url
          ? `<img class="pw-asset-thumb" src="${htmlEscape(summary.thumbnail.url)}" alt="${htmlEscape(summary.title)}" />`
          : asset.asset_type === "sound"
            ? '<div class="pw-asset-thumb pw-asset-thumb--empty">audio</div>'
            : isVideoTextureAsset(asset)
              ? '<div class="pw-asset-thumb pw-asset-thumb--empty">video</div>'
              : ""}
        <p>${htmlEscape(summary.meta)}</p>
        <small>${htmlEscape(summary.note)}</small>
      </article>
    `;
  }).join("");
}

function renderProfileLauncherTabs() {
  const activeTab = normalizeProfileLauncherTab(state.profileLauncherTab);
  state.profileLauncherTab = activeTab;
  for (const button of elements.profileLauncherTabButtons ?? []) {
    const isActive = button.getAttribute("data-profile-launcher-tab") === activeTab;
    button.classList.toggle("is-active", isActive);
    button.setAttribute("aria-selected", String(isActive));
  }
  for (const pane of elements.profileLauncherPanes ?? []) {
    pane.hidden = pane.getAttribute("data-profile-pane") !== activeTab;
  }
}

function renderProfileLauncher() {
  renderProfileLauncherTabs();
  renderProfile();
  renderProfileWorldBrowser();
  renderProfileGameLibrarySummary();
  renderProfileResourcesBrowser();
}

function loadProfileLauncherData(tab = state.profileLauncherTab) {
  const activeTab = normalizeProfileLauncherTab(tab);
  if (!state.session) {
    return;
  }
  if (activeTab === "worlds") {
    void loadWorlds();
  }
  if (activeTab === "resources") {
    void loadProfileAssets();
  }
}

function setProfileLauncherTab(tab, options = {}) {
  state.profileLauncherTab = normalizeProfileLauncherTab(tab);
  if (!canShowCreateWorldDialog(state.launcherTab, state.profileLauncherTab)) {
    state.createWorldDialogOpen = false;
  }
  syncCreateWorldDialogVisibility();
  renderProfileLauncher();
  if (options.load === false) {
    return;
  }
  loadProfileLauncherData(state.profileLauncherTab);
}

function renderSessionSummary() {
  if (!elements.panelSessionLabel || !elements.panelOpenAccess) {
    return;
  }
  if (!state.authReady) {
    elements.panelSessionLabel.textContent = "Checking your account.";
    elements.panelOpenAccess.classList.remove("is-profile-icon");
    if (elements.panelOpenAccessIcon) {
      elements.panelOpenAccessIcon.hidden = true;
    }
    if (elements.panelOpenAccessLabel) {
      elements.panelOpenAccessLabel.classList.remove("pw-visually-hidden");
      elements.panelOpenAccessLabel.textContent = "Loading";
    }
    elements.panelOpenAccess.setAttribute("aria-label", "Loading account");
    elements.panelOpenAccess.disabled = true;
    return;
  }
  elements.panelOpenAccess.disabled = false;
  if (state.session && state.profile) {
    elements.panelSessionLabel.textContent = `Signed in as @${state.profile.username || "user"}.`;
    elements.panelOpenAccess.classList.add("is-profile-icon");
    if (elements.panelOpenAccessIcon) {
      elements.panelOpenAccessIcon.hidden = false;
    }
    if (elements.panelOpenAccessLabel) {
      elements.panelOpenAccessLabel.classList.add("pw-visually-hidden");
      elements.panelOpenAccessLabel.textContent = "My profile";
    }
    elements.panelOpenAccess.setAttribute("aria-label", "Open my profile");
    return;
  }
  if (state.session) {
    elements.panelSessionLabel.textContent = "Signed in.";
    elements.panelOpenAccess.classList.add("is-profile-icon");
    if (elements.panelOpenAccessIcon) {
      elements.panelOpenAccessIcon.hidden = false;
    }
    if (elements.panelOpenAccessLabel) {
      elements.panelOpenAccessLabel.classList.add("pw-visually-hidden");
      elements.panelOpenAccessLabel.textContent = "My profile";
    }
    elements.panelOpenAccess.setAttribute("aria-label", "Open my profile");
    return;
  }
  elements.panelSessionLabel.textContent = "Sign in to open your private worlds.";
  elements.panelOpenAccess.classList.remove("is-profile-icon");
  if (elements.panelOpenAccessIcon) {
    elements.panelOpenAccessIcon.hidden = true;
  }
  if (elements.panelOpenAccessLabel) {
    elements.panelOpenAccessLabel.classList.remove("pw-visually-hidden");
    elements.panelOpenAccessLabel.textContent = "Sign In";
  }
  elements.panelOpenAccess.setAttribute("aria-label", "Sign in");
}

async function loadWorlds() {
  if (!state.session) {
    state.worldsLoading = false;
    state.worldsError = "";
    state.worlds = [];
    renderLauncherWorldBrowser();
    renderProfileWorldBrowser();
    return;
  }
  state.worldsLoading = true;
  state.worldsError = "";
  renderLauncherWorldBrowser();
  renderProfileWorldBrowser();
  try {
    const payload = await apiFetch("/private/worlds", {
      search: {
        q: elements.worldSearch?.value || "",
      },
    });
    state.worlds = payload.worlds ?? [];
    state.worldsError = "";
  } catch (error) {
    state.worldsError = String(error?.message || "Could not load your private worlds.");
  } finally {
    state.worldsLoading = false;
    renderLauncherWorldBrowser();
    renderProfileWorldBrowser();
    if (state.launcherOpen && state.launcherTab !== "profile" && !state.selectedWorld && !state.worldsError) {
      setLauncherTab(getPreferredLauncherTab());
    }
  }
}

async function loadAssets() {
  if (!state.session) {
    state.assetsLoading = false;
    state.assets = [];
    renderAssetsLibrary();
    return;
  }
  state.assetsLoading = true;
  renderAssetsLibrary();
  try {
    const payload = await apiFetch("/private/assets", {
      search: {
        q: state.assetQuery || "",
        assetType: state.assetFilterType === "all" ? undefined : state.assetFilterType,
      },
    });
    state.assets = payload.assets ?? [];
  } catch (_error) {
    state.assets = [];
  } finally {
    state.assetsLoading = false;
    renderAssetsLibrary();
  }
}

async function loadProfileAssets() {
  if (!state.session) {
    state.profileAssetsLoading = false;
    state.profileAssets = [];
    renderProfileResourcesBrowser();
    return;
  }
  state.profileAssetsLoading = true;
  renderProfileResourcesBrowser();
  try {
    const payload = await apiFetch("/private/assets", {
      search: {
        q: state.profileResourceQuery || "",
      },
    });
    state.profileAssets = payload.assets ?? [];
  } catch (_error) {
    state.profileAssets = [];
  } finally {
    state.profileAssetsLoading = false;
    renderProfileResourcesBrowser();
  }
}

function readFileAsDataUrl(file, label = "file") {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onerror = () => reject(new Error(`Could not read that ${label}.`));
    reader.onload = () => resolve(String(reader.result ?? ""));
    reader.readAsDataURL(file);
  });
}

async function uploadPrivateSoundAsset(file, options = {}) {
  if (!state.session || !state.selectedWorld) {
    throw new Error("Sign in and open a world before uploading sounds.");
  }
  const dataUrl = await readFileAsDataUrl(file, "audio file");
  const target = options.target ?? getSelectedSoundAttachTarget();
  const payload = await apiFetch("/private/assets/upload-sound", {
    method: "POST",
    body: {
      name: (options.name ?? file.name.replace(/\.[^.]+$/, "")) || "Sound Asset",
      file_name: file.name || "sound-asset.mp3",
      content_type: file.type || "audio/mpeg",
      data_url: dataUrl,
      intended_use: options.intendedUse ?? (target ? `Sound for ${target.title}` : "Private world sound"),
      world_context_summary: options.worldContextSummary ?? `Uploaded for ${state.selectedWorld.name}.`,
      worldId: state.selectedWorld.world_id,
      worldName: state.selectedWorld.name,
      targetLabel: target?.title ?? "",
    },
  });
  await loadAssets();
  const assetId = payload?.asset?.id || "";
  if (assetId && target) {
    applySoundAssetToSelection(assetId, {
      targetKind: target.kind,
      targetId: target.id,
    });
  }
  setSceneDrawerOpen(true);
  setSceneDrawerTab("assets");
  state.assetFilterType = "sound";
  if (elements.assetTypeFilter) {
    elements.assetTypeFilter.value = "sound";
  }
  setStatus(`Uploaded sound asset ${payload?.asset?.name || file.name}.`);
  pushEvent("asset:sound-uploaded", payload?.asset?.name || file.name);
  return payload?.asset ?? null;
}

async function uploadPrivateVideoTextureAsset(file, options = {}) {
  if (!state.session || !state.selectedWorld) {
    throw new Error("Sign in and open a world before uploading video textures.");
  }
  const dataUrl = await readFileAsDataUrl(file, "video file");
  const target = options.target ?? getSelectedTextureAttachTarget();
  const payload = await apiFetch("/private/assets/upload-video-texture", {
    method: "POST",
    body: {
      name: (options.name ?? file.name.replace(/\.[^.]+$/, "")) || "Video Texture",
      file_name: file.name || "video-texture.mp4",
      content_type: file.type || "video/mp4",
      data_url: dataUrl,
      intended_use: options.intendedUse ?? (target ? `Video texture for ${target.title}` : "Private world video texture"),
      world_context_summary: options.worldContextSummary ?? `Uploaded for ${state.selectedWorld.name}.`,
      worldId: state.selectedWorld.world_id,
      worldName: state.selectedWorld.name,
      targetLabel: target?.title ?? "",
    },
  });
  await loadAssets();
  const assetId = payload?.asset?.id || "";
  if (assetId && target) {
    applyTextureAssetToSelection(assetId, {
      targetKind: target.kind,
      targetId: target.id,
    });
  }
  setSceneDrawerOpen(true);
  setSceneDrawerTab("assets");
  state.assetFilterType = "texture";
  if (elements.assetTypeFilter) {
    elements.assetTypeFilter.value = "texture";
  }
  setStatus(`Uploaded video texture ${payload?.asset?.name || file.name}.`);
  pushEvent("asset:video-texture-uploaded", payload?.asset?.name || file.name);
  return payload?.asset ?? null;
}

async function loadPublicWorlds() {
  state.publicWorldsLoading = true;
  state.publicWorldsError = "";
  renderLauncherWorldBrowser();
  try {
    const payload = await apiFetch("/public/private-worlds", {
      search: {
        q: elements.worldSearch?.value || "",
        worldType: elements.publicWorldType?.value || "",
      },
    });
    state.publicWorlds = payload.worlds ?? [];
    state.publicWorldsError = "";
  } catch (error) {
    state.publicWorldsError = String(error?.message || "Could not load all private worlds.");
  } finally {
    state.publicWorldsLoading = false;
    renderLauncherWorldBrowser();
  }
}

function renderLauncherWorldBrowser() {
  if (!elements.worldList) {
    return;
  }
  renderLauncherWorldTabs();
  const activeTab = normalizeLauncherWorldTab(state.launcherWorldTab);
  const worlds = activeTab === "all" ? state.publicWorlds : state.worlds;
  const loading = activeTab === "all" ? state.publicWorldsLoading : state.worldsLoading;
  const error = activeTab === "all" ? state.publicWorldsError : state.worldsError;
  if (loading) {
    elements.worldList.innerHTML = [
      '<div class="world-private-gate__placeholder" aria-hidden="true"></div>',
      '<div class="world-private-gate__placeholder" aria-hidden="true"></div>',
      '<div class="world-private-gate__placeholder" aria-hidden="true"></div>',
    ].join("");
    return;
  }
  if (error) {
    elements.worldList.innerHTML = `<p class="world-empty">${htmlEscape(error)}</p>`;
    return;
  }
  if (!worlds.length) {
    elements.worldList.innerHTML = activeTab === "all"
      ? '<p class="world-empty">No private worlds match this search right now.</p>'
      : '<div class="pw-world-card"><p>No private worlds yet. Create one to get started.</p></div>';
    return;
  }
  elements.worldList.innerHTML = buildPrivateWorldBrowserResultsMarkup(worlds, {
    selectedKey: state.selectedWorld ? getPrivateWorldBrowserKey(state.selectedWorld) : "",
    resultDataAttribute: "data-launcher-world-result",
    includeCreator: activeTab === "all",
    includeOccupancy: activeTab === "all",
    includeLineage: activeTab === "all",
    includeStatus: activeTab !== "all",
  });
}

function renderWorldList() {
  renderLauncherWorldBrowser();
}

function buildMetaRows(world) {
  if (!world) {
    return [];
  }
  const accessPolicy = getWorldAccessPolicy(world);
  const creatorUsername = String(world.creator?.username ?? world.creator_username ?? "").trim();
  const creatorDisplayName = String(world.creator?.display_name ?? world.creator_display_name ?? creatorUsername).trim();
  const dimensions = [world.width, world.length, world.height]
    .map((value) => Number(value))
    .filter((value) => Number.isFinite(value) && value > 0);
  const sizeLabel = dimensions.length === 3
    ? `${dimensions[0]} × ${dimensions[1]} × ${dimensions[2]}`
    : "Not set";
  const typeParts = [
    String(world.world_type ?? "").trim(),
    String(world.template_size ?? "").trim(),
  ].filter(Boolean);
  const viewerCount = Number(world.active_instance?.viewer_count);
  const maxViewers = Number(world.max_viewers);
  const viewerLabel = Number.isFinite(viewerCount) && Number.isFinite(maxViewers) && maxViewers > 0
    ? `${Math.max(0, viewerCount)} inside now · ${Math.max(1, maxViewers)} max`
    : Number.isFinite(viewerCount)
      ? `${Math.max(0, viewerCount)} inside now`
      : Number.isFinite(maxViewers) && maxViewers > 0
        ? `${Math.max(1, maxViewers)} max`
        : "No live occupancy";
  const lineageImported = Boolean(
    world.lineage?.is_imported
    || world.origin_world_id
    || world.origin_creator_username
    || world.origin_world_name,
  );
  const lineageWorld = String(world.lineage?.origin_world_name ?? world.lineage?.origin_world_id ?? world.origin_world_name ?? world.origin_world_id ?? "").trim();
  const lineageCreator = String(world.lineage?.origin_creator_username ?? world.origin_creator_username ?? "").trim();
  const creatorLabel = creatorDisplayName && creatorUsername && creatorDisplayName.toLowerCase() !== creatorUsername.toLowerCase()
    ? `${creatorDisplayName} (@${creatorUsername})`
    : creatorUsername
      ? `@${creatorUsername}`
      : creatorDisplayName || "Unknown creator";
  const activeStatus = String(world.active_instance?.status ?? "").trim().toLowerCase();
  const isActive = activeStatus === "active";
  return [
    { label: "World ID", value: String(world.world_id ?? "").trim() || "Not set" },
    { label: "Creator", value: creatorLabel },
    { label: "Size", value: sizeLabel },
    { label: "Type", value: typeParts.join(" · ") || "Not set" },
    { label: "Viewers", value: viewerLabel },
    { label: "Entry", value: isActive ? "Copy Entry above to jump straight in." : "Inactive right now. The entry link still resolves it." },
    {
      label: "Viewer package access",
      value: `${accessPolicy.allowNonEditorExport ? "Export on" : "Export off"} · ${accessPolicy.allowNonEditorFork ? "Fork on" : "Fork off"}`,
    },
    {
      label: "Lineage",
      value: lineageImported
        ? `Forked from ${lineageWorld || "another world"}${lineageCreator ? ` by @${lineageCreator}` : ""}`
        : "Original world",
    },
  ];
}

function buildPrivateWorldEntryUrl(world = state.selectedWorld) {
  if (!world) {
    return "";
  }
  const url = new URL("/social/private-worlds.html", window.location.origin);
  url.searchParams.set("worldId", world.world_id);
  url.searchParams.set("creatorUsername", world.creator.username);
  url.searchParams.set("autojoin", "true");
  return url.toString();
}

function renderMetaRows(target, rows) {
  if (!target) {
    return;
  }
  target.innerHTML = rows.map((row) => `
    <div class="pw-world-meta__row">
      <strong>${htmlEscape(row.label)}</strong>
      <span>${htmlEscape(String(row.value ?? "").trim() || "Not set")}</span>
    </div>
  `).join("");
}

function getSceneById(sceneId = "", world = state.selectedWorld) {
  const normalizedSceneId = String(sceneId ?? "").trim();
  if (!normalizedSceneId) {
    return null;
  }
  return (world?.scenes ?? []).find((scene) => scene.id === normalizedSceneId) ?? null;
}

function getSelectedScene() {
  return getSceneById(state.selectedSceneId) ?? state.selectedWorld?.scenes?.[0] ?? null;
}

function getSceneDrawerFocusedScene() {
  return getSceneById(state.sceneDrawerFocusId) ?? getSelectedScene();
}

function getSceneEditorScene() {
  return state.sceneDrawerTab === "scenes"
    ? getSceneDrawerFocusedScene()
    : getSelectedScene();
}

function syncSceneDrawerFocusScene(world = state.selectedWorld) {
  const scenes = Array.isArray(world?.scenes) ? world.scenes : [];
  if (!scenes.length) {
    state.sceneDrawerFocusId = "";
    return null;
  }
  if (state.sceneDrawerTab !== "scenes") {
    state.sceneDrawerFocusId = getSelectedScene()?.id ?? scenes[0].id;
    return getSceneById(state.sceneDrawerFocusId, world);
  }
  const focusedScene = getSceneById(state.sceneDrawerFocusId, world);
  if (focusedScene) {
    return focusedScene;
  }
  state.sceneDrawerFocusId = getSelectedScene()?.id ?? scenes[0].id;
  return getSceneById(state.sceneDrawerFocusId, world);
}

function resolvePreferredSelectedSceneId(world = state.selectedWorld, options = {}) {
  const scenes = Array.isArray(world?.scenes) ? world.scenes : [];
  if (!scenes.length) {
    return "";
  }
  const previousSelectedSceneId = String(options.previousSelectedSceneId ?? state.selectedSceneId ?? "").trim();
  const activeSceneId = String(world?.active_instance?.active_scene_id ?? "").trim();
  const defaultSceneId = activeSceneId
    || String(world?.default_scene_id ?? "").trim()
    || scenes.find((scene) => scene.is_default === true)?.id
    || scenes[0]?.id
    || "";
  const canPreserveSelection =
    options.preferSelected !== false
    && state.mode === "build"
    && world?.permissions?.can_edit === true
    && scenes.some((scene) => scene.id === previousSelectedSceneId);
  return canPreserveSelection ? previousSelectedSceneId : defaultSceneId;
}

function getDefaultScene(world = state.selectedWorld) {
  const scenes = world?.scenes ?? [];
  return scenes.find((scene) => scene.id === world?.default_scene_id)
    ?? scenes.find((scene) => scene.is_default === true)
    ?? scenes[0]
    ?? null;
}

function buildSceneEditorSnapshot(scene = getSceneEditorScene(), overrides = {}) {
  const sceneId = String(overrides.sceneId ?? scene?.id ?? state.sceneEditorSceneId ?? state.selectedSceneId ?? "").trim();
  if (!sceneId || !elements.sceneForm?.elements) {
    return null;
  }
  return {
    sceneId,
    name: overrides.name != null
      ? String(overrides.name)
      : String(elements.sceneForm.elements.name?.value ?? scene?.name ?? ""),
    isDefault: overrides.isDefault != null
      ? Boolean(overrides.isDefault)
      : elements.sceneForm.elements.isDefault?.checked === true,
    sceneDocText: overrides.sceneDocText != null
      ? String(overrides.sceneDocText)
      : String(elements.sceneForm.elements.sceneDoc?.value ?? (scene ? JSON.stringify(scene.scene_doc ?? {}, null, 2) : "")),
    scriptDslText: overrides.scriptDslText != null
      ? String(overrides.scriptDslText)
      : String(elements.sceneForm.elements.scriptDsl?.value ?? scene?.scene_doc?.script_dsl ?? ""),
  };
}

function getSceneDraft(sceneId = state.sceneEditorSceneId || state.selectedSceneId) {
  const key = String(sceneId ?? "").trim();
  return key ? state.sceneDrafts.get(key) ?? null : null;
}

function rememberSceneDraft(overrides = {}) {
  const snapshot = buildSceneEditorSnapshot(getSceneEditorScene(), overrides);
  if (snapshot?.sceneId) {
    state.sceneDrafts.set(snapshot.sceneId, snapshot);
  }
}

function discardSceneDraft(sceneId = state.sceneEditorSceneId || state.selectedSceneId) {
  const key = String(sceneId ?? "").trim();
  if (!key) {
    return;
  }
  state.sceneDrafts.delete(key);
  if (state.sceneEditorSceneId === key) {
    state.sceneEditorSceneId = "";
  }
}

function buildSceneDocFromDraft(scene = null, draft = null) {
  if (!scene && !draft) {
    return null;
  }
  const sceneDocText = String(draft?.sceneDocText ?? JSON.stringify(scene?.scene_doc ?? {}, null, 2));
  try {
    const sceneDoc = JSON.parse(sceneDocText || "{}");
    sceneDoc.script_dsl = String(draft?.scriptDslText ?? sceneDoc.script_dsl ?? scene?.scene_doc?.script_dsl ?? "").trim();
    return sceneDoc;
  } catch (_error) {
    return scene?.scene_doc ?? null;
  }
}

function normalizePrivateSceneEnvironmentSettings(settings = {}) {
  const skybox = String(settings?.skybox ?? settings?.skyboxPreset ?? "blank").trim().toLowerCase();
  const ambientLight = String(settings?.ambient_light ?? settings?.ambientLight ?? "even").trim().toLowerCase();
  return {
    skybox: Object.hasOwn(PRIVATE_SCENE_ENVIRONMENT_PRESETS, skybox) ? skybox : "blank",
    ambient_light: Object.hasOwn(PRIVATE_SCENE_AMBIENT_PRESETS, ambientLight) ? ambientLight : "even",
  };
}

function buildPrivateSceneEnvironmentTheme(settings = {}) {
  const normalized = normalizePrivateSceneEnvironmentSettings(settings);
  const skyboxPreset = PRIVATE_SCENE_ENVIRONMENT_PRESETS[normalized.skybox] ?? PRIVATE_SCENE_ENVIRONMENT_PRESETS.blank;
  const ambientPreset = PRIVATE_SCENE_AMBIENT_PRESETS[normalized.ambient_light] ?? PRIVATE_SCENE_AMBIENT_PRESETS.even;
  return {
    ...PRIVATE_WORLD_STYLE,
    ...skyboxPreset,
    skybox: normalized.skybox,
    ambient_light: normalized.ambient_light,
    ambientIntensity: ambientPreset.hemisphereIntensity,
    sunIntensity: Number((skyboxPreset.sunIntensity * ambientPreset.sunIntensityMultiplier).toFixed(4)),
  };
}

function getPrivateSceneEnvironmentSettings(sceneDoc = null) {
  return normalizePrivateSceneEnvironmentSettings(
    sceneDoc?.settings
      ?? getSelectedScene()?.scene_doc?.settings
      ?? {},
  );
}

function buildSceneEnvironmentHint(settings = {}) {
  const normalized = normalizePrivateSceneEnvironmentSettings(settings);
  const skyboxLabel = normalized.skybox === "blank"
    ? "White background"
    : normalized.skybox === "day"
      ? "Day sky"
      : normalized.skybox === "sunset"
        ? "Sunset sky"
        : "Night sky";
  const ambientLabel = normalized.ambient_light === "dim" ? "dimmer ambient light" : "even ambient light";
  return `${skyboxLabel} with ${ambientLabel}.`;
}

function renderSceneEnvironmentControls(sceneDoc = null) {
  if (!elements.sceneForm?.elements) {
    return;
  }
  const settings = getPrivateSceneEnvironmentSettings(sceneDoc);
  if (elements.sceneForm.elements.sceneSkybox) {
    elements.sceneForm.elements.sceneSkybox.value = settings.skybox;
  }
  if (elements.sceneForm.elements.sceneAmbientLight) {
    elements.sceneForm.elements.sceneAmbientLight.value = settings.ambient_light;
  }
  if (elements.sceneEnvironmentHint) {
    elements.sceneEnvironmentHint.textContent = buildSceneEnvironmentHint(settings);
  }
}

function buildEmptySceneDoc() {
  return {
    settings: {
      gravity: { x: 0, y: -9.8, z: 0 },
      camera_mode: "third_person",
      start_on_ready: true,
      skybox: "blank",
      ambient_light: "even",
    },
    voxels: [],
    primitives: [],
    panels: [],
    models: [],
    screens: [],
    players: [],
    texts: [],
    trigger_zones: [],
    prefabs: [],
    prefab_instances: [],
    particles: [],
    rules: [],
    script_dsl: "",
  };
}

function buildSceneCountLabel(count = 0) {
  return `${count} scene${count === 1 ? "" : "s"}`;
}

function createNextSceneName(scenes = state.selectedWorld?.scenes ?? []) {
  const usedNames = new Set((scenes ?? []).map((scene) => String(scene?.name ?? "").trim().toLowerCase()).filter(Boolean));
  let index = (scenes?.length ?? 0) + 1;
  while (usedNames.has(`scene ${index}`.toLowerCase())) {
    index += 1;
  }
  return `Scene ${index}`;
}

function createScriptFunctionId(seed = "") {
  const randomToken = Math.random().toString(36).slice(2, 8);
  return `scriptfn_${slugToken(seed || `logic_${Date.now().toString(36)}_${randomToken}`)}`;
}

const DEFAULT_LOGIC_SCRIPT_TEMPLATES = [
  {
    id: "starter_apply_force_facing",
    name: "Starter · Apply Force In Facing Direction",
    body: `
# Replace the player id, object id, and key or mouse token.
# You can keep your actual key in the control function above by changing @bind fire_key or @bind alt_fire_key.
# Supported live rule syntax today:
# key_press key mouse_left from player_1 -> apply_force to primitive_1 direction facing strength 12
# Parameter ideas to customize when you replace this starter:
# strength 12
# upward_bonus 0
# force_mode impulse
# space world
# cooldown_ms 250
# affect_mass true
# key_press key fire_key from player_1 -> apply_force to primitive_1 direction facing strength 12
    `.trim(),
  },
  {
    id: "starter_launch_bullet",
    name: "Starter · Spawn Bullet With Script Runtime",
    body: `
# Replace the sphere id and the projectile values.
# This spawns a real primitive bullet every timer tick.
# Make sure the bullet target script below destroys it on hit or after lifetime.
# Example editable constants:
# @set timer_ms 1200
# @set bullet_speed 32
# @set bullet_lifetime_ms 1800
# let target = nearest(players(), self.position)
# if (!target) return
# let direction = normalize(target.position - self.position)
# spawn("sphere", self.position + direction, self.rotation, { kind: "primitive", shape: "sphere", scale: {x:0.35,y:0.35,z:0.35}, velocity: direction * bullet_speed, physics: { ignore_gravity: true, friction: 0, restitution: 0 }, lifetime_ms: bullet_lifetime_ms, group_id: "enemy_bullets" })
    `.trim(),
  },
];

const MATERIALIZED_LOGIC_MODULE_ORDER = [
  "physics.world",
  "playmode.wasd_jump",
  "camera.overworld_drag_pan",
  "behavior.face_mouse_orthogonal",
];

function buildMaterializedLogicFunctionId(moduleKind = "", targetId = "scene") {
  const moduleToken = slugToken(moduleKind) || "module";
  const targetToken = slugToken(targetId || "scene") || "scene";
  return `scriptfn_system_${moduleToken}_${targetToken}`;
}

function getPlayerLogicModuleLabel(sceneDoc = {}, playerId = "") {
  const normalizedPlayerId = String(playerId ?? "").trim();
  const player = Array.isArray(sceneDoc?.players)
    ? sceneDoc.players.find((entry) => String(entry?.id ?? "").trim() === normalizedPlayerId)
    : null;
  return String(player?.label ?? normalizedPlayerId).trim() || normalizedPlayerId;
}

function buildMaterializedLogicFunctionName(moduleKind = "", targetId = "", sceneDoc = {}) {
  const playerLabel = getPlayerLogicModuleLabel(sceneDoc, targetId);
  if (moduleKind === "physics.world") {
    return "World Physics";
  }
  if (moduleKind === "playmode.wasd_jump") {
    return `Player Controls · ${playerLabel}`;
  }
  if (moduleKind === "camera.overworld_drag_pan") {
    return `Overworld Drag Pan · ${playerLabel}`;
  }
  if (moduleKind === "behavior.face_mouse_orthogonal") {
    return `Face Mouse Orthogonal · ${playerLabel}`;
  }
  return `${moduleKind} · ${targetId || "scene"}`;
}

function buildDesiredMaterializedLogicModules(sceneDoc = {}, scriptConfig = null) {
  const modules = [];
  if (scriptConfig?.world_physics) {
    modules.push({
      module_kind: "physics.world",
      target_id: "scene",
      ...scriptConfig.world_physics,
    });
  }
  for (const player of sceneDoc?.players ?? []) {
    const playerId = String(player?.id ?? "").trim();
    if (!playerId) {
      continue;
    }
    const control = scriptConfig?.player_controls?.[playerId];
    if (control) {
      modules.push({
        module_kind: "playmode.wasd_jump",
        target_id: playerId,
        ...control,
      });
    }
    const behaviors = scriptConfig?.camera_behaviors?.[playerId] ?? null;
    if (behaviors?.overworld_drag_pan) {
      modules.push({
        module_kind: "camera.overworld_drag_pan",
        target_id: playerId,
        ...behaviors.overworld_drag_pan,
      });
    }
    if (behaviors?.face_mouse_orthogonal) {
      modules.push({
        module_kind: "behavior.face_mouse_orthogonal",
        target_id: playerId,
        ...behaviors.face_mouse_orthogonal,
      });
    }
  }
  const order = new Map(MATERIALIZED_LOGIC_MODULE_ORDER.map((value, index) => [value, index]));
  return modules.sort((left, right) => {
    const leftOrder = order.get(left.module_kind) ?? 999;
    const rightOrder = order.get(right.module_kind) ?? 999;
    if (leftOrder !== rightOrder) {
      return leftOrder - rightOrder;
    }
    return String(left.target_id ?? "").localeCompare(String(right.target_id ?? ""));
  });
}

function appendMissingModuleDirectiveSurface(entry = {}, parsedEntry = {}, moduleConfig = {}) {
  const moduleKind = String(parsedEntry?.module_kind ?? moduleConfig?.module_kind ?? "").trim().toLowerCase();
  const definition = PRIVATE_WORLD_MODULE_DEFINITIONS[moduleKind] ?? null;
  if (!definition) {
    return false;
  }
  const existingBody = String(entry?.body ?? "").replace(/\s+$/g, "");
  const extraLines = [];
  const existingDirectiveSet = new Set((parsedEntry?.directives ?? []).map((directive) => directive.directive));
  const existingParamSet = new Set(Object.keys(parsedEntry?.params ?? {}));
  const existingBindingSet = new Set(Object.keys(parsedEntry?.bindings ?? {}));
  if (!existingDirectiveSet.has("enabled")) {
    extraLines.push(`@enabled ${moduleConfig?.enabled !== false ? "true" : "false"}`);
  }
  for (const binding of definition.bindings ?? []) {
    if (existingBindingSet.has(binding.name)) {
      continue;
    }
    const value = String(moduleConfig?.bindings?.[binding.name] ?? "").trim();
    if (value) {
      extraLines.push(`@bind ${binding.name} ${value}`);
    }
  }
  for (const param of definition.params ?? []) {
    if (existingParamSet.has(param.name)) {
      continue;
    }
    if (!Object.hasOwn(moduleConfig?.params ?? {}, param.name)) {
      continue;
    }
    extraLines.push(`@set ${param.name} ${String(serializePrivateWorldModuleFunctionBody({
      module_kind: moduleKind,
      target_id: moduleConfig?.target_id ?? parsedEntry?.target_id ?? "",
      enabled: moduleConfig?.enabled,
      params: { [param.name]: moduleConfig.params[param.name] },
      bindings: {},
    }).split("\n").find((line) => line.startsWith(`@set ${param.name} `)) ?? "").replace(`@set ${param.name} `, "")}`);
  }
  if (!extraLines.length) {
    return false;
  }
  entry.body = [existingBody, extraLines.join("\n")].filter(Boolean).join("\n");
  return true;
}

function buildStarterLogicFunctionEntry(template = {}, functions = []) {
  return normalizeScriptFunctionEntry({
    id: String(template.id ?? "").trim() || createScriptFunctionId(template.name || "logic"),
    name: buildScriptTemplateFunctionName(functions, template.name || "Logic Function"),
    body: String(template.body ?? "").trim(),
  }, functions.length);
}

function materializeSceneLogicFunctions(sceneDoc = {}, currentScriptDsl = "") {
  const scriptDslText = String(currentScriptDsl ?? sceneDoc?.script_dsl ?? "").trim();
  const compile = compileSharedPrivateWorldScriptDsl(scriptDslText, {
    sceneDoc,
    entityAliases: buildPrivateScriptDslEntityAliasMap(sceneDoc),
  });
  const functions = parseScriptFunctionLibrary(scriptDslText);
  const desiredModules = buildDesiredMaterializedLogicModules(sceneDoc, compile.script_config);
  let changed = false;
  const reparsedFunctions = parseSharedPrivateWorldScriptFunctions(serializeScriptFunctionLibrary(functions));
  const moduleIndexByKey = new Map();
  for (const [index, parsedEntry] of reparsedFunctions.entries()) {
    if (!parsedEntry?.module_kind || !parsedEntry?.target_id) {
      continue;
    }
    moduleIndexByKey.set(`${parsedEntry.module_kind}::${parsedEntry.target_id}`, index);
  }
  const functionIndexById = new Map(functions.map((entry, index) => [String(entry?.id ?? "").trim(), index]));
  for (const moduleConfig of desiredModules) {
    const moduleKey = `${moduleConfig.module_kind}::${moduleConfig.target_id}`;
    const existingIndex = moduleIndexByKey.get(moduleKey);
    const expectedId = buildMaterializedLogicFunctionId(moduleConfig.module_kind, moduleConfig.target_id);
    const expectedName = buildMaterializedLogicFunctionName(moduleConfig.module_kind, moduleConfig.target_id, sceneDoc);
    if (Number.isInteger(existingIndex) && functions[existingIndex]) {
      const existingEntry = functions[existingIndex];
      if (existingEntry.id === expectedId && existingEntry.name !== expectedName) {
        existingEntry.name = expectedName;
        changed = true;
      }
      changed = appendMissingModuleDirectiveSurface(existingEntry, reparsedFunctions[existingIndex], moduleConfig) || changed;
      continue;
    }
    const existingSystemIndex = functionIndexById.get(expectedId);
    if (Number.isInteger(existingSystemIndex) && functions[existingSystemIndex]) {
      const nextBody = serializePrivateWorldModuleFunctionBody(moduleConfig);
      const existingEntry = functions[existingSystemIndex];
      if (existingEntry.name !== expectedName || existingEntry.body !== nextBody) {
        existingEntry.name = expectedName;
        existingEntry.body = nextBody;
        changed = true;
      }
      continue;
    }
    functions.push(normalizeScriptFunctionEntry({
      id: expectedId,
      name: expectedName,
      body: serializePrivateWorldModuleFunctionBody(moduleConfig),
    }, functions.length));
    changed = true;
  }
  for (const template of DEFAULT_LOGIC_SCRIPT_TEMPLATES) {
    const existing = functions.find((entry) => entry.id === template.id || entry.name === template.name);
    if (existing) {
      continue;
    }
    functions.push(buildStarterLogicFunctionEntry(template, functions));
    changed = true;
  }
  const nextScriptDsl = changed ? serializeScriptFunctionLibrary(functions) : scriptDslText;
  return {
    changed,
    functions,
    scriptDslText: nextScriptDsl,
  };
}

function normalizeScriptFunctionEntry(entry = {}, index = 0) {
  const normalized = normalizeSharedScriptFunctionEntry(entry, index);
  return {
    ...normalized,
    id: String(normalized.id ?? "").trim() || createScriptFunctionId(`logic_${index + 1}`),
  };
}

function parseScriptFunctionLibrary(value = "") {
  return parseSharedScriptFunctionLibrary(value).map((entry, index) => normalizeScriptFunctionEntry(entry, index));
}

function serializeScriptFunctionLibrary(functions = []) {
  return serializeSharedScriptFunctionLibrary(
    functions.map((entry, index) => normalizeScriptFunctionEntry(entry, index)),
  );
}

function getSceneScriptFunctions() {
  return parseScriptFunctionLibrary(elements.sceneForm?.elements?.scriptDsl?.value || "");
}

function getSceneDocForLogicValidation() {
  try {
    return parseSceneTextarea();
  } catch (_error) {
    return getSelectedScene()?.scene_doc ?? buildEmptySceneDoc();
  }
}

function pushScriptFunctionDiagnostic(map, functionId = "", issue = {}) {
  const normalizedFunctionId = String(functionId ?? "").trim();
  if (!normalizedFunctionId) {
    return;
  }
  if (!map.has(normalizedFunctionId)) {
    map.set(normalizedFunctionId, []);
  }
  const issues = map.get(normalizedFunctionId);
  const normalizedIssue = {
    line: Number(issue.line ?? 0) || 0,
    message: String(issue.message ?? "").trim(),
  };
  if (!normalizedIssue.message) {
    return;
  }
  if (issues.some((entry) => entry.line === normalizedIssue.line && entry.message === normalizedIssue.message)) {
    return;
  }
  issues.push(normalizedIssue);
}

function buildSceneScriptFunctionDiagnostics(sceneDoc = {}, scriptDslText = "") {
  const aliasMap = buildPrivateScriptDslEntityAliasMap(sceneDoc);
  const targetCatalog = buildPrivateScriptDslTargetCatalog(sceneDoc);
  const compile = compileSharedPrivateWorldScriptDsl(scriptDslText, {
    sceneDoc,
    entityAliases: aliasMap,
    targetCatalog,
  });
  const issuesByFunctionId = new Map();
  for (const error of compile.errors ?? []) {
    const functionId = String(error?.function_id ?? "").trim();
    if (!functionId) {
      continue;
    }
    pushScriptFunctionDiagnostic(issuesByFunctionId, functionId, error);
  }
  for (const functionEntry of compile.functions ?? []) {
    for (const error of functionEntry?.errors ?? []) {
      pushScriptFunctionDiagnostic(issuesByFunctionId, functionEntry.id, error);
    }
  }
  for (const rule of compile.rules ?? []) {
    const functionId = String(rule?.function_id ?? "").trim();
    const line = Number(rule?.source_line_number ?? 0) || 0;
    const sourceTarget = rule?.source_id ? (targetCatalog.get(rule.source_id) ?? null) : null;
    const directTarget = rule?.target_id ? (targetCatalog.get(rule.target_id) ?? null) : null;
    const payloadTarget = rule?.payload?.target_id ? (targetCatalog.get(rule.payload.target_id) ?? null) : null;
    const particleTarget = rule?.payload?.particle_id ? (targetCatalog.get(rule.payload.particle_id) ?? null) : null;
    const textTarget = rule?.payload?.text_id ? (targetCatalog.get(rule.payload.text_id) ?? null) : null;
    if (rule?.source_id && !sourceTarget) {
      pushScriptFunctionDiagnostic(issuesByFunctionId, functionId, {
        line,
        message: `Rule references missing source \`${rule.source_id}\`.`,
      });
    }
    if (rule?.target_id && !directTarget) {
      pushScriptFunctionDiagnostic(issuesByFunctionId, functionId, {
        line,
        message: `Rule references missing target \`${rule.target_id}\`.`,
      });
    } else if (directTarget && !isPrivateWorldRuleTargetAllowed(rule.action, directTarget.target_kind)) {
      pushScriptFunctionDiagnostic(issuesByFunctionId, functionId, {
        line,
        message: `Action \`${rule.action}\` cannot target \`${rule.target_id}\` because it is a ${String(directTarget.target_kind ?? "scene").replace(/_/g, " ")}.`,
      });
    }
    if (rule?.payload?.target_id && !payloadTarget) {
      pushScriptFunctionDiagnostic(issuesByFunctionId, functionId, {
        line,
        message: `Rule references missing payload target \`${rule.payload.target_id}\`.`,
      });
    }
    if (rule?.payload?.particle_id && !particleTarget) {
      pushScriptFunctionDiagnostic(issuesByFunctionId, functionId, {
        line,
        message: `Rule references missing particle \`${rule.payload.particle_id}\`.`,
      });
    }
    if (rule?.payload?.text_id && !textTarget) {
      pushScriptFunctionDiagnostic(issuesByFunctionId, functionId, {
        line,
        message: `Rule references missing text \`${rule.payload.text_id}\`.`,
      });
    }
  }
  for (const issues of issuesByFunctionId.values()) {
    issues.sort((left, right) => {
      if (left.line !== right.line) {
        return left.line - right.line;
      }
      return left.message.localeCompare(right.message);
    });
  }
  return issuesByFunctionId;
}

function parseScriptFunctionEntryMetadata(entry = {}) {
  const serialized = serializeScriptFunctionLibrary([normalizeScriptFunctionEntry(entry, 0)]);
  return parseSharedPrivateWorldScriptFunctions(serialized)[0] ?? normalizeScriptFunctionEntry(entry, 0);
}

function buildScriptFunctionSummary(entry = {}, diagnostics = []) {
  const parsedEntry = parseScriptFunctionEntryMetadata(entry);
  const ruleLines = Array.isArray(parsedEntry.ruleLines)
    ? parsedEntry.ruleLines.map((line) => String(line?.line ?? "").trim()).filter(Boolean)
    : [];
  const programLines = Array.isArray(parsedEntry.programLines)
    ? parsedEntry.programLines.map((line) => String(line?.line ?? "").trim()).filter(Boolean)
    : [];
  const moduleKind = String(parsedEntry.module_kind ?? "").trim();
  const targetId = String(parsedEntry.target_id ?? "").trim();
  const issues = Array.isArray(diagnostics) ? diagnostics.filter(Boolean) : [];
  const primaryParams = [
    ...Object.entries(parsedEntry.params ?? {}).slice(0, 2).map(([key, value]) => `${key}=${Array.isArray(value) ? value.join(",") : typeof value === "object" ? JSON.stringify(value) : value}`),
    ...Object.entries(parsedEntry.bindings ?? {}).slice(0, 1).map(([key, value]) => `${key}=${value}`),
  ].filter(Boolean);
  const modulePreview = moduleKind
    ? [
      moduleKind,
      targetId ? `target ${targetId}` : "",
      primaryParams.length ? primaryParams.join(" · ") : "",
    ].filter(Boolean).join(" · ")
    : "";
  const programPreview = programLines[0] || "";
  const logicalLineCount = moduleKind === "script.runtime" ? programLines.length : ruleLines.length;
  return {
    lineCount: logicalLineCount,
    moduleKind,
    targetId,
    issueCount: issues.length,
    issuePreview: issues[0]?.message || "",
    preview: issues.length > 0
      ? `${issues.length} issue${issues.length === 1 ? "" : "s"} · ${issues[0]?.message || ""}`
      : (modulePreview || programPreview || ruleLines[0] || "No rules yet"),
  };
}

function appendDefaultLogicScriptTemplates(functions = []) {
  const inserted = [];
  for (const template of DEFAULT_LOGIC_SCRIPT_TEMPLATES) {
    const nextEntry = buildStarterLogicFunctionEntry(template, functions);
    functions.push(nextEntry);
    inserted.push(nextEntry);
  }
  return inserted;
}

function getScreenAiPrompt(screenId = "") {
  const normalizedScreenId = String(screenId ?? "").trim();
  if (!normalizedScreenId) {
    return "";
  }
  return String(state.screenAiPromptDrafts.get(normalizedScreenId) ?? "");
}

function setScreenAiPrompt(screenId = "", value = "") {
  const normalizedScreenId = String(screenId ?? "").trim();
  if (!normalizedScreenId) {
    return;
  }
  state.screenAiPromptDrafts.set(normalizedScreenId, String(value ?? ""));
}

function getSelectedScreenEntryForInspector(sceneDoc = null) {
  try {
    const resolvedSceneDoc = sceneDoc ?? parseSceneTextarea();
    const selected = getSelectedEntity(resolvedSceneDoc);
    return selected?.kind === "screen" ? selected.entry : null;
  } catch (_error) {
    return null;
  }
}

function getScreenPreviewDraft(screenId = "") {
  const normalizedScreenId = String(screenId ?? "").trim();
  if (!normalizedScreenId) {
    return { state: {}, assets: {} };
  }
  const draft = state.screenPreviewDrafts.get(normalizedScreenId);
  return {
    state: isRecordObject(draft?.state) ? draft.state : {},
    assets: isRecordObject(draft?.assets) ? draft.assets : {},
  };
}

function ensureScreenPreviewDraft(screenId = "") {
  const normalizedScreenId = String(screenId ?? "").trim();
  if (!normalizedScreenId) {
    return { state: {}, assets: {} };
  }
  const existing = getScreenPreviewDraft(normalizedScreenId);
  state.screenPreviewDrafts.set(normalizedScreenId, existing);
  return existing;
}

function hasScreenPreviewDraftValues(draft = {}) {
  return Boolean(
    isRecordObject(draft?.state) && Object.keys(draft.state).length
    || isRecordObject(draft?.assets) && Object.keys(draft.assets).length,
  );
}

function parseScreenPreviewBindingValue(rawValue) {
  const text = String(rawValue ?? "");
  const trimmed = text.trim();
  if (!trimmed) {
    return { clear: true, value: undefined };
  }
  try {
    return { clear: false, value: JSON.parse(trimmed) };
  } catch (_error) {
    return { clear: false, value: text };
  }
}

function formatScreenPreviewBindingValue(value) {
  if (value == null) {
    return value === null ? "null" : "";
  }
  if (typeof value === "string") {
    return value;
  }
  try {
    return JSON.stringify(value);
  } catch (_error) {
    return String(value);
  }
}

function summarizeScreenBindingValue(value) {
  if (value === undefined) {
    return "Missing";
  }
  if (value === null) {
    return "null";
  }
  if (typeof value === "string") {
    return value ? truncatePrivateUiLabel(value, 80) : '""';
  }
  if (typeof value === "number" || typeof value === "boolean") {
    return String(value);
  }
  try {
    return truncatePrivateUiLabel(JSON.stringify(value), 80);
  } catch (_error) {
    return truncatePrivateUiLabel(String(value), 80);
  }
}

function flattenScreenBindingPaths(value, prefix = "") {
  if (!isRecordObject(value)) {
    return [];
  }
  const paths = [];
  for (const [key, childValue] of Object.entries(value)) {
    const nextPath = prefix ? `${prefix}.${key}` : key;
    if (isRecordObject(childValue) && Object.keys(childValue).length > 0) {
      paths.push(...flattenScreenBindingPaths(childValue, nextPath));
      continue;
    }
    paths.push(nextPath);
  }
  return paths;
}

function getScreenBindingPathMeta(fullPath = "") {
  const normalized = String(fullPath ?? "").trim();
  if (normalized.startsWith("state.")) {
    return {
      fullPath: normalized,
      kind: "state",
      localPath: normalized.slice("state.".length),
    };
  }
  if (normalized.startsWith("assets.")) {
    return {
      fullPath: normalized,
      kind: "assets",
      localPath: normalized.slice("assets.".length),
    };
  }
  return {
    fullPath: normalized,
    kind: "",
    localPath: "",
  };
}

function setScreenPreviewBindingDraft(screenId = "", fullPath = "", rawValue = "") {
  const normalizedScreenId = String(screenId ?? "").trim();
  const pathMeta = getScreenBindingPathMeta(fullPath);
  if (!normalizedScreenId || !pathMeta.kind || !pathMeta.localPath) {
    return;
  }
  const draft = ensureScreenPreviewDraft(normalizedScreenId);
  const parsed = parseScreenPreviewBindingValue(rawValue);
  if (parsed.clear) {
    deleteByPath(draft[pathMeta.kind], pathMeta.localPath);
  } else {
    setByPath(draft[pathMeta.kind], pathMeta.localPath, parsed.value);
  }
  if (hasScreenPreviewDraftValues(draft)) {
    state.screenPreviewDrafts.set(normalizedScreenId, draft);
  } else {
    state.screenPreviewDrafts.delete(normalizedScreenId);
  }
}

function clearScreenPreviewBindingDraft(screenId = "", fullPath = "") {
  const normalizedScreenId = String(screenId ?? "").trim();
  const pathMeta = getScreenBindingPathMeta(fullPath);
  if (!normalizedScreenId || !pathMeta.kind || !pathMeta.localPath) {
    return;
  }
  const draft = ensureScreenPreviewDraft(normalizedScreenId);
  deleteByPath(draft[pathMeta.kind], pathMeta.localPath);
  if (hasScreenPreviewDraftValues(draft)) {
    state.screenPreviewDrafts.set(normalizedScreenId, draft);
  } else {
    state.screenPreviewDrafts.delete(normalizedScreenId);
  }
}

function clearScreenPreviewDraft(screenId = "") {
  const normalizedScreenId = String(screenId ?? "").trim();
  if (!normalizedScreenId) {
    return;
  }
  state.screenPreviewDrafts.delete(normalizedScreenId);
}

function buildScreenInspectorRenderableEntry(screen = {}) {
  const draft = getScreenPreviewDraft(screen.id);
  const renderable = deepClone(screen) ?? {};
  renderable.state = isRecordObject(screen.state) ? deepClone(screen.state) : {};
  renderable.assets = isRecordObject(screen.assets) ? deepClone(screen.assets) : {};
  for (const path of flattenScreenBindingPaths(draft.state ?? {})) {
    const previewInfo = getValueByPath(draft.state ?? {}, path);
    if (previewInfo.exists) {
      setByPath(renderable.state, path, deepClone(previewInfo.value));
    }
  }
  for (const path of flattenScreenBindingPaths(draft.assets ?? {})) {
    const previewInfo = getValueByPath(draft.assets ?? {}, path);
    if (previewInfo.exists) {
      setByPath(renderable.assets, path, deepClone(previewInfo.value));
    }
  }
  return renderable;
}

function getScreenInspectorBindingDescriptors(screen = {}) {
  const draft = getScreenPreviewDraft(screen.id);
  const templateBindings = new Set(
    collectScreenTemplateBindings(screen.html ?? "")
      .filter((path) => String(path ?? "").startsWith("state.") || String(path ?? "").startsWith("assets.")),
  );
  const savedBindings = [
    ...flattenScreenBindingPaths(screen.state ?? {}, "state"),
    ...flattenScreenBindingPaths(screen.assets ?? {}, "assets"),
  ];
  const previewBindings = [
    ...flattenScreenBindingPaths(draft.state ?? {}, "state"),
    ...flattenScreenBindingPaths(draft.assets ?? {}, "assets"),
  ];
  return [...new Set([
    ...templateBindings,
    ...savedBindings,
    ...previewBindings,
  ])]
    .map((fullPath) => {
      const pathMeta = getScreenBindingPathMeta(fullPath);
      if (!pathMeta.kind || !pathMeta.localPath) {
        return null;
      }
      const savedInfo = getValueByPath(screen[pathMeta.kind] ?? {}, pathMeta.localPath);
      const previewInfo = getValueByPath(draft[pathMeta.kind] ?? {}, pathMeta.localPath);
      const effectiveInfo = previewInfo.exists ? previewInfo : savedInfo;
      return {
        ...pathMeta,
        usedInTemplate: templateBindings.has(fullPath),
        savedInfo,
        previewInfo,
        effectiveInfo,
      };
    })
    .filter(Boolean)
    .sort((left, right) => {
      if (left.kind !== right.kind) {
        return left.kind.localeCompare(right.kind);
      }
      return left.localPath.localeCompare(right.localPath, undefined, { numeric: true, sensitivity: "base" });
    });
}

function buildScreenInspectorBindingMarkup(screen = {}) {
  const bindings = getScreenInspectorBindingDescriptors(screen);
  if (!bindings.length) {
    return `
      <div class="pw-screen-binding-empty">
        <strong>No bindings yet</strong>
        <p>Add placeholders like <code>{{state.score}}</code> or <code>{{assets.fire_icon}}</code> in the HTML to inspect them here.</p>
      </div>
    `;
  }
  return bindings.map((binding) => {
    const badges = [
      binding.usedInTemplate ? '<span class="pw-screen-binding-row__badge">used</span>' : "",
      binding.savedInfo.exists ? '<span class="pw-screen-binding-row__badge">saved</span>' : "",
      binding.previewInfo.exists ? '<span class="pw-screen-binding-row__badge is-preview">test</span>' : "",
    ].filter(Boolean).join("");
    const stateClass = !binding.effectiveInfo.exists
      ? " is-missing"
      : (binding.previewInfo.exists ? " is-preview" : "");
    const summary = binding.previewInfo.exists
      ? `Preview ${summarizeScreenBindingValue(binding.previewInfo.value)}${binding.savedInfo.exists ? ` · saved ${summarizeScreenBindingValue(binding.savedInfo.value)}` : ""}`
      : binding.savedInfo.exists
        ? `Saved ${summarizeScreenBindingValue(binding.savedInfo.value)}`
        : "No saved value yet";
    const inputValue = binding.previewInfo.exists ? formatScreenPreviewBindingValue(binding.previewInfo.value) : "";
    const placeholder = binding.kind === "assets"
      ? (binding.savedInfo.exists ? summarizeScreenBindingValue(binding.savedInfo.value) : "URL or data URL")
      : (binding.savedInfo.exists ? summarizeScreenBindingValue(binding.savedInfo.value) : "Text or JSON");
    return `
      <div class="pw-screen-binding-row${stateClass}">
        <div class="pw-screen-binding-row__meta">
          <div class="pw-screen-binding-row__head">
            <code>${htmlEscape(binding.fullPath)}</code>
            <div class="pw-screen-binding-row__badges">${badges}</div>
          </div>
          <small>${htmlEscape(summary)}</small>
        </div>
        <label class="pw-screen-binding-row__field">
          <span>Test value</span>
          <input
            type="text"
            data-screen-preview-binding="${htmlEscape(binding.fullPath)}"
            value="${htmlEscape(inputValue)}"
            placeholder="${htmlEscape(placeholder)}"
            spellcheck="false"
          />
        </label>
        <button
          type="button"
          class="is-muted"
          data-screen-preview-clear-binding="${htmlEscape(binding.fullPath)}"
          ${binding.previewInfo.exists ? "" : "disabled"}
        >Clear</button>
      </div>
    `;
  }).join("");
}

function buildScreenInspectorPreviewMarkup(screen = {}) {
  const html = String(resolveScreenHtmlSource(buildScreenInspectorRenderableEntry(screen)) ?? "").trim();
  if (!html) {
    return `
      <div class="pw-screen-binding-empty">
        <strong>No preview yet</strong>
        <p>Add screen HTML above to preview the resolved layout here.</p>
      </div>
    `;
  }
  return `
    <iframe
      class="pw-screen-preview__frame"
      sandbox="allow-same-origin"
      loading="lazy"
      referrerpolicy="no-referrer"
      srcdoc="${htmlEscape(html)}"
      title="Screen preview"
    ></iframe>
  `;
}

function refreshSelectedScreenInspectorPanels(options = {}) {
  if (!elements.entityEditor) {
    return;
  }
  const screen = getSelectedScreenEntryForInspector();
  if (!screen) {
    return;
  }
  if (options.rerenderBindings !== false) {
    const bindingsHost = elements.entityEditor.querySelector("[data-screen-binding-list]");
    if (bindingsHost) {
      bindingsHost.innerHTML = buildScreenInspectorBindingMarkup(screen);
    }
  }
  const previewHost = elements.entityEditor.querySelector("[data-screen-preview-frame]");
  if (previewHost) {
    previewHost.innerHTML = buildScreenInspectorPreviewMarkup(screen);
  }
  const clearButton = elements.entityEditor.querySelector("[data-screen-preview-clear]");
  if (clearButton) {
    clearButton.disabled = !hasScreenPreviewDraftValues(getScreenPreviewDraft(screen.id));
  }
}

function ensureSelectedScriptFunction(functions = getSceneScriptFunctions()) {
  const normalizedFunctions = Array.isArray(functions) ? functions : [];
  if (!normalizedFunctions.length) {
    state.selectedScriptFunctionId = "";
    return null;
  }
  const selected = normalizedFunctions.find((entry) => entry.id === state.selectedScriptFunctionId) ?? normalizedFunctions[0];
  state.selectedScriptFunctionId = selected.id;
  return selected;
}

function renderSceneLogicLibrary() {
  if (!elements.scriptFunctionList || !elements.sceneForm?.elements) {
    return;
  }
  const scene = getSelectedScene();
  const hasScene = Boolean(scene);
  const canEdit = hasScene && isEditor() && state.mode === "build";
  const functions = getSceneScriptFunctions();
  const sceneDocForValidation = getSceneDocForLogicValidation();
  const diagnosticsByFunctionId = buildSceneScriptFunctionDiagnostics(
    sceneDocForValidation,
    String(elements.sceneForm?.elements?.scriptDsl?.value ?? sceneDocForValidation?.script_dsl ?? ""),
  );
  const normalizedQuery = String(state.scriptFunctionQuery ?? "").trim().toLowerCase();
  const visibleFunctions = functions.filter((entry) => {
    const haystack = [entry.name, entry.body].join(" ").toLowerCase();
    return !normalizedQuery || haystack.includes(normalizedQuery);
  });
  if (visibleFunctions.length > 0 && !visibleFunctions.some((entry) => entry.id === state.selectedScriptFunctionId)) {
    state.selectedScriptFunctionId = visibleFunctions[0].id;
  }
  const selectedFunction = ensureSelectedScriptFunction(functions);
  const editorFunction = hasScene && visibleFunctions.length ? selectedFunction : null;
  if (elements.scriptFunctionSearch && elements.scriptFunctionSearch.value !== String(state.scriptFunctionQuery ?? "")) {
    elements.scriptFunctionSearch.value = String(state.scriptFunctionQuery ?? "");
  }
  if (elements.scriptFunctionSearch) {
    elements.scriptFunctionSearch.disabled = !hasScene;
  }
  if (elements.scriptFunctionNew) {
    elements.scriptFunctionNew.disabled = !canEdit;
  }
  if (elements.scriptFunctionOpenGenerate) {
    elements.scriptFunctionOpenGenerate.disabled = !canEdit || !state.selectedWorld || !state.session;
  }
  if (elements.scriptFunctionDelete) {
    elements.scriptFunctionDelete.disabled = !canEdit || !editorFunction;
  }
  if (elements.scriptFunctionGenerate) {
    elements.scriptFunctionGenerate.disabled = !canEdit || !state.selectedWorld || !state.session;
  }
  if (!hasScene) {
    elements.scriptFunctionList.innerHTML = '<div class="pw-script-card"><p>No scene selected yet.</p></div>';
    if (elements.scriptFunctionSearchHint) {
      elements.scriptFunctionSearchHint.textContent = "Open a scene to organize its logic.";
    }
  } else if (!functions.length) {
    elements.scriptFunctionList.innerHTML = '<div class="pw-script-card"><p>No functions yet. Add one to keep scene logic in tidy pieces.</p></div>';
    if (elements.scriptFunctionSearchHint) {
      elements.scriptFunctionSearchHint.textContent = "Each function compiles back into the single scene script automatically.";
    }
  } else if (!visibleFunctions.length) {
    elements.scriptFunctionList.innerHTML = '<div class="pw-script-card"><p>No functions match that search.</p></div>';
    if (elements.scriptFunctionSearchHint) {
      elements.scriptFunctionSearchHint.textContent = "Try a different function name or clear the search.";
    }
  } else {
    if (elements.scriptFunctionSearchHint) {
      elements.scriptFunctionSearchHint.textContent = `${visibleFunctions.length} function${visibleFunctions.length === 1 ? "" : "s"} in this scene. Click one to edit, use Generate to create a new function, or use Brainstorm with AI below to revise the current selection.`;
    }
    elements.scriptFunctionList.innerHTML = visibleFunctions.map((entry, index) => {
      const diagnostics = diagnosticsByFunctionId.get(entry.id) ?? [];
      const summary = buildScriptFunctionSummary(entry, diagnostics);
      const isSelected = selectedFunction?.id === entry.id;
      const lineLabel = summary.moduleKind === "script.runtime"
        ? `${summary.lineCount} script line${summary.lineCount === 1 ? "" : "s"}`
        : `${summary.lineCount} rule${summary.lineCount === 1 ? "" : "s"}`;
      return `
        <article class="pw-script-card ${isSelected ? "is-active" : ""} ${summary.issueCount > 0 ? "has-issues" : ""}" data-script-function-id="${htmlEscape(entry.id)}">
          <div class="pw-script-card__head">
            <div class="pw-script-card__title">
              <strong>${htmlEscape(entry.name)}</strong>
              <span>${htmlEscape(summary.moduleKind ? `${summary.moduleKind}${summary.lineCount ? ` · ${lineLabel}` : ""}` : lineLabel)}</span>
            </div>
            <div class="pw-script-card__badges">
              ${summary.issueCount > 0 ? `<span class="pw-script-card__badge is-warning">${htmlEscape(`${summary.issueCount} issue${summary.issueCount === 1 ? "" : "s"}`)}</span>` : ""}
              <span class="pw-script-card__badge">${isSelected ? "editing" : `f${index + 1}`}</span>
            </div>
          </div>
          <p>${htmlEscape(summary.preview)}</p>
        </article>
      `;
    }).join("");
  }

  const showEditor = Boolean(editorFunction);
  if (elements.scriptFunctionEmpty) {
    elements.scriptFunctionEmpty.hidden = showEditor;
    elements.scriptFunctionEmpty.textContent = !hasScene
      ? "Open a scene to start shaping scene logic."
      : !functions.length
        ? "Add a function to start shaping scene logic."
        : !visibleFunctions.length
          ? "No function matches the current search."
          : "Select a function to edit its rules.";
  }
  if (elements.scriptFunctionFields) {
    elements.scriptFunctionFields.hidden = !showEditor;
  }
  if (!editorFunction) {
    if (elements.scriptFunctionName) {
      elements.scriptFunctionName.value = "";
      elements.scriptFunctionName.disabled = true;
    }
    if (elements.scriptFunctionBody) {
      elements.scriptFunctionBody.value = "";
      elements.scriptFunctionBody.disabled = true;
    }
    if (elements.scriptFunctionMeta) {
      elements.scriptFunctionMeta.textContent = "";
    }
    if (elements.scriptFunctionStatus) {
      elements.scriptFunctionStatus.hidden = true;
      elements.scriptFunctionStatus.innerHTML = "";
    }
    if (elements.scriptFunctionPrompt) {
      elements.scriptFunctionPrompt.disabled = true;
    }
    return;
  }
  const diagnostics = diagnosticsByFunctionId.get(editorFunction.id) ?? [];
  const summary = buildScriptFunctionSummary(editorFunction, diagnostics);
  if (elements.scriptFunctionName) {
    elements.scriptFunctionName.disabled = !canEdit;
    if (elements.scriptFunctionName.value !== editorFunction.name) {
      elements.scriptFunctionName.value = editorFunction.name;
    }
  }
  if (elements.scriptFunctionBody) {
    elements.scriptFunctionBody.disabled = !canEdit;
    if (elements.scriptFunctionBody.value !== editorFunction.body) {
      elements.scriptFunctionBody.value = editorFunction.body;
    }
  }
  if (elements.scriptFunctionPrompt) {
    elements.scriptFunctionPrompt.disabled = !canEdit || !state.session;
  }
  if (elements.scriptFunctionStatus) {
    if (diagnostics.length > 0) {
      elements.scriptFunctionStatus.hidden = false;
      elements.scriptFunctionStatus.innerHTML = `
        <strong>${htmlEscape(`${diagnostics.length} issue${diagnostics.length === 1 ? "" : "s"} to fix`)}</strong>
        <ul>
          ${diagnostics.slice(0, 8).map((issue) => `<li>${htmlEscape(issue.line > 0 ? `Line ${issue.line}: ${issue.message}` : issue.message)}</li>`).join("")}
        </ul>
      `;
    } else {
      elements.scriptFunctionStatus.hidden = true;
      elements.scriptFunctionStatus.innerHTML = "";
    }
  }
  if (elements.scriptFunctionMeta) {
    const lineLabel = summary.moduleKind === "script.runtime"
      ? `${summary.lineCount} script line${summary.lineCount === 1 ? "" : "s"}`
      : `${summary.lineCount} rule${summary.lineCount === 1 ? "" : "s"}`;
    elements.scriptFunctionMeta.textContent = [
      summary.moduleKind ? `module ${summary.moduleKind}${summary.targetId ? ` → ${summary.targetId}` : ""}` : lineLabel,
      summary.moduleKind && summary.lineCount ? lineLabel : "",
      diagnostics.length > 0 ? `${diagnostics.length} issue${diagnostics.length === 1 ? "" : "s"}` : "",
      "comments are okay",
      "saved as one scene script behind the scenes",
    ].filter(Boolean).join(" · ");
  }
}

function mutateSceneScriptFunctions(mutator, options = {}) {
  if (!elements.sceneForm?.elements?.scriptDsl) {
    return [];
  }
  const nextFunctions = getSceneScriptFunctions().map((entry, index) => normalizeScriptFunctionEntry(entry, index));
  mutator(nextFunctions);
  const scriptDslText = serializeScriptFunctionLibrary(nextFunctions);
  elements.sceneForm.elements.scriptDsl.value = scriptDslText;
  void acquireSceneLock();
  mutateSceneDoc((sceneDoc) => {
    sceneDoc.script_dsl = scriptDslText;
  }, {
    renderBuilder: false,
    updatePreview: false,
  });
  if (options.render !== false) {
    renderSceneLogicLibrary();
  }
  return nextFunctions;
}

function normalizeGeneratedScriptBody(value = "") {
  let cleaned = String(value ?? "").trim();
  const fenced = cleaned.match(/^```(?:[\w-]+)?\n?([\s\S]*?)```$/);
  if (fenced) {
    cleaned = String(fenced[1] ?? "").trim();
  }
  return cleaned
    .split(/\r?\n/)
    .filter((line) => !SCRIPT_FUNCTION_HEADER_RE.test(line.trim()))
    .join("\n")
    .trim();
}

function shouldValidateAiDialogScriptResult(dialog = state.aiDialog) {
  return dialog?.artifactType === "world_script"
    && (dialog?.targetKind === "script_function" || dialog?.targetKind === "new_script_function");
}

function buildAiDialogScriptValidationResult(result = "", dialog = state.aiDialog) {
  const normalizedBody = normalizeGeneratedScriptBody(result);
  if (!shouldValidateAiDialogScriptResult(dialog)) {
    return {
      ok: true,
      normalizedBody,
      diagnostics: [],
      targetId: "",
      functionName: "",
      requiresUserClarification: false,
    };
  }
  const functions = getSceneScriptFunctions().map((entry, index) => normalizeScriptFunctionEntry(entry, index));
  let targetEntry = null;
  if (dialog.targetKind === "script_function") {
    targetEntry = functions.find((entry) => entry.id === dialog.targetId) ?? null;
    if (!targetEntry) {
      return {
        ok: false,
        normalizedBody,
        diagnostics: [{ line: 0, message: "That logic function is no longer available." }],
        targetId: String(dialog.targetId ?? "").trim(),
        functionName: "",
        requiresUserClarification: false,
      };
    }
    targetEntry.body = normalizedBody;
  } else {
    targetEntry = functions.find((entry) => entry.id === dialog.createdScriptFunctionId) ?? null;
    if (targetEntry) {
      targetEntry.body = normalizedBody;
    } else {
      const nextEntry = normalizeScriptFunctionEntry({
        id: createScriptFunctionId("generated_logic_preview"),
        name: buildScriptTemplateFunctionName(functions, "Generated Function"),
        body: normalizedBody,
      }, functions.length);
      functions.push(nextEntry);
      targetEntry = nextEntry;
    }
  }
  const diagnostics = buildSceneScriptFunctionDiagnostics(
    getSceneDocForLogicValidation(),
    serializeScriptFunctionLibrary(functions),
  ).get(String(targetEntry?.id ?? "").trim()) ?? [];
  return {
    ok: diagnostics.length === 0,
    normalizedBody,
    diagnostics,
    targetId: String(targetEntry?.id ?? "").trim(),
    functionName: String(targetEntry?.name ?? "").trim(),
    requiresUserClarification: diagnostics.length > 0,
  };
}

function buildAiDialogScriptValidationQuestions(diagnostics = []) {
  const questions = [];
  const pushQuestion = (text = "") => {
    const normalized = String(text ?? "").trim();
    if (!normalized || questions.includes(normalized)) {
      return;
    }
    questions.push(normalized);
  };
  for (const issue of Array.isArray(diagnostics) ? diagnostics : []) {
    const message = String(issue?.message ?? "").trim();
    if (!message) {
      continue;
    }
    let match = message.match(/Rule references missing (?:source|target|payload target|particle|text) `([^`]+)`\./i);
    if (match) {
      pushQuestion(`Which exact scene id should replace \`${match[1]}\`? Please reply with the id you want this logic to use.`);
      continue;
    }
    match = message.match(/Target `([^`]+)` no longer exists in this scene\./i);
    if (match) {
      pushQuestion(`Which exact scene id should this function target instead of \`${match[1]}\`?`);
      continue;
    }
    match = message.match(/Module `([^`]+)` can only target players\./i);
    if (match) {
      pushQuestion(`Should this module target a player instead? If yes, which player id should it use?`);
      continue;
    }
    match = message.match(/Parameter `([^`]+)` is not supported by module `([^`]+)`\./i);
    if (match) {
      pushQuestion(`The module \`${match[2]}\` does not support \`${match[1]}\`. What exact behavior do you want there instead?`);
      continue;
    }
    match = message.match(/Binding `([^`]+)` is not supported by module `([^`]+)`\./i);
    if (match) {
      pushQuestion(`Which supported input binding should replace \`${match[1]}\` for module \`${match[2]}\`?`);
      continue;
    }
    match = message.match(/Parameter `([^`]+)` expects true or false\./i);
    if (match) {
      pushQuestion(`What true/false value should \`${match[1]}\` use?`);
      continue;
    }
    match = message.match(/Parameter `([^`]+)` expects a numeric value\./i);
    if (match) {
      pushQuestion(`What numeric value should \`${match[1]}\` use?`);
      continue;
    }
    match = message.match(/Parameter `([^`]+)` must stay between ([^ ]+) and ([^ .]+)\./i);
    if (match) {
      pushQuestion(`What value should \`${match[1]}\` use between ${match[2]} and ${match[3]}?`);
      continue;
    }
    match = message.match(/Parameter `([^`]+)` must be one of: (.+)\./i);
    if (match) {
      pushQuestion(`Which option should \`${match[1]}\` use: ${match[2]}?`);
      continue;
    }
    match = message.match(/Parameter `([^`]+)` expects a vector/i);
    if (match) {
      pushQuestion(`What vector should \`${match[1]}\` use? Please reply like \`(x,y,z)\`.`);
      continue;
    }
    match = message.match(/Unsupported action: (.+)$/i);
    if (match) {
      pushQuestion(`That action is not supported. What supported Mauworld action should this rule use instead?`);
      continue;
    }
    match = message.match(/Unsupported trigger: (.+)$/i);
    if (match) {
      pushQuestion(`What supported trigger should start this rule instead?`);
      continue;
    }
    match = message.match(/Action `([^`]+)` cannot target `([^`]+)` because it is a (.+)\./i);
    if (match) {
      pushQuestion(`Which valid target should action \`${match[1]}\` control instead of \`${match[2]}\`?`);
      continue;
    }
    if (/Expected `trigger -> action`/i.test(message)) {
      pushQuestion("What trigger and action should this rule use? Please describe the exact behavior you want.");
      continue;
    }
  }
  if (!questions.length) {
    pushQuestion("Please clarify the exact target ids, supported action or module, and any missing values you want so I can regenerate this cleanly.");
  }
  return questions.slice(0, 4);
}

function buildAiDialogScriptValidationFollowUp(validation = {}) {
  const diagnostics = Array.isArray(validation?.diagnostics) ? validation.diagnostics.filter(Boolean) : [];
  const issueLines = diagnostics.slice(0, 6).map((issue) =>
    `- ${issue.line > 0 ? `Line ${issue.line}: ` : ""}${String(issue.message ?? "").trim()}`);
  const questions = buildAiDialogScriptValidationQuestions(diagnostics);
  return [
    "I couldn't apply that final script yet because it still fails scene-logic validation.",
    "I kept the current script draft on the Generated script tab, but I did not apply it to the function.",
    "",
    "What still needs clarification:",
    ...(issueLines.length ? issueLines : ["- The generated script still needs more detail before it can compile cleanly."]),
    "",
    "Please reply with:",
    ...questions.map((question) => `- ${question}`),
  ].join("\n");
}

function handleAiDialogInvalidScriptResult(validation = {}, activeThread = getActiveAiDialogThread()) {
  const followUpText = buildAiDialogScriptValidationFollowUp(validation);
  const lastMessage = activeThread.messages.at(-1) ?? null;
  if (lastMessage?.role !== "assistant" || lastMessage?.text !== followUpText) {
    activeThread.messages = [...activeThread.messages, { role: "assistant", text: followUpText }];
  }
  activeThread.awaitingValidationClarification = true;
  touchAiDialogThread(activeThread);
  state.aiDialog.activePane = "conversation";
  const issueCount = Array.isArray(validation?.diagnostics) ? validation.diagnostics.length : 0;
  setAiDialogStatus(
    issueCount > 0
      ? `The generated script still has ${issueCount} issue${issueCount === 1 ? "" : "s"}. I asked follow-up questions instead of applying it.`
      : "The generated script still needs clarification before it can be applied.",
    "error",
  );
  persistAiDialogThreadState();
  renderAiDialog();
  window.setTimeout(() => {
    elements.aiDialogInput?.focus?.();
  }, 0);
}

function buildScriptTemplateFunctionName(functions = [], baseName = "Logic Function") {
  const normalizedBase = String(baseName ?? "").trim() || "Logic Function";
  const existingNames = new Set(functions.map((entry) => String(entry?.name ?? "").trim().toLowerCase()).filter(Boolean));
  if (!existingNames.has(normalizedBase.toLowerCase())) {
    return normalizedBase;
  }
  let index = 2;
  while (existingNames.has(`${normalizedBase} ${index}`.toLowerCase())) {
    index += 1;
  }
  return `${normalizedBase} ${index}`;
}

function appendScriptTemplateFunction(sceneDoc, template = {}, context = {}) {
  if (!sceneDoc || !template?.body) {
    return false;
  }
  const functions = parseScriptFunctionLibrary(sceneDoc.script_dsl || "");
  const body = String(template.body ?? "")
    .replaceAll("{{id}}", String(context.entityId ?? "").trim())
    .trim();
  if (!body) {
    return false;
  }
  functions.push(normalizeScriptFunctionEntry({
    id: createScriptFunctionId(template.name || context.entityId || "logic"),
    name: buildScriptTemplateFunctionName(functions, template.name || "Logic Function"),
    body,
  }, functions.length));
  sceneDoc.script_dsl = serializeScriptFunctionLibrary(functions);
  return true;
}

function focusSelectedScriptFunctionBody() {
  window.setTimeout(() => {
    elements.scriptFunctionBody?.focus?.();
    if (elements.scriptFunctionBody?.value) {
      elements.scriptFunctionBody.selectionStart = elements.scriptFunctionBody.value.length;
      elements.scriptFunctionBody.selectionEnd = elements.scriptFunctionBody.value.length;
    }
  }, 0);
}

function isEditor() {
  return state.selectedWorld?.permissions?.can_edit === true;
}

function getLocalParticipant(world = state.selectedWorld) {
  if (!world?.active_instance?.participants?.length) {
    return null;
  }
  if (state.profile?.id) {
    return world.active_instance.participants.find((entry) => entry.profile?.id === state.profile.id) ?? null;
  }
  return world.active_instance.participants.find((entry) => entry.guest_session_id === getGuestSessionId()) ?? null;
}

function getNearbyInhabitablePlayerCandidate(world = state.selectedWorld) {
  if (
    !world
    || state.mode !== "play"
    || state.entryLoading === true
    || !state.session
  ) {
    return null;
  }
  const localParticipant = getLocalParticipant(world);
  if (!localParticipant || localParticipant.join_role === "player") {
    return null;
  }
  const sceneDoc = getRenderableSceneDoc();
  const scenePlayers = Array.isArray(sceneDoc?.players) ? sceneDoc.players : [];
  if (!scenePlayers.length) {
    return null;
  }
  const runtime = state.runtimeSnapshot ?? world?.active_instance?.runtime ?? null;
  const runtimePlayers = Array.isArray(runtime?.players) ? runtime.players : [];
  const runtimePlayerIds = getRuntimePlayerIds();
  const viewerX = Number(state.viewerPosition.x ?? 0) || 0;
  const viewerY = Number(state.viewerPosition.y ?? 0) || 0;
  const viewerZ = Number(state.viewerPosition.z ?? 0) || 0;
  let bestCandidate = null;
  for (const player of scenePlayers) {
    if (!player || player.occupiable === false) {
      continue;
    }
    const authoredPlayerId = String(player.id ?? "").trim();
    if (!authoredPlayerId) {
      continue;
    }
    const resolvedPlayerId = resolvePrivatePlayerEntityId(authoredPlayerId, runtimePlayerIds) ?? authoredPlayerId;
    const runtimePlayer = runtimePlayers.find((entry) => {
      const runtimePlayerId = String(entry?.id ?? "").trim();
      return runtimePlayerId === resolvedPlayerId || runtimePlayerId === authoredPlayerId;
    }) ?? null;
    if (runtimePlayer?.visible === false) {
      continue;
    }
    const occupiedByUsername = String(runtimePlayer?.occupied_by_username ?? "").trim();
    const occupiedByDisplayName = String(runtimePlayer?.occupied_by_display_name ?? "").trim();
    if (occupiedByUsername || occupiedByDisplayName) {
      continue;
    }
    const position = runtimePlayer?.position ?? player.position;
    if (!position) {
      continue;
    }
    const playerX = Number(position.x ?? 0) || 0;
    const playerY = Number(position.y ?? 0) || 0;
    const playerZ = Number(position.z ?? 0) || 0;
    const scale = Math.max(
      0.25,
      Number(runtimePlayer?.scale ?? player.scale ?? PRIVATE_PLAYER_DEFAULT_SCALE) || PRIVATE_PLAYER_DEFAULT_SCALE,
    );
    const collisionSize = getPrivatePlayerCollisionSize(scale);
    const touchDistance = (Math.max(collisionSize.x, collisionSize.z) / 2)
      + PRIVATE_PLAYER_INHABIT.viewerRadius
      + PRIVATE_PLAYER_INHABIT.touchBuffer;
    const planarDistance = Math.hypot(viewerX - playerX, viewerZ - playerZ);
    if (planarDistance > touchDistance) {
      continue;
    }
    const verticalTolerance = Math.max(collisionSize.y, PRIVATE_PLAYER_INHABIT.minVerticalTolerance);
    if (Math.abs(viewerY - playerY) > verticalTolerance) {
      continue;
    }
    const label = String(runtimePlayer?.label ?? player.label ?? "").trim();
    if (!bestCandidate || planarDistance < bestCandidate.planarDistance) {
      bestCandidate = {
        id: resolvedPlayerId || authoredPlayerId,
        label,
        planarDistance,
      };
    }
  }
  return bestCandidate;
}

function getPrivateInhabitButtonLabel() {
  const label = String(state.nearbyInhabitablePlayerLabel ?? "").trim();
  return label ? `Inhabit ${label}` : "Inhabit";
}

function setNearbyInhabitablePlayerCandidate(candidate = null, options = {}) {
  const nextId = String(candidate?.id ?? "").trim();
  const nextLabel = String(candidate?.label ?? "").trim();
  const changed =
    nextId !== String(state.nearbyInhabitablePlayerId ?? "").trim()
    || nextLabel !== String(state.nearbyInhabitablePlayerLabel ?? "").trim();
  state.nearbyInhabitablePlayerId = nextId;
  state.nearbyInhabitablePlayerLabel = nextLabel;
  if (changed && options.render !== false) {
    renderPrivateRuntimeActions();
  }
  return changed;
}

function syncNearbyInhabitablePlayerCandidate(world = state.selectedWorld, options = {}) {
  return setNearbyInhabitablePlayerCandidate(
    getNearbyInhabitablePlayerCandidate(world),
    options,
  );
}

function getRuntimeSnapshotWorldKey(world = state.selectedWorld) {
  const worldId = String(world?.world_id ?? "").trim();
  const creatorUsername = String(world?.creator?.username ?? "").trim().toLowerCase();
  return worldId && creatorUsername ? `${creatorUsername}:${worldId}` : "";
}

function clearRuntimeSnapshot() {
  stopPrivateWorldSoundPlayers();
  state.runtimeSnapshot = null;
  state.runtimeSnapshotSourcePriority = 0;
  state.runtimeSnapshotWorldKey = "";
}

function hasRuntimeSnapshotIdentityChange(currentRuntime, nextRuntime) {
  if (!currentRuntime || !nextRuntime) {
    return false;
  }
  return (
    String(currentRuntime.instance_id ?? "") !== String(nextRuntime.instance_id ?? "")
    || String(currentRuntime.active_scene_id ?? "") !== String(nextRuntime.active_scene_id ?? "")
    || String(currentRuntime.scene_updated_at ?? "") !== String(nextRuntime.scene_updated_at ?? "")
    || Number(currentRuntime.scene_version ?? 0) !== Number(nextRuntime.scene_version ?? 0)
    || String(currentRuntime.started_at ?? "") !== String(nextRuntime.started_at ?? "")
    || String(currentRuntime.status ?? "") !== String(nextRuntime.status ?? "")
    || Boolean(currentRuntime.scene_started) !== Boolean(nextRuntime.scene_started)
  );
}

function setRuntimeSnapshot(nextRuntime, options = {}) {
  const sourcePriority = Math.max(0, Number(options.sourcePriority ?? 0) || 0);
  const worldKey = String(options.worldKey ?? getRuntimeSnapshotWorldKey()).trim();
  const previousRuntime = state.runtimeSnapshot;
  const previousWorldKey = String(state.runtimeSnapshotWorldKey ?? "").trim();
  if (!nextRuntime) {
    if (options.clear !== false) {
      clearRuntimeSnapshot();
    }
    return {
      accepted: options.clear !== false,
      previousRuntime,
      snapshot: state.runtimeSnapshot,
    };
  }
  const nextTick = Number.isFinite(Number(nextRuntime.tick)) ? Number(nextRuntime.tick) : -1;
  const currentTick = Number.isFinite(Number(previousRuntime?.tick)) ? Number(previousRuntime.tick) : -1;
  const currentPriority = Math.max(0, Number(state.runtimeSnapshotSourcePriority ?? 0) || 0);
  const sameWorld = !previousWorldKey || !worldKey || previousWorldKey === worldKey;
  const identityChanged = hasRuntimeSnapshotIdentityChange(previousRuntime, nextRuntime);
  if (sameWorld && previousRuntime) {
    if (nextTick < currentTick && !identityChanged) {
      return {
        accepted: false,
        previousRuntime,
        snapshot: previousRuntime,
      };
    }
    if (nextTick === currentTick && sourcePriority < currentPriority && !identityChanged) {
      return {
        accepted: false,
        previousRuntime,
        snapshot: previousRuntime,
      };
    }
  }
  state.runtimeSnapshot = nextRuntime;
  state.runtimeSnapshotSourcePriority = sourcePriority;
  state.runtimeSnapshotWorldKey = worldKey;
  return {
    accepted: true,
    previousRuntime,
    snapshot: nextRuntime,
  };
}

function getPossessedRuntimePlayer() {
  const localParticipant = getLocalParticipant();
  if (!localParticipant?.player_entity_id) {
    return null;
  }
  const playerId = resolvePrivatePlayerEntityId(localParticipant.player_entity_id, getRuntimePlayerIds());
  if (!playerId) {
    return null;
  }
  return state.runtimeSnapshot?.players?.find((entry) => entry.id === playerId) ?? null;
}

function getLocallyControlledPlayerEntityId() {
  const localParticipant = getLocalParticipant();
  if (localParticipant?.join_role !== "player") {
    return "";
  }
  return resolvePrivatePlayerEntityId(localParticipant.player_entity_id, getRuntimePlayerIds()) ?? "";
}

function getLocalPossessedPlayerPrediction(playerId = getLocallyControlledPlayerEntityId()) {
  const prediction = state.predictedPossessedPlayer;
  if (!prediction?.playerId || !playerId || prediction.playerId !== playerId) {
    return null;
  }
  return prediction;
}

function clearPossessedPlayerPrediction() {
  state.predictedPossessedPlayer = null;
  state.overworldCameraCenter = null;
  state.overworldCameraPlayerId = "";
  resetRuntimeLookSync();
}

function buildPrivateScriptDslEntityAliasMap(sceneDoc = {}) {
  const entityEntries = [
    ...(sceneDoc?.voxels ?? []),
    ...(sceneDoc?.primitives ?? []),
    ...(sceneDoc?.panels ?? []),
    ...(sceneDoc?.models ?? []),
    ...(sceneDoc?.screens ?? []),
    ...(sceneDoc?.players ?? []),
    ...(sceneDoc?.texts ?? []),
    ...(sceneDoc?.trigger_zones ?? []),
    ...(sceneDoc?.prefab_instances ?? []),
    ...(sceneDoc?.particles ?? []),
    ...(sceneDoc?.sounds ?? []),
  ];
  return new Map(
    entityEntries
      .map((entry) => String(entry?.id ?? "").trim())
      .filter(Boolean)
      .map((entryId) => [entryId, entryId]),
  );
}

function buildPrivateScriptDslTargetCatalog(sceneDoc = {}) {
  return buildPrivateWorldScriptTargetCatalog(sceneDoc);
}

function getActivePrivateWorldRuntime() {
  return state.runtimeSnapshot ?? state.selectedWorld?.active_instance?.runtime ?? null;
}

function getActivePrivateWorldScriptConfig(options = {}) {
  const runtime = options.runtime ?? getActivePrivateWorldRuntime();
  if (runtime?.script_config) {
    return runtime.script_config;
  }
  const scene = options.scene ?? getSelectedScene();
  if (scene?.compiled_doc?.runtime?.script_config && state.mode === "play") {
    return scene.compiled_doc.runtime.script_config;
  }
  let sceneDoc = options.sceneDoc ?? null;
  if (!sceneDoc) {
    try {
      sceneDoc = getRenderableSceneDoc();
    } catch (_error) {
      sceneDoc = scene?.scene_doc ?? null;
    }
  }
  if (!sceneDoc) {
    return scene?.compiled_doc?.runtime?.script_config ?? null;
  }
  return compileSharedPrivateWorldScriptDsl(sceneDoc.script_dsl ?? "", {
    sceneDoc,
    entityAliases: buildPrivateScriptDslEntityAliasMap(sceneDoc),
  }).script_config ?? scene?.compiled_doc?.runtime?.script_config ?? null;
}

function resolvePrivateWorldScriptPlayerId(player = null) {
  const explicitPlayerId = String(player?.id ?? player?.playerId ?? "").trim();
  if (explicitPlayerId) {
    return explicitPlayerId;
  }
  return String(getPossessedRuntimePlayer()?.id ?? state.predictedPossessedPlayer?.playerId ?? "").trim();
}

function getPlayerScriptControlConfig(player = null, options = {}) {
  const playerId = resolvePrivateWorldScriptPlayerId(player);
  if (!playerId) {
    return null;
  }
  return getActivePrivateWorldScriptConfig(options)?.player_controls?.[playerId] ?? null;
}

function getPlayerScriptCameraBehaviors(player = null, options = {}) {
  const playerId = resolvePrivateWorldScriptPlayerId(player);
  if (!playerId) {
    return null;
  }
  return getActivePrivateWorldScriptConfig(options)?.camera_behaviors?.[playerId] ?? null;
}

function getPlayerBindingToken(player = null, bindingName = "", fallback = "", options = {}) {
  const normalizedBinding = String(bindingName ?? "").trim().toLowerCase();
  if (!normalizedBinding) {
    return String(fallback ?? "").trim().toLowerCase();
  }
  const controlBinding = getPlayerScriptControlConfig(player, options)?.bindings?.[normalizedBinding];
  if (controlBinding) {
    return String(controlBinding).trim().toLowerCase();
  }
  const cameraBehaviors = getPlayerScriptCameraBehaviors(player, options);
  if (cameraBehaviors?.overworld_drag_pan?.bindings?.[normalizedBinding]) {
    return String(cameraBehaviors.overworld_drag_pan.bindings[normalizedBinding]).trim().toLowerCase();
  }
  if (cameraBehaviors?.face_mouse_orthogonal?.bindings?.[normalizedBinding]) {
    return String(cameraBehaviors.face_mouse_orthogonal.bindings[normalizedBinding]).trim().toLowerCase();
  }
  return String(fallback ?? "").trim().toLowerCase();
}

function getMovementBindingAliases(bindingName = "", resolvedToken = "") {
  const normalizedBinding = String(bindingName ?? "").trim().toLowerCase();
  const normalizedToken = String(resolvedToken ?? "").trim().toLowerCase();
  if (normalizedBinding === "move_forward_key" && normalizedToken === "w") {
    return ["arrowup"];
  }
  if (normalizedBinding === "move_back_key" && normalizedToken === "s") {
    return ["arrowdown"];
  }
  if (normalizedBinding === "move_left_key" && normalizedToken === "a") {
    return ["arrowleft"];
  }
  if (normalizedBinding === "move_right_key" && normalizedToken === "d") {
    return ["arrowright"];
  }
  return [];
}

function isBindingPressed(pressedKeys = state.pressedRuntimeKeys, bindingName = "", resolvedToken = "") {
  const pressed = pressedKeys instanceof Set ? pressedKeys : new Set();
  const normalizedToken = String(resolvedToken ?? "").trim().toLowerCase();
  if (normalizedToken && pressed.has(normalizedToken)) {
    return true;
  }
  for (const alias of getMovementBindingAliases(bindingName, normalizedToken)) {
    if (pressed.has(alias)) {
      return true;
    }
  }
  return false;
}

function getPrivateWorldGravityMagnitude(scriptConfig = getActivePrivateWorldScriptConfig()) {
  return Math.abs(Number(scriptConfig?.world_physics?.params?.gravity?.y ?? PRIVATE_PLAYER_RUNTIME.gravity) || PRIVATE_PLAYER_RUNTIME.gravity);
}

function getPlayerGravityScale(player = null, options = {}) {
  return Math.max(
    0,
    Number(getPlayerScriptControlConfig(player, options)?.params?.gravity_scale ?? 1) || 1,
  );
}

function getPlayerGravityMagnitude(player = null, options = {}) {
  return getPrivateWorldGravityMagnitude(options.scriptConfig) * getPlayerGravityScale(player, options);
}

function getPlayerMoveSpeed(player = null, options = {}) {
  return Math.max(
    0,
    Number(getPlayerScriptControlConfig(player, options)?.params?.move_speed ?? PRIVATE_PLAYER_RUNTIME.moveSpeed) || PRIVATE_PLAYER_RUNTIME.moveSpeed,
  );
}

function getPlayerSprintSpeed(player = null, options = {}) {
  return Math.max(
    getPlayerMoveSpeed(player, options),
    Number(getPlayerScriptControlConfig(player, options)?.params?.sprint_speed ?? PRIVATE_PLAYER_RUNTIME.sprintSpeed) || PRIVATE_PLAYER_RUNTIME.sprintSpeed,
  );
}

function getPlayerAcceleration(player = null, options = {}) {
  return Math.max(
    0,
    Number(getPlayerScriptControlConfig(player, options)?.params?.acceleration ?? PRIVATE_PLAYER_RUNTIME.acceleration) || PRIVATE_PLAYER_RUNTIME.acceleration,
  );
}

function getPlayerDeceleration(player = null, options = {}) {
  return Math.max(
    0,
    Number(getPlayerScriptControlConfig(player, options)?.params?.deceleration ?? getPlayerAcceleration(player, options)) || getPlayerAcceleration(player, options),
  );
}

function getPlayerAirControl(player = null, options = {}) {
  return clampNumber(
    Number(getPlayerScriptControlConfig(player, options)?.params?.air_control ?? 0.72) || 0.72,
    0.72,
    0,
    1,
  );
}

function getPlayerJumpHeight(player = null, options = {}) {
  const fallbackJumpHeight = 12.5 * PRIVATE_WORLD_BLOCK_UNIT;
  return Math.max(
    0,
    Number(getPlayerScriptControlConfig(player, options)?.params?.jump_height ?? fallbackJumpHeight) || fallbackJumpHeight,
  );
}

function getPlayerMaxFallSpeed(player = null, options = {}) {
  const rawValue = Number(getPlayerScriptControlConfig(player, options)?.params?.max_fall_speed);
  return Number.isFinite(rawValue) ? Math.max(0, rawValue) : Infinity;
}

function getPlayerJumpVelocity(player = null, options = {}) {
  return Math.sqrt(Math.max(0, getPlayerGravityMagnitude(player, options) * 2 * getPlayerJumpHeight(player, options)));
}

function getPlayerMoveForwardBinding(player = null, options = {}) {
  return getPlayerBindingToken(player, "move_forward_key", "w", options) || "w";
}

function getPlayerMoveBackBinding(player = null, options = {}) {
  return getPlayerBindingToken(player, "move_back_key", "s", options) || "s";
}

function getPlayerMoveLeftBinding(player = null, options = {}) {
  return getPlayerBindingToken(player, "move_left_key", "a", options) || "a";
}

function getPlayerMoveRightBinding(player = null, options = {}) {
  return getPlayerBindingToken(player, "move_right_key", "d", options) || "d";
}

function getPlayerJumpBinding(player = null, options = {}) {
  return getPlayerBindingToken(player, "jump_key", "space", options) || "space";
}

function getPlayerSprintBinding(player = null, options = {}) {
  return getPlayerBindingToken(player, "sprint_key", "shift", options) || "shift";
}

function getPlayerOverworldDragPanConfig(player = null, options = {}) {
  return getPlayerScriptCameraBehaviors(player, options)?.overworld_drag_pan ?? null;
}

function isPlayerOverworldDragPanEnabled(player = null, options = {}) {
  const cameraMode = normalizePlayerCameraMode(player?.camera_mode ?? player?.cameraMode ?? getActivePossessedCameraMode());
  if (!isDraggableOverworldCameraMode(cameraMode)) {
    return false;
  }
  const config = getPlayerOverworldDragPanConfig(player, options);
  if (!config) {
    return true;
  }
  return config.enabled !== false && config.params?.drag_enabled !== false;
}

function shouldClampPlayerOverworldPanToWorld(player = null, options = {}) {
  const config = getPlayerOverworldDragPanConfig(player, options);
  return config ? config.params?.clamp_to_world !== false : true;
}

function getPlayerOverworldDragButton(player = null, options = {}) {
  return getPlayerBindingToken(player, "drag_button", "mouse_left", options) || "mouse_left";
}

function getPlayerOverworldPanSpeed(player = null, options = {}) {
  return Math.max(0, Number(getPlayerOverworldDragPanConfig(player, options)?.params?.pan_speed ?? 1) || 1);
}

function getPlayerOverworldDragSensitivity(player = null, options = {}) {
  return Math.max(0, Number(getPlayerOverworldDragPanConfig(player, options)?.params?.drag_sensitivity ?? 1) || 1);
}

function getPlayerOverworldZoomSpeed(player = null, options = {}) {
  return Math.max(0, Number(getPlayerOverworldDragPanConfig(player, options)?.params?.zoom_speed ?? 1) || 1);
}

function getPlayerOverworldZoomMin(player = null, options = {}) {
  return Math.max(0, Number(getPlayerOverworldDragPanConfig(player, options)?.params?.zoom_min ?? PRIVATE_PLAYER_VIEW.minRadius) || PRIVATE_PLAYER_VIEW.minRadius);
}

function getPlayerOverworldZoomMax(player = null, options = {}) {
  return Math.max(
    getPlayerOverworldZoomMin(player, options),
    Number(getPlayerOverworldDragPanConfig(player, options)?.params?.zoom_max ?? PRIVATE_PLAYER_VIEW.maxRadius) || PRIVATE_PLAYER_VIEW.maxRadius,
  );
}

function isPlayerFaceMouseOrthogonalEnabled(player = null, options = {}) {
  const cameraMode = normalizePlayerCameraMode(player?.camera_mode ?? player?.cameraMode ?? getActivePossessedCameraMode());
  if (cameraMode !== "orthogonal" && cameraMode !== "fixed_orthogonal") {
    return false;
  }
  const config = getPlayerScriptCameraBehaviors(player, options)?.face_mouse_orthogonal ?? null;
  if (!config) {
    return false;
  }
  return config.enabled !== false && config.params?.enabled !== false;
}

function getPlayerFaceMouseSnapMode(player = null, options = {}) {
  return String(getPlayerScriptCameraBehaviors(player, options)?.face_mouse_orthogonal?.params?.snap_mode ?? "4_way").trim().toLowerCase() || "4_way";
}

function getPlayerFaceMouseTurnSmoothing(player = null, options = {}) {
  return Math.max(0, Number(getPlayerScriptCameraBehaviors(player, options)?.face_mouse_orthogonal?.params?.turn_smoothing ?? 0) || 0);
}

function getPlayerFaceMouseDeadzonePx(player = null, options = {}) {
  return Math.max(0, Number(getPlayerScriptCameraBehaviors(player, options)?.face_mouse_orthogonal?.params?.deadzone_px ?? 8) || 8);
}

function getTrackedRuntimeInputTokens() {
  const tokens = new Set(RUNTIME_INPUT_KEYS);
  const actionTokens = getActivePrivateWorldScriptConfig()?.action_metadata?.input_tokens ?? [];
  for (const token of actionTokens) {
    const normalized = normalizePrivateInputKey({ key: token, code: token });
    if (normalized) {
      tokens.add(normalized);
    }
  }
  const player = getPossessedRuntimePlayer() ?? state.predictedPossessedPlayer ?? null;
  if (player) {
    const controlBindings = Object.values(getPlayerScriptControlConfig(player)?.bindings ?? {});
    const cameraBindings = Object.values(getPlayerScriptCameraBehaviors(player)?.overworld_drag_pan?.bindings ?? {});
    for (const token of [...controlBindings, ...cameraBindings]) {
      const normalized = normalizePrivateInputKey({ key: token, code: token });
      if (normalized) {
        tokens.add(normalized);
      }
    }
  }
  return tokens;
}

function isTrackedRuntimeInputKey(value = "") {
  const normalized = String(value ?? "").trim().toLowerCase();
  return Boolean(normalized) && getTrackedRuntimeInputTokens().has(normalized);
}

function getRuntimePointerToken(event = {}) {
  return normalizePrivateInputKey({ button: event?.button });
}

function buildRuntimeMovementIntent(pressedKeys = state.pressedRuntimeKeys) {
  const movementEnabled = isActivePossessedPlayerMovementEnabled();
  const player = getPossessedRuntimePlayer() ?? state.predictedPossessedPlayer ?? null;
  const left = isBindingPressed(pressedKeys, "move_left_key", getPlayerMoveLeftBinding(player));
  const right = isBindingPressed(pressedKeys, "move_right_key", getPlayerMoveRightBinding(player));
  const forward = isBindingPressed(pressedKeys, "move_forward_key", getPlayerMoveForwardBinding(player));
  const backward = isBindingPressed(pressedKeys, "move_back_key", getPlayerMoveBackBinding(player));
  const cameraMode = getActivePossessedCameraMode();
  const orthogonalCamera = isOrthogonalCameraMode(cameraMode);
  const faceMouseOrthogonal = orthogonalCamera
    && isPlayerFaceMouseOrthogonalEnabled(player);
  const orthogonalOrientation = orthogonalCamera
    ? getPlayerFixedTopDownOrientation(getActivePossessedFixedTopDownDirection())
    : null;
  const headingY = faceMouseOrthogonal
    ? normalizeAngle(privateInputState.yaw)
    : orthogonalCamera
    ? orthogonalOrientation.headingY
    : normalizeAngle(privateInputState.yaw);
  if (isPlayerOverworldDragPanEnabled(player)) {
    return {
      x: 0,
      z: 0,
      headingY,
      active: false,
      sprint: false,
    };
  }
  const forwardAmount = Number(forward) - Number(backward);
  const strafeAmount = Number(right) - Number(left);
  const forwardVector = orthogonalCamera
    ? orthogonalOrientation.planarForwardVector
    : getPrivateFlatForwardVector(headingY);
  const rightVector = orthogonalCamera
    ? orthogonalOrientation.rightVector
    : new THREE.Vector3(Math.cos(headingY), 0, -Math.sin(headingY));
  let x = forwardVector.x * forwardAmount + rightVector.x * strafeAmount;
  let z = forwardVector.z * forwardAmount + rightVector.z * strafeAmount;
  const length = Math.hypot(x, z);
  if (length > 0.000001) {
    x /= length;
    z /= length;
  }
  if (!movementEnabled) {
    x = 0;
    z = 0;
  }
  return {
    x,
    z,
    headingY,
    active: movementEnabled && length > 0.000001,
    sprint: movementEnabled
      && isBindingPressed(pressedKeys, "sprint_key", getPlayerSprintBinding(player))
      && length > 0.000001,
  };
}

function createPossessedPlayerPrediction(runtimePlayer = {}) {
  const position = runtimePlayer.position ?? {};
  const velocity = runtimePlayer.velocity ?? {};
  const rotation = runtimePlayer.rotation ?? {};
  const positionX = Number(position.x);
  const positionY = Number(position.y);
  const positionZ = Number(position.z);
  const velocityX = Number(velocity.x);
  const velocityY = Number(velocity.y);
  const velocityZ = Number(velocity.z);
  const rotationX = Number(rotation.x);
  const rotationY = Number(rotation.y);
  const rotationZ = Number(rotation.z);
  const prediction = {
    playerId: String(runtimePlayer.id ?? "").trim(),
    position: new THREE.Vector3(
      Number.isFinite(positionX) ? positionX : 0,
      Number.isFinite(positionY) ? positionY : 0,
      Number.isFinite(positionZ) ? positionZ : 0,
    ),
    velocity: new THREE.Vector3(
      Number.isFinite(velocityX) ? velocityX : 0,
      Number.isFinite(velocityY) ? velocityY : 0,
      Number.isFinite(velocityZ) ? velocityZ : 0,
    ),
    rotation: {
      x: Number.isFinite(rotationX) ? rotationX : 0,
      y: Number.isFinite(rotationY) ? rotationY : 0,
      z: Number.isFinite(rotationZ) ? rotationZ : 0,
    },
    scale: Math.max(0.25, Number(runtimePlayer.scale ?? PRIVATE_PLAYER_DEFAULT_SCALE) || PRIVATE_PLAYER_DEFAULT_SCALE),
    cameraMode: normalizePlayerCameraMode(runtimePlayer.camera_mode ?? "third_person"),
    fixedTopDownDirection: normalizePlayerFixedTopDownDirection(runtimePlayer.fixed_top_down_direction ?? "north"),
    fixedTopDownAngle: normalizePlayerFixedTopDownAngle(runtimePlayer.fixed_top_down_angle ?? 90),
    fixedTopDownDistance: normalizePlayerFixedTopDownDistance(runtimePlayer.fixed_top_down_distance ?? PRIVATE_PLAYER_VIEW.defaultRadius),
    fixedTopDownWidth: Math.max(0, Number(runtimePlayer.fixed_top_down_width ?? 0) || 0),
    fixedTopDownHeight: Math.max(0, Number(runtimePlayer.fixed_top_down_height ?? 0) || 0),
    movementEnabled: isPlayerMovementEnabled(runtimePlayer),
    jumpEnabled: isPlayerJumpEnabled(runtimePlayer),
    bodyMode: String(runtimePlayer.body_mode ?? "rigid").trim() || "rigid",
    baseGroundY: Number.isFinite(positionY) ? positionY : 0,
    groundY: Number.isFinite(positionY) ? positionY : 0,
    onGround: runtimePlayer.on_ground === true || String(runtimePlayer.body_mode ?? "rigid").trim().toLowerCase() === "ghost",
    jumpHeld: false,
    lastConsumedJumpPulseSeq: 0,
    localJumpUntilMs: 0,
    jumpVisualOffsetY: 0,
    jumpVisualVelocityY: 0,
    localCarryPlatformId: "",
    localCarryPlatformPosition: null,
    localCarryPlatformOffset: null,
    motionState: null,
  };
  return prediction;
}

function resetPossessedPlayerJumpBridge(prediction = null) {
  if (!prediction) {
    return;
  }
  prediction.localJumpUntilMs = 0;
  prediction.jumpVisualOffsetY = 0;
  prediction.jumpVisualVelocityY = 0;
}

function clearPossessedOverworldCameraCenter() {
  state.overworldCameraCenter = null;
  state.overworldCameraPlayerId = "";
}

function normalizePlayerCameraMode(value = "third_person") {
  const normalized = String(value ?? "third_person")
    .trim()
    .toLowerCase()
    .replace(/[\s-]+/g, "_");
  if (normalized === "top_down") {
    return "orthogonal";
  }
  if (normalized === "fixed_top_down" || normalized === "fixed_top_down_first_person" || normalized === "orthogonal_fixed") {
    return "fixed_orthogonal";
  }
  return PLAYER_CAMERA_MODES.includes(normalized) ? normalized : "third_person";
}

function isOrthogonalCameraMode(value = "third_person") {
  const normalized = normalizePlayerCameraMode(value);
  return normalized === "orthogonal"
    || normalized === "fixed_orthogonal"
    || normalized === "overworld"
    || normalized === "overworld_fixed";
}

function isFixedTopDownCameraMode(value = "third_person") {
  const normalized = normalizePlayerCameraMode(value);
  return normalized === "fixed_orthogonal" || normalized === "overworld_fixed";
}

function isOverworldCameraMode(value = "third_person") {
  const normalized = normalizePlayerCameraMode(value);
  return normalized === "overworld" || normalized === "overworld_fixed";
}

function isDraggableOverworldCameraMode(value = "third_person") {
  return normalizePlayerCameraMode(value) === "overworld";
}

function isPlayerMovementToggleCameraMode(value = "third_person") {
  const normalized = normalizePlayerCameraMode(value);
  return normalized === "third_person" || normalized === "first_person";
}

function normalizePlayerMovementEnabled(value = true) {
  return value !== false;
}

function normalizePlayerJumpEnabled(value = false) {
  return value !== false;
}

function isPlayerMovementEnabled(player = {}) {
  const controlConfig = getPlayerScriptControlConfig(player);
  if (controlConfig) {
    return controlConfig.enabled !== false;
  }
  const cameraMode = normalizePlayerCameraMode(player?.camera_mode ?? player?.cameraMode ?? "third_person");
  if (!isPlayerMovementToggleCameraMode(cameraMode)) {
    return true;
  }
  return normalizePlayerMovementEnabled(player?.movement_enabled ?? player?.movementEnabled ?? true);
}

function isPlayerJumpEnabled(player = {}) {
  const controlConfig = getPlayerScriptControlConfig(player);
  if (Object.hasOwn(controlConfig?.params ?? {}, "jump_enabled")) {
    return controlConfig.params.jump_enabled === true;
  }
  return normalizePlayerJumpEnabled(player?.jump_enabled ?? player?.jumpEnabled ?? false);
}

function shouldSuppressPossessedRuntimeMovement(player = {}) {
  return !isPlayerMovementEnabled(player)
    || isPlayerOverworldDragPanEnabled(player);
}

function normalizePlayerFixedTopDownDirection(value = "north") {
  const normalized = String(value ?? "north")
    .trim()
    .toLowerCase()
    .replace(/[\s-]+/g, "_");
  const resolved = ({
    northeast: "north_east",
    southeast: "south_east",
    southwest: "south_west",
    northwest: "north_west",
  })[normalized] ?? normalized;
  return PLAYER_FIXED_TOP_DOWN_DIRECTION_OPTIONS.some((option) => option.value === resolved)
    ? resolved
    : "north";
}

function normalizePlayerFixedTopDownAngle(value = 90) {
  const normalized = Math.round(Number(value));
  return PLAYER_FIXED_TOP_DOWN_ANGLE_OPTIONS.some((option) => Number(option.value) === normalized)
    ? normalized
    : 90;
}

function normalizePlayerFixedTopDownDistance(value = PRIVATE_PLAYER_VIEW.defaultRadius) {
  return clampNumber(
    value,
    PRIVATE_PLAYER_VIEW.defaultRadius,
    PRIVATE_WORLD_BLOCK_UNIT * 2,
    4096,
  );
}

function getPlayerFixedTopDownDirectionVector(direction = "north") {
  const resolvedDirection = normalizePlayerFixedTopDownDirection(direction);
  const diagonal = Math.SQRT1_2;
  if (resolvedDirection === "north_east") {
    return new THREE.Vector3(diagonal, 0, -diagonal);
  }
  if (resolvedDirection === "east") {
    return new THREE.Vector3(1, 0, 0);
  }
  if (resolvedDirection === "south_east") {
    return new THREE.Vector3(diagonal, 0, diagonal);
  }
  if (resolvedDirection === "south") {
    return new THREE.Vector3(0, 0, 1);
  }
  if (resolvedDirection === "south_west") {
    return new THREE.Vector3(-diagonal, 0, diagonal);
  }
  if (resolvedDirection === "west") {
    return new THREE.Vector3(-1, 0, 0);
  }
  if (resolvedDirection === "north_west") {
    return new THREE.Vector3(-diagonal, 0, -diagonal);
  }
  return new THREE.Vector3(0, 0, -1);
}

function getPlayerFixedTopDownOrientation(direction = "north", angle = 90) {
  const resolvedDirection = normalizePlayerFixedTopDownDirection(direction);
  const resolvedAngle = normalizePlayerFixedTopDownAngle(angle);
  const planarForwardVector = getPlayerFixedTopDownDirectionVector(resolvedDirection);
  const downVector = new THREE.Vector3(0, -1, 0);
  const worldUpVector = new THREE.Vector3(0, 1, 0);
  const rightVector = new THREE.Vector3().crossVectors(downVector, planarForwardVector).normalize();
  const headingY = normalizeAngle(Math.atan2(-planarForwardVector.x, -planarForwardVector.z));
  const angleRadians = THREE.MathUtils.degToRad(resolvedAngle);
  const viewDirection = new THREE.Vector3(
    planarForwardVector.x * Math.cos(angleRadians),
    -Math.sin(angleRadians),
    planarForwardVector.z * Math.cos(angleRadians),
  ).normalize();
  const upHint = resolvedAngle >= 89.999
    ? planarForwardVector.clone()
    : worldUpVector.clone();
  const cameraRightVector = new THREE.Vector3().crossVectors(viewDirection, upHint);
  if (cameraRightVector.lengthSq() <= 0.000001) {
    cameraRightVector.copy(rightVector);
  } else {
    cameraRightVector.normalize();
  }
  const cameraUpVector = new THREE.Vector3().crossVectors(cameraRightVector, viewDirection);
  if (cameraUpVector.lengthSq() <= 0.000001) {
    cameraUpVector.copy(planarForwardVector);
  } else {
    cameraUpVector.normalize();
  }
  return {
    direction: resolvedDirection,
    angle: resolvedAngle,
    planarForwardVector,
    rightVector,
    headingY,
    viewDirection,
    cameraRightVector,
    cameraUpVector,
    cameraOffsetDirection: viewDirection.clone().multiplyScalar(-1),
  };
}

function getActivePossessedCameraMode() {
  const prediction = state.predictedPossessedPlayer;
  if (prediction?.cameraMode) {
    return normalizePlayerCameraMode(prediction.cameraMode);
  }
  return normalizePlayerCameraMode(getPossessedRuntimePlayer()?.camera_mode ?? "third_person");
}

function getActivePossessedFixedTopDownDirection() {
  const prediction = state.predictedPossessedPlayer;
  if (prediction?.fixedTopDownDirection) {
    return normalizePlayerFixedTopDownDirection(prediction.fixedTopDownDirection);
  }
  return normalizePlayerFixedTopDownDirection(getPossessedRuntimePlayer()?.fixed_top_down_direction ?? "north");
}

function isActivePossessedPlayerMovementEnabled() {
  const prediction = state.predictedPossessedPlayer;
  if (prediction) {
    return isPlayerMovementEnabled(prediction);
  }
  return isPlayerMovementEnabled(getPossessedRuntimePlayer() ?? {});
}

function getPlayerFixedTopDownWindow(player = {}, world = state.selectedWorld) {
  if (!isFixedTopDownCameraMode(player?.camera_mode ?? "")) {
    const distance = normalizePlayerFixedTopDownDistance(
      player?.fixed_top_down_distance ?? PRIVATE_PLAYER_VIEW.defaultRadius,
    );
    const viewportWidth = Math.max(1, Number(state.preview?.viewportWidth) || 1);
    const viewportHeight = Math.max(1, Number(state.preview?.viewportHeight) || 1);
    const aspect = viewportWidth / Math.max(1, viewportHeight);
    if (aspect >= 1) {
      return {
        width: Math.max(PRIVATE_WORLD_BLOCK_UNIT * 2, distance * aspect),
        height: Math.max(PRIVATE_WORLD_BLOCK_UNIT * 2, distance),
      };
    }
    return {
      width: Math.max(PRIVATE_WORLD_BLOCK_UNIT * 2, distance),
      height: Math.max(PRIVATE_WORLD_BLOCK_UNIT * 2, distance / Math.max(0.0001, aspect)),
    };
  }
  const direction = normalizePlayerFixedTopDownDirection(player?.fixed_top_down_direction ?? "north");
  const angle = normalizePlayerFixedTopDownAngle(player?.fixed_top_down_angle ?? 90);
  const orientation = getPlayerFixedTopDownOrientation(direction, angle);
  const worldWidth = getProjectedWorldAxisSpan(world, orientation.cameraRightVector);
  const worldHeight = getProjectedWorldAxisSpan(world, orientation.cameraUpVector);
  const followWidth = Math.max(PRIVATE_WORLD_BLOCK_UNIT * 6, Math.min(worldWidth, PRIVATE_PLAYER_VIEW.defaultRadius * 1.6));
  const followHeight = Math.max(PRIVATE_WORLD_BLOCK_UNIT * 4, Math.min(worldHeight, PRIVATE_PLAYER_VIEW.defaultRadius));
  const defaultWidth = isFixedTopDownCameraMode(player?.camera_mode ?? "")
    ? worldWidth
    : followWidth;
  const defaultHeight = isFixedTopDownCameraMode(player?.camera_mode ?? "")
    ? worldHeight
    : followHeight;
  const width = Number(player?.fixed_top_down_width ?? 0);
  const height = Number(player?.fixed_top_down_height ?? 0);
  return {
    width: Math.max(PRIVATE_WORLD_BLOCK_UNIT * 2, Number.isFinite(width) && width > 0 ? width : defaultWidth),
    height: Math.max(PRIVATE_WORLD_BLOCK_UNIT * 2, Number.isFinite(height) && height > 0 ? height : defaultHeight),
  };
}

function shouldHidePossessedPlayerForCameraMode(value = "third_person") {
  return isOverworldCameraMode(value);
}

function getPossessedOverworldCameraCenter(player = getPossessedRuntimePlayer() ?? state.predictedPossessedPlayer ?? null) {
  const resolvedPlayer = player ?? null;
  const playerId = String(resolvedPlayer?.id ?? resolvedPlayer?.playerId ?? "").trim();
  const cameraMode = normalizePlayerCameraMode(resolvedPlayer?.camera_mode ?? resolvedPlayer?.cameraMode ?? "third_person");
  if (!playerId || !isDraggableOverworldCameraMode(cameraMode)) {
    clearPossessedOverworldCameraCenter();
    return null;
  }
  if (!state.overworldCameraCenter || state.overworldCameraPlayerId !== playerId) {
    state.overworldCameraCenter = new THREE.Vector3(
      Number(resolvedPlayer?.position?.x ?? 0) || 0,
      Number(resolvedPlayer?.position?.y ?? 0) || 0,
      Number(resolvedPlayer?.position?.z ?? 0) || 0,
    );
    state.overworldCameraPlayerId = playerId;
  }
  return state.overworldCameraCenter;
}

function getPossessedOverworldGroundPointAtClient(clientX = 0, clientY = 0, planeY = 0, preview = state.preview) {
  const metrics = getPreviewPointerMetrics({ clientX, clientY });
  if (!metrics || metrics.preview !== preview || !preview?.camera) {
    return null;
  }
  const plane = new THREE.Plane(new THREE.Vector3(0, 1, 0), -planeY);
  preview.raycaster.setFromCamera(metrics.pointer, preview.camera);
  const point = new THREE.Vector3();
  return preview.raycaster.ray.intersectPlane(plane, point) ? point : null;
}

function panPossessedOverworldByScreenDelta(previousClientX = 0, previousClientY = 0, clientX = 0, clientY = 0, preview = state.preview) {
  if (!preview?.camera?.isOrthographicCamera) {
    return false;
  }
  const player = getPossessedRuntimePlayer();
  const prediction = ensurePossessedPlayerPrediction(player);
  const cameraCenter = getPossessedOverworldCameraCenter(player ?? prediction);
  if (!player || !prediction || !cameraCenter || !isPlayerOverworldDragPanEnabled(player ?? prediction)) {
    return false;
  }
  const planeY = Number(player?.position?.y ?? cameraCenter.y) || cameraCenter.y || 0;
  const previousPoint = getPossessedOverworldGroundPointAtClient(previousClientX, previousClientY, planeY, preview);
  const currentPoint = getPossessedOverworldGroundPointAtClient(clientX, clientY, planeY, preview);
  if (!previousPoint || !currentPoint) {
    return false;
  }
  const sensitivity = getPlayerOverworldDragSensitivity(player ?? prediction);
  const panSpeed = getPlayerOverworldPanSpeed(player ?? prediction);
  const translation = previousPoint.clone().sub(currentPoint).multiplyScalar(sensitivity * panSpeed);
  if (translation.lengthSq() <= 0.000001) {
    return false;
  }
  if (shouldClampPlayerOverworldPanToWorld(player ?? prediction)) {
    const bounds = getPrivateWorldBounds(state.selectedWorld);
    cameraCenter.x = clampNumber(cameraCenter.x + translation.x, cameraCenter.x, bounds.minX, bounds.maxX);
    cameraCenter.z = clampNumber(cameraCenter.z + translation.z, cameraCenter.z, bounds.minZ, bounds.maxZ);
  } else {
    cameraCenter.x += translation.x;
    cameraCenter.z += translation.z;
  }
  cameraCenter.y = planeY;
  updatePossessedCamera(preview, 0);
  return true;
}

function updatePossessedFaceMouseFromPointer(pointerSource, preview = state.preview) {
  if (!preview?.camera) {
    return false;
  }
  const player = state.predictedPossessedPlayer ?? getPossessedRuntimePlayer() ?? null;
  if (!player || !isPlayerFaceMouseOrthogonalEnabled(player)) {
    return false;
  }
  const metrics = getPreviewPointerMetrics(pointerSource);
  if (!metrics || metrics.preview !== preview) {
    return false;
  }
  const planeY = Number(player?.position?.y ?? 0) || 0;
  const playerX = Number(player?.position?.x ?? 0) || 0;
  const playerZ = Number(player?.position?.z ?? 0) || 0;
  const plane = new THREE.Plane(new THREE.Vector3(0, 1, 0), -planeY);
  preview.raycaster.setFromCamera(metrics.pointer, preview.camera);
  const point = new THREE.Vector3();
  if (!preview.raycaster.ray.intersectPlane(plane, point)) {
    return false;
  }
  const deltaX = point.x - playerX;
  const deltaZ = point.z - playerZ;
  const deadzonePx = getPlayerFaceMouseDeadzonePx(player);
  const pointerDeltaX = Number(metrics.canvasX ?? 0) - Number(metrics.viewport?.x ?? 0) - Number((metrics.viewport?.width ?? 0) / 2);
  const pointerDeltaY = Number(metrics.canvasY ?? 0) - Number(metrics.viewport?.y ?? 0) - Number((metrics.viewport?.height ?? 0) / 2);
  if (Math.hypot(deltaX, deltaZ) <= 0.0001 || Math.hypot(pointerDeltaX, pointerDeltaY) <= deadzonePx) {
    return false;
  }
  let nextYaw = normalizeAngle(Math.atan2(-deltaX, -deltaZ));
  const snapMode = getPlayerFaceMouseSnapMode(player);
  if (snapMode === "4_way") {
    nextYaw = normalizeAngle(Math.round(nextYaw / (Math.PI / 2)) * (Math.PI / 2));
  } else if (snapMode === "8_way") {
    nextYaw = normalizeAngle(Math.round(nextYaw / (Math.PI / 4)) * (Math.PI / 4));
  }
  const smoothing = getPlayerFaceMouseTurnSmoothing(player);
  privateInputState.yaw = smoothing > 0
    ? normalizeAngle(THREE.MathUtils.lerp(privateInputState.yaw, nextYaw, clampNumber(smoothing * 0.12, 0.12, 0, 1)))
    : nextYaw;
  if (state.predictedPossessedPlayer?.rotation) {
    state.predictedPossessedPlayer.rotation.y = privateInputState.yaw;
  }
  if (getLocalParticipant()?.join_role === "player") {
    syncRuntimeLookHeading();
  }
  return true;
}

function getProjectedWorldAxisSpan(world = state.selectedWorld, axis = null) {
  const axisVector = axis instanceof THREE.Vector3
    ? axis.clone()
    : new THREE.Vector3(
      Number(axis?.x ?? 0) || 0,
      Number(axis?.y ?? 0) || 0,
      Number(axis?.z ?? 0) || 0,
    );
  if (axisVector.lengthSq() <= 0.000001) {
    return PRIVATE_WORLD_BLOCK_UNIT * 2;
  }
  axisVector.normalize();
  const bounds = getPrivateWorldBounds(world);
  const rig = getPrivateViewerRigConfig(world);
  const xs = [bounds.minX, bounds.maxX];
  const ys = [0, rig.height];
  const zs = [bounds.minZ, bounds.maxZ];
  let minProjection = Infinity;
  let maxProjection = -Infinity;
  for (const x of xs) {
    for (const y of ys) {
      for (const z of zs) {
        const projection = x * axisVector.x + y * axisVector.y + z * axisVector.z;
        minProjection = Math.min(minProjection, projection);
        maxProjection = Math.max(maxProjection, projection);
      }
    }
  }
  if (!Number.isFinite(minProjection) || !Number.isFinite(maxProjection)) {
    return PRIVATE_WORLD_BLOCK_UNIT * 2;
  }
  return Math.max(PRIVATE_WORLD_BLOCK_UNIT * 2, maxProjection - minProjection);
}

function applyPossessedCameraModeRig(cameraMode = "third_person", runtimePlayer = null, options = {}) {
  const resolvedMode = normalizePlayerCameraMode(cameraMode);
  const previousMode = normalizePlayerCameraMode(options.previousCameraMode ?? "");
  const headingY = Number(runtimePlayer?.rotation?.y);
  if (resolvedMode !== previousMode) {
    clearPossessedOverworldCameraCenter();
    const nextHeadingY = isOrthogonalCameraMode(resolvedMode)
      ? getPlayerFixedTopDownOrientation(
        runtimePlayer?.fixed_top_down_direction ?? "north",
        runtimePlayer?.fixed_top_down_angle ?? 90,
      ).headingY
      : (Number.isFinite(headingY) ? headingY : getRuntimeInputHeadingY());
    releaseHeldRuntimeKeys({ headingY: nextHeadingY });
    privateInputState.keys.clear();
    privateInputState.sprintHoldSeconds = 0;
  }
  if (isOrthogonalCameraMode(resolvedMode)) {
    privateInputState.yaw = getPlayerFixedTopDownOrientation(
      runtimePlayer?.fixed_top_down_direction ?? "north",
      runtimePlayer?.fixed_top_down_angle ?? 90,
    ).headingY;
    privateInputState.pitch = -1.05;
  } else if (Number.isFinite(headingY)) {
    privateInputState.yaw = normalizeAngle(headingY);
  }
  if (resolvedMode === "first_person") {
    privateInputState.pitch = 0;
  } else if (resolvedMode === "third_person") {
    privateInputState.pitch = -0.34;
    state.cameraRadius = PRIVATE_PLAYER_VIEW.defaultRadius;
  }
  if (options.resetLookSync !== false) {
    resetRuntimeLookSync();
  }
  return resolvedMode;
}

function ensurePossessedPlayerPrediction(runtimePlayer = getPossessedRuntimePlayer()) {
  if (!runtimePlayer || getLocalParticipant()?.join_role !== "player") {
    clearPossessedPlayerPrediction();
    return null;
  }
  const playerId = String(runtimePlayer.id ?? "").trim();
  if (!playerId) {
    clearPossessedPlayerPrediction();
    return null;
  }
  let prediction = state.predictedPossessedPlayer;
  if (!prediction || prediction.playerId !== playerId) {
    const nextCameraMode = applyPossessedCameraModeRig(runtimePlayer.camera_mode, runtimePlayer, {
      previousCameraMode: prediction?.cameraMode ?? "",
    });
    state.cameraRadius = clampNumber(
      state.cameraRadius,
      PRIVATE_PLAYER_VIEW.defaultRadius,
      PRIVATE_PLAYER_VIEW.minRadius,
      PRIVATE_PLAYER_VIEW.maxRadius,
    );
    prediction = createPossessedPlayerPrediction(runtimePlayer);
    prediction.cameraMode = nextCameraMode;
    state.predictedPossessedPlayer = prediction;
    if (shouldSuppressPossessedRuntimeMovement(prediction) && state.pressedRuntimeKeys.size > 0) {
      releaseHeldRuntimeKeys({
        headingY: getRuntimeInputHeadingY(),
        shouldReleaseKey: isRuntimeMovementInputKey,
      });
      privateInputState.sprintHoldSeconds = 0;
    }
    return prediction;
  }
  prediction.scale = Math.max(0.25, Number(runtimePlayer.scale ?? prediction.scale ?? PRIVATE_PLAYER_DEFAULT_SCALE) || PRIVATE_PLAYER_DEFAULT_SCALE);
  const nextCameraMode = normalizePlayerCameraMode(runtimePlayer.camera_mode ?? prediction.cameraMode ?? "third_person");
  if (nextCameraMode !== prediction.cameraMode) {
    prediction.cameraMode = applyPossessedCameraModeRig(nextCameraMode, runtimePlayer, {
      previousCameraMode: prediction.cameraMode,
    });
  } else {
    prediction.cameraMode = nextCameraMode;
  }
  prediction.movementEnabled = isPlayerMovementEnabled(runtimePlayer);
  prediction.jumpEnabled = isPlayerJumpEnabled(runtimePlayer);
  prediction.fixedTopDownDirection = normalizePlayerFixedTopDownDirection(
    runtimePlayer.fixed_top_down_direction ?? prediction.fixedTopDownDirection ?? "north",
  );
  prediction.fixedTopDownAngle = normalizePlayerFixedTopDownAngle(
    runtimePlayer.fixed_top_down_angle ?? prediction.fixedTopDownAngle ?? 90,
  );
  prediction.fixedTopDownDistance = normalizePlayerFixedTopDownDistance(
    runtimePlayer.fixed_top_down_distance ?? prediction.fixedTopDownDistance ?? PRIVATE_PLAYER_VIEW.defaultRadius,
  );
  prediction.fixedTopDownWidth = Math.max(0, Number(runtimePlayer.fixed_top_down_width ?? prediction.fixedTopDownWidth ?? 0) || 0);
  prediction.fixedTopDownHeight = Math.max(0, Number(runtimePlayer.fixed_top_down_height ?? prediction.fixedTopDownHeight ?? 0) || 0);
  prediction.bodyMode = String(runtimePlayer.body_mode ?? prediction.bodyMode ?? "rigid").trim() || "rigid";
  if (shouldSuppressPossessedRuntimeMovement(prediction) && state.pressedRuntimeKeys.size > 0) {
    releaseHeldRuntimeKeys({
      headingY: getRuntimeInputHeadingY(),
      shouldReleaseKey: isRuntimeMovementInputKey,
    });
    privateInputState.sprintHoldSeconds = 0;
  }
  return prediction;
}

function reconcilePossessedPlayerPrediction(runtimePlayer = getPossessedRuntimePlayer()) {
  const prediction = ensurePossessedPlayerPrediction(runtimePlayer);
  if (!prediction || !runtimePlayer) {
    return null;
  }
  return prediction;
}

function toPlainCollisionScale(scale = {}, fallback = { x: 1, y: 1, z: 1 }) {
  const fallbackX = Number(fallback?.x ?? 1);
  const fallbackY = Number(fallback?.y ?? 1);
  const fallbackZ = Number(fallback?.z ?? 1);
  return {
    x: Math.max(0.1, Number(scale?.x ?? fallbackX) || fallbackX || 1),
    y: Math.max(0.1, Number(scale?.y ?? fallbackY) || fallbackY || 1),
    z: Math.max(0.1, Number(scale?.z ?? fallbackZ) || fallbackZ || 1),
  };
}

function getPrivatePlayerCollisionSize(scale = PRIVATE_PLAYER_DEFAULT_SCALE) {
  const resolvedScale = Math.max(0.25, Number(scale ?? PRIVATE_PLAYER_DEFAULT_SCALE) || PRIVATE_PLAYER_DEFAULT_SCALE);
  return {
    x: PRIVATE_PLAYER_METRICS.width * resolvedScale,
    y: PRIVATE_PLAYER_METRICS.height * resolvedScale,
    z: PRIVATE_PLAYER_METRICS.width * resolvedScale,
  };
}

function isPrivateCollisionModeRigid(value = "rigid") {
  return String(value ?? "rigid").trim().toLowerCase() !== "ghost";
}

function getPrivateCollisionEntrySize(kind, entry = {}) {
  if (entry?.collider_scale) {
    return toPlainCollisionScale(entry.collider_scale, entry.scale ?? { x: 1, y: 1, z: 1 });
  }
  if (kind === "voxel") {
    return getPrivateVoxelScale(entry.scale);
  }
  const size = getEntityApproxRenderSize(kind, entry);
  return toPlainCollisionScale(size, { x: 1, y: 1, z: 1 });
}

function getPrivateCollisionSupportEnvelope(position = {}, size = {}, rotation = {}) {
  const normalizedPosition = {
    x: Number(position?.x ?? 0) || 0,
    y: Number(position?.y ?? 0) || 0,
    z: Number(position?.z ?? 0) || 0,
  };
  const normalizedSize = toPlainCollisionScale(size, { x: 1, y: 1, z: 1 });
  const normalizedRotation = {
    x: Number(rotation?.x ?? 0) || 0,
    y: Number(rotation?.y ?? 0) || 0,
    z: Number(rotation?.z ?? 0) || 0,
  };
  const half = getRotatedCollisionHalfExtents(normalizedSize, normalizedRotation);
  return {
    position: normalizedPosition,
    size: normalizedSize,
    rotation: normalizedRotation,
    half,
    surfaceY: normalizedPosition.y + half.y,
  };
}

function samplePrivateCollisionSupportSurface(position = {}, size = {}, rotation = {}, samplePosition = {}, padding = {}) {
  return sampleCollisionSupportSurface({
    position,
    size,
    rotation,
    samplePosition,
    paddingX: Math.max(0, Number(padding?.x ?? 0) || 0),
    paddingZ: Math.max(0, Number(padding?.z ?? 0) || 0),
  });
}

function getPrivatePlatformCarryVerticalTolerance(playerHalf = {}, platformHalf = null) {
  const playerHalfY = Math.max(0, Number(playerHalf?.y ?? 0) || 0);
  const platformHalfY = Math.max(0, Number(platformHalf?.y ?? 0) || 0);
  const scaledTolerance = Math.max(
    playerHalfY * 0.28,
    platformHalfY * 0.5,
  );
  return Math.max(
    PRIVATE_PLATFORM_CARRY_VERTICAL_TOLERANCE,
    Math.min(PRIVATE_WORLD_BLOCK_UNIT * 0.25, scaledTolerance),
  );
}

function getPrivatePlatformCarryRecoveryTolerance(playerHalf = {}, platformHalf = null) {
  const playerHalfY = Math.max(0, Number(playerHalf?.y ?? 0) || 0);
  const platformHalfY = Math.max(0, Number(platformHalf?.y ?? 0) || 0);
  const scaledRecovery = Math.max(
    getPrivatePlatformCarryVerticalTolerance(playerHalf, platformHalf),
    playerHalfY * 0.75,
    platformHalfY,
  );
  return Math.max(
    PRIVATE_PLATFORM_CARRY_VERTICAL_TOLERANCE,
    Math.min(
      Math.max(PRIVATE_WORLD_BLOCK_UNIT * 0.9, playerHalfY),
      scaledRecovery,
    ),
  );
}

function buildPrivateCollisionProbe(startPosition = {}, desiredPosition = {}, playerSize = {}) {
  const probePadding = PRIVATE_WORLD_BLOCK_UNIT * 2;
  const playerHalf = getHalfExtentsFromScale(playerSize);
  const minX = Math.min(Number(startPosition.x ?? 0) || 0, Number(desiredPosition.x ?? 0) || 0) - playerHalf.x - probePadding;
  const maxX = Math.max(Number(startPosition.x ?? 0) || 0, Number(desiredPosition.x ?? 0) || 0) + playerHalf.x + probePadding;
  const minY = Math.min(Number(startPosition.y ?? 0) || 0, Number(desiredPosition.y ?? 0) || 0) - playerHalf.y - probePadding;
  const maxY = Math.max(Number(startPosition.y ?? 0) || 0, Number(desiredPosition.y ?? 0) || 0) + playerHalf.y + probePadding;
  const minZ = Math.min(Number(startPosition.z ?? 0) || 0, Number(desiredPosition.z ?? 0) || 0) - playerHalf.z - probePadding;
  const maxZ = Math.max(Number(startPosition.z ?? 0) || 0, Number(desiredPosition.z ?? 0) || 0) + playerHalf.z + probePadding;
  return { minX, maxX, minY, maxY, minZ, maxZ };
}

function addPrivateCollisionBlocker(blockers, blocker = {}, probe = null) {
  const envelope = getPrivateCollisionSupportEnvelope(blocker.position, blocker.size, blocker.rotation);
  const { position, size, rotation, half } = envelope;
  if (probe) {
    if (
      position.x + half.x < probe.minX
      || position.x - half.x > probe.maxX
      || position.y + half.y < probe.minY
      || position.y - half.y > probe.maxY
      || position.z + half.z < probe.minZ
      || position.z - half.z > probe.maxZ
    ) {
      return;
    }
  }
  blockers.push({
    position,
    size,
    rotation,
  });
}

function addPrivateSupportSurface(surfaces, surface = {}, probe = null) {
  const envelope = getPrivateCollisionSupportEnvelope(surface.position, surface.size, surface.rotation);
  const { position, size, rotation, half } = envelope;
  if (probe) {
    if (
      position.x + half.x < probe.minX
      || position.x - half.x > probe.maxX
      || position.y + half.y < probe.minY
      || position.y - half.y > probe.maxY
      || position.z + half.z < probe.minZ
      || position.z - half.z > probe.maxZ
    ) {
      return;
    }
  }
  surfaces.push({
    position,
    size,
    rotation,
    carry_riders: surface.carry_riders === true,
    velocity: {
      x: Number(surface.velocity?.x ?? 0) || 0,
      y: Number(surface.velocity?.y ?? 0) || 0,
      z: Number(surface.velocity?.z ?? 0) || 0,
    },
    anchorPosition: surface.anchorPosition ? {
      x: Number(surface.anchorPosition?.x ?? position.x) || 0,
      y: Number(surface.anchorPosition?.y ?? position.y) || 0,
      z: Number(surface.anchorPosition?.z ?? position.z) || 0,
    } : null,
    entryId: String(surface.entryId ?? "").trim(),
    entry: surface.entry ?? null,
  });
}

function getPrivateDynamicEntryMotionSample(entry = null, options = {}) {
  const entryId = String(entry?.id ?? "").trim();
  const mesh = entryId ? (state.preview?.entityMeshes?.get(entryId) ?? null) : null;
  const motionState = mesh?.userData?.privateWorldRuntimeMotionState ?? null;
  const useAuthoritative = options.authoritative === true;
  let worldPosition = null;
  if (options.worldSpace === true && mesh && typeof mesh.getWorldPosition === "function") {
    const resolvedWorldPosition = mesh.getWorldPosition(new THREE.Vector3());
    worldPosition = {
      x: Number(resolvedWorldPosition?.x ?? 0) || 0,
      y: Number(resolvedWorldPosition?.y ?? 0) || 0,
      z: Number(resolvedWorldPosition?.z ?? 0) || 0,
    };
  }
  const positionSource = useAuthoritative
    ? (worldPosition ?? motionState?.authoritativePosition ?? entry?.position ?? motionState?.renderPosition ?? mesh?.position ?? null)
    : (worldPosition ?? motionState?.renderPosition ?? mesh?.position ?? motionState?.authoritativePosition ?? entry?.position ?? null);
  const velocitySource = useAuthoritative
    ? (motionState?.authoritativeVelocity ?? entry?.velocity ?? motionState?.renderVelocity ?? null)
    : (motionState?.renderVelocity ?? entry?.velocity ?? motionState?.authoritativeVelocity ?? null);
  return {
    mesh,
    motionState,
    position: {
      x: Number(positionSource?.x ?? mesh?.position?.x ?? entry?.position?.x ?? 0) || 0,
      y: Number(positionSource?.y ?? mesh?.position?.y ?? entry?.position?.y ?? 0) || 0,
      z: Number(positionSource?.z ?? mesh?.position?.z ?? entry?.position?.z ?? 0) || 0,
    },
    velocity: {
      x: Number(velocitySource?.x ?? entry?.velocity?.x ?? 0) || 0,
      y: Number(velocitySource?.y ?? entry?.velocity?.y ?? 0) || 0,
      z: Number(velocitySource?.z ?? entry?.velocity?.z ?? 0) || 0,
    },
  };
}

function getPrivatePrefabInstanceMotionSample(entry = null, options = {}) {
  const baseSample = getPrivateDynamicEntryMotionSample(entry, options);
  const mesh = baseSample.mesh ?? null;
  const resolvedRotation = (() => {
    if (options.worldSpace === true && mesh && typeof mesh.getWorldQuaternion === "function") {
      const quaternion = mesh.getWorldQuaternion(new THREE.Quaternion());
      const euler = new THREE.Euler().setFromQuaternion(quaternion, "XYZ");
      return {
        x: Number(euler.x) || 0,
        y: Number(euler.y) || 0,
        z: Number(euler.z) || 0,
      };
    }
    return {
      x: Number(mesh?.rotation?.x ?? entry?.rotation?.x ?? 0) || 0,
      y: Number(mesh?.rotation?.y ?? entry?.rotation?.y ?? 0) || 0,
      z: Number(mesh?.rotation?.z ?? entry?.rotation?.z ?? 0) || 0,
    };
  })();
  const resolvedScale = (() => {
    if (options.worldSpace === true && mesh && typeof mesh.getWorldScale === "function") {
      const scale = mesh.getWorldScale(new THREE.Vector3());
      return {
        x: Number(scale?.x ?? 1) || 1,
        y: Number(scale?.y ?? 1) || 1,
        z: Number(scale?.z ?? 1) || 1,
      };
    }
    return {
      x: Number(mesh?.scale?.x ?? entry?.scale?.x ?? 1) || 1,
      y: Number(mesh?.scale?.y ?? entry?.scale?.y ?? 1) || 1,
      z: Number(mesh?.scale?.z ?? entry?.scale?.z ?? 1) || 1,
    };
  })();
  return {
    ...baseSample,
    rotation: resolvedRotation,
    scale: resolvedScale,
  };
}

function multiplyPrivateScale3(left = {}, right = {}) {
  return {
    x: (Number(left?.x ?? 1) || 1) * (Number(right?.x ?? 1) || 1),
    y: (Number(left?.y ?? 1) || 1) * (Number(right?.y ?? 1) || 1),
    z: (Number(left?.z ?? 1) || 1) * (Number(right?.z ?? 1) || 1),
  };
}

function addPrivateEuler3(left = {}, right = {}) {
  return {
    x: (Number(left?.x ?? 0) || 0) + (Number(right?.x ?? 0) || 0),
    y: (Number(left?.y ?? 0) || 0) + (Number(right?.y ?? 0) || 0),
    z: (Number(left?.z ?? 0) || 0) + (Number(right?.z ?? 0) || 0),
  };
}

function rotatePrivatePointByEuler(point = {}, rotation = {}) {
  let x = Number(point?.x ?? 0) || 0;
  let y = Number(point?.y ?? 0) || 0;
  let z = Number(point?.z ?? 0) || 0;
  const rx = Number(rotation?.x ?? 0) || 0;
  const ry = Number(rotation?.y ?? 0) || 0;
  const rz = Number(rotation?.z ?? 0) || 0;
  const cosX = Math.cos(rx);
  const sinX = Math.sin(rx);
  const cosY = Math.cos(ry);
  const sinY = Math.sin(ry);
  const cosZ = Math.cos(rz);
  const sinZ = Math.sin(rz);

  let nextY = y * cosX - z * sinX;
  let nextZ = y * sinX + z * cosX;
  y = nextY;
  z = nextZ;

  let nextX = x * cosY + z * sinY;
  nextZ = -x * sinY + z * cosY;
  x = nextX;
  z = nextZ;

  nextX = x * cosZ - y * sinZ;
  nextY = x * sinZ + y * cosZ;
  x = nextX;
  y = nextY;

  return { x, y, z };
}

function transformPrivatePrefabPosition(localPosition = {}, parentTransform = {}) {
  const scaled = {
    x: (Number(localPosition?.x ?? 0) || 0) * (Number(parentTransform?.scale?.x ?? 1) || 1),
    y: (Number(localPosition?.y ?? 0) || 0) * (Number(parentTransform?.scale?.y ?? 1) || 1),
    z: (Number(localPosition?.z ?? 0) || 0) * (Number(parentTransform?.scale?.z ?? 1) || 1),
  };
  const rotated = rotatePrivatePointByEuler(scaled, parentTransform.rotation);
  return {
    x: rotated.x + (Number(parentTransform?.position?.x ?? 0) || 0),
    y: rotated.y + (Number(parentTransform?.position?.y ?? 0) || 0),
    z: rotated.z + (Number(parentTransform?.position?.z ?? 0) || 0),
  };
}

function getRuntimePrefabTransformState(sceneInstance = {}, runtimeInstance = null) {
  const motionSample = runtimeInstance
    ? getPrivatePrefabInstanceMotionSample(runtimeInstance, { worldSpace: true })
    : null;
  return {
    id: String(runtimeInstance?.id ?? sceneInstance?.id ?? "").trim(),
    entry: runtimeInstance ?? sceneInstance,
    position: motionSample?.position ?? {
      x: Number(sceneInstance?.position?.x ?? 0) || 0,
      y: Number(sceneInstance?.position?.y ?? 0) || 0,
      z: Number(sceneInstance?.position?.z ?? 0) || 0,
    },
    rotation: motionSample?.rotation ?? {
      x: Number(sceneInstance?.rotation?.x ?? 0) || 0,
      y: Number(sceneInstance?.rotation?.y ?? 0) || 0,
      z: Number(sceneInstance?.rotation?.z ?? 0) || 0,
    },
    scale: motionSample?.scale ?? {
      x: Number(sceneInstance?.scale?.x ?? 1) || 1,
      y: Number(sceneInstance?.scale?.y ?? 1) || 1,
      z: Number(sceneInstance?.scale?.z ?? 1) || 1,
    },
    velocity: motionSample?.velocity ?? {
      x: Number(runtimeInstance?.velocity?.x ?? 0) || 0,
      y: Number(runtimeInstance?.velocity?.y ?? 0) || 0,
      z: Number(runtimeInstance?.velocity?.z ?? 0) || 0,
    },
  };
}

function visitRenderablePrefabCollisionEntries(sceneDoc = null, runtime = null, visitor = () => {}, options = {}) {
  if (!sceneDoc || typeof visitor !== "function") {
    return;
  }
  const runtimeSceneId = String(runtime?.active_scene_id ?? "").trim();
  const selectedSceneId = String(state.selectedSceneId ?? "").trim();
  const runtimeMatchesSelectedScene = Boolean(runtime && runtimeSceneId && runtimeSceneId === selectedSceneId);
  const runtimePrefabById = new Map((runtime?.prefab_instances ?? []).map((entry) => [String(entry?.id ?? "").trim(), entry]));
  const recursePrefabDocument = (prefabDoc = {}, parentState, visitedPrefabIds = new Set()) => {
    for (const voxel of prefabDoc.voxels ?? []) {
      visitor({
        kind: "voxel",
        entry: {
          ...voxel,
          position: transformPrivatePrefabPosition(voxel.position, parentState),
          rotation: addPrivateEuler3(voxel.rotation, parentState.rotation),
          scale: multiplyPrivateScale3(voxel.scale ?? { x: 1, y: 1, z: 1 }, parentState.scale),
        },
        parent: parentState,
        velocity: parentState.velocity,
      });
    }
    for (const primitive of prefabDoc.primitives ?? []) {
      visitor({
        kind: "primitive",
        entry: {
          ...primitive,
          position: transformPrivatePrefabPosition(primitive.position, parentState),
          rotation: addPrivateEuler3(primitive.rotation, parentState.rotation),
          scale: multiplyPrivateScale3(primitive.scale ?? { x: 1, y: 1, z: 1 }, parentState.scale),
        },
        parent: parentState,
        velocity: parentState.velocity,
      });
    }
    for (const model of prefabDoc.models ?? []) {
      const scale = multiplyPrivateScale3(model.scale ?? { x: 1, y: 1, z: 1 }, parentState.scale);
      const bounds = model.bounds ?? { x: 1, y: 1, z: 1 };
      visitor({
        kind: "model",
        entry: {
          ...model,
          position: transformPrivatePrefabPosition(model.position, parentState),
          rotation: addPrivateEuler3(model.rotation, parentState.rotation),
          scale,
          collider_scale: {
            x: (Number(scale?.x ?? 1) || 1) * (Number(bounds?.x ?? 1) || 1),
            y: (Number(scale?.y ?? 1) || 1) * (Number(bounds?.y ?? 1) || 1),
            z: (Number(scale?.z ?? 1) || 1) * (Number(bounds?.z ?? 1) || 1),
          },
        },
        parent: parentState,
        velocity: parentState.velocity,
      });
    }
    for (const nestedInstance of prefabDoc.prefab_instances ?? []) {
      if (nestedInstance?.overrides?.visible === false) {
        continue;
      }
      const nestedPrefabId = String(nestedInstance?.prefab_id ?? "").trim();
      if (!nestedPrefabId || visitedPrefabIds.has(nestedPrefabId)) {
        continue;
      }
      const nestedPrefab = getSelectedPrefabEntry(nestedPrefabId);
      if (!nestedPrefab?.prefab_doc) {
        continue;
      }
      const nestedParentState = {
        id: parentState.id,
        entry: parentState.entry,
        position: transformPrivatePrefabPosition(nestedInstance.position, parentState),
        rotation: addPrivateEuler3(nestedInstance.rotation, parentState.rotation),
        scale: multiplyPrivateScale3(nestedInstance.scale ?? { x: 1, y: 1, z: 1 }, parentState.scale),
        velocity: parentState.velocity,
      };
      recursePrefabDocument(
        nestedPrefab.prefab_doc ?? {},
        nestedParentState,
        new Set([...visitedPrefabIds, nestedPrefabId]),
      );
    }
  };
  for (const sceneInstance of sceneDoc.prefab_instances ?? []) {
    const prefabId = String(sceneInstance?.prefab_id ?? "").trim();
    if (!prefabId) {
      continue;
    }
    const prefab = getSelectedPrefabEntry(prefabId);
    if (!prefab?.prefab_doc) {
      continue;
    }
    const runtimeInstance = runtimeMatchesSelectedScene
      ? (runtimePrefabById.get(String(sceneInstance?.id ?? "").trim()) ?? null)
      : null;
    const parentState = getRuntimePrefabTransformState(sceneInstance, runtimeInstance);
    recursePrefabDocument(prefab.prefab_doc ?? {}, parentState, new Set([prefabId]));
  }
}

function getPrefabCarryPlatformStateById(sceneDoc = null, runtime = null, prefabInstanceId = "") {
  const resolvedPrefabInstanceId = String(prefabInstanceId ?? "").trim();
  if (!sceneDoc || !runtime || !resolvedPrefabInstanceId) {
    return null;
  }
  const runtimeEntry = (runtime.prefab_instances ?? []).find((entry) => String(entry?.id ?? "").trim() === resolvedPrefabInstanceId) ?? null;
  const sceneEntry = (sceneDoc.prefab_instances ?? []).find((entry) => String(entry?.id ?? "").trim() === resolvedPrefabInstanceId) ?? null;
  if (!runtimeEntry && !sceneEntry) {
    return null;
  }
  const parentState = getRuntimePrefabTransformState(sceneEntry ?? runtimeEntry, runtimeEntry);
  let aggregateHalf = null;
  let highestSurfaceY = Number.NEGATIVE_INFINITY;
  visitRenderablePrefabCollisionEntries(sceneDoc, runtime, (candidate) => {
    if (String(candidate?.parent?.id ?? "").trim() !== resolvedPrefabInstanceId) {
      return;
    }
    if (
      (candidate.kind !== "primitive" && candidate.kind !== "model")
      || candidate.entry?.physics?.carry_riders !== true
      || !isPrivateCollisionModeRigid(candidate.entry?.rigid_mode)
    ) {
      return;
    }
    const size = getPrivateCollisionEntrySize(candidate.kind, candidate.entry);
    const envelope = getPrivateCollisionSupportEnvelope(candidate.entry.position, size, candidate.entry.rotation);
    highestSurfaceY = Math.max(highestSurfaceY, Number(envelope.surfaceY ?? Number.NEGATIVE_INFINITY));
    const offsetHalf = {
      x: Math.abs((Number(envelope.position?.x ?? 0) || 0) - parentState.position.x) + envelope.half.x,
      y: Math.abs((Number(envelope.position?.y ?? 0) || 0) - parentState.position.y) + envelope.half.y,
      z: Math.abs((Number(envelope.position?.z ?? 0) || 0) - parentState.position.z) + envelope.half.z,
    };
    aggregateHalf = aggregateHalf
      ? {
          x: Math.max(aggregateHalf.x, offsetHalf.x),
          y: Math.max(aggregateHalf.y, offsetHalf.y),
          z: Math.max(aggregateHalf.z, offsetHalf.z),
        }
      : offsetHalf;
  });
  if (!aggregateHalf) {
    return null;
  }
  return {
    entry: parentState.entry,
    entryId: resolvedPrefabInstanceId,
    position: parentState.position,
    velocity: parentState.velocity,
    size: {
      x: aggregateHalf.x * 2,
      y: aggregateHalf.y * 2,
      z: aggregateHalf.z * 2,
    },
    half: aggregateHalf,
    surfaceY: Number.isFinite(highestSurfaceY) ? highestSurfaceY : parentState.position.y + aggregateHalf.y,
  };
}

function getPrivatePossessedSupportSurfaces(prediction, desiredPosition = prediction?.position) {
  if (!prediction || !isPrivateCollisionModeRigid(prediction.bodyMode)) {
    return [];
  }
  const playerSize = getPrivatePlayerCollisionSize(prediction.scale);
  const probe = buildPrivateCollisionProbe(prediction.position, desiredPosition, playerSize);
  const surfaces = [];
  let sceneDoc = null;
  try {
    sceneDoc = getRenderableSceneDoc();
  } catch (_error) {
    sceneDoc = null;
  }

  for (const voxel of sceneDoc?.voxels ?? []) {
    addPrivateSupportSurface(surfaces, {
      position: voxel.position,
      size: getPrivateCollisionEntrySize("voxel", voxel),
      rotation: voxel.rotation,
    }, probe);
  }

  const runtime = state.runtimeSnapshot ?? state.selectedWorld?.active_instance?.runtime ?? null;
  const runtimeSceneId = String(runtime?.active_scene_id ?? "").trim();
  const selectedSceneId = String(state.selectedSceneId ?? "").trim();
  const runtimeMatchesSelectedScene = Boolean(runtime && runtimeSceneId && runtimeSceneId === selectedSceneId);
  const runtimeDynamicIds = new Set();

  if (runtimeMatchesSelectedScene) {
    for (const entry of runtime.dynamic_objects ?? []) {
      const entryId = String(entry?.id ?? "").trim();
      if (entryId) {
        runtimeDynamicIds.add(entryId);
      }
      if (entry?.carry_riders !== true && !isPrivateCollisionModeRigid(entry?.rigid_mode)) {
        continue;
      }
      const kind = entry?.entity_kind === "model" ? "model" : "primitive";
      const motionSample = getPrivateDynamicEntryMotionSample(entry);
      addPrivateSupportSurface(surfaces, {
        position: motionSample.position,
        size: getPrivateCollisionEntrySize(kind, entry),
        rotation: entry.rotation,
        carry_riders: entry?.carry_riders === true,
        velocity: motionSample.velocity,
        entryId,
        entry,
      }, probe);
    }
  }

  for (const primitive of sceneDoc?.primitives ?? []) {
    const primitiveId = String(primitive?.id ?? "").trim();
    if (runtimeDynamicIds.has(primitiveId)) {
      continue;
    }
    if (primitive?.physics?.carry_riders !== true && !isPrivateCollisionModeRigid(primitive?.rigid_mode)) {
      continue;
    }
    addPrivateSupportSurface(surfaces, {
      position: primitive.position,
      size: getPrivateCollisionEntrySize("primitive", primitive),
      rotation: primitive.rotation,
      carry_riders: primitive?.physics?.carry_riders === true,
      entryId: primitiveId,
      entry: primitive,
    }, probe);
  }

  for (const model of sceneDoc?.models ?? []) {
    const modelId = String(model?.id ?? "").trim();
    if (runtimeDynamicIds.has(modelId)) {
      continue;
    }
    if (model?.physics?.carry_riders !== true && !isPrivateCollisionModeRigid(model?.rigid_mode)) {
      continue;
    }
    addPrivateSupportSurface(surfaces, {
      position: model.position,
      size: getPrivateCollisionEntrySize("model", model),
      rotation: model.rotation,
      carry_riders: model?.physics?.carry_riders === true,
      entryId: modelId,
      entry: model,
    }, probe);
  }

  visitRenderablePrefabCollisionEntries(sceneDoc, runtime, ({ kind, entry, parent, velocity }) => {
    if (kind === "voxel") {
      addPrivateSupportSurface(surfaces, {
        position: entry.position,
        size: getPrivateCollisionEntrySize("voxel", entry),
        rotation: entry.rotation,
      }, probe);
      return;
    }
    if ((kind !== "primitive" && kind !== "model") || (entry?.physics?.carry_riders !== true && !isPrivateCollisionModeRigid(entry?.rigid_mode))) {
      return;
    }
    addPrivateSupportSurface(surfaces, {
      position: entry.position,
      size: getPrivateCollisionEntrySize(kind, entry),
      rotation: entry.rotation,
      carry_riders: entry?.physics?.carry_riders === true,
      velocity,
      anchorPosition: parent?.position ?? entry.position,
      entryId: parent?.id ?? entry.id,
      entry: parent?.entry ?? entry,
    }, probe);
  });

  return surfaces;
}

function getLocalCarryPlatformSupport(playerLike = null) {
  if (!playerLike?.position) {
    return null;
  }
  const runtime = state.runtimeSnapshot ?? state.selectedWorld?.active_instance?.runtime ?? null;
  if (!runtime) {
    return null;
  }
  const playerScale = Math.max(
    0.25,
    Number(playerLike.scale ?? PRIVATE_PLAYER_DEFAULT_SCALE) || PRIVATE_PLAYER_DEFAULT_SCALE,
  );
  const playerSize = getPrivatePlayerCollisionSize(playerScale);
  const playerHalf = getHalfExtentsFromScale(playerSize);
  const playerPosition = {
    x: Number(playerLike.position?.x ?? 0) || 0,
    y: Number(playerLike.position?.y ?? 0) || 0,
    z: Number(playerLike.position?.z ?? 0) || 0,
  };
  let sceneDoc = null;
  try {
    sceneDoc = getRenderableSceneDoc();
  } catch (_error) {
    sceneDoc = null;
  }
  const playerBottom = playerPosition.y - playerHalf.y;
  let bestSupport = null;
  for (const entry of runtime.dynamic_objects ?? []) {
    if (entry?.carry_riders !== true) {
      continue;
    }
    const entryId = String(entry?.id ?? "").trim();
    const kind = entry?.entity_kind === "model" ? "model" : "primitive";
    const size = getPrivateCollisionEntrySize(kind, entry);
    const motionSample = getPrivateDynamicEntryMotionSample(entry);
    const envelope = getPrivateCollisionSupportEnvelope(motionSample.position, size, entry.rotation);
    const position = envelope.position;
    const half = envelope.half;
    const supportSample = samplePrivateCollisionSupportSurface(
      motionSample.position,
      size,
      entry.rotation,
      playerPosition,
      {
        x: playerHalf.x + PRIVATE_PLATFORM_CARRY_HORIZONTAL_BUFFER,
        z: playerHalf.z + PRIVATE_PLATFORM_CARRY_HORIZONTAL_BUFFER,
      },
    );
    if (!supportSample) {
      continue;
    }
    const velocity = motionSample.velocity;
    const platformTop = supportSample.surfaceY;
    const verticalGap = playerBottom - platformTop;
    const verticalTolerance = playerLike?.onGround === true
      ? getPrivatePlatformCarryRecoveryTolerance(playerHalf, half)
      : getPrivatePlatformCarryVerticalTolerance(playerHalf, half);
    if (
      verticalGap < -verticalTolerance
      || verticalGap > verticalTolerance
    ) {
      continue;
    }
    const limitX = half.x + playerHalf.x + PRIVATE_PLATFORM_CARRY_HORIZONTAL_BUFFER;
    const limitZ = half.z + playerHalf.z + PRIVATE_PLATFORM_CARRY_HORIZONTAL_BUFFER;
    if (
      Math.abs(playerPosition.x - position.x) > limitX
      || Math.abs(playerPosition.z - position.z) > limitZ
    ) {
      continue;
    }
    const absoluteGap = Math.abs(verticalGap);
    if (!bestSupport || absoluteGap < bestSupport.absoluteGap) {
      bestSupport = {
        entry,
        entryId,
        position,
        velocity,
        surfaceY: platformTop,
        supportedPlayerY: platformTop + playerHalf.y,
        verticalGap,
        absoluteGap,
      };
    }
  }
  visitRenderablePrefabCollisionEntries(sceneDoc, runtime, ({ kind, entry, parent, velocity }) => {
    if (
      (kind !== "primitive" && kind !== "model")
      || entry?.physics?.carry_riders !== true
      || !isPrivateCollisionModeRigid(entry?.rigid_mode)
    ) {
      return;
    }
    const size = getPrivateCollisionEntrySize(kind, entry);
    const envelope = getPrivateCollisionSupportEnvelope(entry.position, size, entry.rotation);
    const supportSample = samplePrivateCollisionSupportSurface(
      entry.position,
      size,
      entry.rotation,
      playerPosition,
      {
        x: playerHalf.x + PRIVATE_PLATFORM_CARRY_HORIZONTAL_BUFFER,
        z: playerHalf.z + PRIVATE_PLATFORM_CARRY_HORIZONTAL_BUFFER,
      },
    );
    if (!supportSample) {
      return;
    }
    const platformTop = supportSample.surfaceY;
    const verticalGap = playerBottom - platformTop;
    const verticalTolerance = playerLike?.onGround === true
      ? getPrivatePlatformCarryRecoveryTolerance(playerHalf, envelope.half)
      : getPrivatePlatformCarryVerticalTolerance(playerHalf, envelope.half);
    if (verticalGap < -verticalTolerance || verticalGap > verticalTolerance) {
      return;
    }
    const limitX = envelope.half.x + playerHalf.x + PRIVATE_PLATFORM_CARRY_HORIZONTAL_BUFFER;
    const limitZ = envelope.half.z + playerHalf.z + PRIVATE_PLATFORM_CARRY_HORIZONTAL_BUFFER;
    if (
      Math.abs(playerPosition.x - envelope.position.x) > limitX
      || Math.abs(playerPosition.z - envelope.position.z) > limitZ
    ) {
      return;
    }
    const absoluteGap = Math.abs(verticalGap);
    if (!bestSupport || absoluteGap < bestSupport.absoluteGap) {
      bestSupport = {
        entry: parent?.entry ?? entry,
        entryId: parent?.id ?? entry.id,
        position: parent?.position ?? entry.position,
        velocity: velocity ?? { x: 0, y: 0, z: 0 },
        surfaceY: platformTop,
        supportedPlayerY: platformTop + playerHalf.y,
        verticalGap,
        absoluteGap,
      };
    }
  });
  return bestSupport;
}

function getLocalCarryPlatformStateById(platformId = "") {
  const resolvedPlatformId = String(platformId ?? "").trim();
  if (!resolvedPlatformId) {
    return null;
  }
  const runtime = state.runtimeSnapshot ?? state.selectedWorld?.active_instance?.runtime ?? null;
  if (!runtime) {
    return null;
  }
  let sceneDoc = null;
  try {
    sceneDoc = getRenderableSceneDoc();
  } catch (_error) {
    sceneDoc = null;
  }
  const entry = (runtime.dynamic_objects ?? []).find((candidate) => {
    if (candidate?.carry_riders !== true) {
      return false;
    }
    return String(candidate?.id ?? "").trim() === resolvedPlatformId;
  }) ?? null;
  if (!entry) {
    return getPrefabCarryPlatformStateById(sceneDoc, runtime, resolvedPlatformId);
  }
  const entryId = String(entry?.id ?? "").trim();
  const kind = entry?.entity_kind === "model" ? "model" : "primitive";
  const size = getPrivateCollisionEntrySize(kind, entry);
  const motionSample = getPrivateDynamicEntryMotionSample(entry);
  const envelope = getPrivateCollisionSupportEnvelope(motionSample.position, size, entry.rotation);
  const position = envelope.position;
  const velocity = motionSample.velocity;
  return {
    entry,
    entryId,
    position,
    velocity,
    size,
    half: envelope.half,
    surfaceY: envelope.surfaceY,
  };
}

function getRememberedCarryPlatformSupport(prediction = null) {
  if (!prediction || !isPrivateCollisionModeRigid(prediction.bodyMode)) {
    return null;
  }
  const platformState = getLocalCarryPlatformStateById(prediction.localCarryPlatformId);
  if (!platformState) {
    return null;
  }
  const playerHalf = getHalfExtentsFromScale(getPrivatePlayerCollisionSize(prediction.scale));
  const carryOffset = prediction.localCarryPlatformOffset;
  const relativeX = Number.isFinite(Number(carryOffset?.x))
    ? Number(carryOffset.x)
    : ((Number(prediction.position?.x ?? 0) || 0) - platformState.position.x);
  const relativeZ = Number.isFinite(Number(carryOffset?.z))
    ? Number(carryOffset.z)
    : ((Number(prediction.position?.z ?? 0) || 0) - platformState.position.z);
  const limitX = platformState.half.x + playerHalf.x + PRIVATE_PLATFORM_CARRY_HORIZONTAL_BUFFER;
  const limitZ = platformState.half.z + playerHalf.z + PRIVATE_PLATFORM_CARRY_HORIZONTAL_BUFFER;
  if (Math.abs(relativeX) > limitX || Math.abs(relativeZ) > limitZ) {
    return null;
  }
  const fallbackSupportSample = samplePrivateCollisionSupportSurface(
    platformState.position,
    platformState.size,
    platformState.entry?.rotation,
    {
      x: platformState.position.x + relativeX,
      z: platformState.position.z + relativeZ,
    },
    {
      x: playerHalf.x + PRIVATE_PLATFORM_CARRY_HORIZONTAL_BUFFER,
      z: playerHalf.z + PRIVATE_PLATFORM_CARRY_HORIZONTAL_BUFFER,
    },
  );
  const supportedPlayerY = Number.isFinite(Number(carryOffset?.y))
    ? (platformState.position.y + Number(carryOffset.y))
    : ((Number(fallbackSupportSample?.surfaceY ?? platformState.surfaceY) || platformState.surfaceY) + playerHalf.y);
  return {
    entry: platformState.entry,
    entryId: platformState.entryId,
    position: platformState.position,
    velocity: platformState.velocity,
    surfaceY: platformState.surfaceY,
    supportedPlayerY,
    verticalGap: 0,
    absoluteGap: 0,
  };
}

function applyLocalCarryPlatformDelta(prediction = null) {
  if (!prediction || !isPrivateCollisionModeRigid(prediction.bodyMode)) {
    return null;
  }
  const platformState = getLocalCarryPlatformStateById(prediction.localCarryPlatformId);
  if (!platformState) {
    prediction.localCarryPlatformId = "";
    prediction.localCarryPlatformPosition = null;
    prediction.localCarryPlatformOffset = null;
    return null;
  }
  const carryOffset = prediction.localCarryPlatformOffset;
  if (
    carryOffset
    && Number.isFinite(Number(carryOffset.x))
    && Number.isFinite(Number(carryOffset.y))
    && Number.isFinite(Number(carryOffset.z))
  ) {
    const targetX = platformState.position.x + Number(carryOffset.x);
    const targetY = platformState.position.y + Number(carryOffset.y);
    const targetZ = platformState.position.z + Number(carryOffset.z);
    prediction.position.x = targetX;
    prediction.position.y = targetY;
    prediction.position.z = targetZ;
    prediction.groundY = targetY;
  } else {
    const previousPosition = prediction.localCarryPlatformPosition;
    if (
      previousPosition
      && Number.isFinite(Number(previousPosition.x))
      && Number.isFinite(Number(previousPosition.y))
      && Number.isFinite(Number(previousPosition.z))
    ) {
      const deltaX = platformState.position.x - Number(previousPosition.x);
      const deltaY = platformState.position.y - Number(previousPosition.y);
      const deltaZ = platformState.position.z - Number(previousPosition.z);
      if (
        Math.abs(deltaX) > PRIVATE_PLATFORM_CARRY_DELTA_EPSILON
        || Math.abs(deltaY) > PRIVATE_PLATFORM_CARRY_DELTA_EPSILON
        || Math.abs(deltaZ) > PRIVATE_PLATFORM_CARRY_DELTA_EPSILON
      ) {
        prediction.position.x += deltaX;
        prediction.position.y += deltaY;
        prediction.position.z += deltaZ;
        if (Number.isFinite(Number(prediction.groundY))) {
          prediction.groundY = Number(prediction.groundY) + deltaY;
        }
      }
    }
  }
  prediction.localCarryPlatformPosition = {
    x: platformState.position.x,
    y: platformState.position.y,
    z: platformState.position.z,
  };
  return platformState;
}

function getLocalPossessedGroundSupport(prediction = null, options = {}) {
  if (!prediction || !isPrivateCollisionModeRigid(prediction.bodyMode)) {
    return {
      hasSupport: false,
      groundY: Number.NaN,
      velocityY: Number.NaN,
      carrySupport: null,
    };
  }
  const playerHalf = getHalfExtentsFromScale(getPrivatePlayerCollisionSize(prediction.scale));
  const supportVerticalTolerance = prediction.onGround === true
    ? getPrivatePlatformCarryRecoveryTolerance(playerHalf)
    : getPrivatePlatformCarryVerticalTolerance(playerHalf);
  const startPosition = options.startPosition ?? prediction.position;
  const desiredPosition = options.desiredPosition ?? prediction.position;
  const supportResult = resolvePlayerGroundSupport({
    startPosition,
    desiredPosition,
    playerSize: getPrivatePlayerCollisionSize(prediction.scale),
    blockers: getPrivatePossessedSupportSurfaces(prediction, desiredPosition),
    verticalTolerance: supportVerticalTolerance,
  });
  const activeCarryPlatformId = String(prediction.localCarryPlatformId ?? "").trim();
  const storedGroundY = Number(prediction.groundY);
  const baseGroundY = Number(prediction.baseGroundY);
  const stableGroundTolerance = Math.max(0.08, supportVerticalTolerance * 0.5);
  const allowStableGroundFallback = (
    !activeCarryPlatformId
    && Number.isFinite(storedGroundY)
    && Number.isFinite(baseGroundY)
    && Math.abs(storedGroundY - baseGroundY) <= stableGroundTolerance
  );
  let carrySupport = null;
  let groundY = Number.NaN;
  let resolvedHasSupport = false;
  let velocityY = 0;
  if (supportResult?.hasSupport) {
    groundY = Number(supportResult.groundY);
    resolvedHasSupport = Number.isFinite(groundY);
    if (supportResult.blocker?.carry_riders === true) {
      carrySupport = {
        entry: supportResult.blocker.entry ?? null,
        entryId: String(supportResult.blocker.entryId ?? "").trim(),
        position: supportResult.blocker.anchorPosition ?? supportResult.blocker.position ?? null,
        velocity: supportResult.blocker.velocity ?? null,
        surfaceY: Number(supportResult.surfaceY),
        supportedPlayerY: groundY,
        verticalGap: Number(supportResult.verticalGap),
        absoluteGap: Number(supportResult.absoluteGap),
      };
      velocityY = Number(carrySupport?.velocity?.y ?? 0) || 0;
    }
  } else {
    carrySupport = getRememberedCarryPlatformSupport(prediction);
    if (Number.isFinite(Number(carrySupport?.supportedPlayerY))) {
      groundY = Number(carrySupport.supportedPlayerY);
      resolvedHasSupport = true;
      velocityY = Number(carrySupport?.velocity?.y ?? 0) || 0;
    }
  }
  if (!resolvedHasSupport) {
    const projectedSurface = getPrivatePlayerProjectedShadowSurface({
      ...prediction,
      position: desiredPosition,
      onGround: prediction.onGround === true,
    }, {
      allowCurrentSurfaceFallback: allowStableGroundFallback,
    });
    const surfaceY = Number(projectedSurface?.surfaceY);
    if (Number.isFinite(surfaceY)) {
      groundY = surfaceY + playerHalf.y;
      resolvedHasSupport = true;
      if (!carrySupport && projectedSurface?.carrySupport?.entryId) {
        carrySupport = {
          ...projectedSurface.carrySupport,
          supportedPlayerY: groundY,
        };
        velocityY = Number(carrySupport?.velocity?.y ?? 0) || 0;
      }
    }
  }
  if (!resolvedHasSupport && allowStableGroundFallback) {
    const playerY = Number(desiredPosition?.y ?? prediction.position?.y);
    if (
      Number.isFinite(storedGroundY)
      && Number.isFinite(playerY)
      && Math.abs(playerY - storedGroundY) <= stableGroundTolerance
    ) {
      groundY = storedGroundY;
      resolvedHasSupport = true;
    }
  }
  return {
    hasSupport: resolvedHasSupport,
    groundY,
    velocityY,
    carrySupport,
  };
}

function getPrivatePlayerProjectedShadowSurface(playerLike = null, options = {}) {
  if (!playerLike?.position) {
    return null;
  }
  const allowCurrentSurfaceFallback = options?.allowCurrentSurfaceFallback !== false;
  const playerScale = Math.max(
    0.25,
    Number(playerLike.scale ?? PRIVATE_PLAYER_DEFAULT_SCALE) || PRIVATE_PLAYER_DEFAULT_SCALE,
  );
  const playerSize = getPrivatePlayerCollisionSize(playerScale);
  const playerHalf = getHalfExtentsFromScale(playerSize);
  const playerPosition = {
    x: Number(playerLike.position?.x ?? 0) || 0,
    y: Number(playerLike.position?.y ?? 0) || 0,
    z: Number(playerLike.position?.z ?? 0) || 0,
  };
  const playerBottom = playerPosition.y - playerHalf.y;
  const overlapRecovery = playerLike?.onGround === true;
  let bestSurface = null;
  const considerSurface = (position = {}, size = {}, rotation = {}, metadata = null) => {
    const envelope = getPrivateCollisionSupportEnvelope(position, size, rotation);
    const half = envelope.half;
    const supportSample = samplePrivateCollisionSupportSurface(position, size, rotation, playerPosition, {
      x: playerHalf.x,
      z: playerHalf.z,
    });
    if (!supportSample) {
      return;
    }
    const topY = supportSample.surfaceY;
    const verticalTolerance = overlapRecovery
      ? getPrivatePlatformCarryRecoveryTolerance(playerHalf, half)
      : getPrivatePlatformCarryVerticalTolerance(playerHalf, half);
    const overlapLiftTolerance = overlapRecovery
      ? Math.max(verticalTolerance, playerHalf.y * 0.22)
      : verticalTolerance;
    if (topY > playerBottom + overlapLiftTolerance) {
      return;
    }
    const limitX = half.x + playerHalf.x;
    const limitZ = half.z + playerHalf.z;
    if (
      Math.abs(playerPosition.x - envelope.position.x) > limitX
      || Math.abs(playerPosition.z - envelope.position.z) > limitZ
    ) {
      return;
    }
    if (!bestSurface || topY > bestSurface.surfaceY) {
      bestSurface = {
        surfaceY: topY,
        carrySupport: metadata?.carry_riders === true
          ? {
              entry: metadata?.entry ?? null,
              entryId: String(metadata?.entryId ?? "").trim(),
              position: metadata?.anchorPosition ?? {
                x: envelope.position.x,
                y: envelope.position.y,
                z: envelope.position.z,
              },
              velocity: {
                x: Number(metadata?.velocity?.x ?? 0) || 0,
                y: Number(metadata?.velocity?.y ?? 0) || 0,
                z: Number(metadata?.velocity?.z ?? 0) || 0,
              },
              surfaceY: topY,
              supportedPlayerY: topY + playerHalf.y,
              verticalGap: playerBottom - topY,
              absoluteGap: Math.abs(playerBottom - topY),
            }
          : null,
      };
    }
  };

  let sceneDoc = null;
  try {
    sceneDoc = getRenderableSceneDoc();
  } catch (_error) {
    sceneDoc = null;
  }

  for (const voxel of sceneDoc?.voxels ?? []) {
    considerSurface(voxel.position, getPrivateCollisionEntrySize("voxel", voxel), voxel.rotation);
  }

  const runtime = state.runtimeSnapshot ?? state.selectedWorld?.active_instance?.runtime ?? null;
  const runtimeSceneId = String(runtime?.active_scene_id ?? "").trim();
  const selectedSceneId = String(state.selectedSceneId ?? "").trim();
  const runtimeMatchesSelectedScene = Boolean(runtime && runtimeSceneId && runtimeSceneId === selectedSceneId);
  const runtimeDynamicIds = new Set();

  if (runtimeMatchesSelectedScene) {
    for (const entry of runtime.dynamic_objects ?? []) {
      const entryId = String(entry?.id ?? "").trim();
      if (entryId) {
        runtimeDynamicIds.add(entryId);
      }
      if (entry?.carry_riders !== true && !isPrivateCollisionModeRigid(entry?.rigid_mode)) {
        continue;
      }
      const kind = entry?.entity_kind === "model" ? "model" : "primitive";
      const motionSample = getPrivateDynamicEntryMotionSample(entry);
      considerSurface(
        motionSample.position,
        getPrivateCollisionEntrySize(kind, entry),
        entry.rotation,
        {
          carry_riders: entry?.carry_riders === true,
          velocity: motionSample.velocity,
          entryId,
          entry,
        },
      );
    }
  }

  for (const primitive of sceneDoc?.primitives ?? []) {
    const primitiveId = String(primitive?.id ?? "").trim();
    if (runtimeDynamicIds.has(primitiveId)) {
      continue;
    }
    if (primitive?.physics?.carry_riders !== true && !isPrivateCollisionModeRigid(primitive?.rigid_mode)) {
      continue;
    }
    considerSurface(primitive.position, getPrivateCollisionEntrySize("primitive", primitive), primitive.rotation, {
      carry_riders: primitive?.physics?.carry_riders === true,
      entryId: primitiveId,
      entry: primitive,
    });
  }

  for (const model of sceneDoc?.models ?? []) {
    const modelId = String(model?.id ?? "").trim();
    if (runtimeDynamicIds.has(modelId)) {
      continue;
    }
    if (model?.physics?.carry_riders !== true && !isPrivateCollisionModeRigid(model?.rigid_mode)) {
      continue;
    }
    considerSurface(model.position, getPrivateCollisionEntrySize("model", model), model.rotation, {
      carry_riders: model?.physics?.carry_riders === true,
      entryId: modelId,
      entry: model,
    });
  }

  visitRenderablePrefabCollisionEntries(sceneDoc, runtime, ({ kind, entry, parent, velocity }) => {
    if (kind === "voxel") {
      considerSurface(entry.position, getPrivateCollisionEntrySize("voxel", entry), entry.rotation);
      return;
    }
    if ((kind !== "primitive" && kind !== "model") || (entry?.physics?.carry_riders !== true && !isPrivateCollisionModeRigid(entry?.rigid_mode))) {
      return;
    }
    considerSurface(entry.position, getPrivateCollisionEntrySize(kind, entry), entry.rotation, {
      carry_riders: entry?.physics?.carry_riders === true,
      velocity: velocity ?? { x: 0, y: 0, z: 0 },
      entryId: parent?.id ?? entry.id,
      entry: parent?.entry ?? entry,
      anchorPosition: parent?.position ?? entry.position,
    });
  });

  if (!bestSurface && allowCurrentSurfaceFallback && playerLike?.onGround === true) {
    bestSurface = {
      surfaceY: playerBottom,
    };
  }
  return bestSurface;
}

function clampRenderablePlayerToSupportSurface(mesh, playerLike = {}) {
  if (!mesh) {
    return null;
  }
  const onGround = playerLike?.onGround === true || playerLike?.on_ground === true || mesh.userData.privateWorldPlayerOnGround === true;
  if (!onGround) {
    return null;
  }
  const resolvedScale = Math.max(0.25, Number(playerLike?.scale ?? mesh.scale?.x ?? 1) || 1);
  const playerHalf = getHalfExtentsFromScale(getPrivatePlayerCollisionSize(resolvedScale));
  const playerPosition = {
    x: Number(playerLike?.position?.x ?? mesh.position?.x ?? 0) || 0,
    y: Number(playerLike?.position?.y ?? mesh.position?.y ?? 0) || 0,
    z: Number(playerLike?.position?.z ?? mesh.position?.z ?? 0) || 0,
  };
  const supportSurface = getPrivatePlayerProjectedShadowSurface({
    ...playerLike,
    position: playerPosition,
    scale: resolvedScale,
    onGround: true,
  });
  const surfaceY = Number(supportSurface?.surfaceY);
  if (!Number.isFinite(surfaceY)) {
    return null;
  }
  const supportedY = surfaceY + playerHalf.y;
  if (playerPosition.y + 0.0001 >= supportedY) {
    return null;
  }
  mesh.position.y = supportedY;
  if (mesh.userData.privateWorldRuntimeTargetPosition) {
    mesh.userData.privateWorldRuntimeTargetPosition.y = Math.max(
      Number(mesh.userData.privateWorldRuntimeTargetPosition.y ?? supportedY) || supportedY,
      supportedY,
    );
  }
  const motionState = mesh.userData.privateWorldRuntimeMotionState;
  if (motionState?.renderPosition) {
    motionState.renderPosition.y = Math.max(Number(motionState.renderPosition.y ?? supportedY) || supportedY, supportedY);
    if (motionState.renderVelocity) {
      motionState.renderVelocity.y = Math.max(0, Number(motionState.renderVelocity.y ?? 0) || 0);
    }
  }
  return supportedY;
}

function getPrivatePossessedCollisionBlockers(prediction, desiredPosition = prediction?.position) {
  if (!prediction || !isPrivateCollisionModeRigid(prediction.bodyMode)) {
    return [];
  }
  const playerSize = getPrivatePlayerCollisionSize(prediction.scale);
  const probe = buildPrivateCollisionProbe(prediction.position, desiredPosition, playerSize);
  const blockers = [];
  let sceneDoc = null;
  try {
    sceneDoc = getRenderableSceneDoc();
  } catch (_error) {
    sceneDoc = null;
  }

  for (const voxel of sceneDoc?.voxels ?? []) {
    addPrivateCollisionBlocker(blockers, {
      position: voxel.position,
      size: getPrivateCollisionEntrySize("voxel", voxel),
      rotation: voxel.rotation,
    }, probe);
  }

  const runtime = state.runtimeSnapshot ?? state.selectedWorld?.active_instance?.runtime ?? null;
  const runtimeSceneId = String(runtime?.active_scene_id ?? "").trim();
  const selectedSceneId = String(state.selectedSceneId ?? "").trim();
  const runtimeMatchesSelectedScene = Boolean(runtime && runtimeSceneId && runtimeSceneId === selectedSceneId);
  const localPlayerId = String(prediction.playerId ?? getLocallyControlledPlayerEntityId() ?? "").trim();

  if (runtimeMatchesSelectedScene) {
    for (const entry of runtime.dynamic_objects ?? []) {
      if (!isPrivateCollisionModeRigid(entry?.rigid_mode) || entry?.carry_riders === true) {
        continue;
      }
      const kind = entry?.entity_kind === "model" ? "model" : "primitive";
      addPrivateCollisionBlocker(blockers, {
        position: entry.position,
        size: getPrivateCollisionEntrySize(kind, entry),
        rotation: entry.rotation,
      }, probe);
    }
    for (const entry of runtime.players ?? []) {
      const playerId = String(entry?.id ?? "").trim();
      if (!playerId || playerId === localPlayerId || !isPrivateCollisionModeRigid(entry?.body_mode)) {
        continue;
      }
      addPrivateCollisionBlocker(blockers, {
        position: entry.position,
        size: getPrivatePlayerCollisionSize(entry.scale),
        rotation: entry.rotation,
      }, probe);
    }
    visitRenderablePrefabCollisionEntries(sceneDoc, runtime, ({ kind, entry }) => {
      if (kind === "voxel") {
        addPrivateCollisionBlocker(blockers, {
          position: entry.position,
          size: getPrivateCollisionEntrySize("voxel", entry),
          rotation: entry.rotation,
        }, probe);
        return;
      }
      if ((kind !== "primitive" && kind !== "model") || !isPrivateCollisionModeRigid(entry?.rigid_mode) || entry?.physics?.carry_riders === true) {
        return;
      }
      addPrivateCollisionBlocker(blockers, {
        position: entry.position,
        size: getPrivateCollisionEntrySize(kind, entry),
        rotation: entry.rotation,
      }, probe);
    });
    return blockers;
  }

  for (const primitive of sceneDoc?.primitives ?? []) {
    if (!isPrivateCollisionModeRigid(primitive?.rigid_mode) || primitive?.physics?.carry_riders === true) {
      continue;
    }
    addPrivateCollisionBlocker(blockers, {
      position: primitive.position,
      size: getPrivateCollisionEntrySize("primitive", primitive),
      rotation: primitive.rotation,
    }, probe);
  }
  for (const model of sceneDoc?.models ?? []) {
    if (!isPrivateCollisionModeRigid(model?.rigid_mode) || model?.physics?.carry_riders === true) {
      continue;
    }
    addPrivateCollisionBlocker(blockers, {
      position: model.position,
      size: getPrivateCollisionEntrySize("model", model),
      rotation: model.rotation,
    }, probe);
  }
  const runtimePlayerIds = getRuntimePlayerIds();
  for (const player of sceneDoc?.players ?? []) {
    const playerId = resolvePrivatePlayerEntityId(player?.id, runtimePlayerIds) ?? String(player?.id ?? "").trim();
    if (!playerId || playerId === localPlayerId || !isPrivateCollisionModeRigid(player?.body_mode)) {
      continue;
    }
    addPrivateCollisionBlocker(blockers, {
      position: player.position,
      size: getPrivatePlayerCollisionSize(player.scale),
      rotation: player.rotation,
    }, probe);
  }
  visitRenderablePrefabCollisionEntries(sceneDoc, runtime, ({ kind, entry }) => {
    if (kind === "voxel") {
      addPrivateCollisionBlocker(blockers, {
        position: entry.position,
        size: getPrivateCollisionEntrySize("voxel", entry),
        rotation: entry.rotation,
      }, probe);
      return;
    }
    if ((kind !== "primitive" && kind !== "model") || !isPrivateCollisionModeRigid(entry?.rigid_mode) || entry?.physics?.carry_riders === true) {
      return;
    }
    addPrivateCollisionBlocker(blockers, {
      position: entry.position,
      size: getPrivateCollisionEntrySize(kind, entry),
      rotation: entry.rotation,
    }, probe);
  });
  return blockers;
}

function getPrivateDynamicObjectCollisionBlockers(objectId = "", objectSize = { x: 1, y: 1, z: 1 }, startPosition = {}, desiredPosition = startPosition) {
  const resolvedObjectId = String(objectId ?? "").trim();
  const probe = buildPrivateCollisionProbe(startPosition, desiredPosition, objectSize);
  const blockers = [];
  let sceneDoc = null;
  try {
    sceneDoc = getRenderableSceneDoc();
  } catch (_error) {
    sceneDoc = null;
  }

  for (const voxel of sceneDoc?.voxels ?? []) {
    addPrivateCollisionBlocker(blockers, {
      position: voxel.position,
      size: getPrivateCollisionEntrySize("voxel", voxel),
      rotation: voxel.rotation,
    }, probe);
  }

  const runtime = state.runtimeSnapshot ?? state.selectedWorld?.active_instance?.runtime ?? null;
  const runtimeSceneId = String(runtime?.active_scene_id ?? "").trim();
  const selectedSceneId = String(state.selectedSceneId ?? "").trim();
  const runtimeMatchesSelectedScene = Boolean(runtime && runtimeSceneId && runtimeSceneId === selectedSceneId);
  const localPlayerId = String(getLocallyControlledPlayerEntityId() ?? "").trim();

  if (runtimeMatchesSelectedScene) {
    for (const entry of runtime.dynamic_objects ?? []) {
      const entryId = String(entry?.id ?? "").trim();
      if (!entryId || entryId === resolvedObjectId || !isPrivateCollisionModeRigid(entry?.rigid_mode) || entry?.carry_riders === true) {
        continue;
      }
      const kind = entry?.entity_kind === "model" ? "model" : "primitive";
      addPrivateCollisionBlocker(blockers, {
        position: entry.position,
        size: getPrivateCollisionEntrySize(kind, entry),
        rotation: entry.rotation,
      }, probe);
    }
    for (const entry of runtime.players ?? []) {
      const playerId = String(entry?.id ?? "").trim();
      if (!playerId || playerId === localPlayerId || !isPrivateCollisionModeRigid(entry?.body_mode)) {
        continue;
      }
      addPrivateCollisionBlocker(blockers, {
        position: entry.position,
        size: getPrivatePlayerCollisionSize(entry.scale),
        rotation: entry.rotation,
      }, probe);
    }
    visitRenderablePrefabCollisionEntries(sceneDoc, runtime, ({ kind, entry, parent }) => {
      if (kind === "voxel") {
        addPrivateCollisionBlocker(blockers, {
          position: entry.position,
          size: getPrivateCollisionEntrySize("voxel", entry),
          rotation: entry.rotation,
        }, probe);
        return;
      }
      if ((kind !== "primitive" && kind !== "model") || !isPrivateCollisionModeRigid(entry?.rigid_mode) || entry?.physics?.carry_riders === true) {
        return;
      }
      if (String(parent?.id ?? "").trim() === resolvedObjectId) {
        return;
      }
      addPrivateCollisionBlocker(blockers, {
        position: entry.position,
        size: getPrivateCollisionEntrySize(kind, entry),
        rotation: entry.rotation,
      }, probe);
    });
    return blockers;
  }

  for (const primitive of sceneDoc?.primitives ?? []) {
    if (!isPrivateCollisionModeRigid(primitive?.rigid_mode) || primitive?.physics?.carry_riders === true) {
      continue;
    }
    addPrivateCollisionBlocker(blockers, {
      position: primitive.position,
      size: getPrivateCollisionEntrySize("primitive", primitive),
      rotation: primitive.rotation,
    }, probe);
  }
  for (const model of sceneDoc?.models ?? []) {
    if (!isPrivateCollisionModeRigid(model?.rigid_mode) || model?.physics?.carry_riders === true) {
      continue;
    }
    addPrivateCollisionBlocker(blockers, {
      position: model.position,
      size: getPrivateCollisionEntrySize("model", model),
      rotation: model.rotation,
    }, probe);
  }
  const runtimePlayerIds = getRuntimePlayerIds();
  for (const player of sceneDoc?.players ?? []) {
    const playerId = resolvePrivatePlayerEntityId(player?.id, runtimePlayerIds) ?? String(player?.id ?? "").trim();
    if (!playerId || playerId === localPlayerId || !isPrivateCollisionModeRigid(player?.body_mode)) {
      continue;
    }
    addPrivateCollisionBlocker(blockers, {
      position: player.position,
      size: getPrivatePlayerCollisionSize(player.scale),
      rotation: player.rotation,
    }, probe);
  }
  visitRenderablePrefabCollisionEntries(sceneDoc, runtime, ({ kind, entry, parent }) => {
    if (kind === "voxel") {
      addPrivateCollisionBlocker(blockers, {
        position: entry.position,
        size: getPrivateCollisionEntrySize("voxel", entry),
        rotation: entry.rotation,
      }, probe);
      return;
    }
    if ((kind !== "primitive" && kind !== "model") || !isPrivateCollisionModeRigid(entry?.rigid_mode) || entry?.physics?.carry_riders === true) {
      return;
    }
    if (String(parent?.id ?? "").trim() === resolvedObjectId) {
      return;
    }
    addPrivateCollisionBlocker(blockers, {
      position: entry.position,
      size: getPrivateCollisionEntrySize(kind, entry),
      rotation: entry.rotation,
    }, probe);
  });
  return blockers;
}

function stepPossessedPlayerPrediction(deltaSeconds = 0) {
  const runtimePlayer = getPossessedRuntimePlayer();
  const prediction = ensurePossessedPlayerPrediction(runtimePlayer);
  if (!prediction || !runtimePlayer) {
    return null;
  }
  const scriptConfig = getActivePrivateWorldScriptConfig();
  const moveSpeed = getPlayerMoveSpeed(runtimePlayer, { scriptConfig });
  const sprintSpeed = getPlayerSprintSpeed(runtimePlayer, { scriptConfig });
  const acceleration = getPlayerAcceleration(runtimePlayer, { scriptConfig });
  const deceleration = getPlayerDeceleration(runtimePlayer, { scriptConfig });
  const airControl = getPlayerAirControl(runtimePlayer, { scriptConfig });
  const jumpVelocity = getPlayerJumpVelocity(runtimePlayer, { scriptConfig });
  const gravity = getPlayerGravityMagnitude(runtimePlayer, { scriptConfig });
  const maxFallSpeed = getPlayerMaxFallSpeed(runtimePlayer, { scriptConfig });
  const dt = clampNumber(deltaSeconds, 1 / 60, 0, 0.05);
  if (dt <= 0) {
    return prediction;
  }
  const frameStartPosition = {
    x: prediction.position.x,
    y: prediction.position.y,
    z: prediction.position.z,
  };
  const intent = buildRuntimeMovementIntent();
  const now = performance.now();
  const rigidBodyMode = isPrivateCollisionModeRigid(prediction.bodyMode);
  const jumpPulseSeq = Math.max(0, Number(state.runtimeJumpPulseSeq ?? 0) || 0);
  const jumpPulseAt = Math.max(0, Number(state.runtimeJumpPulseAt ?? 0) || 0);
  const jumpPulsePending = jumpPulseSeq > Math.max(0, Number(prediction.lastConsumedJumpPulseSeq ?? 0) || 0);
  const jumpPulseFresh = jumpPulsePending && (now - jumpPulseAt) <= PRIVATE_PLAYER_RUNTIME.jumpPulseMs;
  const speed = intent.sprint
    ? sprintSpeed
    : moveSpeed;
  const controlBlend = intent.active ? acceleration : deceleration;
  const controlScale = prediction.onGround ? 1 : airControl;
  const blend = clampNumber(controlBlend * dt * controlScale, 1, 0, 1);
  prediction.velocity.x += (intent.x * speed - prediction.velocity.x) * blend;
  prediction.velocity.z += (intent.z * speed - prediction.velocity.z) * blend;
  const preJumpLocalJumpActive = prediction.localJumpUntilMs > now
    || prediction.jumpVisualOffsetY > 0.0001
    || prediction.jumpVisualVelocityY > 0.0001;
  if (rigidBodyMode && !preJumpLocalJumpActive) {
    applyLocalCarryPlatformDelta(prediction);
  }
  const preJumpGroundSupport = rigidBodyMode && !preJumpLocalJumpActive
    ? getLocalPossessedGroundSupport(prediction, {
      startPosition: frameStartPosition,
      desiredPosition: prediction.position,
    })
    : null;
  if (
    rigidBodyMode
    && !preJumpLocalJumpActive
    && preJumpGroundSupport?.hasSupport
    && Number.isFinite(Number(preJumpGroundSupport.groundY))
  ) {
    prediction.groundY = Number(preJumpGroundSupport.groundY);
    prediction.position.y = Number(preJumpGroundSupport.groundY);
    prediction.velocity.y = Number.isFinite(Number(preJumpGroundSupport.velocityY))
      ? Number(preJumpGroundSupport.velocityY)
      : 0;
    prediction.onGround = true;
  } else if (rigidBodyMode && !preJumpLocalJumpActive) {
    prediction.onGround = false;
  }
  if (
    jumpPulseFresh
    && prediction.jumpEnabled
    && prediction.onGround
  ) {
    prediction.onGround = false;
    prediction.lastConsumedJumpPulseSeq = jumpPulseSeq;
    if (rigidBodyMode) {
      prediction.localJumpUntilMs = now + PRIVATE_PLAYER_RUNTIME.localJumpHoldMs;
      prediction.jumpVisualVelocityY = jumpVelocity;
      if (prediction.jumpVisualOffsetY <= 0.0001) {
        prediction.jumpVisualOffsetY = 0;
      }
    } else {
      prediction.localJumpUntilMs = now + PRIVATE_PLAYER_RUNTIME.localJumpHoldMs;
      prediction.velocity.y = jumpVelocity;
    }
  } else if (jumpPulsePending && !jumpPulseFresh) {
    prediction.lastConsumedJumpPulseSeq = jumpPulseSeq;
  }
  const localJumpActive = prediction.localJumpUntilMs > now
    || prediction.jumpVisualOffsetY > 0.0001
    || prediction.jumpVisualVelocityY > 0.0001;
  const desiredPosition = {
    x: prediction.position.x + prediction.velocity.x * dt,
    y: prediction.position.y,
    z: prediction.position.z + prediction.velocity.z * dt,
  };
  if (isPrivateCollisionModeRigid(prediction.bodyMode)) {
    const collision = resolvePlayerMovementAgainstBlockers({
      startPosition: {
        x: prediction.position.x,
        y: prediction.position.y,
        z: prediction.position.z,
      },
      desiredPosition,
      playerSize: getPrivatePlayerCollisionSize(prediction.scale),
      blockers: getPrivatePossessedCollisionBlockers(prediction, desiredPosition),
    });
    prediction.position.x = collision.position.x;
    prediction.position.z = collision.position.z;
  } else {
    prediction.position.x = desiredPosition.x;
    prediction.position.z = desiredPosition.z;
  }
  if (!rigidBodyMode) {
    if (!prediction.onGround || Math.abs(Number(prediction.velocity.y ?? 0) || 0) >= 0.05) {
      prediction.velocity.y -= gravity * dt;
      if (Number.isFinite(maxFallSpeed)) {
        prediction.velocity.y = Math.max(-maxFallSpeed, prediction.velocity.y);
      }
      prediction.position.y += prediction.velocity.y * dt;
      const groundY = Number(prediction.groundY ?? prediction.position.y);
      if (prediction.position.y <= groundY) {
        prediction.position.y = groundY;
        prediction.groundY = groundY;
        prediction.velocity.y = 0;
        prediction.onGround = true;
        prediction.localJumpUntilMs = 0;
      } else {
        prediction.onGround = false;
      }
    } else {
      const groundY = Number(prediction.groundY);
      if (Number.isFinite(groundY)) {
        prediction.groundY = groundY;
        prediction.position.y = groundY;
      }
      prediction.velocity.y = 0;
      prediction.onGround = true;
    }
    if (intent.active) {
      prediction.rotation.y = intent.headingY;
    }
    return prediction;
  }
  if (localJumpActive) {
    prediction.jumpVisualVelocityY -= gravity * dt;
    prediction.jumpVisualOffsetY = Math.max(
      0,
      prediction.jumpVisualOffsetY + prediction.jumpVisualVelocityY * dt,
    );
    if (
      prediction.localJumpUntilMs <= now
      && prediction.jumpVisualOffsetY <= 0.0001
      && prediction.jumpVisualVelocityY <= 0
    ) {
      resetPossessedPlayerJumpBridge(prediction);
    }
  }
  let currentJumpActive = prediction.localJumpUntilMs > now
    || prediction.jumpVisualOffsetY > 0.0001
    || prediction.jumpVisualVelocityY > 0.0001;
  const resolvedGroundSupport = !currentJumpActive
    ? getLocalPossessedGroundSupport(prediction, {
      startPosition: frameStartPosition,
      desiredPosition: prediction.position,
    })
    : null;
  let finalGroundSupport = resolvedGroundSupport;
  if (currentJumpActive) {
    const jumpBaseGroundY = Number.isFinite(Number(prediction.groundY))
      ? Number(prediction.groundY)
      : prediction.position.y;
    prediction.position.y = jumpBaseGroundY
      + Math.max(0, Number(prediction.jumpVisualOffsetY ?? 0) || 0);
    prediction.velocity.y = prediction.jumpVisualVelocityY;
    prediction.onGround = false;
    const descendingJumpSupport = prediction.jumpVisualVelocityY <= 0
      ? getLocalPossessedGroundSupport(prediction, {
        startPosition: frameStartPosition,
        desiredPosition: prediction.position,
      })
      : null;
    const jumpLandingGroundY = Number(descendingJumpSupport?.groundY);
    const jumpLandingGap = Number.isFinite(jumpLandingGroundY)
      ? ((Number(prediction.position.y ?? jumpLandingGroundY) || jumpLandingGroundY) - jumpLandingGroundY)
      : Number.POSITIVE_INFINITY;
    const jumpLandingSnapTolerance = Math.min(
      0.22,
      Math.max(
        0.05,
        Math.abs(Number(prediction.jumpVisualVelocityY ?? 0) || 0) * dt + 0.02,
      ),
    );
    if (
      descendingJumpSupport?.hasSupport === true
      && Number.isFinite(jumpLandingGroundY)
      && jumpLandingGap <= jumpLandingSnapTolerance
    ) {
      prediction.groundY = jumpLandingGroundY;
      prediction.position.y = jumpLandingGroundY;
      prediction.velocity.y = Number.isFinite(Number(descendingJumpSupport?.velocityY))
        ? Number(descendingJumpSupport.velocityY)
        : 0;
      prediction.onGround = true;
      resetPossessedPlayerJumpBridge(prediction);
      currentJumpActive = false;
      finalGroundSupport = descendingJumpSupport;
    } else {
      finalGroundSupport = null;
    }
  } else {
    const hasLocalSupport = resolvedGroundSupport?.hasSupport === true;
    const supportGroundY = Number(resolvedGroundSupport?.groundY);
    if (hasLocalSupport && Number.isFinite(supportGroundY)) {
      prediction.groundY = supportGroundY;
      prediction.position.y = supportGroundY;
      prediction.velocity.y = Number.isFinite(Number(resolvedGroundSupport?.velocityY))
        ? Number(resolvedGroundSupport.velocityY)
        : 0;
      prediction.onGround = true;
    } else {
      const airborneStartPosition = {
        x: prediction.position.x,
        y: prediction.position.y,
        z: prediction.position.z,
      };
      const baseVelocityY = Number(prediction.velocity.y ?? 0) || 0;
      const nextVelocityY = (prediction.onGround ? Math.min(0, baseVelocityY) : baseVelocityY)
        - gravity * dt;
      prediction.groundY = Number.NaN;
      prediction.velocity.y = nextVelocityY;
      prediction.position.y += nextVelocityY * dt;
      finalGroundSupport = getLocalPossessedGroundSupport(prediction, {
        startPosition: airborneStartPosition,
        desiredPosition: prediction.position,
      });
      const landingGroundY = Number(finalGroundSupport?.groundY);
      if (finalGroundSupport?.hasSupport === true && Number.isFinite(landingGroundY)) {
        prediction.groundY = landingGroundY;
        prediction.position.y = landingGroundY;
        prediction.velocity.y = Number.isFinite(Number(finalGroundSupport?.velocityY))
          ? Number(finalGroundSupport.velocityY)
          : 0;
        prediction.onGround = true;
      } else {
        const baseGroundY = Number(prediction.baseGroundY);
        if (Number.isFinite(baseGroundY) && prediction.position.y <= baseGroundY) {
          prediction.groundY = baseGroundY;
          prediction.position.y = baseGroundY;
          prediction.velocity.y = 0;
          prediction.onGround = true;
          finalGroundSupport = null;
        } else {
          prediction.onGround = false;
        }
      }
    }
  }
  if (!currentJumpActive && finalGroundSupport?.carrySupport?.entryId && prediction.onGround) {
    prediction.localCarryPlatformId = String(finalGroundSupport.carrySupport.entryId ?? "");
    prediction.localCarryPlatformPosition = {
      x: Number(finalGroundSupport.carrySupport.position?.x ?? prediction.position.x) || 0,
      y: Number(finalGroundSupport.carrySupport.position?.y ?? prediction.position.y) || 0,
      z: Number(finalGroundSupport.carrySupport.position?.z ?? prediction.position.z) || 0,
    };
    prediction.localCarryPlatformOffset = {
      x: prediction.position.x - (Number(finalGroundSupport.carrySupport.position?.x ?? 0) || 0),
      y: prediction.position.y - (Number(finalGroundSupport.carrySupport.position?.y ?? 0) || 0),
      z: prediction.position.z - (Number(finalGroundSupport.carrySupport.position?.z ?? 0) || 0),
    };
  } else if (currentJumpActive || !finalGroundSupport?.carrySupport || !prediction.onGround) {
    prediction.localCarryPlatformId = "";
    prediction.localCarryPlatformPosition = null;
    prediction.localCarryPlatformOffset = null;
  }
  if (intent.active) {
    prediction.rotation.y = intent.headingY;
  }
  return prediction;
}

function renderRuntimeStatusThrottled() {
  const now = performance.now();
  if (now - state.lastRuntimeStatusRenderedAt < PRIVATE_RUNTIME_STATUS_THROTTLE_MS) {
    return;
  }
  state.lastRuntimeStatusRenderedAt = now;
  renderRuntimeStatus();
}

function getRenderableSceneDoc() {
  const scene = getSelectedScene();
  if (!scene) {
    return null;
  }
  if (state.mode === "play") {
    return scene.compiled_doc?.runtime?.resolved_scene_doc ?? scene.scene_doc ?? null;
  }
  if (isEditor() && state.sceneEditorSceneId === String(scene.id ?? "").trim()) {
    try {
      return parseSceneTextarea();
    } catch (error) {
      if (state.mode === "build") {
        throw error;
      }
    }
  }
  return buildSceneDocFromDraft(scene, getSceneDraft(scene.id)) ?? scene.scene_doc ?? null;
}

function setMode(mode, options = {}) {
  const nextMode = mode === "build" && isEditor() ? "build" : "play";
  const previousMode = state.mode;
  state.mode = nextMode;
  if (previousMode === "play" && nextMode === "build" && state.pressedRuntimeKeys.size > 0) {
    const pressedKeys = [...state.pressedRuntimeKeys];
    state.pressedRuntimeKeys.clear();
    for (const key of pressedKeys) {
      void sendRuntimeInput(key, "up", {
        headingY: getRuntimeInputHeadingY(),
      });
    }
  }
  if (nextMode === "play") {
    state.buildModifierKeys.clear();
    endBuildDrag();
    state.buildSuppressedClick = null;
    clearPlacementTool();
    writeBuilderSelection([]);
    state.sceneDrawerOpen = false;
  }
  if (nextMode === "build") {
    if (previousMode === "play" && state.buildReturnSceneId) {
      const returnScene = state.selectedWorld?.scenes?.find((scene) => scene.id === state.buildReturnSceneId) ?? null;
      if (returnScene) {
        state.selectedSceneId = returnScene.id;
      }
    }
    for (const key of ["q", "e", "shift"]) {
      privateInputState.keys.delete(key);
    }
  }
  document.body.classList.toggle("is-play-mode", nextMode === "play");
  document.body.classList.toggle("is-build-mode", nextMode === "build");
  if (nextMode === "build") {
    refreshBuildHoverFromStoredPointer();
  }
  updateShellState();
  syncPrivatePreviewEnvironmentState();
  updatePreviewFromSelection();
}

function syncRuntimeFromWorld(world = state.selectedWorld) {
  const nextRuntime = world?.active_instance?.runtime ?? null;
  if (!nextRuntime) {
    if (
      !world?.active_instance
      || getRuntimeSnapshotWorldKey(world) !== String(state.runtimeSnapshotWorldKey ?? "").trim()
    ) {
      clearRuntimeSnapshot();
    }
    return;
  }
  const result = setRuntimeSnapshot(nextRuntime, {
    sourcePriority: PRIVATE_RUNTIME_SNAPSHOT_PRIORITY.worldDetail,
    worldKey: getRuntimeSnapshotWorldKey(world),
  });
  if (world?.active_instance) {
    world.active_instance.runtime = result.snapshot ?? null;
    if (result.snapshot?.status) {
      world.active_instance.status = result.snapshot.status;
    }
  }
}

function migrateLegacyPanelsInSceneDoc(sceneDoc = {}) {
  const nextSceneDoc = typeof sceneDoc === "object" && sceneDoc ? sceneDoc : {};
  const legacyPanels = Array.isArray(nextSceneDoc.panels) ? nextSceneDoc.panels : [];
  if (!legacyPanels.length) {
    return nextSceneDoc;
  }
  const convertedPanels = legacyPanels.map((panel, index) => ({
    id: panel?.id || `panel_${index + 1}`,
    label: String(panel?.label ?? `Panel ${index + 1}`).trim() || `Panel ${index + 1}`,
    shape: "panel",
    position: deepClone(panel?.position ?? { x: 0, y: 2, z: 0 }),
    rotation: deepClone(panel?.rotation ?? { x: 0, y: 0, z: 0 }),
    scale: deepClone(panel?.scale ?? { x: 4, y: 2.25, z: 0.1 }),
    material: deepClone(panel?.material ?? { color: "#f4f7fb", texture_preset: "none", emissive_intensity: 0 }),
    rigid_mode: String(panel?.rigid_mode ?? panel?.rigidMode ?? "ghost").trim().toLowerCase() === "rigid" ? "rigid" : "ghost",
    physics: deepClone(panel?.physics ?? { gravity_scale: 0, restitution: 0, friction: 0.7, mass: 0 }),
    facing_mode: normalizeFacingMode(panel?.facing_mode ?? panel?.facingMode),
    particle_effect: String(panel?.particle_effect ?? panel?.particleEffect ?? "").trim(),
    trail_effect: String(panel?.trail_effect ?? panel?.trailEffect ?? "").trim(),
    invisible: panel?.invisible === true,
    group_id: String(panel?.group_id ?? panel?.groupId ?? "").trim(),
  }));
  nextSceneDoc.primitives = [...convertedPanels, ...(Array.isArray(nextSceneDoc.primitives) ? nextSceneDoc.primitives : [])];
  nextSceneDoc.panels = [];
  return nextSceneDoc;
}

function parseSceneTextarea() {
  try {
    const sceneDoc = migrateLegacyPanelsInSceneDoc(JSON.parse(elements.sceneForm?.elements.sceneDoc.value || "{}"));
    if (elements.sceneForm?.elements.scriptDsl) {
      sceneDoc.script_dsl = String(elements.sceneForm.elements.scriptDsl.value || "").trim();
    }
    return sceneDoc;
  } catch (error) {
    throw new Error(`Scene JSON is invalid: ${error.message}`);
  }
}

function renderSceneEditor() {
  const scene = getSceneEditorScene();
  const canEdit = isEditor();
  const buildMode = state.mode === "build";
  const sceneId = String(scene?.id ?? "").trim();
  const draft = getSceneDraft(sceneId);
  const selectedScene = getSelectedScene();
  const selectedSceneId = String(selectedScene?.id ?? "").trim();
  const isFocusedSceneActive = Boolean(sceneId) && sceneId === selectedSceneId;
  let sceneDocForControls = buildEmptySceneDoc();
  if (!scene) {
    elements.sceneForm.elements.name.value = "";
    elements.sceneForm.elements.isDefault.checked = false;
    elements.sceneForm.elements.sceneDoc.value = "";
    elements.sceneForm.elements.scriptDsl.value = "";
    state.selectedScriptFunctionId = "";
    state.scriptFunctionQuery = "";
    state.sceneEditorSceneId = "";
  } else if (!draft || state.sceneEditorSceneId !== sceneId) {
    elements.sceneForm.elements.name.value = draft?.name ?? scene?.name ?? "";
    elements.sceneForm.elements.isDefault.checked = draft?.isDefault ?? scene?.is_default === true;
    elements.sceneForm.elements.sceneDoc.value = draft?.sceneDocText ?? JSON.stringify(scene.scene_doc ?? {}, null, 2);
    elements.sceneForm.elements.scriptDsl.value = draft?.scriptDslText ?? scene?.scene_doc?.script_dsl ?? "";
    state.selectedScriptFunctionId = "";
    state.scriptFunctionQuery = "";
    state.sceneEditorSceneId = sceneId;
  }
  try {
    sceneDocForControls = JSON.parse(elements.sceneForm.elements.sceneDoc.value || "{}");
  } catch (_error) {
    sceneDocForControls = scene?.scene_doc ?? buildEmptySceneDoc();
  }
  sceneDocForControls.script_dsl = String(elements.sceneForm.elements.scriptDsl.value || sceneDocForControls?.script_dsl || "");
  if (scene && canEdit && buildMode) {
    const materialized = materializeSceneLogicFunctions(sceneDocForControls, sceneDocForControls.script_dsl);
    if (materialized.changed) {
      sceneDocForControls.script_dsl = materialized.scriptDslText;
      const sceneDocText = JSON.stringify(sceneDocForControls, null, 2);
      elements.sceneForm.elements.scriptDsl.value = materialized.scriptDslText;
      elements.sceneForm.elements.sceneDoc.value = sceneDocText;
      rememberSceneDraft({
        sceneId,
        sceneDocText,
        scriptDslText: materialized.scriptDslText,
      });
    }
  }
  if (elements.sceneSwitchButton) {
    const canSwitchScene = Boolean(scene) && canEdit && buildMode && !isFocusedSceneActive;
    elements.sceneSwitchButton.hidden = !scene;
    elements.sceneSwitchButton.disabled = !canSwitchScene;
    elements.sceneSwitchButton.textContent = isFocusedSceneActive
      ? "Current editing scene"
      : "Switch to this scene";
  }
  elements.saveScene.disabled = !canEdit || !scene || !buildMode || !isFocusedSceneActive;
  elements.refreshScene.disabled = !scene;
  elements.sceneForm.elements.name.disabled = !canEdit || !buildMode || !isFocusedSceneActive;
  elements.sceneForm.elements.isDefault.disabled = !canEdit || !buildMode || !isFocusedSceneActive;
  elements.sceneForm.elements.sceneSkybox.disabled = !canEdit || !scene || !buildMode || !isFocusedSceneActive;
  elements.sceneForm.elements.sceneAmbientLight.disabled = !canEdit || !scene || !buildMode || !isFocusedSceneActive;
  elements.sceneForm.elements.scriptDsl.disabled = !canEdit || !buildMode || !isFocusedSceneActive;
  elements.sceneForm.elements.sceneDoc.disabled = !canEdit || !buildMode || !isFocusedSceneActive;
  renderSceneEnvironmentControls(sceneDocForControls);
  renderSceneLogicLibrary();
  const buildPanel = document.querySelector("[data-build-panel]");
  if (buildPanel) {
    buildPanel.hidden = false;
  }
  renderSceneBuilder();
}

function buildSceneLibrarySummary(scene = {}) {
  const stats = scene.compiled_doc?.stats ?? {};
  const entityCount =
    Number(stats.solid_voxel_count ?? 0)
    + Number(stats.primitive_count ?? 0)
    + Number(stats.panel_count ?? 0)
    + Number(stats.model_count ?? 0)
    + Number(stats.screen_count ?? 0)
    + Number(stats.player_count ?? 0)
    + Number(stats.text_count ?? 0)
    + Number(stats.trigger_zone_count ?? 0)
    + Number(stats.prefab_instance_count ?? 0);
  const ruleCount = Number(stats.dsl_rule_count ?? stats.rule_count ?? 0);
  const meta = [];
  meta.push(`${entityCount} item${entityCount === 1 ? "" : "s"}`);
  meta.push(`${ruleCount} rule${ruleCount === 1 ? "" : "s"}`);
  if (scene.is_default) {
    meta.push("default");
  }
  return meta.join(" · ");
}

function getSceneStatusLabel(scene = getSelectedScene()) {
  if (!scene) {
    return "none";
  }
  const activeRuntimeSceneId = state.selectedWorld?.active_instance?.active_scene_id || "";
  if (scene.id === activeRuntimeSceneId) {
    return "live";
  }
  if (scene.id === state.selectedSceneId) {
    return "editing";
  }
  if (scene.is_default) {
    return "default";
  }
  return "saved";
}

function renderSceneDrawerSceneIndicator(scene = getSceneDrawerFocusedScene()) {
  if (!elements.sceneDrawerSceneIndicator) {
    return;
  }
  if (!scene) {
    elements.sceneDrawerSceneIndicator.innerHTML = `
      <span>Scene Focus</span>
      <strong>No scene selected</strong>
      <small>Pick a scene from the Scenes tab.</small>
    `;
    return;
  }
  const activeRuntimeSceneId = String(state.selectedWorld?.active_instance?.active_scene_id ?? "").trim();
  const activeRuntimeScene = activeRuntimeSceneId
    ? (state.selectedWorld?.scenes ?? []).find((entry) => entry.id === activeRuntimeSceneId) ?? null
    : null;
  const selectedScene = getSelectedScene();
  const status = getSceneStatusLabel(scene);
  const statusNote = activeRuntimeScene && activeRuntimeScene.id !== scene.id
    ? `Live now: ${activeRuntimeScene.name || "Untitled Scene"}`
    : buildSceneLibrarySummary(scene);
  const editingNote = selectedScene && selectedScene.id !== scene.id
    ? `Editing in world: ${selectedScene.name || "Untitled Scene"}`
    : "";
  elements.sceneDrawerSceneIndicator.innerHTML = `
    <span>Scene Focus</span>
    <strong>${htmlEscape(scene.name || "Untitled Scene")}</strong>
    <small>${htmlEscape(status)} · ${htmlEscape(buildSceneLibrarySummary(scene))}</small>
    ${statusNote !== buildSceneLibrarySummary(scene) ? `<small>${htmlEscape(statusNote)}</small>` : ""}
    ${editingNote ? `<small>${htmlEscape(editingNote)}</small>` : ""}
  `;
}

function renderSceneLibrary() {
  if (!elements.sceneLibraryList) {
    return;
  }
  const scenes = state.selectedWorld?.scenes ?? [];
  if (elements.sceneLibraryHint) {
    elements.sceneLibraryHint.textContent = scenes.length
      ? `${buildSceneCountLabel(scenes.length)} ready. Pick one to review on the right, then switch only when you want the world to move there.`
      : "No scenes yet. Add one to start building a different room, level, or state.";
  }
  if (!scenes.length) {
    elements.sceneLibraryList.innerHTML = '<div class="pw-scene-library-item"><p class="pw-builder-empty">No scenes yet.</p></div>';
    return;
  }
  const activeRuntimeSceneId = state.selectedWorld?.active_instance?.active_scene_id || "";
  elements.sceneLibraryList.innerHTML = scenes.map((scene) => `
    <button
      type="button"
      class="pw-scene-library-item ${scene.id === state.sceneDrawerFocusId ? "is-active" : ""}"
      data-scene-library-id="${htmlEscape(scene.id)}"
    >
      <div class="pw-scene-library-item__head">
        <strong>${htmlEscape(scene.name)}</strong>
        <span>${scene.id === activeRuntimeSceneId ? "live" : scene.id === state.selectedSceneId ? "editing" : scene.is_default ? "default" : "saved"}</span>
      </div>
      <small>${htmlEscape(buildSceneLibrarySummary(scene))}</small>
    </button>
  `).join("");
}

function buildQuickSceneOptionLabel(scene = {}) {
  const status = getSceneStatusLabel(scene);
  return `${scene.name || "Untitled Scene"}${status ? ` · ${status}` : ""}`;
}

function focusSceneInDrawer(sceneId) {
  const nextSceneId = String(sceneId ?? "").trim();
  if (!nextSceneId || nextSceneId === state.sceneDrawerFocusId) {
    return;
  }
  if (state.sceneEditorSceneId) {
    rememberSceneDraft();
  }
  const scenes = state.selectedWorld?.scenes ?? [];
  if (!scenes.some((scene) => scene.id === nextSceneId)) {
    return;
  }
  state.sceneDrawerFocusId = nextSceneId;
  renderSceneLibrary();
  renderSceneDrawerSceneIndicator();
  renderSceneEditor();
}

function selectSceneForEditing(sceneId) {
  const nextSceneId = String(sceneId ?? "").trim();
  if (!nextSceneId || nextSceneId === state.selectedSceneId) {
    return;
  }
  const scenes = state.selectedWorld?.scenes ?? [];
  if (!scenes.some((scene) => scene.id === nextSceneId)) {
    return;
  }
  state.selectedSceneId = nextSceneId;
  state.sceneDrawerFocusId = nextSceneId;
  renderSelectedWorld();
}

function buildOptions(options = [], selectedValue = "") {
  return options.map((value) => `
    <option value="${htmlEscape(value)}" ${String(selectedValue) === String(value) ? "selected" : ""}>${htmlEscape(value || "none")}</option>
  `).join("");
}

function buildLabeledOptions(options = [], selectedValue = "") {
  return options.map((option) => `
    <option value="${htmlEscape(option.value)}" ${String(selectedValue) === String(option.value) ? "selected" : ""}>${htmlEscape(option.label || option.value || "none")}</option>
  `).join("");
}

function normalizeFacingMode(value = "") {
  const normalized = String(value ?? "").trim().toLowerCase();
  if (normalized === "billboard") {
    return "billboard";
  }
  if (normalized === "upright_billboard" || normalized === "billboard_y") {
    return "upright_billboard";
  }
  return "fixed";
}

function getFacingModeLabel(value = "") {
  const normalized = normalizeFacingMode(value);
  return FACING_MODE_OPTIONS.find((entry) => entry.value === normalized)?.label || "Fixed";
}

function isPrimitivePanelShape(entry = {}) {
  return String(entry?.shape ?? "").trim().toLowerCase() === "panel";
}

function getPrimitivePanelDimensions(entry = {}) {
  return {
    x: Math.max(0.2, Number(entry.scale?.x ?? 4) || 4),
    y: Math.max(0.2, Number(entry.scale?.y ?? 2.25) || 2.25),
    z: Math.max(0.05, Number(entry.scale?.z ?? 0.1) || 0.1),
  };
}

function getPrimitivePlacementPresetEntry() {
  return extractToolPresetEntry("primitive", getToolPreset("primitive")?.entry ?? createBaseToolPresetEntry("primitive"));
}

function buildFacingModeOptions(selectedValue = "fixed") {
  return buildLabeledOptions(FACING_MODE_OPTIONS, normalizeFacingMode(selectedValue));
}

function buildFacingModeEditor(entry = {}, note = "Fixed uses the saved rotation. Billboard turns toward each viewer, and upright billboard only turns around Y.") {
  return `
    <label>
      <span>Facing</span>
      <select data-entity-field="facing_mode" data-value-type="text">${buildFacingModeOptions(entry.facing_mode || "fixed")}</select>
    </label>
    <p class="pw-inspector-note">${htmlEscape(note)}</p>
  `;
}

function isVideoTextureAsset(asset = {}) {
  if (!asset || asset.asset_type !== "texture") {
    return false;
  }
  const videoFile = getPrivateAssetFile(asset, "base_color_video");
  if (videoFile?.url) {
    return true;
  }
  return String(asset?.context?.media_kind ?? "").trim().toLowerCase() === "video_texture";
}

function canApplyVideoTextureToRef(targetKind = "", targetId = "") {
  const normalizedTargetKind = String(targetKind ?? "").trim();
  const normalizedTargetId = String(targetId ?? "").trim();
  if (!normalizedTargetId || !VIDEO_TEXTURE_TARGET_ENTITY_KINDS.has(normalizedTargetKind)) {
    return false;
  }
  return canApplyTextureToRef(normalizedTargetKind, normalizedTargetId);
}

function canApplyTextureAssetToTarget(asset = null, target = null) {
  if (!asset || asset.asset_type !== "texture" || !target?.kind || !target?.id) {
    return false;
  }
  if (isVideoTextureAsset(asset)) {
    return canApplyVideoTextureToRef(target.kind, target.id);
  }
  return canApplyTextureToRef(target.kind, target.id);
}

function getMaterialAppearanceLabel(material = {}) {
  if (String(material?.video_asset_id ?? material?.videoAssetId ?? "").trim()) {
    return "video texture";
  }
  if (String(material?.texture_asset_id ?? material?.textureAssetId ?? "").trim()) {
    return "asset texture";
  }
  return material?.texture_preset || "none";
}

function getRenderableAnimationSettings(entry = {}) {
  return {
    clip: String(entry?.animation_clip ?? entry?.animationClip ?? "").trim(),
    autoplay: entry?.animation_autoplay === true || entry?.animationAutoplay === true,
    loop: entry?.animation_loop !== false && entry?.animationLoop !== false,
    speed: clampNumber(
      entry?.animation_speed ?? entry?.animationSpeed,
      1,
      0,
      4,
    ),
  };
}

function buildModelAnimationEditor(entry = {}, options = {}) {
  const targetKind = String(options.targetKind ?? "").trim();
  const assetId = String(entry?.asset_id ?? entry?.assetId ?? "").trim();
  if (!assetId || !MODEL_ASSET_TARGET_ENTITY_KINDS.has(targetKind)) {
    return "";
  }
  const settings = getRenderableAnimationSettings(entry);
  return `
    <section class="pw-material-texture-card">
      <div class="pw-material-texture-card__body">
        <span class="pw-material-texture-card__eyebrow">GLB Animation</span>
        <strong>Playback</strong>
        <p class="pw-material-texture-card__summary">Leave Clip blank to use the first animation inside the GLB. Autoplay is off by default so older worlds stay visually stable until you enable it.</p>
      </div>
      <div class="pw-inspector-grid pw-inspector-grid--2">
        <div>
          <label>
            <span>Clip</span>
            <input type="text" data-entity-field="animation_clip" data-value-type="text" value="${htmlEscape(settings.clip)}" placeholder="first clip" />
          </label>
        </div>
        <div>
          <label>
            <span>Speed</span>
            <input type="number" min="0" max="4" step="0.1" data-entity-field="animation_speed" data-value-type="number" value="${htmlEscape(settings.speed)}" />
          </label>
        </div>
      </div>
      <div class="pw-checkbox">
        <input type="checkbox" data-entity-field="animation_autoplay" data-value-type="checkbox" ${settings.autoplay ? "checked" : ""} />
        <span>Autoplay animation</span>
      </div>
      <div class="pw-checkbox">
        <input type="checkbox" data-entity-field="animation_loop" data-value-type="checkbox" ${settings.loop ? "checked" : ""} />
        <span>Loop animation</span>
      </div>
    </section>
  `;
}

function buildEntitySummary(kind, entry = {}) {
  if (kind === "sound") {
    const assetLabel = entry.asset_id ? "audio linked" : "no audio";
    const spatialLabel = entry.spatial === false ? "global" : `spatial ${Number(entry.max_distance ?? 24).toFixed(0)}`;
    return `${describeVector3(entry.position)} · ${assetLabel} · vol ${Number(entry.volume ?? 0.85).toFixed(2)} · ${entry.loop ? "loop" : "one-shot"} · ${entry.autoplay ? "autoplay" : "manual"} · ${spatialLabel}`;
  }
  if (kind === "particle") {
    return `${entry.target_id || "no target"} · ${describeVector3(entry.position)} · ${entry.enabled === false ? "off" : "on"}`;
  }
  if (kind === "prefab_instance") {
    return `${entry.prefab_id || "choose prefab"} · ${describeVector3(entry.position)}`;
  }
  if (kind === "model") {
    const bounds = entry.bounds ?? { x: 1, y: 1, z: 1 };
    const textureLabel = getMaterialAppearanceLabel(entry.material);
    return `${describeVector3(entry.position)} · ${textureLabel} · ${Number(bounds.x ?? 1).toFixed(1)} x ${Number(bounds.y ?? 1).toFixed(1)} x ${Number(bounds.z ?? 1).toFixed(1)}`;
  }
  if (kind === "primitive" && isPrimitivePanelShape(entry)) {
    const scale = getPrimitivePanelDimensions(entry);
    const appearanceLabel = entry.asset_id
      ? "model asset"
      : getMaterialAppearanceLabel(entry.material);
    return `${describeVector3(entry.position)} · ${getFacingModeLabel(entry.facing_mode)} · ${appearanceLabel} · ${Number(scale.x ?? 4).toFixed(1)} x ${Number(scale.y ?? 2.25).toFixed(1)}`;
  }
  if (kind === "primitive") {
    const scale = entry.scale ?? { x: 1, y: 1, z: 1 };
    const appearanceLabel = entry.asset_id
      ? "model asset"
      : getMaterialAppearanceLabel(entry.material);
    return `${describeVector3(entry.position)} · ${entry.shape || "box"} · ${appearanceLabel} · ${Number(scale.x ?? 1).toFixed(1)} x ${Number(scale.y ?? 1).toFixed(1)} x ${Number(scale.z ?? 1).toFixed(1)}`;
  }
  if (kind === "panel") {
    const scale = entry.scale ?? { x: 4, y: 2.25, z: 0.1 };
    const textureLabel = getMaterialAppearanceLabel(entry.material);
    return `${describeVector3(entry.position)} · ${getFacingModeLabel(entry.facing_mode)} · ${textureLabel} · ${Number(scale.x ?? 4).toFixed(1)} x ${Number(scale.y ?? 2.25).toFixed(1)}`;
  }
  if (kind === "screen") {
    return `${describeVector3(entry.position)} · ${getFacingModeLabel(entry.facing_mode)} · ${String(entry.html || "").slice(0, 18) || "empty html"}`;
  }
  if (kind === "text") {
    return `${describeVector3(entry.position)} · ${getFacingModeLabel(entry.facing_mode)} · scale ${Number(entry.scale ?? 1).toFixed(1)}`;
  }
  if (kind === "player") {
    const appearanceSummary = entry.asset_id
      ? "model asset"
      : getMaterialAppearanceLabel(entry.material);
    return `${describeVector3(entry.position)} · ${entry.camera_mode || "third_person"} · ${appearanceSummary} · scale ${Number(entry.scale ?? 1).toFixed(1)}`;
  }
  const details = [];
  if (entry.material?.texture_preset) {
    details.push(entry.material.texture_preset);
  }
  if ((Number(entry.material?.emissive_intensity) || 0) > 0) {
    details.push(`light ${roundPrivateValue(entry.material.emissive_intensity, 1)}`);
  }
  if (entry.invisible === true) {
    details.push("hidden in play");
  }
  return `${describeVector3(entry.position)}${details.length ? ` · ${details.join(" · ")}` : ""}`;
}

function renderSceneBuilder() {
  if (!elements.entitySections || !elements.entityEditor || !elements.prefabList || !elements.prefabDetail) {
    return;
  }
  let sceneDoc = null;
  try {
    sceneDoc = parseSceneTextarea();
  } catch (_error) {
    writeBuilderSelection([]);
    updateShellState();
    elements.entitySections.innerHTML = '<div class="pw-builder-group"><p class="pw-builder-empty">Fix the scene JSON to continue editing.</p></div>';
    if (elements.entityLibrarySummary) {
      elements.entityLibrarySummary.innerHTML = "";
    }
    elements.entityEditor.innerHTML = "";
    elements.prefabList.innerHTML = "";
    elements.prefabDetail.innerHTML = "";
    return;
  }
  const selected = ensureBuilderSelection(sceneDoc);
  updateShellState();
  if (elements.entitySearch && elements.entitySearch.value !== String(state.entityQuery ?? "")) {
    elements.entitySearch.value = String(state.entityQuery ?? "");
  }
  if (elements.entityFilter && elements.entityFilter.value !== String(state.entityFilterKind ?? "all")) {
    elements.entityFilter.value = String(state.entityFilterKind ?? "all");
  }
  if (elements.prefabSearch && elements.prefabSearch.value !== String(state.prefabQuery ?? "")) {
    elements.prefabSearch.value = String(state.prefabQuery ?? "");
  }
  renderEntitySections(sceneDoc, selected);
  renderEntityInspector(sceneDoc, selected);
  renderPrefabList(sceneDoc);
  renderAssetsLibrary();
  renderToolPresetPanel();
  const inspectorDisabled = !isEditor() || state.mode !== "build";
  for (const field of elements.entityEditor.querySelectorAll("input, select, textarea")) {
    field.disabled = inspectorDisabled;
  }
}

function renderEntitySections(sceneDoc, selected = null) {
  const normalizedQuery = String(state.entityQuery ?? "").trim().toLowerCase();
  const normalizedKind = String(state.entityFilterKind ?? "all").trim() || "all";
  const allEntries = ENTITY_COLLECTIONS.flatMap((config) => getEntityArray(sceneDoc, config.key).map((entry, index) => {
    const name = getDisplayNameForEntity(config.kind, entry, index);
    const summary = buildEntitySummary(config.kind, entry);
    return {
      config,
      entry,
      index,
      name,
      summary,
      searchText: [config.label, entry.id, name, summary, entry.label, entry.value, entry.effect, entry.prefab_id].filter(Boolean).join(" ").toLowerCase(),
    };
  }));
  const totalCount = allEntries.length;
  const visibleEntries = allEntries
    .filter((item) => (normalizedKind === "all" || item.config.kind === normalizedKind) && (!normalizedQuery || item.searchText.includes(normalizedQuery)))
    .sort((left, right) => {
      const leftSelected = isEntitySelected(left.config.kind, left.entry.id) ? 1 : 0;
      const rightSelected = isEntitySelected(right.config.kind, right.entry.id) ? 1 : 0;
      if (leftSelected !== rightSelected) {
        return rightSelected - leftSelected;
      }
      const kindCompare = left.config.label.localeCompare(right.config.label);
      if (kindCompare !== 0) {
        return kindCompare;
      }
      return left.name.localeCompare(right.name, undefined, { numeric: true, sensitivity: "base" });
    });
  const selectedEntries = getSelectedEntities(sceneDoc);
  const selectedSummary = !selectedEntries.length
    ? "No item selected."
    : selectedEntries.length === 1
      ? `${getDisplayNameForEntity(selectedEntries[0].kind, selectedEntries[0].entry, selectedEntries[0].index)} selected.`
      : `${selectedEntries.length} items selected together.`;
  const typeCounts = ENTITY_COLLECTIONS.map((config) => ({
    kind: config.kind,
    label: config.label,
    count: allEntries.filter((item) => item.config.kind === config.kind).length,
  })).filter((entry) => entry.count > 0);
  const filterLabel = normalizedKind === "all"
    ? "All items"
    : getEntityCollection(normalizedKind)?.label || "Items";
  const filterConfig = normalizedKind === "all" ? null : getEntityCollection(normalizedKind);
  const scopedSceneCount = normalizedKind === "all"
    ? totalCount
    : (typeCounts.find((entry) => entry.kind === normalizedKind)?.count ?? 0);
  const filterCountLabel = ((scopedSceneCount === 1 ? filterConfig?.singular : filterConfig?.label) || "item").toLowerCase();
  const scopedSceneSummary = normalizedKind === "all"
    ? `${totalCount} item${totalCount === 1 ? "" : "s"} in this scene.`
    : `${scopedSceneCount} ${filterCountLabel} in this scene.`;
  const breakdownMarkup = normalizedKind === "all" && typeCounts.length > 0
    ? `
      <div class="pw-item-summary__breakdown">
        ${typeCounts.map((entry) => `
          <span><strong>${htmlEscape(entry.count)}</strong> ${htmlEscape(entry.label)}</span>
        `).join("")}
      </div>
    `
    : "";
  if (elements.entitySearch) {
    elements.entitySearch.disabled = totalCount === 0;
  }
  if (elements.entityFilter) {
    elements.entityFilter.disabled = totalCount === 0;
  }
  if (elements.entitySearchHint) {
    elements.entitySearchHint.textContent = totalCount === 0
      ? "Add items to this scene, then browse them here when the world gets crowded."
      : !visibleEntries.length
        ? "No items match this search or type filter."
        : `${visibleEntries.length} item${visibleEntries.length === 1 ? "" : "s"} shown. Click one to select it and edit it in the inspector.`;
  }
  if (elements.entityLibrarySummary) {
    elements.entityLibrarySummary.innerHTML = `
      <div class="pw-scene-focus">
        <div class="pw-scene-focus__head">
          <strong>${htmlEscape(filterLabel)}</strong>
          <span>${visibleEntries.length} shown</span>
        </div>
        <small>${htmlEscape(scopedSceneSummary)}</small>
        ${breakdownMarkup}
        <small>${htmlEscape(selectedSummary)}</small>
      </div>
    `;
  }
  if (!totalCount) {
    elements.entitySections.innerHTML = '<div class="pw-builder-group"><p class="pw-builder-empty">No items in this scene yet.</p></div>';
    return;
  }
  if (!visibleEntries.length) {
    elements.entitySections.innerHTML = '<div class="pw-builder-group"><p class="pw-builder-empty">No items match that search yet.</p></div>';
    return;
  }
  elements.entitySections.innerHTML = visibleEntries.map((item) => `
    <button
      type="button"
      class="pw-scene-library-item pw-entity-row ${isEntitySelected(item.config.kind, item.entry.id) ? "is-active" : ""}"
      data-select-kind="${htmlEscape(item.config.kind)}"
      data-select-id="${htmlEscape(item.entry.id)}"
    >
      <div class="pw-scene-library-item__head">
        <strong>${htmlEscape(item.name)}</strong>
        <span>${htmlEscape(item.config.label)}</span>
      </div>
      <small>${htmlEscape(item.summary)}</small>
      ${item.entry.id && item.entry.id !== item.name ? `<small>${htmlEscape(item.entry.id)}</small>` : ""}
    </button>
  `).join("");
}

function buildVectorFields(label, basePath, value = {}) {
  return `
    <div>
      <label>
        <span>${htmlEscape(label)} X</span>
        <input type="number" step="0.1" data-entity-field="${htmlEscape(basePath)}.x" data-value-type="number" value="${htmlEscape(value.x ?? 0)}" />
      </label>
    </div>
    <div>
      <label>
        <span>${htmlEscape(label)} Y</span>
        <input type="number" step="0.1" data-entity-field="${htmlEscape(basePath)}.y" data-value-type="number" value="${htmlEscape(value.y ?? 0)}" />
      </label>
    </div>
    <div>
      <label>
        <span>${htmlEscape(label)} Z</span>
        <input type="number" step="0.1" data-entity-field="${htmlEscape(basePath)}.z" data-value-type="number" value="${htmlEscape(value.z ?? 0)}" />
      </label>
    </div>
  `;
}

function buildMaterialEditor(material = {}, options = {}) {
  const fieldPrefix = String(options.pathPrefix ?? "material.");
  const allowEmission = options.allowEmission === true;
  const textureTargetKind = String(options.textureTargetKind ?? "").trim();
  const textureTargetId = String(options.textureTargetId ?? "").trim();
  const allowVideoTexture = options.allowVideoTexture === true;
  const linkedTextureId = String(material.texture_asset_id ?? "").trim();
  const linkedTexture = linkedTextureId ? getPrivateAssetById(linkedTextureId) : null;
  const linkedTextureThumb = getPrivateAssetFile(linkedTexture, "base_color");
  const canChooseTexture = Boolean(textureTargetKind && textureTargetId && canApplyTextureToRef(textureTargetKind, textureTargetId));
  const linkedVideoId = String(material.video_asset_id ?? material.videoAssetId ?? "").trim();
  const linkedVideo = linkedVideoId ? getPrivateAssetById(linkedVideoId) : null;
  const canChooseVideo = allowVideoTexture
    && Boolean(textureTargetKind && textureTargetId && canApplyVideoTextureToRef(textureTargetKind, textureTargetId));
  const textureActionsDisabled = !canChooseTexture || !state.session || !state.selectedWorld || !isEditor() || state.mode !== "build";
  const videoActionsDisabled = !canChooseVideo || !state.session || !state.selectedWorld || !isEditor() || state.mode !== "build";
  const textureTitle = linkedTexture?.name
    || (linkedTextureId ? "Linked texture asset" : "No custom texture linked");
  const textureSummary = linkedTexture
    ? (linkedTexture.intended_use || linkedTexture.world_context_summary || buildAssetSummary(linkedTexture))
    : linkedTextureId
      ? `Texture asset ${linkedTextureId} is linked here, but it is not available in your library right now.`
      : `Current pattern: ${material.texture_preset || "none"}. Choose a library texture or generate a new one with AI.`;
  const textureIdNote = linkedTextureId
    ? `<small class="pw-material-texture-card__id">${htmlEscape(linkedTextureId)}</small>`
    : "";
  const texturePreview = linkedTextureThumb?.url
    ? `<img class="pw-material-texture-card__thumb" src="${htmlEscape(linkedTextureThumb.url)}" alt="${htmlEscape(textureTitle)} preview" />`
    : `<div class="pw-material-texture-card__thumb pw-material-texture-card__thumb--empty" aria-hidden="true">${htmlEscape(material.texture_preset || "none")}</div>`;
  const textureActions = canChooseTexture
    ? `
      <div class="pw-inline-actions pw-material-texture-card__actions">
        <button type="button" data-open-texture-library ${textureActionsDisabled ? "disabled" : ""}>Choose from library</button>
        <button type="button" class="is-muted" data-generate-texture-from-inspector ${textureActionsDisabled ? "disabled" : ""}>Generate with AI</button>
        ${linkedTextureId ? `<button type="button" class="is-muted" data-clear-texture-asset-path="${htmlEscape(fieldPrefix)}" ${textureActionsDisabled ? "disabled" : ""}>Clear</button>` : ""}
      </div>
    `
    : "";
  const videoIdNote = linkedVideoId
    ? `<small class="pw-material-texture-card__id">${htmlEscape(linkedVideoId)}</small>`
    : "";
  const videoTitle = linkedVideo?.name
    || (linkedVideoId ? "Linked video texture" : "No video texture linked");
  const videoSummary = linkedVideo
    ? (linkedVideo.intended_use || linkedVideo.world_context_summary || buildAssetSummary(linkedVideo))
    : linkedVideoId
      ? `Video texture asset ${linkedVideoId} is linked here, but it is not available in your library right now.`
      : "Movie textures stretch one looping video across the surface. Audio stays muted here, so pair it with a Sound item when you want audible playback.";
  const videoActions = canChooseVideo
    ? `
      <div class="pw-inline-actions pw-material-texture-card__actions">
        <button type="button" data-open-video-texture-library ${videoActionsDisabled ? "disabled" : ""}>Choose from library</button>
        ${linkedVideoId ? `<button type="button" class="is-muted" data-clear-video-asset-path="${htmlEscape(fieldPrefix)}" ${videoActionsDisabled ? "disabled" : ""}>Clear</button>` : ""}
      </div>
    `
    : "";
  return `
    <div class="pw-inspector-grid pw-inspector-grid--2">
      <div>
        <label>
          <span>Color</span>
          <input type="color" data-entity-field="${htmlEscape(`${fieldPrefix}color`)}" data-value-type="color" value="${htmlEscape(material.color || "#c8d0d8")}" />
        </label>
      </div>
      <div>
        <label>
          <span>Pattern</span>
          <select data-entity-field="${htmlEscape(`${fieldPrefix}texture_preset`)}" data-value-type="text">
            ${buildOptions(MATERIAL_PRESET_OPTIONS, material.texture_preset || "none")}
          </select>
        </label>
      </div>
    </div>
    <section class="pw-material-texture-card">
      <div class="pw-material-texture-card__row">
        ${texturePreview}
        <div class="pw-material-texture-card__body">
          <span class="pw-material-texture-card__eyebrow">Texture</span>
          <strong>${htmlEscape(textureTitle)}</strong>
          <p class="pw-material-texture-card__summary">${htmlEscape(textureSummary)}</p>
          ${textureIdNote}
        </div>
      </div>
      ${textureActions}
    </section>
    ${allowVideoTexture ? `
      <section class="pw-material-texture-card">
        <div class="pw-material-texture-card__row">
          <div class="pw-material-texture-card__thumb pw-material-texture-card__thumb--empty" aria-hidden="true">video</div>
          <div class="pw-material-texture-card__body">
            <span class="pw-material-texture-card__eyebrow">Video Texture</span>
            <strong>${htmlEscape(videoTitle)}</strong>
            <p class="pw-material-texture-card__summary">${htmlEscape(videoSummary)}</p>
            ${videoIdNote}
          </div>
        </div>
        ${videoActions}
      </section>
    ` : ""}
    ${allowEmission ? `
      <div class="pw-inspector-grid pw-inspector-grid--2">
        <div>
          <label>
            <span>Light Emission</span>
            <input type="number" min="0" max="8" step="0.1" data-entity-field="${htmlEscape(`${fieldPrefix}emissive_intensity`)}" data-value-type="number" value="${htmlEscape(material.emissive_intensity ?? 0)}" />
          </label>
        </div>
      </div>
    ` : ""}
  `;
}

function getPrivatePlayerDefaultMaterial(playerLike = {}) {
  const bodyMode = String(playerLike?.body_mode ?? playerLike?.bodyMode ?? "rigid").trim().toLowerCase();
  return {
    color: bodyMode === "ghost" ? "#6dd3ff" : "#ff8e4f",
    texture_preset: "none",
    texture_asset_id: null,
    video_asset_id: null,
    emissive_intensity: 0,
  };
}

function getResolvedPrivatePlayerMaterial(playerLike = {}, options = {}) {
  const fallback = options.fallback ?? getPrivatePlayerDefaultMaterial(playerLike);
  const material = typeof playerLike?.material === "object" && playerLike.material
    ? playerLike.material
    : {};
  return {
    color: String(material.color ?? "").trim() || fallback.color,
    texture_preset: String(material.texture_preset ?? material.texturePreset ?? "").trim() || fallback.texture_preset,
    texture_asset_id: String(material.texture_asset_id ?? material.textureAssetId ?? "").trim() || fallback.texture_asset_id,
    video_asset_id: String(material.video_asset_id ?? material.videoAssetId ?? "").trim() || fallback.video_asset_id,
    emissive_intensity: Math.max(
      0,
      Number(material.emissive_intensity ?? material.emissiveIntensity ?? fallback.emissive_intensity ?? 0) || 0,
    ),
  };
}

function getRenderablePrivatePlayerMaterial(playerLike = {}, options = {}) {
  const resolved = getResolvedPrivatePlayerMaterial(playerLike, options);
  return {
    ...resolved,
    color: options.occupied === true ? "#ff5a6f" : resolved.color,
  };
}

function canApplyModelAssetToRef(targetKind = "", targetId = "") {
  const normalizedTargetKind = String(targetKind ?? "").trim();
  const normalizedTargetId = String(targetId ?? "").trim();
  if (!normalizedTargetId || !MODEL_ASSET_TARGET_ENTITY_KINDS.has(normalizedTargetKind)) {
    return false;
  }
  try {
    const sceneDoc = parseSceneTextarea();
    return Boolean(findEntityByRef(sceneDoc, { kind: normalizedTargetKind, id: normalizedTargetId })?.entry);
  } catch (_error) {
    return false;
  }
}

function getSelectedModelAttachTarget() {
  const targetKind = String(state.builderSelection?.kind ?? "").trim();
  const targetId = String(state.builderSelection?.id ?? "").trim();
  if (!targetKind || !targetId || !MODEL_ASSET_TARGET_ENTITY_KINDS.has(targetKind)) {
    return null;
  }
  try {
    const sceneDoc = parseSceneTextarea();
    const found = findEntityByRef(sceneDoc, { kind: targetKind, id: targetId });
    if (!found?.entry) {
      return null;
    }
    return {
      kind: targetKind,
      id: targetId,
      entry: found.entry,
      index: found.index,
      name: getDisplayNameForEntity(targetKind, found.entry, found.index),
      title: buildCompactEntityTitle(targetKind, found.entry, found.index),
      meta: [
        getEntityCollection(targetKind)?.singular || "Item",
        found.entry?.id ? truncatePrivateUiLabel(found.entry.id, 72) : "",
      ].filter(Boolean).join(" · "),
      summary: buildEntitySummary(targetKind, found.entry),
    };
  } catch (_error) {
    return null;
  }
}

function applyModelAssetToSelection(assetId, options = {}) {
  const targetKind = String(options.targetKind ?? state.builderSelection?.kind ?? "").trim();
  const targetId = String(options.targetId ?? state.builderSelection?.id ?? "").trim();
  const asset = getPrivateAssetById(assetId);
  if (!asset || asset.asset_type !== "model" || !canApplyModelAssetToRef(targetKind, targetId)) {
    return false;
  }
  mutateSceneDoc((sceneDoc) => {
    const found = findEntityByRef(sceneDoc, { kind: targetKind, id: targetId });
    if (!found?.entry) {
      return;
    }
    found.entry.asset_id = asset.id;
    if (targetKind === "model" && !found.entry.bounds) {
      found.entry.bounds = cloneJson(asset.bounds ?? { x: 1, y: 1, z: 1 });
    }
    if (targetKind === "player") {
      found.entry.material = found.entry.material || getPrivatePlayerDefaultMaterial(found.entry);
    }
  });
  pushEvent("asset:model-applied", asset.name || asset.id);
  return true;
}

function clearModelAssetFromSelection(path = "asset_id") {
  const normalizedPath = String(path ?? "asset_id").trim() || "asset_id";
  updateSelectedEntityField(normalizedPath, "", "text");
}

function getModelAssetTargetActionLabel(target = null) {
  const targetKind = String(target?.kind ?? "").trim();
  if (targetKind === "player") {
    return "Use on selected player";
  }
  if (targetKind === "primitive") {
    return "Use on selected object";
  }
  if (targetKind === "model") {
    return "Swap selected model";
  }
  return "Use selected model";
}

function buildModelAssetEditor(assetId = "", options = {}) {
  const normalizedAssetId = String(assetId ?? "").trim();
  const fieldPath = String(options.path ?? "asset_id").trim() || "asset_id";
  const targetKind = String(options.targetKind ?? "").trim();
  const targetId = String(options.targetId ?? "").trim();
  const asset = normalizedAssetId ? getPrivateAssetById(normalizedAssetId) : null;
  const thumbnail = getPrivateAssetFile(asset, "thumbnail");
  const canChooseModel = Boolean(targetKind && targetId && canApplyModelAssetToRef(targetKind, targetId));
  const disabled = !canChooseModel || !state.session || !state.selectedWorld || !isEditor() || state.mode !== "build";
  const title = asset?.name
    || (normalizedAssetId ? "Linked model asset" : "No custom model linked");
  const summary = asset
    ? (asset.intended_use || asset.world_context_summary || buildAssetSummary(asset))
    : normalizedAssetId
      ? `Model asset ${normalizedAssetId} is linked here, but it is not available in your library right now.`
      : "Choose a model asset from your library or generate one with AI.";
  const idNote = normalizedAssetId
    ? `<small class="pw-material-texture-card__id">${htmlEscape(normalizedAssetId)}</small>`
    : "";
  const preview = thumbnail?.url
    ? `<img class="pw-material-texture-card__thumb" src="${htmlEscape(thumbnail.url)}" alt="${htmlEscape(title)} preview" />`
    : `<div class="pw-material-texture-card__thumb pw-material-texture-card__thumb--empty" aria-hidden="true">model</div>`;
  const actions = canChooseModel
    ? `
      <div class="pw-inline-actions pw-material-texture-card__actions">
        <button type="button" data-open-model-library ${disabled ? "disabled" : ""}>Choose from library</button>
        <button type="button" class="is-muted" data-generate-model-from-inspector ${disabled ? "disabled" : ""}>Generate with AI</button>
        ${normalizedAssetId ? `<button type="button" class="is-muted" data-clear-model-asset-path="${htmlEscape(fieldPath)}" ${disabled ? "disabled" : ""}>Clear</button>` : ""}
      </div>
    `
    : "";
  return `
    <section class="pw-material-texture-card">
      <div class="pw-material-texture-card__row">
        ${preview}
        <div class="pw-material-texture-card__body">
          <span class="pw-material-texture-card__eyebrow">Model</span>
          <strong>${htmlEscape(title)}</strong>
          <p class="pw-material-texture-card__summary">${htmlEscape(summary)}</p>
          ${idNote}
        </div>
      </div>
      ${actions}
    </section>
  `;
}

